/* Bhutan drug library: National Essential Medicines Formulary 2022 monographs and NEML 2025 listings,
   taken from the Bhutan Clinical Reference app (2026-11-22). Read-only reference data. */
window.FORMULARY = [{"k":"HALOTHANE","n":"HALOTHANE","g":"General anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.1 Inhalational medicines","moa":"Volatile anaesthetic; enhances GABA-A and glycine receptor activity and inhibits NMDA receptors, depressing CNS transmission.","f":[["Indications & dose","Induction and maintenance of anaesthesia by inhalation with or without nitrous oxide and oxygen, ADULT and CHILD 1-2%, gradually introduce halothane up to 2-4%. CHILD 1.5-2%; Maintenance ADULT and CHILD 0.5-2%."],["Contraindications","History of unexplained jaundice or pyrexia following previous exposure to halothane, family history of malignant hyperthermia, raised cerebrospinal fluid pressure and porphyria."],["Cautions","Previous exposure and reactions to halothane (at least 3 months between each exposure)."],["Side effects","Hepatotoxicity (there is an increased risk with frequent exposure to halothane), arrhythmias, bradycardia, and respiratory depression."],["Pregnancy category","C"],["Breast-feeding","Use with caution. Low levels anticipated in milk due to its properties but may persist for a prolonged period."]],"f25":[],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ISOFLURANE","n":"ISOFLURANE","g":"General anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.1 Inhalational medicines","moa":"Volatile anaesthetic; potentiates GABA-A and glycine receptors, inhibits NMDA receptors and opens K+ channels.","f":[["Indications & dose","Induction of anaesthesia (in oxygen or nitrous oxide-oxygen) by inhalation, ADULT and CHILD 0.5-3%. Maintenance of anaesthesia (in nitrous oxide-oxygen) ADULT and CHILD 1-2.5% an additional 0.5-1 % may be required when given with oxygen alone. Maintenance of anaesthesia in caesarean section (in nitrous oxide-oxygen) ADULT: 0.5-0.75%, by inhalation."],["Contraindications","Susceptibility to malignant hyperthermia."],["Cautions","Can trigger malignant hyperthermia, raised intracranial pressure, and children under 2 years."],["Side effects","Breath-holding, cough, irritate mucous membrane and laryngospasm."],["Pregnancy category","C"],["Breast-feeding","Can be resumed as soon as mother has recovered sufficiently from anaesthesia."]],"f25":[{"i":"Isoflurane solution 99.9% v/v (250mL) bottle","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Isoflurane inhalation (250mL) bottle → now Isoflurane solution 99.9% v/v (250mL) bottle"]],"al":""},{"k":"NITROUS OXIDE","n":"NITROUS OXIDE","g":"General anaesthetic and labour analgesia.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.1 Inhalational medicines","moa":"NMDA receptor antagonist with weak anaesthetic and strong analgesic effect; low blood solubility gives rapid onset/offset.","f":[["Indications & dose","Maintenance of anaesthesia in conjunction with other anaesthetic agents ADULT and CHILD 50-66%, by inhalation with oxygen. Analgesia ADULT and CHILD Up to 50%, by inhalation with oxygen adjusted according to the patient’s need."],["Contraindications","Closed collections of air or gas in any body space including intestinal obstruction, middle ear occlusion, eye surgery and in pneumothorax."],["Cautions","Pneumothorax, presence of intracranial air after head injury, and recent intraocular gas injection."],["Side effects","Depression of white cell formation, hypoxia, megaloblastic anaemia, and neurological toxic effects."],["Breast-feeding","Can be resumed as soon as mother has recovered sufficiently from anaesthesia."]],"f25":[{"i":"Nitrous oxide inhalation cylinder","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"OXYGEN","n":"OXYGEN","g":"Medical gas.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.1 Inhalational medicines","moa":"Raises inspired O2 fraction, increasing alveolar and arterial oxygen tension to correct hypoxaemia.","f":[["Indications & dose","The concentration of inspired oxygen used has generally been determined by the condition being treated, but for acute therapy it is preferable to adjust the concentration in line with the patient's oxygen saturation. For most patients, the target oxygen saturation, measured by pulse oximetry, should be 94 to 98%. However, for patients with hypercapnia or at risk of hypercapnia, a lower target range of 88 to 92 % is recommended. Critically ill patients including those with carbon monoxide poisoning High concentration oxygen (reservoir mask at flow rate of 15 litres/minute). Acute hypoxaemia due to conditions such as acute asthma, pneumonia, pulmonary embolism and postoperatively Oxygen saturation below 85% Reservoir mask at flow rate of 10 to 15 litres/minute; Oxygen saturation 85 % or higher Nasal cannulae or simple face mask at flow rate of 2 to 10 litres/minute. Chronic obstructive pulmonary disease or otherwise at risk of hypercapnia if oxygen saturation unknown 28% at 4 litres/minute, or 24% at 2 to 4 litres/minute if there is a history of hypercapnia (via Venturi mask); Oxygen saturation below 88% Nasal cannulae at 2 to 6 litres/minute or simple face mask at 5 litres/minute."],["Cautions","Fire and explosion may be the risk, high oxygen concentrations in incubators have led to the development of retrolental fibroplasia leading to permanent blindness in premature infants."],["Side effects","Pulmonary toxicity usually results from prolonged or repeated exposure. Symptoms include cough, dyspnoea, and substernal discomfort, and there may also be a reduction in vital capacity; alveolar collapse (absorption atelectasis), pulmonary oedema, pneumonitis. CNS toxicity is at pressures above 2 atmospheres absolute; the risk is higher in wet conditions and with physical activity. Symptoms include nausea, mood changes, vertigo, twitching, convulsions, and loss of consciousness. Toxic effects on the eyes may also occur."]],"f25":[{"i":"Oxygen inhalation (Medical gas) cylinder","v":"V","l":"NRH/RRH/DH/PHC","r":"Type B cylinder to be supplied to PHC"}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SEVOFLURANE","n":"SEVOFLURANE","g":"General anaesthetic inhalation.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.1 Inhalational medicines","moa":"Volatile anaesthetic; potentiates GABA-A and glycine receptors; low blood solubility and non-pungent, suits inhalational induction.","f":[["Indications & dose","Induction of anaesthesia (with oxygen or nitrous oxide-oxygen) ADULT and CHILD Initially 0.5-1%, then increased to up to 8%, increased gradually, according to response, to be administered using specifically calibrated vaporizer; NEONATE Initially 0.5-1%, then increased to up to 4%; Maintenance (in oxygen or nitrous oxide-oxygen) ADULT and CHILD 0.5-3%, adjusted according to response, to be administered using specifically calibrated vaporizer; NEONATE 0.5-2%, adjust according to response."],["Contraindications","Known or suspected sensitivity to sevoflurane or other halogenated inhalation anaesthetics. Known or suspected susceptibility to malignant hyperthermia."],["Cautions","Susceptibility to QT-interval prolongation. Dose-related hypotension and hemodynamic changes may occur."],["Side effects","Drowsiness, fever, hypotension, and hypothermia."],["Renal impairment","Use with caution."],["Pregnancy category","May depress neonatal respiration if used during delivery."],["Breast-feeding","Resume as soon as mother has recovered sufficiently from anaesthesia."]],"f25":[{"i":"Sevoflurane 99.9%v/v solution (250mL) bottle","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Sevoflurane inhalation (250mL) bottle → now Sevoflurane 99.9%v/v solution (250mL) bottle"]],"al":""},{"k":"KETAMINE","n":"KETAMINE","g":"General anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.2 Injectable medicines","moa":"Non-competitive NMDA receptor antagonist producing dissociative anaesthesia and analgesia; sympathomimetic, preserves airway reflexes.","f":[["Indications & dose","Induction and maintenance of anaesthesia for short procedures ADULT 6.5-13 mg/kg, IM OR 1-4.5 mg/kg IV administer over at least 60 seconds; CHILD 4-13 mg/kg, IM; CHILD (1 month-11 years) 1-2 mg/kg, IV given over at least 60 seconds; CHILD (12-17 years) 1-4.5 mg/kg, IV given over at least 60 seconds. Diagnostic manoeuvres and procedures not involving intense pain ADULT 4 mg/kg, IM; CHILD 1-2 mg/kg. Induction and maintenance of anaesthesia for long procedures ADULT 0.5-2 mg/kg, IV using an infusion solution containing 1 mg/mL; Maintenance 10-45 mcg/kg/minute; CHILD 0.5-2 mg/kg, IV followed by 10-45 mcg/kg/minute."],["Contraindications","Acute porphyria, eclampsia, head trauma, hypertension, pre-eclampsia, raised intracranial pressure, severe cardiac disease, and stroke."],["Cautions","Acute circulatory failure (shock), cardiovascular disease, dehydration, elderly, fixed cardiac output, hallucinations, head injury, hypertension, hypovolaemia, increased cerebrospinal fluid pressure, intracranial mass lesions, nightmares, predisposition to seizures, psychotic disorders, raised intraocular pressure, respiratory tract infection, thyroid dysfunction."],["Side effects","Diplopia, hallucinations, hypertension, nausea, nightmares, nystagmus, rash, tachycardia, transient psychotic effects, vomiting, arrhythmias, bradycardia, hypotension, laryngospasm, respiratory depression."],["Hepatic impairment","Consider dose reduction."],["Pregnancy category","C"],["Breast-feeding","Avoid for at least 12 hours after the last dose."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9% and water for injection."],["Note","Diazepam administered before, during or after anaesthetic reduces incidence of hallucinations."]],"f25":[{"i":"Ketamine 50 mg/ml (2mL) for both IM and IV injection vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Ketamine 50mg/mL injection (10mL) vial → now Ketamine 50mg/mL injection (2mL) vial"]],"al":""},{"k":"PROPOFOL","n":"PROPOFOL","g":"General anaesthetics (short acting)","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.2 Injectable medicines","moa":"Potentiates GABA-A receptor chloride currents, causing rapid-onset, short-acting hypnosis.","f":[["Indications & dose","Induction of anaesthesia ADULT (18-54 years) 1.5-2.5 mg/kg, IV administer at a rate of 20-40 mg/10 secs until response; ADULT (55 years and over) 1-1.5mg/kg administer at a rate of 20 mg/10 secs until response; CHILD (1 month-16 years) 2.5-4 mg/kg, IV; Maintenance ADULT 4-12 mg/kg/hour, IV and repeat the dose according to response; ELDERLY 3-6 mg/kg/hour, IV; CHILD (1 month-16 years) 9-15 mg/kg/hour, IV. Sedation of ventilated patients in intensive care ADULT 0.3-4 mg/kg/hour, IV; CHILD (16-17 years) 0.3-4 mg/kg/hour; CHILD (1 month-16 years) 1-2 mg/kg, IV. Induction of sedation for surgical and diagnostic procedures ADULT 0.5-1 mg/kg, IV administered over 1-5 minutes. Maintenance of sedation for surgical and diagnostic procedures ADULT 1.5-4.5 mg/kg/hour, IV."],["Contraindications","Porphyria and hypersensitivity, and children under 16 years receiving intensive care."],["Cautions","Acute circulatory failure (shock), cardiac impairment, cardiovascular disease, elderly, epilepsy, fixed cardiac output, hypotension, hypovolaemia, raised intracranial pressure, respiratory impairment."],["Side effects","Headache, hypotension, tachycardia, transient apnoea; phlebitis, thrombosis; anaphylaxis, arrhythmia, convulsions (onset can be delayed), delayed recovery from anaesthesia, euphoria."],["Renal impairment","Use with caution."],["Hepatic impairment","Use with caution."],["Pregnancy category","B"],["Breast-feeding","Can be resumed as soon as the mother has recovered sufficiently from anaesthesia."],["IV fluid compatibility","Dextrose 5% and sodium chloride 0.9%."],["Note","Propofol is not recommended for use in obstetrics including caesarean section; repeated dose can lead to prolonged recovery and should not be used for maintenance; it has no analgesic activity and supplementary analgesia may be required."]],"f25":[{"i":"Propofol 10mg/mL injection (10mL) vial","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"THIOPENTAL SODIUM","n":"THIOPENTAL SODIUM","g":"General anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.1.2 Injectable medicines","moa":"Ultra-short-acting barbiturate; prolongs GABA-A chloride channel opening (and directly opens it at high doses).","f":[["Indications & dose","Induction of anaesthesia ADULT 100-150 mg slow IV, administer over 10-15 seconds usually as a 2.5 % solution, followed by 100-150 mg after 0.5-1 minute; Debilitated patients or adults over 65 years may require a lower dose or increase administration time, alternatively initially up to 4 mg/kg (MAX. 500 mg/dose); CHILD Initially up to 4 mg/kg, slow IV and then 1 mg/kg, repeat if necessary (MAX. 7 mg/kg/dose). Anaesthesia of short duration ADULT 100-150 mg, slow IV, administer over 10-15 seconds usually as a 2.5% solution, followed by 100-150 mg after 0.5-1 minute; debilitated patients or adults over 65 years may require a lower dose or increased administration time, alternatively initially up to 4 mg/kg (MAX. 500 mg/dose). Reduction of raised intracranial pressure if ventilation-controlled ADULT 1.5-3 mg/kg, slow IV repeated if necessary. Status epilepticus (only if other measures fail) ADULT 75-125 mg, slow IV administered as a 2.5% solution."],["Contraindications","Acute porphyrias, myotonic dystrophy."],["Cautions","Acute circulatory failure (shock), avoid intra-arterial injection, cardiovascular disease, elderly, fixed cardiac output, hypovolaemia, reconstituted solution is highly alkaline (extravasation causes tissue necrosis and severe pain). Overdose Respiratory depression progresses through hypotension to circulatory collapse. Repeated dose can lead to prolonged recovery, therefore it should not be used for maintenance."],["Side effects","Arrhythmias, cough, headache, hypersensitivity reactions, hypotension, laryngeal spasm, myocardial depression, rash, sneezing."],["Renal impairment","Caution in severe impairment."],["Hepatic impairment","Use with caution, reduce dose."],["Pregnancy category","C"],["Breast-feeding","Can be resumed as soon as the mother has recovered sufficiently from anaesthesia."]],"f25":[{"i":"Thiopental sodium 1g powder for injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":"thiopentone"},{"k":"BUPIVACAINE","n":"BUPIVACAINE","g":"Local anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.2 Local anaesthetics","moa":"Amide local anaesthetic; blocks voltage-gated Na+ channels from inside the axon, stopping impulse conduction. Long acting, most cardiotoxic.","f":[["Indications & dose","Lumbar epidural block anaesthesia ADULT and CHILD (>12 years) 75-150 mg, by regional administration. Field block anaesthesia ADULT and CHILD (>12 years) Up to 150 mg using a 2.5 mg/mL (0.25%) solution, by regional administration. Thoracic epidural block anaesthesia ADULT and CHILD (>12 years) 12.5-50 mg, by thoracic epidural. Caudal epidural block anaesthesia ADULT and CHILD (>12 years) 50-150 mg, by regional administration. Major nerve block anaesthesia ADULT 50-175 mg, by regional administration. Intra-articular block anaesthesia ADULT by intra-articular injection, up to 100 mg administered using a 2.5 mg/mL (0.25%) solution; when co-administered with bupivacaine by another route, MAX. 150 mg. Thoracic epidural block anaesthesia by continuous epidural infusion, ADULT 6.3-18.8 mg/hour administered using a 1.25mg/mL (0.125%) or 2.5 mg/mL (0.25%) solution; MAX. 400 mg per day. Acute labour pain by continuous epidural infusion, ADULT 6.25-12.5 mg/hour administered using a 1.25 mg/mL (0.125%) solution. MAX. 400 mg per day. Lumbar epidural block anaesthesia Initially by lumbar epidural, ADULT 15-37.5 mg, then 15-37.5 mg, repeat when required at intervals of at least 30 minutes using a 2.5 mg/mL (0.25%) solution, alternatively (by continuous epidural infusion) 12.5-18.8 mg/hour using a 1.25 mg/mL (0.125%) or 2.5 mg/mL (0.25%) solution; MAX. 400 mg per day. Intrathecal anaesthesia by intrathecal injection, ADULT 10-20 mg."],["Contraindications","Application to the middle ear (can cause ototoxicity), infected tissues, inflamed tissues, complete heart block, preparations containing preservatives should not be used for caudal, epidural, or spinal block, or for IV regional anaesthesia (Bier’s block), damaged skin."],["Cautions","Cardiovascular disease, cerebral atheroma, debilitated patients (consider dose reduction), elderly (consider dose reduction), epilepsy, hypertension, hypotension, hypovolaemia, impaired cardiac conduction, impaired respiratory function, myasthenia gravis, myocardial depression may be more severe and more resistant to treatment, shock."],["Side effects","Arrhythmias, blurred vision, cardiac arrest, convulsions, dizziness, drowsiness, feeling of inebriation, headache, light-headedness, muscle twitching, myocardial depression, nausea, numbness of the tongue and perioral region, paraesthesia, peripheral vasodilatation, tremors, vomiting."],["Renal impairment","Use with caution in severe impairment."],["Hepatic impairment","Use with caution in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Amount too small to be harmful."],["Note","To avoid excessive dosage in obese patients, dose may need to be calculated based on ideal body weight."]],"f25":[{"i":"Bupivacaine 0.5% + Dextrose 8% injection (4mL) ampoule","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is OT"},{"i":"Bupivacaine 0.5% preservative free injection (20mL) vial","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"EPHEDRINE","n":"EPHEDRINE","g":"Local anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.2 Local anaesthetics","moa":"Mixed-acting sympathomimetic: releases noradrenaline and directly stimulates alpha and beta receptors, raising BP and heart rate.","f":[["Indications & dose","Reversal of hypotension from spinal or epidural anaesthesia ADULT 3-6 mg IV every 3-4 minutes (MAX. dose 9 mg), adjusted according to response, MAX. 30 mg per course; CHILD (1-11 years) 500-750 mcg/kg IV every 3-4 minutes, adjusted according to response, MAX. 30 mg per course; CHILD (12-17 years) 3-7.5 mg IV every 3-4 minutes (MAX. dose 9 mg), adjusted according to response, MAX. 30 mg per course."],["Cautions","Diabetes mellitus, elderly, hypertension, Hyperthyroidism, ischaemic heart disease, prostatic hypertrophy (risk of acute urinary retention), susceptibility to angle-closure glaucoma."],["Side effects","Anginal pain, anorexia. anxiety, arrhythmias, changes in blood-glucose concentration, confusion, difficulty in micturition, dizziness, dyspnoea, flushing, headache, hypersalivation, insomnia, nausea, psychoses, restlessness, sweating, tachycardia, tremor, urine retention, vasoconstriction with hypertension, vasodilation with hypotension and vomiting."],["Renal impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."]],"f25":[{"i":"Ephedrine 3mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Ephedrine 3mg/mL injection (10mL) ampoule → now Ephedrine 3mg/mL injection (2mL) ampoule"]],"al":""},{"k":"LIGNOCAINE","n":"LIGNOCAINE","g":"Local anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.2 Local anaesthetics","moa":"Amide local anaesthetic and class Ib antiarrhythmic; blocks voltage-gated Na+ channels (use-dependent).","f":[["Indications & dose","Infiltration anaesthesia by local infiltration, ADULT Dose to be given according to patient’s weight and nature of procedure; MAX. 200 mg, MAX. dose 500 mg if given in solutions containing adrenaline; NEONATE Up to 3 mg/kg, dose may be repeated not more often than every 4 hours, 3 mg/kg equivalent to 0.3 mL/kg of 1% solution; CHILD (1 month-11 years) Up to 3 mg/kg, dose may be repeated not more often than every 4 hours, 3 mg/kg equivalent to 0.3 mL/kg of 1% solution; CHILD (12-17 years) MAX. per dose 200 mg, dose may be repeated not more often than every 4 hours. Intravenous regional anaesthesia and nerve block The following table is a guide to dosage for the more commonly used techniques in an average adult. The figures reflect the expected average dose range needed. The lowest dose required for adequate anaesthesia should be used. Individual variations in onset and duration occur. The duration may be prolonged with the adrenaline-containing solutions. Dose Onset Duration of effect without/ with Conc. adrenaline (min) (h) Type of block (mg/mL) Without With mL mg adrenaline adrenaline SURGICAL ANAESTHESIA Lumbar epidural administration 1 20 15-25 300-500 15-20 1.5-2 2-3 Thoracic epidural administration 1 20 10-15 200-300 10-20 1.5-2 2-3 10 20-30 200-300 15-30 1-1.5 1-2 Caudal epidural block 1 20 15-25 300-500 15-30 1.5-2 2-3 30-60 min Intra-articular block 10 ≤40 ≤400 5-10 after washout FIELD BLOCK (e.g., minor nerve blocks and infiltration) Infiltration 10 ≤40 ≤400 1-2 2-3 3-4 Digital block 10 1-5 10-15 2-5 1.5-2 NR Intercostals (per nerve) [Maximal number of nerves 10 2-5 20-50 3-5 1-2 3-4 blocked at same time should be ≤ 8] Retrobulbar 20 4 80 1.5-2 1.5-2 2-4 Peribulbar 10 10-15 100-150 1.5-2 1.5-2 2-4 Pudendal (each side) 10 10 100 5-10 1.5-2 2-3 MAJOR NERVE BLOCK Paracervical (each side) 10 10 100 3-5 1-1.5 2-2.5 Brachial plexus: Axillary 10 40-50 400-500 15-30 1.5-2 3-4 Supraclavicular, interscalene and subclavian 10 30-40 300-400 15-30 1.5-2 3-4 perivascular Sciatic 20 15-20 300-400 15-30 2-3 3-4 3 in 1 (Femoral, obturator and lateral cutaneous) 10 30-40 300-400 15-30 1.5-2 2-4 1 Dose includes a test dose. Dosage Recommendations in Children (1 - 12 years) Conc Volume Dose Onset Duration (mg/mL) (mL/kg) (mg/kg) (min) (h) Type of block without with with Without With Without adrenaline adrenaline adrenaline adrenaline adrenaline adrenaline Caudal epidural 10 0.5 up to 0.7 5 up to 7 10-15 1-1.5 1.5-2 Consider both age and weight for calculation of dose."],["Contraindications","All grades of atrioventricular block, application to the middle ear (can cause ototoxicity), infected tissues, inflamed tissues, preparations containing preservatives should not be used for caudal, epidural, or spinal block, or for IV regional anaesthesia (Bier’s block), severe myocardial depression, damaged skin, sino-atrial disorders, Children under 3 years of age (with adrenaline)."],["Cautions","Acute porphyria (consider infusion with glucose for its anti-porphyrinogenic effects), children (consider dose reduction), congestive cardiac failure (consider lower dose), debilitated patients (consider dose reduction), elderly (consider dose reduction), epilepsy, hypovolaemia, impaired cardiac conduction, impaired respiratory function, myasthenia gravis, post cardiac surgery (consider lower dose) and shock."],["Side effects","Bradycardia (may lead to cardiac arrest), confusion, convulsions, Hypotension (may lead to cardiac arrest), respiratory depression and anaphylaxis."],["Pregnancy category","B"]],"f25":[{"i":"Lignocaine 10% w/v (50ml) 10mg/puff (for endotracheal use)","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Lignocaine 2% + Adrenaline 1 in 200,000 injection (30mL) vial","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is OT"},{"i":"Lignocaine 2% + Adrenaline 1:80,000 injection (1.8mL) (Dental cartridge)","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Lignocaine 2% gel (30g) tube","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Lignocaine 2% injection (plain) with preservative (30mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""},{"i":"Lignocaine 2% preservative free injection (50mL) vial","v":"V","l":"NRH/RRH","r":""},{"i":"Lignocaine 4% preservative free solution (5mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Lignocaine 10% w/v (50ml) 10mg/puff (for endotracheal use): now supplied down to DH"],["Specification changed in 2025","Lignocaine 10% pump spray (80mL) bottle with dispenser tube → now Lignocaine 10% w/v (50ml) 10mg/puff (for endotracheal use)"],["Specification changed in 2025","Lignocaine 4% solution (30mL) vial → now Lignocaine 4% preservative free solution (5mL) vial"]],"al":"lidocaine xylocaine"},{"k":"LIGNOCAINE + PRILOCAINE","n":"LIGNOCAINE + PRILOCAINE","g":"Local anaesthetic.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.2 Local anaesthetics","moa":"Eutectic mixture of two amide local anaesthetics; blocks Na+ channels in dermal nerve endings after topical absorption.","f":[["Indications & dose","Cannulation or Venipuncture Apply 2.5 g over 20-25 cm of skin surface area, for at least 1 hour prior to procedure. Split thickness skin graft harvesting Apply 2 g per 10 cm of skin and allow it to remain in contact with the skin for at least 2 hours. CHILD (Age 0-3 months or <5 kg) (intact skin) Apply a maximum of 1 g over no more than 10 cm of skin; leave on for no longer than 1 hour. CHILD (Age 3 months to 12 months and >5 kg) Apply no more than a maximum 2 g total over no more than 20 cm of skin; leave on for no longer than 4 hours; CHILD (Age 1-6 years and >10 kg) Apply no more than a maximum of 10 g total over no more than 100 cm of skin; leave on for no longer than 4 hours; CHILD ( Age 7-12 years and >20 kg) Apply no more than a maximum 20 g total over no more than 200 cm of skin; leave on for no longer than 4 hours."],["Cautions","Avoid use on open wounds or near the eyes."],["Side effects","Erythema, itching, rash, burning, and urticaria."]],"f25":[{"i":"Lignocaine 2.5% + Prilocaine 2.5% gel (5g) tube","v":"N","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ATROPINE SULPHATE","n":"ATROPINE SULPHATE","g":"Preoperative and intraoperative medication.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.3 Preoperative medication and sedation for short-term procedures","moa":"Competitive antagonist at muscarinic receptors; blocks vagal effects (raises heart rate, reduces secretions).","f":[["Indications & dose","Premedication by IV injection, ADULT 300-600 mcg, administer immediately before induction of anaesthesia; CHILD (12-17 years) 300-600 micrograms, administer immediately before induction of anaesthesia; By SC or IM injection, 300-600 micrograms, administer 30-60 minutes before induction of anaesthesia; CHILD (12-17 years) 300-600 micrograms, to be administer 30-60 minutes before induction of anaesthesia. Intraoperative bradycardia by IV injection, ADULT 300-600 micrograms, larger doses may be used in emergencies; CHILD (12-17 years) 300-600 micrograms, larger doses may be used in emergencies."],["Contraindications","Angle-closure glaucoma, myasthenia gravis, paralytic ileus, pyloric stenosis, prostatic enlargement."],["Cautions","Down syndrome, children, elderly, ulcerative colitis, diarrhoea, hyperthyroidism, heart failure, hypertension."],["Side effects","Dry mouth, flushing and dryness of skin, rash, difficulty in micturition, less commonly arrhythmias, tachycardia and palpitations, confusion (particularly in the elderly), heat prostration and convulsions, especially in febrile children."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Atropine sulphate 0.6mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"GLYCOPYRROLATE","n":"GLYCOPYRROLATE","g":"Preoperative medication and sedation for short-term procedure.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.3 Preoperative medication and sedation for short-term procedures","moa":"Quaternary antimuscarinic; reduces secretions and vagal bradycardia without crossing the blood-brain barrier.","f":[["Indications & dose","Reduction of nasopharyngeal secretions Preoperative by IM injection, ADULT 4 mcg/kg 30-60 minutes before procedure; CHILD (Age < 2 years) 4-9 mcg/kg 30-60 minutes before procedure; CHILD (>2 years) 4 mcg/kg 30-60 minutes before procedure; Intraoperative by IV injection, ADULT 100 mcg repeat at 2 to 3-minute intervals as needed; CHILD 4 mcg/kg not to exceed 100 mcg; Repeat at 2-to-3-minute intervals as needed. Reversal of neuromuscular blockade by IV injection, ADULT 200 mcg for each 1 mg of neostigmine or 5 mg of pyridostigmine; CHILD 5-15 mcg/kg with 25-70 mcg/kg of neostigmine or 0.1-0.3 mg/kg of pyridostigmine."],["Contraindications","Gastrointestinal obstruction, glaucoma, intestinal atony in elderly or debilitated patients, myasthenia gravis, obstructive uropathy, paralytic ileus, severe ulcerative colitis."],["Cautions","Hypertension, coronary heart disease, congestive heart failure, cardiac arrhythmia, elderly, hyperthyroidism, hepatic impairment."],["Side effects","Dry mouth, dry skin, anhidrosis, flushing, blurred vision, cycloplegia, photophobia, palpitation, xerophthalmia, constipation, urinary retention, angioedema, paradoxical bronchospasm, dysphonia. Renal Impairment No dose adjustment required."],["Hepatic impairment","No dose adjustment required."],["Pregnancy category","B"],["Breast-feeding","Excretion in breast milk unknown, use caution."],["IV fluid compatibility","Dextrose 5% in 0.45% sodium chloride, dextrose 5 %, dextrose 10%, compound sodium lactate and sodium chloride 0.9 % solutions."]],"f25":[{"i":"Glycopyrrolate 0.2mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Glycopyrrolate 0.2mg/mL injection (2mL) vial → now Glycopyrrolate 0.2mg/mL injection (1mL) ampoule"]],"al":""},{"k":"MIDAZOLAM","n":"MIDAZOLAM","g":"Preoperative medication and sedation for short-term procedure.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.3 Preoperative medication and sedation for short-term procedures","moa":"Benzodiazepine; positive allosteric modulator of GABA-A receptors (increases chloride channel opening frequency).","f":[["Indications & dose","Conscious sedation for procedures by slow IV injection, ADULT Initially 2-2.5 mg, administer 5-10 minutes before procedure at a rate of approximately 2 mg/minute, increase in the steps of 1 mg if required, usual total dose is 3.5-5 mg; MAX. 7.5 mg per course; ELDERLY Initially 0.5-1 mg, administer 5-10 minutes before procedure at a rate of approximately 2 mg/minute, increase in steps of 0.5-1 mg if required; MAX. 3.5 mg per course; CHILD (1 month-5 years) Initially 25-50 mcg/kg, administer over 2-3 minutes, 5-10 minutes before procedure, dose can be increased if necessary in small steps to MAX. 6 mg per course; CHILD (6-11 years) Initially 25-50 mcg/kg, administer over 2-3 minutes, 5-10 minutes before procedure, dose can be increased if necessary in small steps to MAX. 10 mg per course; CHILD (12-17 years) Initially 25-50 mcg/kg, administer over 2-3 minutes, 5-10 minutes before procedure, dose can be increased if necessary in small steps to MAX. 7.5 mg per course. Sedative in combined anaesthesia Initially by IV injection, ADULT 30-100 mcg/kg, repeat if necessary; Alternatively (by continuous IV infusion) 30-100 mcg/kg/hour; ELDERLY Lower doses needed. Sedation of patient receiving intensive care Initially by slow IV injection, ADULT Initially 30-300 mcg/kg in steps of 1-2.5 mg every 2 minutes, then 30-200 mcg/kg/hour, reduce dose or omit initial dose in hypovolaemia, vasoconstriction, or hypothermia; Lower doses may be adequate if opioid analgesic also used; CHILD (6 months-11 years) Initially 50-200 mcg/kg, administer over at least 3 minutes, followed by (by continuous IV infusion) 30-120 mcg/kg/hour, adjust according to response, initial dose may not be required and lower maintenance doses needed if opioid analgesics also used; Reduce dose or omit initial dose in hypovolaemia, vasoconstriction or hypothermia; CHILD (12-17 years) Initially 30-300 mcg/kg in steps of 1-2.5 mg every 2 minutes, followed by 30-200 mcg/kg/hour, adjust according to response, initial dose may not be required and lower maintenance doses needed if opioid analgesics also used; reduce dose or omit initial dose in hypovolaemia, vasoconstriction, or hypothermia; By continuous IV infusion NEONATE (up to 32 weeks corrected gestational age) 60 mcg/kg/hour for 24 hours, then reduce to 30 mcg/kg/hour, adjust according to response for maximum treatment duration of 4 days; NEONATE (32 weeks corrected gestational age and above) 60 mcg/kg/hour, adjust according to response for maximum treatment duration of 4 days; CHILD (1-5 months) 60 mcg/kg/hour, adjust according to response."],["Contraindications","CNS depression, compromised airway, severe respiratory depression."],["Cautions","Cardiac disease, children (particularly if cardiovascular impairment), concentration in children under 15 kg not to exceed 1 mg/mL, debilitated patients, hypothermia, hypovolaemia, neonates, risk of airways obstruction and hypoventilation in children under 6 months, vasoconstriction."],["Side effects","Amnesia, anaphylaxis, ataxia, blood disorders, bronchospasm, cardiac arrest, confusion, convulsions (more common in neonates), depression of consciousness, dizziness, drowsiness, dry mouth, dysarthria, euphoria, fatigue, gastro-intestinal disturbances, hallucinations, headache, heart rate changes, hiccups, hypotension, incontinence, increased appetite, injection-site reactions. involuntary movements, jaundice, laryngospasm, muscle weakness, paradoxical aggression, paradoxical excitement, respiratory arrest (particularly with high doses or on rapid injection), respiratory depression (may be severe with sedative and perioperative use), respiratory depression (particularly with high doses or on rapid injection), restlessness (with sedative and perioperative use); salivation changes, severe disinhibition (with sedative and perioperative use), skin reactions, thrombosis, urinary retention, vertigo, visual disturbances."],["Renal impairment","Use with caution in chronic renal failure."],["Hepatic impairment","Use with caution particularly."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, avoid breast-feeding for 24 hours after administration."],["Counselling","The dangers of taking alcohol should be emphasised."]],"f25":[{"i":"Midazolam 1mg/mL injection (10mL) vial","v":"V","l":"NRH/RRH/DH","r":"Supplied to DH where there is OT and ICU"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Midazolam 1mg/mL injection (10mL) vial: now supplied down to DH"]],"al":""},{"k":"MORPHINE","n":"MORPHINE","g":"Preoperative medication and sedation for short-term procedure.","sec":"1. ANAESTHETICS, PREOPERATIVE MEDICINES AND MEDICAL GASES","sub":"1.3 Preoperative medication and sedation for short-term procedures","moa":"Mu-opioid receptor agonist; inhibits adenylyl cyclase, opens K+ and closes Ca2+ channels, reducing nociceptive transmission.","f":[["Indications & dose","Preoperative medication ADULT: 10 mg SubQ or IM inj. 60 to 90 minutes before surgery; CHILD, by subcutaneous injection, (neonates): 100 mcg/kg every 6 hours; CHILD (1 to 6 months): 100 to 200 mcg/kg every 6 hours; CHILD (6 months to 2 years): 100 to 200 mcg/kg every 4 hours; CHILD (2 to 12 years): 200 mcg/kg every 4 hours; CHILD (12 to 18 years): 2.5 to 10 mg every 4 hours; CHILD, by intravenous injection over at least 5 minutes, (neonates): 50 mcg/kg every 6 hours; CHILD (1 to 6 months): 100 mcg/kg every 6 hours; CHILD (6 months to 12 years): 100 mcg/kg every 4 hours; CHILD (12 to 18 years): 5 mg every 4 hours. For details, refer to page no. 21"]],"f25":[{"i":"Morphine 10mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Morphine 15mg extended release tablet","v":"E","l":"NRH/RRH","r":""},{"i":"Morphine 10mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ASPIRIN","n":"ASPIRIN","g":"Non-steroidal Anti-inflammatory Medicines (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"Irreversibly acetylates COX-1 and COX-2, reducing prostaglandins (analgesic, anti-inflammatory) and platelet thromboxane A2.","f":[["Indications & dose","Osteoarthritis and rheumatoid arthritis 300 mg PO three to four times daily, MAX. 4 g daily; Not recommended in children below 16 years."],["Contraindications","Hypersensitivity to aspirin or other NSAIMs, use other than as an antiplatelet in children and adolescents under 16 years (Reye’s syndrome), active peptic ulceration, haemophilia, other bleeding disorders."],["Cautions","Asthma, uncontrolled hypertension, pregnancy, breastfeeding."],["Side effects","Bronchospasm, gastrointestinal haemorrhage, vomiting, upset stomach, heartburn, drowsiness, or headache."],["Counselling","To be taken after or with meals."]],"f25":[{"i":"Aspirin 300mg (Effervescent) tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Aspirin 75mg enteric coated tablet","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Aspirin 300mg (soluble) tablet → now Aspirin 300mg (Effervescent) tablet"]],"al":""},{"k":"DICLOFENAC SODIUM","n":"DICLOFENAC SODIUM","g":"Non-steroidal Anti-inflammatory Medicines (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"NSAID; reversible COX-1/COX-2 inhibitor (relatively COX-2 preferring), reducing prostaglandin synthesis.","f":[["Indications & dose","Acute exacerbations of pain and postoperative pain by deep IM injection, ADULT 75 mg once daily for maximum 2 days, administer into the gluteal muscle. Acute exacerbations of pain and postoperative pain (severe cases) by deep IM injection, ADULT 75 mg twice daily for maximum 2 days, administered into the gluteal muscle. Ureteric colic by deep IM injection, ADULT 75 mg, then 75 mg after 30 minutes if required. Acute postoperative pain (in supervised settings) by IV injection, ADULT 75 mg every 4-6 hours if required for maximum 2 days; MAX. 150 mg per day. Prevention of postoperative pain by IV injection, ADULT 25-50 mg, give after surgery; further doses given after 4-6 hours if necessary; MAX.150 mg in 24 hours for 2 days."],["Contraindications","Patients with a history of hypersensitivity to aspirin or any other NSAID-which includes those in whom attacks of asthma, angioedema, urticaria or rhinitis have been precipitated by aspirin or any other NSAID, history of asthma, confirmed or suspected cerebrovascular bleeding and haemorrhagic diathesis, active GI bleeding and ulceration, cerebrovascular disease, ischaemic heart disease, mild to severe heart failure, peripheral arterial disease."],["Cautions","Allergic disorders, cardiac impairment (NSAIDs may impair renal function), coagulation defects, connective-tissue disorders, Crohn’s disease (may be exacerbated), elderly (risk of serious side-effects and fatalities), history of cardiac failure, hypertension, left ventricular dysfunction, oedema, risk factors for cardiovascular events, ulcerative colitis (may be exacerbated)."],["Side effects","Alveolitis, aseptic meningitis (patients with connective-tissue disorders such as systemic lupus erythematosus may be especially susceptible), hepatic damage, interstitial fibrosis associated with NSAIDs can lead to renal failure, pancreatitis, papillary necrosis associated with NSAIDs can lead to renal failure, pulmonary eosinophilia, Stevens-Johnson syndrome, toxic epidermal necrolysis, visual disturbances, injection site reactions."],["Renal impairment","Avoid if possible or use with caution; the lowest effective dose should be used for the shortest possible duration. Avoid IV use if serum creatinine is greater than 160 micromol/litre. Not recommended in moderate or severe renal impairment."],["Hepatic impairment","Use with caution; Avoid in severe liver disease."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Diclofenac sodium 25mg/mL for both IM and IV injection (3mL) ampoule","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"IBUPROFEN","n":"IBUPROFEN","g":"Non-steroidal Anti-inflammatory Medicines (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"NSAID; reversible non-selective COX-1/COX-2 inhibitor, reducing prostaglandin synthesis.","f":[["Indications & dose","Pain and inflammation in rheumatic disease and other musculoskeletal disorders, Mild to moderate pain including dysmenorrhoea, Postoperative analgesia, and Migraine and Dental pain ADULT Initially 400 mg PO, 3 times a day; increase if necessary up to 600 mg 4 times a day; Maintenance 400 mg 3 times a day. Mild to moderate pain, Pain and inflammation of soft tissue injuries and Pyrexia with discomfort CHILD (3-5 months) 50 mg PO, 3 times a day; CHILD (6-11 months) 50 mg PO, 3-4 times a day; CHILD (1-3 years) 100 mg PO, 3 times a day; CHILD (4-6 years) 150 mg PO, 3 times a day; CHILD (7-9 years) 200 mg PO, 3 times a day; CHILD (10-11 years) 300 mg PO, 3 times a day; CHILD (12-17 years) Initially 300-400 mg PO, 3-4 times a day; increased if necessary up to 600 mg 4 times a day; maintenance 200–400 mg 3 times a day. For CHILD, maximum daily dose to be given in 3-4 divided doses; for 3 months-6 years, maximum 30 mg/kg per day and for 7-9 years, maximum 2.4 g per day."],["Contraindications","Active GI bleeding and ulceration, history of GI bleeding and perforation related to previous NSAID therapy, history of recurrent GI haemorrhage and ulceration (two or more distinct episodes), established ischaemic heart disease, peripheral arterial disease, cerebrovascular disease, congestive heart failure and uncontrolled hypertension."],["Cautions","Cardiac impairment; cerebrovascular disease, coagulation defects, connective-tissue disorders, Crohn’s disease, heart failure, ischaemic heart disease, peripheral arterial disease, risk factors for cardiovascular events, risk factors for cardiovascular events, ulcerative colitis, uncontrolled hypertension."],["Side effects","Dizziness, epigastric pain, heartburn, constipation, nausea, rash, tinnitus, oedema, headache, vomiting."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Take after/with food or water to avoid GI effects."]],"f25":[{"i":"Ibuprofen 400mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"INDOMETHACIN","n":"INDOMETHACIN","g":"Non-steroidal Anti-inflammatory Medicines (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"Potent non-selective COX inhibitor; also used to close patent ductus arteriosus.","f":[["Indications & dose","Ankylosing spondylitis; Osteoarthritis and Rheumatoid arthritis ADULT and CHILD (> 15 years) Initial, 25 mg PO, 2 to 3 times daily; increase daily dosage by 25 to 50 mg at weekly intervals if necessary, until satisfactory pain control to total daily dosage of 150 to 200 mg, MAX. 100 mg/dose or 200 mg/day; For patients with persistent night pain or morning stiffness, 100 mg of the total daily dose may be administered at bedtime. Acute gout ADULT and CHILD (> 15 years) Initial, 50 mg PO 3 times daily until pain is tolerable; rapidly taper based on pain response to discontinuation. Acute shoulder pain ADULT and CHILD (> 15 years) 75 to 150 mg PO, 3 to 4 divided doses for 7 to 14 days."],["Contraindications","Active GI bleeding and ulceration, history of GI bleeding and perforation related to previous NSAID therapy, history of recurrent GI haemorrhage and ulceration (two or more distinct episodes), established ischaemic heart disease, peripheral arterial disease, cerebrovascular disease, congestive heart failure and uncontrolled hypertension."],["Cautions","Cardiac impairment; cerebrovascular disease, coagulation defects, connective-tissue disorders, Crohn’s disease, heart failure, ischaemic heart disease, peripheral arterial disease, risk factors for cardiovascular events, risk factors for cardiovascular events, ulcerative colitis, uncontrolled hypertension."],["Side effects","Dizziness, epigastric pain, heartburn, constipation, nausea, rash, tinnitus, oedema, headache, vomiting."],["Renal impairment","Avoid in severe impairment. The lowest effective dose should be used for the shortest possible duration."],["Hepatic impairment","Use with caution, avoid in severe liver disease."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Take with/after food."]],"f25":[{"i":"Indomethacin 25mg capsule","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"MEFENAMIC ACID","n":"MEFENAMIC ACID","g":"Nonsteroidal anti-inflammatory medicines (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"Fenamate NSAID; inhibits COX and may antagonise prostaglandin receptors, useful in dysmenorrhoea.","f":[["Indications & dose","Acute pain in dysmenorrhoea and menorrhagia ADULT 500 mg PO, 3 times a day; CHILD (12-17 years) 500 mg PO, 3 times a day."],["Contraindications","Active GI bleeding and ulceration, history of GI bleeding and perforation related to previous NSAIMs therapy, history of recurrent GI haemorrhage and ulceration (two or more distinct episodes), inflammatory bowel disease, severe heart failure."],["Cautions","Acute porphyrias, allergic disorders, cardiac impairment, cerebrovascular disease, coagulation defects, connective tissue disorders, Crohn’s disease, elderly, epilepsy, heart failure, ischaemic heart disease, peripheral arterial disease, ulcerative colitis, uncontrolled hypertension."],["Side effects","Diarrhoea, rashes, stomatitis, fatigue, and paraesthesia."],["Renal impairment","Avoid in severe impairment. Use the lowest effective dose for the shortest possible duration."],["Hepatic impairment","Use with caution, there is an increased risk of GI bleeding and fluid retention. Avoid in severe liver disease."],["Pregnancy category","C"],["Breast-feeding","Amount too small to be harmful."],["Counselling","Take with or after food."]],"f25":[{"i":"Mefenamic acid 500mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Mefenamic acid 500mg tablet: now supplied down to DH"],["Specification changed in 2025","Mefenamic acid 250mg tablet → now Mefenamic acid 500mg tablet"]],"al":""},{"k":"PARACETAMOL","n":"PARACETAMOL","g":"Non-steroidal Anti-inflammatory Medicines (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"Central COX inhibition (weak peripheral effect) plus serotonergic and cannabinoid pathways; analgesic and antipyretic, not anti-inflammatory.","f":[["Indications & dose","Mild to moderate pain and pyrexia ADULT 0.5-1 g, PO every 4-6 hours; MAX. 4 g per day; ADULT (body weight 10-50 kg) 15 mg/kg by IV injection, every 4-6 hours, dose to be administered over 15 minutes; MAX. 60 mg/kg per day; ADULT (body weight 50 kg and above) 1 g by IV injection, every 4-6 hours, dose to be administered over 15 minutes; MAX. 4 g per day; ADULT: 0.5-1 g By rectum, every 4-6 hours; MAX. 4 g per day. Mild to moderate pain in patients with risk factors for hepatotoxicity ADULT (body weight 50 kg and above) 1 g by IV infusion, every 4-6 hours, dose to be administered over 15 minutes; MAX. 3 g per day. Pain and Pyrexia with discomfort NEONATE (28 - 32 weeks) corrected gestational age 20 mg/kg PO for 1 dose, then 10-15 mg/kg every 8-12 hours as required, maximum daily dose to be given in divided doses; MAX. 30 mg/kg per day; NEONATE (32 weeks corrected gestational age and above) 20 mg/kg for 1 dose, then 10-15 mg/kg every 6-8 hours as required, maximum daily dose to be given in divided doses; MAX. 60 mg/kg per day; CHILD (3-5 months) 60 mg every 4-6 hours; max. 4 doses per day; CHILD (6 months-1 year) 120 mg every 4-6 hours; MAX. 4 doses per day; CHILD (2-3 years) 180 mg every 4-6 hours; MAX. 4 doses per day; CHILD (4-5 years) 240 mg every 4-6 hours, MAX. 4 doses per day; CHILD (6-7 years) 240-250mg every 4-6 hours, MAX. 4 doses per day; CHILD (8-9 years) 360-375 mg every 4-6 hours, MAX. 4 doses per day; CHILD (10-11 years): 480-500 mg every 4-6 hours, MAX. 4 doses per day; CHILD (12-15 years) 480-750 mg every 4-6 hours, MAX. 4 doses per day; CHILD (16-17 years) 0.5-1 g every 4-6 hours, MAX. 4 doses per day; By rectum, CHILD (3-11 months) 60-125 mg every 4-6 hours as required, MAX. 4 doses per day; CHILD (1-4 years) 125-250 mg every 4-6 hours as required; MAX. 4 doses per day; CHILD (Child 5-11 years) 250-500mg every 4-6 hours as required, MAX. 4 doses per day; CHILD (12-17 years) 500mg every 4-6 hours. Post-immunisation pyrexia in infants CHILD (2 months) 60 mg for 1 dose PO, then 60 mg after 4-6 hours if required."],["Contraindications","Severe hepatic failure."],["Cautions","Alcohol dependence; before administering, check when paracetamol last administered and cumulative paracetamol dose over the previous 24 hours. Chronic alcoholism, chronic dehydration, chronic malnutrition hepatocellular insufficiency."],["Side effects","Acute generalised exanthematous pustulosis, malaise, skin reactions, Stevens-Johnson syndrome, toxic epidermal necrolysis; With IV use: flushing, tachycardia. Overdose Single ingestion of more than 150mg/kg in less than one hour or children who have ingested more than 10-15 g in single ingestion in less than one hour may result in severe liver damage, hypoglycemia and acute renal tubular necrosis."],["Renal impairment","Increase infusion dose interval to every 6 hours in severe renal impairment (CrCl ≤ 30 mL/min)."],["Hepatic impairment","Dose-related toxicity, avoid large doses."],["Pregnancy category","B"],["Breast-feeding","Amount too small to be harmful."]],"f25":[{"i":"Paracetamol 250mg/5ml syrup (60mL) bottle","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Paracetamol 150mg/mL for both IM and IV injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Paracetamol 250mg suppository","v":"N","l":"NRH/RRH/DH","r":""},{"i":"Paracetamol 500mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"pcm acetaminophen"},{"k":"PIROXICAM","n":"PIROXICAM","g":"Non-opioid analgesic, Nonsteroidal Inflammatory Medicine (NSAIMs).","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.1 Non-opioids & Nonsteroidal Anti-inflammatory Medicines (NSAIMs)","moa":"Oxicam NSAID; long half-life non-selective COX inhibitor.","f":[["Indications & dose","Rheumatoid arthritis and osteoarthritis ADULT 20 mg once a day. Ankylosing spondylitis ADULT 10-20 mg/day in 1 to 2 divided doses. Juvenile idiopathic arthritis CHILD 0.2 - 0.4 mg/kg per day, MAX. dose 20 mg once daily."],["Contraindications","Asthma, urticaria, or allergic type reaction to aspirin or NSAIMs. Active or history of gastro-intestinal bleeding. Coronary artery bypass surgery (CABG). Third trimester pregnancy."],["Cautions","History of gastro-intestinal disorders, ischemic heart disease, risk of cardiovascular events, coagulation defects, connective tissue disorder, uncontrolled hypertension, cerebrovascular disease, hyperkalaemia."],["Side effects","Skin rash, oedema, blurring of vision, dizziness, drowsiness, constipation, vomiting, nausea, headache, abdominal pain, bronchospasm, anorexia, eosinophilia, fatigue, anaemia, hyponatremia, leukopenia, thrombocytopenia, abnormal renal function, tinnitus, hyperkalaemia, hyponatremia, increased liver function test, heart failure, myocardial infarction."],["Renal impairment","If eGFR 30 - 60 mL/min, temporarily discontinue to avoid acute kidney injury. If eGFR <30 mL/min, avoid."],["Hepatic impairment","Use with caution, with low dose as possible. In advanced liver disease or hepatotoxicity during treatment, discontinue the use of piroxicam."],["Pregnancy category","C"],["Breast-feeding","Use with caution, amount too small to be harmful. However, if the infant has platelet dysfunction, thrombocytopenia, or a ductal-dependent cardiac lesion maternal use of piroxicam should be avoided."],["Counselling","Take with/after food. Advise patients to immediately report if they develop signs of congestive heart failure, myocardial infarction, cardiovascular events or stroke, GI irritation. Avoid use in third trimester pregnancy, renal and hepatic failure. Instruct patients to report symptoms of skin rashes."]],"f25":[{"i":"Piroxicam 20mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CODEINE PHOSPHATE","n":"CODEINE PHOSPHATE","g":"Opioid analgesic.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.2 Opioid analgesics","moa":"Prodrug; CYP2D6 converts it to morphine, which acts at mu-opioid receptors. Also suppresses the medullary cough centre and slows gut motility.","f":[["Indications & dose","Acute diarrhoea ADULT 30 mg PO 3-4 times a day, usual dose 15-60 mg 3-4 times a day; CHILD (12-17 years) 30 mg 3-4 times a day, usual dose 15-60 mg 3-4 times a day. Mild to moderate pain ADULT 30-60 mg every 4 hours if required; MAX. 240 mg per day. Short-term treatment of acute moderate pain CHILD (12-17 years) 30-60 mg every 6 hours if required for maximum 3 days; MAX. 240 mg per day. Dry or painful cough ADULT: 15-30 mg 3-4 times a day."],["Contraindications","Acute ulcerative colitis, antibiotic associated colitis, children under 12, children under 18 years who undergo the removal of tonsils or adenoids, conditions where abdominal distension develops, conditions where inhibition of peristalsis, known ultra-rapid codeine metabolizers, breast-feeding."],["Cautions","Cardiac arrhythmias, gallstones."],["Side effects","Abdominal pain, anorexia, antidiuretic effect, hypothermia, malaise, muscle fasciculation, pancreatitis, seizures."],["Renal impairment","Avoid use or reduce dose."],["Pregnancy category","C"],["Breast-feeding","Avoid."],["Note","Tolerance and dependence may occur with prolonged use; In terminal care, this should not inhibit treatment, but simultaneous administration of laxative medicines may be required; chronic diarrhoea should be investigated before any attempt to suppress it with codeine phosphate. Should not drive or operate machinery. Do not use codeine in children under 12 years and breast-feeding mothers. Codeine is not recommended for adolescents (12-18 years) who have problems with breathing."]],"f25":[{"i":"Codeine phosphate 15mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FENTANYL CITRATE","n":"FENTANYL CITRATE","g":"Opioid analgesic.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.2 Opioid analgesics","moa":"Highly potent, lipophilic mu-opioid agonist with rapid onset.","f":[["Indications & dose","Chronic intractable pain by transdermal application ADULT Initially 50 -100 mcg/hour every 72 hours. Spontaneous respiration for Analgesia and enhancement of anaesthesia during operation by slow IV injection, ADULT Initially 50-100 mcg (MAX. dose 200 mcg), then 25-50 mcg as required; By IV infusion, ADULT 3-4.8 mcg/kg/hour, adjust according to response; CHILD (1 month-11 years) Initially 1-3 mcg/kg, then 1 mcg/kg as required, administer over at least 30 seconds; CHILD (12-17 years) Initially 50-100 mcg (MAX. dose 200 mcg), then 25-50 mcg as required, administered over at least 30 seconds. Assisted ventilation for Analgesia and enhancement of anaesthesia during operation by slow IV injection, ADULT Initially 300-3500 mcg, then 100-200 mcg as required; By IV infusion, Initially 10 mcg/kg, given over 10 minutes, then 6 mcg/kg/hour, adjust according to response, may require up to 180 mcg/kg/hour during cardiac surgery; NEONATE Initially 1-5 mcg/kg, then 1-3 mcg/kg administer over at least 30 seconds; CHILD (1 month-11 years) Initially 1-5 mcg/kg, then 1-3 mcg/kg administer over at least 30 seconds; CHILD (12-17 years) Initially 1-5 mcg/kg, then 50-200 mcg administer over at least 30 seconds. Assisted ventilation for analgesia and respiratory depression in intensive care By slow IV injection, ADULT Initially 300-3500 mcg, then 100-200 mcg as required; By IV infusion, ADULT Initially 10 mcg/kg, administer over 10 minutes, then 6 mcg/kg/hour, adjust according to response, may require up to 180 mcg/kg/hour during cardiac surgery; NEONATE Initially 1-5 mcg/kg, then (by IV infusion) 1.5 mcg/kg/hour, adjust according to response; CHILD Initially 1-5 mcg/kg, then (by IV infusion) 1-6 mcg/kg/hour, adjust according to response."],["Contraindications","Known or suspected GI obstruction, significant respiratory depression, acute or severe bronchial asthma."],["Cautions","Cerebral tumour, impaired consciousness; With transdermal patch: not suitable for acute pain or in those patients whose analgesic requirements are changing rapidly; With intravenous: repeated intra-operative doses should be given with care."],["Side effects","Abdominal pain, asthenia, anorexia, anxiety, appetite changes, application-site reactions, diarrhoea, dyspepsia, dyspnoea, gastroesophageal reflux disease, hypertension, myoclonus, paraesthesia, pharyngitis, rhinitis, stomatitis, tremor, vasodilation, myoclonic movements, laryngospasm, asystole, insomnia."],["Renal impairment","Avoid use or reduce dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["Note","For patches, apply to dry, non-irritated, non-irradiated and non-hairy skin on torso or upper arm. Remove after 72 hours and siting replacement patch on a different area (avoid using the same area for several days). Patches should be removed immediately in case of breathing difficulties, marked drowsiness, confusion, dizziness, or impaired speech, and seek prompt medical attention."]],"f25":[{"i":"Fentanyl citrate transdermal patch 25 mcg/hr (72 hr)","v":"E","l":"NRH/RRH","r":""},{"i":"Fentanyl citrate 50µg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Fentanyl Patch 50mcg/hr → now Fentanyl transdermal patch 25 mcg/hr"]],"al":""},{"k":"PETHIDINE","n":"PETHIDINE","g":"Opioid analgesic.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.2 Opioid analgesics","moa":"Synthetic mu-opioid agonist; metabolite norpethidine is neurotoxic (seizures) with repeated doses.","f":[["Indications & dose","Acute pain by SC or IM injection, ADULT 25-100 mg, then 25-100 mg after 4 hours, for debilitated patients use elderly dose; ELDERLY Initially 25 mg, then 25-100 mg after 4 hours; By slow IV injection, ADULT 25-50 mg, then 25-50 mg after 4 hours, for debilitated patients use elderly dose; ELDERLY Initially 25 mg, then 25-50 mg after 4 hours. Obstetric analgesia by SC or IM injection, ADULT 50-100 mg, then 50-100 mg after 1-3 hours if required; MAX. 400 mg per day. Premedication by IM injection, ADULT 25-100 mg, 1 hour before operation, for debilitated patients use elderly dose; ELDERLY 25 mg, 1 hour before operation. Postoperative pain by SC or IM injection, ADULT 25-100 mg every 2-3 hours if required, for debilitated patients use elderly dose; ELDERLY Initially 25 mg every 2-3 hours if required."],["Contraindications","Pheochromocytoma."],["Cautions","Accumulation of metabolites may result in neurotoxicity, cardiac arrhythmias; not suitable for severe continuing pain, severe cor pulmonale."],["Side effects","Hypothermia, restlessness, tremor."],["Renal impairment","Avoid use or reduce dose."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk but not known to be harmful."]],"f25":[{"i":"Pethidine 50mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"TRAMADOL HYDROCHLORIDE","n":"TRAMADOL HYDROCHLORIDE","g":"Opioid analgesic.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.2 Opioid analgesics","moa":"Weak mu-opioid agonist (mainly via its metabolite) plus serotonin and noradrenaline reuptake inhibition.","f":[["Indications & dose","Moderate to severe pain by IM or IV infusion, ADULT 50-100 mg every 4-6 hours, IV injection to be given over 2-3 minutes; CHILD (12-17 years) 50-100 mg every 4-6 hours, IV injection to be given over 2-3 minutes. Postoperative pain by IV injection, ADULT Initially 100 mg, then 50mg every 10-20 minutes, if required up to total maximum 250 mg (including initial dose) in first hour, then 50-100mg every 4-6 hours, given over 2-3 minutes; MAX. 600 mg per day; CHILD (12-17 years) Initially 100 mg, then 50 mg every 10-20 minutes if required up to total maximum 250 mg (including initial dose) in first hour, then 50-100 mg every 4-6 hours, given over 2-3 minutes; MAX. 600 mg per day."],["Contraindications","Children younger than 12 years, postoperative management in children younger than 18 years of age following tonsillectomy and/or adenoidectomy, significant respiratory depression, acute or severe bronchial asthma, in unmonitored settings or without resuscitative equipment, known or suspected gastrointestinal obstruction, including paralytic ileus, hypersensitivity to opioids, concurrent use of MAOIs or use within the last 14 days."],["Cautions","Excessive bronchial secretions, history of epilepsy-use tramadol only if compelling reasons, impaired consciousness, not suitable as a substitute in opioid-dependent patients, not suitable in some types of general anaesthesia, susceptibility to seizures-use tramadol only if compelling reasons."],["Side effects","Flushing, pruritus, constipation, nausea, vomiting, xerostomia, dizziness, headache, insomnia, somnolence."],["Renal impairment","Avoid use or reduce dose."],["Hepatic impairment","Caution in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Avoid."]],"f25":[{"i":"Tramadol 50mg/mL injection (1mL) ampoule","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"AMITRIPTYLINE","n":"AMITRIPTYLINE","g":"Medicines used for neuropathic pain.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.3 Medicines used in neuropathic pain","moa":"Tricyclic; inhibits serotonin and noradrenaline reuptake, enhancing descending pain inhibition. Also anticholinergic, antihistaminic and alpha-blocking.","f":[["Indications & dose","neuropathic pain 12.5-25 mg daily at bedtime; MAX. 100 mg daily. For details, refer to page no. 145."]],"f25":[{"i":"Amitriptyline 25mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CARBAMAZEPINE","n":"CARBAMAZEPINE","g":"Medicines used for neuropathic pain.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.3 Medicines used in neuropathic pain","moa":"Blocks voltage-gated Na+ channels (stabilises the inactive state), reducing repetitive neuronal firing.","f":[["Indications & dose","Trigeminal neuralgia ADULT Initially 100 mg PO, Q24H to Q12H, increased gradually according to response, increased if necessary up to 1.6 g daily in 3 to 4 divided doses. For detail, refer to page no. 30."]],"f25":[{"i":"Carbamazepine 200mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"GABAPENTIN","n":"GABAPENTIN","g":"Medicines used for neuropathic pain.","sec":"2. MEDICINES FOR PAIN AND PALLIATIVE CARE","sub":"2.3 Medicines used in neuropathic pain","moa":"Binds the alpha-2-delta subunit of voltage-gated Ca2+ channels, reducing excitatory neurotransmitter release.","f":[["Indications & dose","Fibromyalgia ADULT: Initial, 300 mg orally once daily at bedtime; titrate over 6 weeks to a maximum of 2400 mg/day, given as 600 mg twice daily and 1200 mg at bedtime. Neuropathy due to diabetes mellitus ADULT: 1200 to 3600 mg/day orally in 3 divided doses. Postherpetic neuralgia ADULT: 300 mg orally on day 1, increase to 300 mg twice a day on day 2 and to 300 mg 3 times a day on day 3; may increase up to 1800 mg/day (divided into 3 doses). Postoperative pain (Acute), pre-emptive therapy ADULT: 300 to 1200 mg orally as 1 dose administered 1 to 2 hours prior to surgery. Trigeminal neuralgia ADULT: up to 3600 mg orally per day has been used."],["Cautions","History of psychosis, renal impairment, elderly, pregnancy and breastfeeding, diabetes mellitus, avoid abrupt withdrawal."],["Counselling","Take consistently at the same time of the day; continue until advised to stop."]],"f25":[{"i":"Gabapentin 300mg capsule","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Gabapentin 300mg capsule: now supplied down to DH"]],"al":""},{"k":"ADRENALINE","n":"ADRENALINE","g":"Antiallergics and medicines used in anaphylaxis.","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"Alpha and beta agonist. Alpha-1 vasoconstriction raises BP and reduces oedema; beta-1 increases cardiac output; beta-2 bronchodilates and stabilises mast cells.","f":[["Indications & dose","Anaphylaxis, By IM injection, as given below: Age Volume < 1 - year 0.05 mL 2 years 0.2 mL 3 - 4 years 0.3 mL 5 years 0.4 mL 6 - 12 years 0.5 mL ADULT 0.5 - 1.0 mL Doses may be repeated every 10 minutes, according to blood pressure and pulse, until improvement occurs (may be repeated several times). Asthma by IM injection, ADULT 0.1-0.5 mg, IM, Q15-20 minute intervals as required; CHILD 0.01 mg/kg, SC, Q4H if required to a maximum of 0.5 mg. Cardiac arrest ADULT 0.1-0.5 mcg/kg/min, IV; CHILD 0.1-1 mcg/kg/min, IV and titrate to response."],["Cautions","Hyperthyroidism, diabetes mellitus, heart disease, hypertension, arrhythmias, cerebrovascular disease, angle-closure glaucoma, second stage of labour, elderly patients."],["Side effects","Anxiety, tremor, tachycardia, arrhythmias, headache, cold extremities, hypertension (risk of cerebral haemorrhage) and pulmonary oedema (on excessive dosage or extreme sensitivity), nausea, vomiting, sweating, weakness, dizziness, hyperglycaemia. Over dosage Sudden extreme hypertension may lead to cerebral haemorrhage, reversal by vasodilatation with isosorbide dinitrate may be attempted."],["Renal impairment","Use with caution in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown: Use with caution."],["IV fluid compatibility","Dextrose 5%, dextrose 10%, compound sodium lactate solution, sodium chloride 0.9% and dextrose 5% in sodium chloride 0.45%."]],"f25":[{"i":"Adrenaline 1mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"epinephrine"},{"k":"CETIRIZINE","n":"CETIRIZINE","g":"Antiallergic and medicine used in anaphylaxis.","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"Second-generation, peripherally selective H1-receptor inverse agonist; minimal sedation.","f":[["Indications & dose","Symptomatic relief of allergy such as hay fever, urticaria ADULT and CHILD (over 12 years) 10 mg PO, Q24H; CHILD (6-11 years) 5 mg, PO Q12H; CHILD (2-5 years) 2.5 mg, PO, Q12H."],["Contraindications","Acute porphyrias."],["Cautions","Epilepsy."],["Side effects","Blurred vision, dry mouth, GI disturbances, headache, psychomotor impairment, urinary retention."],["Pregnancy category","B"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","May cause drowsiness, do not drive or operate machinery and avoid alcohol."]],"f25":[{"i":"Cetirizine 10mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"DEXAMETHASONE","n":"DEXAMETHASONE","g":"Antiallergic and medicine used in anaphylaxis.","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"Potent long-acting glucocorticoid; binds the cytoplasmic glucocorticoid receptor and alters gene transcription (anti-inflammatory, immunosuppressive). Negligible mineralocorticoid effect.","f":[["Indications & dose","Allergic conditions and inflammation ADULT 1-4 mg PO, Q12H to Q8H daily; CHILD 0.5-2 mg/kg PO, Q12H to Q8H daily. Cerebral oedema ADULT 10 mg IV stat, then 4 mg IM, Q6H until clinical improvement; Shock ADULT 20 mg IV, then 3 mg/kg/day by continuous IV infusion. Multiple Sclerosis ADULT 30 mg/day PO x 1 week, followed by 4-12 mg/day x 1 month. Contraindicated Systemic fungal infections; cerebral malaria; administration of live vaccines."],["Cautions","Prolonged use of steroids increases susceptibility to infections and severity of infections."],["Side effects","Hypertension, cataract, raised intraocular pressure, corneal oedema, depression, euphoria, cardiomyopathy, hyperglycaemia."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["IV fluid compatibility","Dextrose 5% and sodium chloride 0.9%."]],"f25":[{"i":"Dexamethasone 4mg tablet","v":"E","l":"NRH/RRH","r":""},{"i":"Dexamethasone 4mg/mL injection (2mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"HYDROCORTISONE SODIUM SUCCINATE","n":"HYDROCORTISONE SODIUM SUCCINATE","g":"Antiallergic and medicine used in anaphylaxis.","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"Glucocorticoid with mineralocorticoid activity; intracellular receptor-mediated anti-inflammatory and immunosuppressive effects.","f":[["Indications & dose","Acute hypersensitivity reactions such as angioedema of the upper respiratory tract and anaphylaxis (adjunct to adrenaline) ADULT 100-300 mg, IV injection. Acute hypersensitivity reactions and Angioedema CHILD (1-5 months) Initially 25 mg IM or IV injection, Q8H, adjusted according to response; CHILD (1-5 months) Initially 25 mg IM or IV injection, Q8H, adjusted according to response; CHILD (6 months-5 years) Initially 50 mg IM or IV injection, Q8H adjusted according to response; CHILD (6-11 years) Initially 100 mg IM or Iv injection, Q8H, adjusted according to response; CHILD (12-17 years) Initially 200 mg IM or IV injection, Q8H adjusted according to response. For details, refer to page no. 69"]],"f25":[{"i":"Hydrocortisone sodium succinate 100mg/mL injection (2mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PREDNISOLONE","n":"PREDNISOLONE","g":"Antiallergic and medicine used in anaphylaxis.","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"Intermediate-acting glucocorticoid; receptor-mediated suppression of inflammatory gene transcription.","f":[["Indications & dose","Suppression of inflammatory and allergic disorders, Inflammatory bowel disease, Asthma, Immuno-suppression, Rheumatic disease and Nephrotic syndrome ADULT 10-20 mg PO, Q24H daily, may increase to 1 mg/kg (up to 60 mg daily in severe disease), preferably taken in the morning after breakfast; Maintenance 2.5-15 mg PO, Q24H; CHILD: 1-2 mg/kg PO (max 60 mg). Multiple sclerosis ADULT 200 mg PO, Q24H x 1 week, then 80 mg Q24H alternate days x 1 month. Acute exacerbation of COPD ADULT 30-40 mg PO, Q24H x 7-14 days."],["Contraindications","Systemic fungal infections, varicella, superficial herpes simplex keratitis, administration of live or attenuated virus vaccines."],["Cautions","Cirrhosis, diabetes, ocular herpes simplex, hypertension, thyroid disease, seizure disorders, hypothyroidism, myasthenia gravis, hepatic impairment, peptic ulcer disease, osteoporosis, ulcerative colitis, untreated systemic infections, renal insufficiency, pregnancy."],["Side effects","Acne, adrenal suppression, delayed wound healing, diabetes mellitus, GI perforation, glucose intolerance, hepatomegaly, insomnia, menstrual irregularity, myopathy, osteoporosis, peptic ulcer."],["Renal impairment","Use with caution; fluid retention may occur."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, use with caution."],["Note","In acute asthma, tail off steroids within 7-10 days to avoid adrenal suppression."],["Counselling","To be taken after or with meals."]],"f25":[{"i":"Prednisolone 20mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Prednisolone 5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PROMETHAZINE","n":"PROMETHAZINE","g":"Antiallergic (sedating antihistamines).","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"First-generation phenothiazine H1 antagonist; sedative, antiemetic and anticholinergic.","f":[["Indications & dose","Allergic conditions ADULT 10-20 mg PO, Q12H to Q8H; 25-50 mg, deep IM (MAX. per dose 100 mg); CHILD 1 mg/kg/day PO, in divided doses; CHILD (2-4 years) 5 mg PO, Q12H, alternately 5-15 mg PO, Q24H at night; CHILD (5-9 years) 5-10 mg PO, Q12H, alternatively 10-25 mg PO, Q24H at night; CHILD (10-17 years): 10-20 mg PO, Q12H-Q8H, alternatively 25 mg PO, Q24H at night, increased if necessary to 25 mg Q12H. Nausea and vomiting, and motion sickness ADULT 20-25 mg PO at bedtime on night before travel and repeat following morning if necessary; CHILD (2-4 years) 5mg PO at bedtime on night before travel, repeat following morning if necessary; CHILD (5-9 years) 10 mg PO at bedtime on night before travel, repeat following morning if necessary; CHILD (10-17 years) 20-25 mg PO at bedtime on night before travel, repeat following morning if necessary. Emergency treatment of anaphylactic reactions ADULT 25-50 mg (as solution of 2.5 mg/mL in water for injections), IV injections (max. 100 mg/course)."],["Contraindications","Children less than 2 years of age, subcutaneous, coma, treatment of lower respiratory tract symptoms including asthma."],["Cautions","Asthma, epilepsy, prostatic hypertrophy, pyloroduodenal obstruction, severe coronary artery disease, susceptibility to angle-closure glaucoma, urinary retention."],["Side effects","Sedation, dizziness and other CNS symptoms are common at the start of treatment, but tolerance usually develops, GI irritation and anticholinergic effects are occasionally seen."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, not recommended."],["Counselling","May cause drowsiness, do not drive or operate machinery and avoid alcohol."]],"f25":[{"i":"Promethazine hydrochloride 10mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Promethazine hydrochloride 25mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CHARCOAL","n":"CHARCOAL","g":"Non-specific antidote.","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.1 Non-Specific","moa":"Activated charcoal adsorbs toxins in the gut lumen, preventing absorption (and interrupting enterohepatic recirculation).","f":[["Indications & dose","Reduction of absorption of poisons in the GI system ADULT 50 g PO; CHILD (1-2 years) 25-50 g PO; INFANT: 1 g/kg (approx. 5 mL/kg). Active elimination of poisons ADULT: Initially 50 g PO, then 50 g Q4H, reduced if not tolerated to 25 g PO, Q2H; CHILD (1 month-11 years) 1 g/kg PO, Q4H (MAX. per dose 50 g), dose may be reduced and the frequency increased if not tolerated; CHILD (12-17 years) Initially 50 g PO, then 50 g PO, Q4H, reduced if not tolerated to 25 g PO, Q2H."],["Contraindications","Poisoning by corrosive substances (strong acid or alkali), concurrent administration with specific oral antidotes or oral emetics, not for poisoning with petroleum distillates, corrosive substances, alcohols, clofenotane (dicophane, DDT), Malathion, and metal salts including iron and lithium salts, intestinal obstruction."],["Cautions","Comatose and drowsy patients (risk of aspiration), reduced gastrointestinal motility (risk of obstruction)."],["Side effects","Constipation, black stool."],["Administration","Aqueous slurry of charcoal should be made by suspending in a glass of water and administered; following administration of charcoal (after about 2 hours) a cathartic should be administered to enhance removal of poison charcoal complex promptly and to prevent enhanced toxicity; catharsis should occur within 4 to 8 hours after the use of activated charcoal."]],"f25":[{"i":"Charcoal activated powder (450g) packet","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ACETYLCYSTEINE","n":"ACETYLCYSTEINE","g":"Specific antidote (paracetamol poisoning).","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Replenishes glutathione, which detoxifies NAPQI (the toxic paracetamol metabolite). Also mucolytic by breaking disulphide bonds.","f":[["Indications & dose","Paracetamol poisoning ADULT (body weight 40 kg and above) 150 mg/kg IV infusion over 1 H, dose to be administered in 200 mL dextrose 5% (D5%), then 50 mg/kg over 4 hours in 500 mL D5%, then 100 mg/kg over 16 hours, in 1 L D5%; CHILD (body weight 40 kg and above) 150 mg/kg IV infusion over 1 hour, in 200 mL D5%, then 50 mg/kg over 4 hours in 500 mL D5%, then 100 mg/kg over 16 hours, in 1 L D5%; CHILD (body weight 20-39 kg) Initially 150 mg/kg IV infusion over 1 hour in 100 mL D5%, followed by 50 mg/kg over 4 hours, in 250 mL D5%, then 100 mg/kg over 16 hours, 500 mL D5%; CHILD (body weight up to 20 kg) Initially 150 mg/kg IV infusion over 1 hour in 3 mL/kg D5%, followed by 50 mg/kg over 4 hours in 7 mL/kg D5%, then 100 mg/kg over 16 hours in 14 mL/kg D5%."],["Contraindications","Severe tachycardia, cardiovascular disease (IHD)."],["Cautions","Asthma, atopy, may slightly increase INR, may slightly increase prothrombin time."],["Side effects","Hypersensitivity-like reactions, rashes, slight increase in INR and prothrombin time."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk unknown, use with caution."]],"f25":[{"i":"Acetylcysteine 200mg/mL injection (2ml) Vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Acetylcysteine 200mg/mL injection (10mL) ampoule → now Acetylcysteine 200mg/mL injection (2ml) Vial"]],"al":"nac"},{"k":"ANTI-SNAKE VENOM SERUM","n":"ANTI-SNAKE VENOM SERUM","g":"Specific (Antitoxin).","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Polyvalent equine immunoglobulin fragments that bind and neutralise circulating venom toxins.","f":[["Indications & dose","Treatment of bite from viper, cobra and krait Treatment of bite from viper, cobra and krait Dried anti-snake venom serum power is reconstituted usually with 10 mL of sterile water for injection. Two methods of administration are recommended: Intravenous “push” injection Reconstituted antivenom is given by slow intravenous injection (not more than 2 mL/minute) OR Intravenous infusion Reconstituted antivenom is diluted in approximately 5-10 mL of isotonic fluid per kg body weight (i.e. 250-500 mL of isotonic saline or 5% dextrose in the case of an adult patient) and is infused at a constant rate over a period of about one hour."],["Contraindications","Bite by non-poisonous snake, or when puncture marks are not seen, hypersensitive to horse or sheep serum."],["Cautions","History of previous serum injections (including anti-tetanus, anti-diphtheria); history of allergy, asthma or eczema."],["Side effects","Local flare or general anaphylactic reaction may be seen after the test dose or during the full dose. Pallor, sweating, nausea, vomiting, urticaria and hypotension are the features of anaphylaxis. Adrenaline 1mL, by IM injection should be given immediately and 0.5mL after 10 minutes if required."]],"f25":[{"i":"Antisnake venom serum (Viper,cobra and krait) 10g dried powder for injection vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CALCIUM GLUCONATE","n":"CALCIUM GLUCONATE","g":"Specific antidote.","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Supplies Ca2+; stabilises cardiac membrane in hyperkalaemia and reverses hypocalcaemia and magnesium toxicity.","f":[["Indications & dose","Magnesium intoxication or cardiac arrest in the presence of hyperkalemia or hypocalcemia ADULT 500-800 mg/dose (MAX. 3 g/dose); INFANT and CHILD 60-100 mg/kg/dose (MAX. 3 g/dose). Maintenance electrolyte requirements for TPN ADULT 1.7-3.4 g/1000 kcal/24 hours. Not for IM or SC administration. For IV administration only, administer slowly ( 1.5 mL calcium gluconate 10% per ~ minute) through a small needle into a large vein to avoid too rapid increase in serum calcium and extravasation."],["IV fluid compatibility","Stable in dextrose 5% in compound sodium lactate, dextrose 5% in sodium chloride 0.9%, dextrose 5%, dextrose 10%, dextrose 25%, compound sodium lactate, sodium chloride 0.9%. For detail, refer to page no. 156"]],"f25":[{"i":"Calcium gluconate 100mg/mL injection (10mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Calcium gluconate 100mg/mL injection (10mL) vial → now Calcium gluconate 100mg/mL injection (10mL) ampoule"]],"al":""},{"k":"FLUMAZENIL","n":"FLUMAZENIL","g":"Specific antidote.","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Competitive antagonist at the benzodiazepine site of the GABA-A receptor.","f":[["Indications & dose","Reversal of sedative effects of benzodiazepines in anaesthesia and clinical procedures ADULT 0.2 mg IV injection administered over 15 seconds, then 0.1 mg Q1 minute if required; Usual dose 0.3-0.6 mg; max. 1 mg per course. Reversal of sedative effects of benzodiazepines in intensive care ADULT 0.3mg IV injection administered over 15 seconds, then 0.1 mg Q1 minute if required; MAX. 2 mg per course. Reversal of sedative effects of benzodiazepines in intensive care (if drowsiness recurs after initial dose) ADULT 0.1-0.4 mg/hour IV infusion, adjusted according to response."],["Contraindications","Life-threatening condition (e.g., raised intracranial pressure, status epilepticus) controlled by benzodiazepines."],["Cautions","Avoid rapid injection following major surgery, avoid rapid injection in high-risk or anxious patients, benzodiazepine dependence, elderly, ensure neuromuscular blockade cleared before giving, history of panic disorders, prolonged benzodiazepine therapy for epilepsy."],["Side effects","Nausea, vomiting, anxiety, fear, palpitation, agitation, chills, convulsions, dizziness, flushing, sensory disturbance, sweating, tachycardia, transient hypertension."],["Hepatic impairment","Carefully titrate dose. Pregnancy C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5% and sodium chloride 0.9%."]],"f25":[{"i":"Flumazenil 0.1mg/mL injection (5mL) ampoule","v":"V","l":"NRH/RRH/DH","r":"Supplied to DH where there is ICU"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FOLINIC ACID (Leucovorin calcium)","n":"FOLINIC ACID (Leucovorin calcium)","g":"Specific antidote (Chemotherapy rescue agent).","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Reduced folate that bypasses dihydrofolate reductase, rescuing normal cells from methotrexate toxicity.","f":[["Indications & dose","Methotrexate overdose 1:1 ratio for leucovorin to inadvertent methotrexate overdose, within 1 hour. High-dose methotrexate-rescue dose 10 mg/m² IV Q6H starting 24 hours after methotrexate, then may switch to IM Q6H and continue until methotrexate level has fallen below 0.05 micromolar."],["Contraindications","Vitamin B12 deficiency anaemia and pernicious anaemia."],["Side effects","Diarrhoea, nausea, vomiting, stomatitis, thrombocytosis."],["Pregnancy category","C"],["Breast-feeding","Not known whether distributed in breast milk, use with caution."],["IV fluid compatibility","Sodium chloride 0.9%, compound sodium lactate, water for injection and dextrose 5% solution."],["Note","Do not mix leucovorin injection with 5-FU because precipitation will occur."]],"f25":[{"i":"Folinic acid 10mg/mL injection (5mL) vial","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"LIPID EMULSION","n":"LIPID EMULSION","g":"","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Acts as a 'lipid sink' that sequesters lipophilic drugs (e.g. local anaesthetics) and supports myocardial energy supply.","f":[["Indications & dose","ADULT 1.5 mL/kg IV bolus over 2 to 3 minutes; Repeat bolus for persistent asystole or pulseless electrical activity. Maintenance Continuous IV infusion of 0.25 mL/kg/min; if response is achieved after 3 minutes, adjust infusion rate to 0.025 mL/kg/min; increase to 0.25 mL/kg/min if necessary; Continue infusion until hemodynamic stability is achieved or until a total dose of 8 to 10 mL/kg is reached."],["Contraindications","Severe allergies to eggs and legumes, hyperlipidaemia, lipoid nephrosis, acute pancreatitis associated with hyperlipidemia, severe haemorrhagic disorders."],["Cautions","Anaemia, bleeding disorders, patients susceptible to fat embolism, pancreatitis and respiratory disease, premature infants."],["Side effects","Bradycardia, haemorrhage, hyperglycaemia, apnoea, agitation, vomiting, hypertriglyceridemia."],["Hepatic impairment","Use with caution in patients with severe hepatic impairment."],["Pregnancy category","C"],["Note","Strict adherence to proper infusion rates, dosing and monitoring are necessary in premature infants. Infusion rate should not exceed 1g fat/kg in four hours. Monitor serum triglyceride levels."]],"f25":[{"i":"Lipid emulsion 20% injection (250mL) bottle","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"NALOXONE","n":"NALOXONE","g":"Specific antidote (opioid overdose).","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Competitive antagonist at mu, kappa and delta opioid receptors; reverses opioid respiratory depression.","f":[["Indications & dose","Overdose with opioids by IV or IM or SC injection, ADULT Initially 0.4 mg, then 0.8 mg for up to 2 doses at 1 minute intervals; if no response, then increase to 2 mg for 1 dose if still no response (4 mg dose may be required in seriously poisoned patients); further doses may be required if respiratory function deteriorates; CHILD (1 month-11 years) Initially 0.1 mg/kg (Max. per dose 2 mg), if no response, repeat at intervals of 1 minute to a total MAX. 2 mg; further doses may be required if respiratory function deteriorates; CHILD (12-17 years) Initially 0.4 mg, then 0.8 mg for up to 2 doses at 1 minute intervals if no response to preceding dose, then increase to 2 mg for 1 dose if still no response (4mg dose may be required in seriously poisoned patients). Reversal of postoperative respiratory depression ADULT Initially 0.1-0.2 mg IV injection; if response inadequate, give subsequent doses, 0.1 mg Q2 minutes; CHILD (12-17 years) Initially 0.1-0.2 mg IV injection, if response inadequate, give subsequent doses, 0.1mg Q2 minutes; CHILD (1 month-11 years) 0.1 mg/kg IV injection, repeated Q2-3 minutes if required."],["Cautions","Cardiovascular disease or those receiving cardiotoxic medicines (serious adverse cardiovascular effects reported); maternal physical dependence on opioids (may precipitate withdrawal in new-born), pain, physical dependence on opioids (precipitated withdrawal)."],["Side effects","Cardiac arrest (in children), dizziness, dyspnoea (in children), headache, hypertension, hyperventilation (in children), hypotension, nausea, pulmonary oedema (in children), tachycardia, ventricular fibrillation (in children), vomiting."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5% and sodium chloride 0.9%."],["Note","This medicine is short acting, and repeated injections may be required."]],"f25":[{"i":"Naloxone 0.4mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Naloxone 0.4mg/mL injection (1mL) ampoule: now supplied down to DH"]],"al":""},{"k":"PHYTOMENADIONE (Vit K)","n":"PHYTOMENADIONE (Vit K)","g":"Specific antidote (Anticoagulant antagonists).","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Vitamin K1; cofactor for gamma-carboxylation of clotting factors II, VII, IX and X (reverses warfarin).","f":[["Indications & dose","Major bleeding in patients on warfarin ADULT 5 mg slow IV infusion, STAT; INR > 8.0 with minor bleeding in patients on warfarin 1-3 mg slow IV infusion, dose may be repeated if INR still too high after 24 hours; INR > 8.0 with no bleeding in patients on warfarin 1-5 mg PO (IV preparation to be used orally), repeat dose if INR still too high after 24 hours; INR 5.0-8.0 with minor bleeding in patients on warfarin 1-3 mg PO. *Stop warfarin treatment and restart if INR level falls below 5."],["Cautions","Any risk factors for haemorrhage, elderly, rapid IV injection can lead to fatal collapse."],["Side effects","Cyanosis, flushing, hypotension, scleroderma-like lesions."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk; Use with caution."],["Note","Phytomenadione does not neutralise heparin, use protamine sulphate instead. Store at room temperature away from light and moisture."]],"f25":[{"i":"Phytomenadione (Vit. K) 10mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"vitamin k"},{"k":"PRALIDOXIME","n":"PRALIDOXIME","g":"Specific antidote.","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Reactivates acetylcholinesterase phosphorylated by organophosphates (before 'ageing').","f":[["Indications & dose","Adjunct to atropine in the treatment of organophosphorus poisoning or nerve agent ADULT Initially 30 mg/kg IV infusion, to be given over 20 minutes, followed by 8 mg/kg/hour; max. 12 g per day; CHILD Initially 30 mg/kg IV infusion, to be given over 20 minutes, followed by 8 mg/kg/hour; max. 12 g per day."],["Contraindications","Poisoning due to carbamates and to organophosphorus compounds without anticholinesterase activity."],["Cautions","Myasthenia gravis."],["Side effects","Drowsiness, dizziness, disturbances of vision, nausea, tachycardia, headache, hyperventilation, and muscular weakness."],["Renal impairment","Use with caution."],["Pregnancy category","C"],["IV fluid compatibility","Sodium chloride 0.9%."]],"f25":[{"i":"Pralidoxime 25mg/mL injection (20mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PROTAMINE SULPHATE","n":"PROTAMINE SULPHATE","g":"Specific antidote.","sec":"4. ANTIDOTES AND OTHER SUBSTANCES USED IN POISONINGS","sub":"4.2 Specific","moa":"Strongly basic protein that binds acidic heparin to form an inactive complex.","f":[["Indications & dose","Overdose with IV injection of unfractionated heparin ADULT administer at a rate not exceeding 5 mg/minute IV injection, 1 mg neutralises 80-100 units of heparin when given within 15 minutes; if longer than 15 minute since heparin, less protamine required (consult product literature for details) as heparin rapidly excreted; MAX. 50 mg; Overdose with IV infusion of unfractionated heparin ADULT 25-50 mg IV injection, to be administered once heparin infusion stopped at a rate not exceeding 5mg/minute; Overdose with SC injection of unfractionated heparin ADULT Initially 25-50 mg IV injection, to be administered at a rate not exceeding 5mg/minute, 1mg neutralises 100 units of heparin, then (by IV infusion), any remaining dose to be administered over 8-16 hours; MAX. 50 mg per course; Overdose with subcutaneous injection of low molecular weight heparin ADULT administer by intermittent IV injection at a rate not exceeding 5 mg/minute; 1 mg neutralises approx. 100 units of low molecular weight heparin (consult product literature of low molecular weight heparin for details); MAX. 50 mg."],["Contraindications","Hypersensitivity to fish."],["Cautions","Excessive doses can have an anticoagulant effect, increased risk of allergic reaction to protamine (includes previous treatment with protamine or protamine insulin, allergy to fish, men who are infertile or who have had a vasectomy and who may have antibodies to protamine), rapid administration, repeated doses."],["Side effects","Anaphylaxis, angioedema, back pain, bradycardia, dyspnoea, flushing, hypertension, hypotension, lassitude, nausea, pulmonary oedema, rebound bleeding, vomiting."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Note","The long half-life of low molecular weight heparins should be taken into consideration when determining the dose of protamine; the effects of low molecular weight heparins can persist for up to 24 hours after administration; protamine does not neutralise oral anticoagulants."]],"f25":[{"i":"Protamine sulphate 10mg/mL injection (5mL) ampoule","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CLOBAZAM","n":"CLOBAZAM","g":"Antiepileptic (benzodiazepines).","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"1,5-benzodiazepine; positive allosteric modulator of GABA-A receptors.","f":[["Indications & dose","Lennox-Gastaut syndrome, Adjunct ADULT (≥30 kg) and CHILD (≥2 years and ≥30 kg) Initial, 10 mg PO daily (2 divided doses); Titrate to 20 mg daily (2 divided doses) on day 7 and to 40 mg daily (2 divided doses) on day 14; ADULT (≤ 30 kg) and CHILD (≥ 2 years and ≤ 30 kg) Initial, 5 mg once daily; Titrate to 10 mg daily (2 divided doses) on day 7 and to 20 mg daily (2 divided doses) on day 14."],["Contraindications","History of hypersensitivity to the medicine or ingredients."],["Cautions","Abuse, misuse, and addiction, do not exceed the usual recommended dosing frequency, if a substance use disorder is suspected, patient evaluation and early treatment. Concomitant therapy with benzodiazepines or CNS depressants should not be denied access to medication-assisted treatment medicines (e.g., buprenorphine), if concomitant use is necessary, careful management and monitoring recommended. Avoid or minimise concomitant use of CNS depressants and other substances associated with abuse, misuse, and addiction (e.g., opioid analgesics, stimulants)."],["Side effects","Constipation, drooling, ataxia, dysarthria, insomnia, lethargy, sedation, somnolence, aggressive behaviour, fever, Stevens-Johnson syndrome and toxic epidermal necrolysis."],["Renal impairment","No dose adjustment required in mild or moderate CKD. Data not available in severe CKD."],["Hepatic impairment","Mild-to-moderate (Child-Pugh 5-9): starting dose should be 5 mg/day and titrated according to weight, but to half the typical adult dose; additional titration to the maximum dose (20 mg/day or 40 mg/day), depending on the weight group) may be started on day 21. Not recommended in severe hepatic impairment."],["Pregnancy category","X"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Advise the risks and symptoms of benzodiazepine abuse, misuse, and addiction and to report such symptoms. Immediately report a dermatologic reaction. Avoid activities requiring mental alertness or coordination medicine may cause drowsiness. Advise female patients that the medicine decreases the effectiveness of hormonal contraceptives and to use additional non-hormonal methods of contraception during therapy and for 28 days after the last dose. Advise patients against sudden discontinuation of medicines as this may increase seizure frequency. Avoid alcohol and other CNS depressants."]],"f25":[{"i":"Clobazam 5mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CLONAZEPAM","n":"CLONAZEPAM","g":"Antiepileptic (benzodiazepines).","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Benzodiazepine; enhances GABA-A receptor activity (anticonvulsant, anxiolytic).","f":[["Indications & dose","All forms of epilepsy, myoclonus and status epilepticus ADULT 1 mg (0.5 mg in elderly) PO, initially at night for 4 nights, increase according to response over 2-4 weeks to usual maintenance dose of 4-8 mg usually at night in 3-4 divided doses; CHILD (up to 1 year) Initially 0.25 mg PO, increase as above to usual maintenance dose of 0.5-1 mg; CHILD (1-5 years) Initially 0.25 mg PO increased as above to 1-3 mg; CHILD (5-12 years) Initially 0.5 mg increased as above to 3-6 mg."],["Contraindications","Coma, current alcohol and drug abuse, respiratory depression."],["Cautions","Acute porphyrias, airways obstruction, brain damage, cerebellar ataxia, depression, spinal ataxia, suicidal ideation."],["Side effects","Drowsiness, fatigue and light-headedness, persisting until next day; confusion and ataxia in the elderly; salivary hypersecretion in infants; tolerance, amnesia, muscle weakness; hypotension and apnoea."],["Renal impairment","Start with small doses in severe impairment."],["Hepatic impairment","Start with smaller initial doses or reduced doses. Can precipitate coma, avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Do not drive or operate machineries during initiation of therapy; May enhance effects of alcohol."]],"f25":[{"i":"Clonazepam 0.5mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"DIAZEPAM","n":"DIAZEPAM","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Long-acting benzodiazepine; increases GABA-A chloride channel opening frequency.","f":[["Indications & dose","Status epilepticus and Febrile convulsions by IV injection, ADULT and CHILD (12 years and above) 10 mg IV injection, then 10 mg after 10 minutes if required administered at a rate of 1mL/min; CHILD (1 month-11 years) 300-400 mcg/kg (MAX. 10 mg/dose) IV injection, then 300-400 mcg/kg after 10 minutes if required administered over 3-5 minutes."],["Contraindications","Respiratory depression, severe hepatic impairment, chronic psychosis."],["Cautions","Muscle weakness, reduce dose in elderly. avoid prolonged use and abrupt withdrawal."],["Side effects","Drowsiness and light-headedness, persisting until next day, confusion and ataxia in the elderly, tolerance, amnesia, muscle weakness; hypotension and apnoea."],["Renal impairment","Start with small doses in severe impairment."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, avoid."]],"f25":[{"i":"Diazepam 5mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Diazepam 5mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"LAMOTRIGINE","n":"LAMOTRIGINE","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Blocks voltage-gated Na+ channels and reduces glutamate release.","f":[["Indications & dose","Treatment of partial seizures, and primary and secondarily generalised tonic-clonic seizures; seizures associated with Lennox-Gastaut syndrome Monotherapy ADULT and CHILD (12 years and above) Initially 25 mg PO, Q24H x 14 days, then increase to 50 mg PO, Q24H x 14 days, and then increase by max of 50-100 mg, Q24 x H7-14 days; up to 500 mg, Q12H. Adjunctive therapy with valproate ADULT and CHILD (over 12 years): Initially 25 mg PO, alternate Q24H x 14 days, then 25 mg PO, Q24H x 14 days, thereafter increase by max of 25-50 mg, Q24H x 7-14 days; usual maintenance dose, 100-200 mg daily in 1-2 divided doses; CHILD (2-11 years): Initially 0.15 mg/kg PO, Q24H x 14 days, then 0.3 mg/kg Q24H x 14 days, thereafter increased by maximum of 0.3 mg/kg, Q24H x 7-14 days; usual maintenance 1-5 mg/kg, Q24H to Q12H (max. 200 mg/day). Adjunctive therapy without valproate ADULT and CHILD (12 years and above): Initially 50 mg PO, Q24H x 14 days, then 50 mg PO, Q12H x 14 days, thereafter increase by max. of 100 mg, Q24H x 7-14 days; usual maintenance 200-400 mg, Q12H (up to 700 mg daily); CHILD (2-11 years): Initially 0.3 mg/kg PO,Q12H x 14 days, then 0.6 mg/kg, Q12H x 14 days, thereafter increased by maximum of 1.2 mg/kg, Q24H x 7-14 days; usual maintenance 5-15 mg/kg, Q12H (max. 400 mg/day."],["Cautions","Myoclonic seizures, Parkinson’s disease."],["Side effects","Blurred vision, aggression, agitation, arthralgia, ataxia, back pain, diarrhoea, diplopia, dizziness, drowsiness, dry mouth, headache, insomnia, nausea, nystagmus, rash, tremor, vomiting; serious skin reactions including Stevens Johnson syndrome and toxic epidermal necrolysis (rarely with fatalities) have been reported in children."],["Renal impairment","Consider reducing maintenance dose in significant impairment, caution in renal failure."],["Hepatic impairment","Halve dose in moderate impairment, quarter dose in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Lamotrigine 50mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"LEVETIRACETAM","n":"LEVETIRACETAM","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Binds synaptic vesicle protein SV2A, modulating neurotransmitter release.","f":[["Indications & dose","Monotherapy for partial seizures with or without secondary generalisation ADULT and CHILD (over 16 years): Initially 250 mg PO, Q12H, increasing according to response to 500 mg, Q12H after 2 weeks; max. 3 g/day; CHILD (4-15 years or body weight over 50 kg): Initially 10 mg/kg PO, Q12H (max. 30 mg/kg/dose, Q12H). Adjunctive therapy in partial seizure, myoclonic seizure, and general tonic-clonic seizure ADULT and CHILD (over 12 years & body weight > 50 kg): 250 mg PO, Q12H, adjusted in steps of 500 mg, Q12H x Q 2-4 weeks (max. 3 g/day); CHILD (12-18 years and body weight < 50 kg): Initially 10 mg/kg PO, Q12H, adjusted in steps of 10 mg/kg, Q12H x Q 2 weeks; max. 30 mg/kg twice daily."],["Side effects","Abdominal pain, aggression, anorexia, anxiety, ataxia, convulsion, cough, depression, diarrhoea, dizziness, drowsiness, dyspepsia, headache, insomnia, irritability, malaise, naso-pharyngitis, nausea, rash, tremor, vertigo, vomiting."],["Renal impairment","Reduce dose if GFR rate > 80 mL/minute."],["Hepatic impairment","No adjustment required."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Do not drive or operate machinery. This medicine is to be taken whole after meals preferably."]],"f25":[{"i":"Levetiracetam 500mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Levetiracetam 100mg/mL injection (5mL) vial","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Levetiracetam 500mg tablet: now supplied down to DH"]],"al":""},{"k":"LORAZEPAM","n":"LORAZEPAM","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Intermediate-acting benzodiazepine; enhances GABA-A receptor activity. First-line for status epilepticus.","f":[["Indications & dose","Seizure (Adjunct in intractable partial complex seizures) ADULT: 1 mg PO twice daily increasing twice weekly until seizures decreased or toxicity occurred; CHILD (Treatment of serial seizures): 1 to 4 mg sublingually; onset generally observed within 15 minutes (5 to 60 minutes)."],["Contraindications","Chronic psychosis, CNS depression, compromised airway, hyperkinesis, obsessional states, phobic states, respiratory depression."],["Cautions","Muscle weakness, organic brain changes, personality disorder."],["Side effects","Amnesia, ataxia (especially in elderly), confusion (especially in the elderly), dependence, drowsiness the next day, lightheadedness the next day, muscle weakness, paradoxical increase in aggression."],["Renal impairment","Start with small doses in severe impairment."],["Hepatic impairment","May precipitate coma. Avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","drowsiness may affect performance of skilled tasks, avoid driving or operating machinery."]],"f25":[{"i":"Lorazepam 1mg tablet","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"MAGNESIUM SULPHATE","n":"MAGNESIUM SULPHATE","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Blocks NMDA receptors and calcium entry, reducing neuronal excitability and acetylcholine release. Drug of choice in eclampsia.","f":[["Indications & dose","Treatment of seizures and prevention of recurrent seizures in eclampsia, by IV injection, initially 4 g over 5-15 minutes followed either by IV infusion, 1 g/hour for at least 24 hours after the last seizure or delivery (whichever occurs later). Prevention of seizures in pre-eclampsia, by IV injection, initially 4 g over 5-15 minutes followed by IV infusion, 1 g/hour for 24 hours; if seizure occurs, give an additional dose by IV injection of 2 g. Mild hypomagnesaemia, deep IM injection, 1 g every 6 hourly for 4 doses. Severe hypomagnesaemia, by IV infusion, 5 g IV over 3 hours."],["Contraindications","myocardial damage, heart block, diabetic coma, hypermagnesemia, hypercalcemia."],["Cautions","digitalized patients, myasthenia gravis and other neuromuscular diseases."],["Side effects","respiratory depression, oliguria, neuromuscular depression and muscle weakness."],["Renal impairment","Do not exceed 20 g in 48 hours, increased risk of toxicity."],["Pregnancy category","A or C"],["Breast-feeding","Compatible, infant risk is minimal."],["Note","for IV injection, concentration of magnesium sulphate should not exceed 20% (dilute 1 part of magnesium sulphate injection, 50%, with at least 1.5 parts of water for injections); for IM injection, mix magnesium sulphate injection, 50%, with 1 mL of lignocaine injection 2%. Monitor renal function, blood pressure, respiratory rate and deep tendon reflex."]],"f25":[{"i":"Magnesium sulphate 50% injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Magnesium sulphate powder (400g) packet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"PHENOBARBITAL","n":"PHENOBARBITAL","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Barbiturate; prolongs GABA-A channel opening and inhibits glutamate (AMPA) receptors.","f":[["Indications & dose","All forms of epilepsy except absence seizures ADULT: 60-180 mg PO at night; CHILD: 5-8 mg/kg PO, Q24H; Control of acute seizures 200 mg IM injection, Q6H if necessary; CHILD: 15 mg/kg STAT; Status epilepticus ADULT: 10 mg/kg IV injection at a rate of not more than 100 mg/min; max 1 g; CHILD (1 month-11 years): Initially 20 mg/kg slow IV injection administered at a rate no faster than 1 mg/kg/min, then 2.5-5 mg/kg, Q24H to Q12H; CHILD (12-17 years) Initially 20 mg/kg (max. per dose 1 g) slow IV injection administered at a rate no faster than 1 mg/kg/minute, then 30 mg Q12H. For IV injection, dilute injection 1 in 10 with water for injection."],["Contraindications","Porphyria."],["Cautions","Elderly, debilitated, children, impaired renal (avoid large doses) and hepatic function (may precipitate coma), respiratory depression, pregnancy and breastfeeding, avoid sudden withdrawal."],["Side effects","Drowsiness, lethargy, depression, ataxia and allergic skin reactions; paradoxical excitement, restlessness and confusion in the elderly and hyperkinesia in children, megaloblastic anaemia."],["Renal impairment","Use with caution."],["Hepatic impairment","May precipitate coma, avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, avoid."],["Counselling","Do not drive or operate machinery. Do not drink alcohol."]],"f25":[{"i":"Phenobarbital 200mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Phenobarbital 30mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"PHENYTOIN","n":"PHENYTOIN","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Blocks voltage-gated Na+ channels in the inactive state; zero-order kinetics at therapeutic doses.","f":[["Indications & dose","All forms of epilepsy except absence seizures ADULT: Initially 100-200 mg PO, Q24H to Q12H, increased slowly to usual dose of 800-1200 mg/day in divided doses; in some cases, higher doses may be needed; ELDERLY: Reduce initial dose; CHILD (1 month -11 years): Initially 1.5-2.5 mg/kg PO, Q12H, then adjusted according to response to 2.5-5 mg/kg, Q12H (max. per dose 7.5 mg/kg, Q12H); CHILD (12-17 years): Initially 75-150 mg PO, Q12H, then adjusted according to response to 150-200 mg, Q12H (max. per dose 300 mg, Q12H). Status epilepticus by slow IV injection or infusion, ADULT and CHILD (more than 12 years): 15 mg/kg (max. 2 g/dose) loading dose (at a rate not exceeding 1mg/kg/min), then 100 mg slow IV injection or PO, Q6-8H; CHILD (1 month-11 years) 15 mg/kg loading dose, then 2.5-5 mg/kg slow IV injection, Q12H."],["Contraindications","Acute porphyrias, with IV use (Second- and third-degree heart block, sino-atrial block, sinus bradycardia)."],["Cautions","Enteral feeding, Heart failure, hypotension, alkaline injection solutions, respiratory depression."],["Side effects","Gl disturbances including constipation, CNS symptoms including ataxia and confusion, Stevens-Johnson syndrome, visual disturbances (diplopia) are often associated with peak plasma concentrations. Generalized erythematous rash occasionally, gingival hypertrophy and many other symptoms have been reported with high doses."],["Hepatic impairment","Reduce dose to avoid toxicity."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Do not drive or operate machinery. Do not drink alcohol."]],"f25":[{"i":"Phenytoin 100mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Phenytoin 50mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SODIUM VALPROATE","n":"SODIUM VALPROATE","g":"Antiepileptic.","sec":"5. ANTICONVULSANTS/ANTIEPILEPTICS","sub":"","moa":"Blocks Na+ channels and T-type Ca2+ channels and increases GABA levels (inhibits GABA transaminase).","f":[["Indications & dose","All forms of Epilepsy ADULT and CHILD (12 years and above): Initially, 600 mg PO, Q12H, increasing by 200 mg/day at 3-day intervals to a max of 2.5 g daily in divided doses; CHILD (1 month-11 years): Initially 10-15 mg/kg, PO, Q12H to Q8H to a max. 600 mg daily. Absence Seizures, Complex Partial seizure ADULT: 10-15 mg/kg/day IV divided Q12hr infused over 1 hours; may increase dose by 5-10 mg/kg/day at 1-week intervals to a max. of 60 mg/kg/day; do not exceed 14 days."],["Contraindications","Active liver disease, family history of severe hepatic dysfunction, pregnancy."],["Cautions","Monitor liver function before therapy and during the first 6 months, benefit of treatment outweighs risk in pregnancy, folic acid supplement is however needed, monitor platelet function before surgery, may give false positive test for ketonuria in diabetes."],["Side effects","Gastric irritation and nausea, ataxia and tremor, transient hair loss, increased appetite, thrombocytopenia, impaired liver function (withdraw immediately if evidence of hepatitis)."],["Renal impairment","Reduce dose."],["Hepatic impairment","Avoid in active liver disease."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Do not drive or operate machinery. Do not take alcohol. Take the tablet whole, preferably after food."]],"f25":[{"i":"Sodium valproate 200mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ALBENDAZOLE","n":"ALBENDAZOLE","g":"Anthelmintic.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.1.1 Intestinal anthelmintics","moa":"Binds parasite beta-tubulin, inhibiting microtubule polymerisation and glucose uptake.","f":[["Indications & dose","Roundworms, pinworm, whipworm and hookworm infestations ADULT and CHILD (>2 years): 400 mg PO, STAT. Strongyloides and tapeworm infestation ADULT and CHILD (>2 years): 400 mg PO, Q24H x 3 days. Echinococcus granulosus ADULT and CHILD (above 2 years): 10mg/kg/day x 4-8 weeks; Neurocysticercosis ADULT: 400 mg PO, Q12H x 30 days; CHILD (1-2 years): Half the adult dose. Hydatid cyst ADULT (>60 kg): 400 mg PO, Q12H x 28 days; repeat after two weeks for up to 3 cycles; ADULT (<60 kg) and CHILD (less than 6 years): 7.5 mg/kg PO, Q12H (max. 400 mg per dose) x 28 days; repeat after two weeks for up to 3 cycles."],["Contraindications","Pregnancy before twelve weeks."],["Cautions","Liver function tests and blood counts before treatment and twice during each cycle (prolonged treatment)."],["Side effects","GI disturbances, headache, dizziness, increase in liver enzymes, reversible alopecia."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","Tablets should be chewed/crushed thoroughly and washed down with water. Patients should be advised to take it in an empty stomach if it is a single dose. For systemic infestation such as neurocysticercosis, it should be taken with food for better absorption."]],"f25":[{"i":"Albendazole 400mg tablet (Flavoured-chewable)","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Albendazole 400mg tablet (chewable) → now Albendazole 400mg tablet (Flavoured-chewable)"]],"al":""},{"k":"NICLOSAMIDE","n":"NICLOSAMIDE","g":"Intestinal anthelmintic.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.1.1 Intestinal anthelmintics","moa":"Uncouples oxidative phosphorylation in tapeworm mitochondria; kills scolex and proximal segments.","f":[["Indications & dose","Taenia solium ADULT and CHILD (over 6 years): 2 g PO, STAT on empty stomach followed by magnesium sulphate solution after 2 hours; CHILD (under 2 years): 500 mg PO, STAT; CHILD (2-6 years): 1000 mg PO, STAT. Taenia saginata and Diphyllobothrium latum As above but half of the dose on empty stomach and remainder one hour later, followed by a purgative 2 hours after the last dose. Hymenolepis nana ADULT and CHILD (over 6 years): 2 g PO, STAT on first day and then 1 g, Q24H x 6 days; CHILD (under 2 years): 500 mg PO, STAT on first day and then 250 mg, Q24H x 6 days; CHILD (2-6 years): 1 g PO, STAT on first day, then 500 mg, Q24H x 6 days."],["Cautions","Chronic constipation, a laxative should be given the night before treatment, or a purgative 2 hours after the medication."],["Side effects","Light-headedness, pruritus, mild GI disturbances."],["Counselling","Tablets should be chewed thoroughly (or crushed) before washing down with water."]],"f25":[{"i":"Niclosamide 500mg tablet (chewable)","v":"E","l":"NRH/RRH/DH","r":"For tapeworm infestation"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"AMOXICILLIN","n":"AMOXICILLIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Aminopenicillin (beta-lactam); binds penicillin-binding proteins and inhibits cell wall cross-linking. Bactericidal.","f":[["Indications & dose","Urinary tract infections, otitis media, sinusitis, PID, cholera, cholecystitis, peritonitis, bronchitis, pneumonia, dental abscess and other infections depending on culture sensitivity report ADULT: 250-500 mg PO, Q8H, doubled in severe infections; ADULT (under 40 kg): 20-40 mg/kg/day, Q8H, or 25-45 mg/kg/day, Q12H; CHILD (up to 10 years): 125-250 mg PO, Q8H; INFANTS (less than 3 months): Max. dose 30 mg/kg/day, Q12H."],["Cautions","Acute lymphocytic leukaemia (increased risk of erythematous rashes), chronic lymphocytic leukaemia (increased risk of erythematous rashes), cytomegalovirus infection (increased risk of erythematous rashes), glandular fever (erythematous rashes common)."],["Side effects","Nausea, vomiting, headache, diarrhoea, rash."],["Renal impairment","CrCl=10-30 mL/minute: 250-500 mg, Q12H; CrCl <10 mL/minute: 250-500 mg, Q24H."],["Pregnancy category","B"],["Breast-feeding","Excreted in breast milk, use with caution."]],"f25":[{"i":"Amoxicillin 1000mg tablet","v":"E","l":"NRH/RRH/DH","r":"For H. Pylori"},{"i":"Amoxicillin 250mg capsule","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Amoxicillin 125mg/5mL syrup (100mL) Suspension","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Amoxicillin 250mg/5mL syrup (100mL) bottle → now Amoxicillin 125mg/5mL syrup (100mL) Suspension"]],"al":""},{"k":"AMOXICILLIN + CLAVULANIC ACID","n":"AMOXICILLIN + CLAVULANIC ACID","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Amoxicillin inhibits cell wall synthesis; clavulanate irreversibly inhibits many beta-lactamases, widening spectrum.","f":[["Indications & dose","Erysipelas and cellulitis ADULT: 1 g IV injection, Q8H; CHILD (under 3 months): 25 mg/kg IV injection, Q12H; CHILD (3 months and over): 25 mg/kg IV injection, Q8H; Necrotizing infections ADULT and CHILD (40 kg and over): 2 g IV injection, Q8H; CHILD (under 3 months): 50 mg/kg IV injection, Q12H; CHILD (3 months and over and < 40 kg): 50 mg/kg IV injection, Q8H. Upper genital tract infection ADULT: 1 g IV injection, Q8H."],["Contraindications","History of hypersensitivity to beta-lactam antibiotics, hepatic dysfunction."],["Cautions","Increased risk of hepatic dysfunction in elderly and/or males and with prolonged treatment; prolonged use may result in fungal or bacterial superinfection, including C. difficile-associated diarrhoea (CDAD) and pseudomembranous colitis."],["Side effects","Diarrhoea, nausea, vomiting, hepatic disorders, hypersensitivity reactions (anaphylaxis, angioedema, and urticaria)."],["Renal impairment","CrCl=10-30: Q12H; CrCl<10 mL/min: Q24H."],["Pregnancy category","B"]],"f25":[{"i":"Amoxicillin 500mg + clavulanic acid 100mg powder for injection vial","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":"augmentin co-amoxiclav"},{"k":"AMPICILLIN","n":"AMPICILLIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Aminopenicillin; inhibits bacterial cell wall synthesis via penicillin-binding proteins.","f":[["Indications & dose","Endocarditis ADULT: 2 g IV injection, Q4H; CHILD: 50 mg/kg IV injection, Q6H. Meningitis ADULT: 2 g IV injection, Q4H; NEONATE: 50 mg/kg IV injection, Q6H; CHILD (3-12 years): 100 mg/kg IV injection, Q6H (max 12 g daily). Septicaemia ADULT: 500 mg Iv injection, Q4H to Q6H; CHILD (under 10 years): half the adult dose; NEONATE: 25 mg/kg IV injection, Q8H. Peritonitis and cholangitis ADULT: 500 mg IV injection, Q6H. Pneumonia NEONATE: 30 mg/kg IV injection, Q12H; CHILD (4 months-5 years): 200 mg/kg IV injection, Q6H."],["Cautions","History of allergy; renal impairment, erythematous rashes are common in patients with infectious mononucleosis, chronic lymphatic leukaemia and HIV."],["Side effects","Nausea, vomiting, diarrhoea, rashes (discontinue treatment)."],["Renal impairment","CrCl >50 mL/minute: Q6H; CrCl=10-50 mL/minute: Q6-12H; CrCl <10 mL/minute: Q12-24H."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Ampicillin 500mg powder for injection vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"BENZATHINE BENZYLPENICILLIN","n":"BENZATHINE BENZYLPENICILLIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Long-acting depot of penicillin G; slow release maintains low levels for weeks. Inhibits cell wall synthesis.","f":[["Indications & dose","Primary syphilis ADULT: 2.4 g deep IM, on two successive days; Late syphilis ADULT: 2.4 g deep IM, weekly for 3 weeks. Prophylaxis of rheumatic fever ADULT: 1.2 g deep IM, 3 weekly; CHILD (<10 years): Half the ADULT dose. Congenital syphilis (for infants born to seropositive mothers): 50000 IU/kg as a single dose"],["Cautions","Allergy (a test dose should be given); renal impairment, pregnancy, Breast-feeding and in hypertensive patients as it contains sodium."],["Side effects","Maculopapular eruptions, exfoliative dermatitis, urticarial, oedema, chills, fever, arthralgia, Jarsch-Herxheimer reaction, pseudomembranous colitis."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Note","Do not administer IV, intra-arterial or subcutaneous."]],"f25":[{"i":"Benzathine benzylpenicillin 44g (2.4 million IU) powder for injection (5mL) vial","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"BENZYLPENICILLIN (Penicillin G)","n":"BENZYLPENICILLIN (Penicillin G)","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Natural penicillin; inhibits cell wall peptidoglycan cross-linking. Bactericidal, mainly gram-positive and Neisseria.","f":[["Indications & dose","Mild to moderate susceptible infections; Throat infections; Otitis media; Cellulitis; Pneumonia ADULT: 2 million IU IV injection or infusion, Q4H; CHILD: 0.15-0.2 million IU/kg/day IV injection or infusion, Q4H (max 20 million IU/day). Bites and peritonitis ADULT: 1 million IU slow IV injection, Q6H. Neurosyphilis ADULT: 1.2-2.4 million IU slow IV injection, Q4H; Meningitis gonococcal ADULT: 2.4 g slow IV injection or infusion, Q4H; CHILD: 50 mg/kg IV infusion, Q4-6H (max. per dose 2.4 g, Q4H)."],["Contraindications","Avoid intra-arterial routes."],["Cautions","Accumulation of sodium can occur with high doses, history of allergy."],["Side effects","Anaphylaxis, angioedema, fever, hypersensitivity reactions, joint pains, rashes, serum sickness-like reaction, urticaria."],["Renal impairment","CrCl >10mL/min, full loading dose followed by half of the loading dose, Q4-5H; CrCl <10mL/min, full loading dose followed by half of the loading dose, Q8-10H."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, compatible."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Benzylpenicillin 3g (5 million IU) powder for injection vial","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CEPHALEXIN","n":"CEPHALEXIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"First-generation cephalosporin; inhibits cell wall synthesis. Good gram-positive cover.","f":[["Indications & dose","Sensitive infections like urinary tract infections, skin and soft tissue infections, bone infections, biliary tract infections, intra-abdominal infections by oral administration, ADULT: 500mg 12 hourly; CHILD: under 1 year, 125mg 12 hourly; CHILD: 1-5 years, 125mg 8 hourly; CHILD: 6-12 years, 250mg 8 hourly; doses should be doubled in severe infections."],["Contraindications","cephalosporin hypersensitivity."],["Cautions","penicillin hypersensitivity, renal impairment, false positive urinary glucose if tested for reducing substances, false positive Coombs’ test."],["Side effects","diarrhoea, colitis, nausea and vomiting, allergic manifestations including rashes, pruritus and urticaria, also fever, arthralgia and anaphylaxis, abdominal discomfort, headache, erythema multiforme, toxic epidermal necrolysis, disturbances in liver enzymes, transient hepatitis and cholestatic jaundice. Renal Impairment CrCl 10-50 mL/minute: 500 mg every 8-12 hours; CrCl <10: 250-500 mg every 12-24 hours."],["Pregnancy category","B"],["Breast-feeding","excreted in milk (small amount), use caution."],["Counselling","Complete with full course of treatment."]],"f25":[{"i":"Cefalexin 250mg capsule","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Orthopaedic Surgeon, Paediatrician and Medical Specialist"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CEFAZOLIN","n":"CEFAZOLIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"First-generation cephalosporin; inhibits cell wall synthesis. Used for surgical prophylaxis.","f":[["Indications & dose","Respiratory and genito-urinary tract infections that do not respond to penicillins; Skin and soft tissue; Bone and joint infections; septicaemia; Surgical prophylaxis; Endocarditis ADULT: 500-1000 mg IM or IV injection, Q6-12H; CHILD: 25-50 mg/kg/day IM or IV injection, Q6-8H, increased to 100 mg/kg/day in severe infections."],["Cautions","Renal impairment, prolonged treatment."],["Side effects","Anorexia, diarrhoea, fever, eosinophilia, leukopenia, nausea and vomiting, pain at injection site, neutropenia, oral candidiasis."],["Renal impairment","CrCl=35-54 mL/minute: Full dose Q8H; CrCl=11-34 mL/minute: Half dose, Q12H; CrCl=10 mL/minute: Half dose, Q18-24H."],["Hepatic impairment","Use with caution."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["IV fluid compatibility","Dextrose 5%, Dextrose 5% sodium chloride 0.9%, compound solution of sodium lactate, sodium chloride 0.9%."]],"f25":[{"i":"Cefazolin 500mg powder for injection vial","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Surgeon and Paediatrician"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CHLORAMPHENICOL","n":"CHLORAMPHENICOL","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Binds 50S ribosomal subunit and inhibits peptidyl transferase (protein synthesis). Bacteriostatic.","f":[["Indications & dose","Life threatening infections particularly those caused by Haemophilus influenzae; Typhoid fever ADULT: 12.5 mg/kg IV injection or IV infusion, Q6H; in exceptional cases dose can be doubled for severe infections such as septicaemia and meningitis, providing high doses reduced as soon as clinically indicated; CHILD: 12.5 mg/kg IV injection or IV infusion, Q6H; dose may be doubled in severe infections such as septicaemia, meningitis and epiglottitis providing plasma-chloramphenicol concentrations are measured and high doses reduced as soon as indicated."],["Contraindications","Acute porphyrias, breastfeeding."],["Cautions","Acute porphyrias, G6PD deficiency, monitor complete blood count before and during treatment."],["Side effects","Blood disorders, depression, diarrhoea, dry mouth, erythema multiforme, glossitis, headache, nausea, nocturnal haemoglobinuria, optic neuritis, peripheral neuritis, reversible and irreversible aplastic anaemia (with reports of resulting leukaemia), stomatitis, urticaria, vomiting."],["Renal impairment","Avoid in severe renal impairment unless no alternative, dose-related depression of haematopoiesis."],["Hepatic impairment","Reduce dose. Avoid if possible-increased risk of bone-marrow depression."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, compound solution of calcium lactate, sodium chloride 0.9%."],["Note","Associated with serious haematological side effects when given systemically and should therefore be reserved for the treatment of life-threatening infections."]],"f25":[{"i":"Chloramphenicol 0.4% eye drop (5mL)","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Chloramphenicol 1% eye ointment (250mg) soft gelatin capsule","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Chloramphenicol 1g powder for injection vial","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CLOXACILLIN","n":"CLOXACILLIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Penicillinase-resistant penicillin; inhibits cell wall synthesis, active against beta-lactamase-producing staphylococci.","f":[["Indications & dose","Osteomyelitis; Septic arthritis; Staphylococcal endocarditis ADULT: 2 g slow IV or infusion or, PO, Q6H; CHILD, 50 mg/kg 6 hourly. Brain abscess and meningitis ADULT: 2 g slow IV or infusion, Q4H; Cellulitis and paronychia nail infection. ADULT: 250-500 mg PO, Q6H; CHILD (up to 2 years): 1/4th of the adult dose; CHILD (2-10 years): Half the adult dose."],["Contraindications","Jaundice in neonates."],["Cautions","History of allergy, renal impairment, hepatic disease."],["Side effects","Nausea and vomiting, diarrhoea, hypersensitivity reactions including urticaria, fever, joint pain, rash, angioedema, anaphylaxis, serum sickness-like reactions, haemolytic anaemia, and interstitial nephritis, neutropenia, thrombocytopenia, coagulation disorders, rarely antibiotic-associated colitis, hepatitis and cholestatic jaundice (may be delayed in onset), electrolyte disturbances, pain, inflammation, phlebitis, or thrombophlebitis at injection sites."],["Renal impairment","Use with caution; rate of elimination is reduced."],["Hepatic impairment","dose adjustment required."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Take the medicine at least half an hour before food."]],"f25":[{"i":"Cloxacillin 250mg capsule","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Cloxacillin 250mg powder for injection vial","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SULFAMETHOXAZOLE + TRIMETHOPRIM (Co-trimoxazole)","n":"SULFAMETHOXAZOLE + TRIMETHOPRIM (Co-trimoxazole)","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Sequential folate blockade: sulfamethoxazole inhibits dihydropteroate synthase; trimethoprim inhibits dihydrofolate reductase.","f":[["Indications & dose","Upper respiratory infections; urinary tract infection; pneumonia ADULT: 960 mg PO, Q12H; CHILD (over 5 years): 480 mg PO, Q12H; CHILD (6 months-5 years): 240 mg PO, Q12H; CHILD (6 weeks-6 months): 120 mg PO, Q12H. Prophylaxis of Pneumocystis jiroveci pneumonia in HIV patients ADULT: 960 mg PO, Q24H."],["Contraindications","Porphyria, pregnancy at term, infants under 6 weeks old, CrCl<15mL/min, severe hepatic impairment, megaloblastic or folate deficiency anaemia."],["Cautions","G6PD deficiency, renal or hepatic impairment, thyroid dysfunction, asthma, elderly patients, maintain adequate fluid intake."],["Side effects","Anorexia, Nausea, vomiting, vertigo, seizure, rashes, urticarial, toxic epidermal necrolysis, hyponatremia, agranulocytosis, aplastic anaemia, neutropenia, thrombocytopenia, anaphylaxis. Renal Impairment CrCl=15-30 mL/minute: administer 50% of recommended dose, CrCl <15 mL/minute: not recommended."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Note","In case of bacillary dysentery, oral rehydration remains the first requirement of treatment; mild cases may be prolonged by antibiotic treatment."],["Counselling","Drink plenty of fluids with this medicine."]],"f25":[{"i":"Cotrimoxazole (Sulphamethoxazole 200mg + Trimethoprim 40mg) /5mL syrup (60mL) bottle","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Cotrimoxazole (Sulphamethoxazole 400mg+Trimethoprim 80mg) tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"cotrimoxazole septran bactrim"},{"k":"DOXYCYCLINE","n":"DOXYCYCLINE","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Tetracycline; binds 30S ribosomal subunit, blocking aminoacyl-tRNA attachment. Bacteriostatic.","f":[["Indications & dose","Susceptible infections (e.g. chlamydia, rickettsia and mycoplasma) ADULT: 200 mg PO on the first day, then 100mg PO, Q24H. Severe infections 200 mg PO, Q24H; Early syphilis ADULT: 100 mg PO, Q12H x 14 days. Late latent syphilis 200 mg PO, Q12H x 28 days. Uncomplicated genital chlamydia; non-gonococcal urethritis 100 mg PO, Q12H x 7 days (14 days in PID). Acne ADULT and CHILD (>12 years): 100 mg PO, Q24H."],["Contraindications","Children under 12 years, systemic lupus erythematosus."],["Cautions","Alcohol dependence patients."],["Side effects","Anorexia, anxiety, dry mouth, flushing, diarrhoea, dysphagia, and oesophageal irritation."],["Pregnancy category","D"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Take this medicine with plenty of fluid during meals to reduce gastric irritation. Avoid exposure of skin to direct sunlight. Avoid oral iron preparations and antacids."]],"f25":[{"i":"Doxycycline 100mg capsule","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Doxycycline 100mg injection IV","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Added in 2025","Doxycycline 100 mg injection IV added (Till RRH). Reason: It is a key antibiotic for treating severe scrub typhus and is also used for leptospirosis, especially when oral administration is not feasible and is the treatment of choice for suspected scrub typhus in persons of all ages."]],"al":""},{"k":"GENTAMICIN","n":"GENTAMICIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Aminoglycoside; binds 30S subunit causing mRNA misreading. Concentration-dependent bactericidal, gram-negative aerobes.","f":[["Indications & dose","Gram-positive bacterial endocarditis or HACEK endocarditis (in combination with other antibacterial) ADULT: 1 mg/kg IM, or slow IV injection or IV infusion, Q12H administered over at least 3 minutes. Septicaemia; Meningitis and other CNS infections; Biliary tract infection; Acute pyelonephritis; Endocarditis; Pneumonia in hospital patients; Adjunct in listeria meningitis; Prostatitis ADULT: Initially 5-7 mg/kg IV infusion, administered as once daily dose regimen; CHILD: Initially 7 mg/kg IV infusion, to be given in a once daily regimen (not suitable for endocarditis or meningitis). Surgical prophylaxis ADULT: 1.5 mg/kg IV injection administered over at least 3 minutes and 30 minutes before the procedure; dose repeated Q8H for high-risk procedures and up to 3 further doses may be given. Pseudomonas infection in cystic fibrosis CHILD: 3 mg/kg slow IV injection over at least 3 minutes or IV infusion, Q8H as a multiple daily dose regimen."],["Contraindications","Myasthenia gravis."],["Cautions","Care must be taken with dosage (the main side effects of the aminoglycosides are dose-related), conditions characterised by muscular weakness, if possible, dehydration should be corrected before starting an aminoglycoside, whenever possible. Parenteral treatment should not exceed 7 days; risk of ototoxicity, neurotoxicity and nephrotoxicity, renal failure."],["Side effects","Neurotoxicity (vertigo, ataxia), ototoxicity (auditory and vestibular), nephrotoxicity (decreased CrCl), oedema, rash, itching, drowsiness, headache, antibiotic-associated colitis, electrolyte disturbances, nausea, peripheral neuropathy, stomatitis, vomiting."],["Renal impairment","Conventional dosing CrCl >90 mL/min and 60 years: Q8H; CrCl = 60-90 mL/min: Q12H; CrCl=25-60 mL/min: Q24H; CrCl=10-25 mL/min: Q48H; CrCl <10 mL/minute: Q72H. Once daily dose ADULT and CHILD (above 1 year): Avoid, if CrCl <20 mL/ minute."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, use with caution."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Gentamicin 40mg/mL injection (2mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"METRONIDAZOLE","n":"METRONIDAZOLE","g":"Antibacterial and antiprotozoal.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Nitroimidazole; reduced inside anaerobes and protozoa to radicals that damage DNA.","f":[["Indications & dose","Anaerobic infections ADULT: 400 mg PO, Q8H x 7-10 days; 500 mg IV infusion administered over 20 minutes, Q8H x 7 days (for 10-14 days in Clostridium difficile infection); CHILD (2 months-11 years): 7.5 mg/kg PO, Q8H (max.400 mg/dose) x 7 days; 7.5 mg/kg IV infusion, Q8H (max. 500 mg/dose) x 7 days (for 10-14 days in Clostridium difficile infection). Invasive intestinal amoebiasis; Extra-intestinal amoebiasis (including liver abscess) ADULT: 800 mg PO, Q8H; CHILD (1-2 years): 200 mg PO, Q8H x 7 days; CHILD (3-6 years): 200 mg PO, Q6H; CHILD (7-9 years): 400 mg PO, Q8H; * 5 days for intestinal infection and 5-10 days in extra-intestinal infection. Urogenital trichomoniasis ADULT: 200 mg PO, Q8H x 7 days, alternatively 2 g, STAT; CHILD (1-2 years): 50 mg PO, Q8H x 7 days; CHILD (3-6 years): 100 mg PO, Q12H x 7 days; CHILD (7-9 years): 100 mg PO, Q8H x 7 days. Giardiasis ADULT: 2 g PO, Q24H x 3 days, alternatively 400 mg, Q8H x 5 days; CHILD (1-2 years): 500 mg PO, Q24H x 3 days; CHILD (3-6 years): 600-800 mg PO, Q24H x 3 days; CHILD (7-9 years): 1 g PO, Q24H x 3 days. Bacterial vaginosis (notably Gardnerella vaginalis infection) ADULT: 400 mg PO, Q12 x 5-7 days, alternatively 2 g, STAT. Acute ulcerative gingivitis ADULT: 200 mg PO, Q8H x 3 days; CHILD (3-6 years): 100 mg PO, Q12H x 3 days; CHILD (7-9 years): 100 mg PO, Q8H x 3 days. Acute oral infections ADULT: 200 mg PO, Q8H x 3-7 days; CHILD (1-2 years): 50 mg PO, Q8H x 3-7 days; CHILD (3-6 years): 100 mg PO, Q12H x 3-7 days; CHILD (7-9 years): 100 mg PO, Q8H x 3-7 days. Helicobacter pylori eradication; in combination with amoxicillin and omeprazole ADULT: 400 mg PO, Q12H; CHILD (1-5 years): 100 mg PO, Q12H; CHILD (6-11 years): 200 mg PO, Q12H. Pelvic inflammatory disease ADULT and CHILD (12-17 years): 400 mg PO, Q12H x 14 days. Surgical prophylaxis ADULT: 400 mg PO, administered 2 hours before surgery, then 400 mg, Q8H if required for up to 3 doses (in high-risk procedures); 500 mg IV infusion, administered up to 30 minutes before the procedure, then 500 mg, Q8H if required for up to 3 further doses (in high-risk procedures); CHILD (1 month-11 years): 30 mg/kg (max. 500 mg/dose) PO or IV infusion, administered 2 hours before surgery."],["Contraindications","Hypersensitivity to nitroimidazoles, pregnancy (1st trimester), use of disulfiram within the past 2 weeks, use of alcohol during therapy or within 3 days of discontinuing therapy."],["Cautions","History of heart failure, renal impairment, severe hepatic impairment, pregnancy, breastfeeding."],["Side effects","Nausea, vomiting, unpleasant taste, GI disturbances, rashes, headache, dizziness, ataxia, darkening of urine, erythema multiforme, pruritus, urticaria, angioedema, and anaphylaxis, also reported abnormal liver function tests, thrombocytopenia, aplastic anaemia, myalgia, arthralgia, on prolonged or intensive therapy peripheral neuropathy, transient epileptic form seizures, and leukopenia."],["Renal impairment","CrCl <10mL/min: 50% of dose or Q12H."],["Hepatic impairment","In severe liver disease reduces the total daily dose to one-third, and administer once daily."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."],["Counselling","Avoid alcohol intake and direct sunlight."]],"f25":[{"i":"Metronidazole 400mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Metronidazole 5mg/mL solution (100mL) single-dose plastic bottle","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"NITROFURANTOIN","n":"NITROFURANTOIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Reduced by bacterial flavoproteins to reactive intermediates that damage DNA and ribosomes; concentrates in urine.","f":[["Indications & dose","Treatment of uncomplicated urinary-tract infections ADULT and CHILD >12 years (immediate-release): 50-100 mg PO q6hr for 7 days or for 3 days after obtaining sterile urine; Modified-release: 100 mg PO q12hr for 7 days or for 3 days after obtaining sterile urine; CHILD (3 months-11 years): 3 mg/kg PO, Q6H x 3-7 days. Prophylaxis of urinary-tract infection ADULT: 50-100 mg PO, at night; CHILD (3 months-11 years): 1 mg/kg PO, at night."],["Contraindications","Renal impairment (CrCl <60 mL/minute), infants <3 months old (due to the possibility of haemolytic anaemia), pregnancy at term (38-42 weeks gestation), during labour and delivery, or when the onset of labour is imminent."],["Cautions","G6PD deficiency, in long-term therapy, anaemia, renal impairment, diabetes, vitamin B deficiency, electrolyte imbalance."],["Side effects","Anorexia, nausea, vomiting and diarrhoea are common, pulmonary reactions, peripheral neuropathy may occur, urticarial rash and pruritus, many other side effects have been noted."],["Renal impairment","Avoid in CrCl <60 mL/minute."],["Hepatic impairment","Use with caution; cholestasis, jaundice and chronic active hepatitis reported."],["Pregnancy category","B"],["Breast-feeding","Excreted in small amounts, avoid."],["Counselling","Take some food or snack with every dose to avoid nausea and vomiting."]],"f25":[{"i":"Nitrofurantoin 100mg tablet (Monohydrate & Macrocrystal Combination)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Nitrofurantoin 100mg tablet → now Nitrofurantoin 100mg tablet (Monohydrate & Macrocrystal Combination)"]],"al":""},{"k":"PHENOXYMETHYLPENICILLIN (Penicillin V)","n":"PHENOXYMETHYLPENICILLIN (Penicillin V)","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.1 Access group antibiotics","moa":"Acid-stable oral penicillin; inhibits cell wall synthesis.","f":[["Indications & dose","Streptococcal infections; tonsillitis, otitis media, erysipelas; Pharyngitis caused by pneumococci and streptococci, gingivostomatitis; pneumococcal infections ADULT: 500 mg PO, Q6H; CHILD (1-11 months): 62.5 mg PO, Q6H; CHILD (1-5 years): 125 mg PO, Q6H; CHILD (6-12 years): 250 mg PO, Q6H. Secondary prophylaxis of rheumatic fever ADULT: 500 mg PO, Q12H; CHILD (1-5 years): 125 mg PO, Q12H; CHILD (6-12 years): 250mg PO, Q12H."],["Cautions","Severe renal impairment, history with asthma, neonates, history of seizure disorders."],["Side effects","Diarrhoea, nausea and vomiting, oral candidiasis, seizures, anaemia, hypersensitivity."],["Renal impairment","CrCl=10-50 mL/minute: Q8-12H; CrCl<10 mL/minute: Q12-16H."],["Pregnancy category","B"],["Breast-feeding","Excreted in breast milk, compatible."],["Counselling","Tablets should be taken at least 30 minutes before, or 2 hours after food."]],"f25":[{"i":"Phenoxymethylpenicillin 250mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CEFIXIME","n":"CEFIXIME","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Oral third-generation cephalosporin; inhibits cell wall synthesis, mainly gram-negative cover.","f":[["Indications & dose","Respiratory tract infection ADULT: 400 mg/day PO, Q24-12H. Otitis media; Pharyngitis/tonsillitis; uncomplicated UTI ADULT: 400 mg/day PO, Q24-12H; CHILD (6-12 months): 8 mg/kg/day PO, Q24-12H, not to exceed 400 mg/day; CHILD (>12 years): 400 mg/day PO, Q24H-12H. Uncomplicated Gonorrhoea ADULT: 400 mg PO once plus azithromycin 1 g PO once (preferred) or alternatively doxycycline 100 mg PO Q12hr for 7 days, if ceftriaxone unavailable."],["Contraindications","Hypersensitivity to beta lactams."],["Cautions","Renal impairment, pregnancy, breast-feeding."],["Side effects","Diarrhoea, colitis, nausea and vomiting, allergic manifestations including rashes, pruritus and urticaria, also fever, arthralgia and anaphylaxis, abdominal discomfort, headache, erythema multiforme, toxic epidermal necrolysis, disturbances in liver enzymes, transient hepatitis and cholestatic jaundice."],["Renal impairment","CrCl=21-60mL/min: 260mg/day; CrCl <20 mL/min: 200 mg."],["Hepatic impairment","Moderate dosage reduction is recommended in severe liver disease."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Cefixime 200mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CEFOTAXIME","n":"CEFOTAXIME","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Third-generation cephalosporin; inhibits cell wall synthesis. Preferred over ceftriaxone in neonates.","f":[["Indications & dose","Infection due to sensitive gram-positive and gram-negative bacteria; Surgical prophylaxis; Haemophilia, Epiglottitis, Meningitis (preferred in neonate and preterm over ceftriaxone) by IM or IV injection, ADULT: 1 g IM or IV injection, Q12H, increased up to 12 g/day, Q6-8H in severe infections; NEONATE: 50 mg/kg/day IM or IV injection, Q6-12H, increased to 150-200 mg/kg/day in severe infections; CHILD: 100-150 mg/kg/day IM or IV injection, Q6-12H, increased up to 200 mg/kg/day in very severe infections."],["Cautions","Penicillin hypersensitivity, renal impairment, false positive urinary glucose if tested for reducing substances, false positive Coombs’ test."],["Side effects","History of colitis, renal impairment, concomitant use with other nephrotoxic medicines."],["Renal impairment","CrCl=10-50 mL/minute: Q8-12H; CrCl<10 mL/minute: Q24H."],["Hepatic impairment","Moderate dosage reduction in severe liver disease."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["IV fluid compatibility","Dextrose 5%, dextrose 5% sodium chloride 0.9%, Compound solution of sodium lactate, sodium chloride 0.9%."]],"f25":[{"i":"Cefotaxime 1g powder for injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CEFTRIAXONE","n":"CEFTRIAXONE","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Third-generation cephalosporin; inhibits cell wall synthesis. Long half-life, good CSF penetration.","f":[["Indications & dose","Meningitis; Pneumonia; Septicaemia ADULT: 1 g deep IM or IV injection over at least 2-4 minutes, or IV infusion, Q24H; 2-4 g, Q24H in severe infections; IM doses over 1 g should be divided to more than one site; NEONATE: 20-50 mg/kg/day IV infusion, Q24H (max. 50 mg/kg/day); CHILD (under 12 years): 0.5-1 g deep IM injection, or by IV injection over 2–4 minutes, Q24H; Doses of 50 mg/kg and over by IV infusion only. Surgical prophylaxis ADULT: 1 g IM or IV injection, STAT administered before 30 minutes of procedure. 250 mg injection: Uncomplicated gonorrhoea 250 mg deep IM injection, STAT."],["Contraindications","Concomitant calcium-ceftriaxone administration."],["Cautions","Dehydration (risk of ceftriaxone precipitation in gallbladder), treatment longer than 14 days, history of GI disease, breast-feeding women."],["Side effects","Induration after IM injection, eosinophilia, thrombocytosis, diarrhoea, rash, pain, induration at IV site, leukopenia."],["Renal impairment","In adults, if eGFR <10 mL/minute/1.73 m²: reduce dose (max. 2 g daily); in children, max. 50 mg/kg daily (max. 2 g/day) in severe renal impairment."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, compatible."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%, water for injection."]],"f25":[{"i":"Ceftriaxone 1g powder for injection vial","v":"V","l":"NRH/RRH","r":""},{"i":"Ceftriaxone 250mg powder for injection vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CIPROFLOXACIN","n":"CIPROFLOXACIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Fluoroquinolone; inhibits DNA gyrase (topoisomerase II) and topoisomerase IV. Bactericidal.","f":[["Indications & dose","Respiratory-tract infections ADULT: 500 mg PO, Q12H; 400 mg IV infusion, Q8-12H administered over 60 minutes; CHILD: 20 mg/kg PO, Q12H (max. per dose 750 mg); 10 mg/kg IV infusion, Q8H (max. per dose 400 mg), administered over 60 minutes. Pseudomonal lower respiratory-tract infection in cystic fibrosis ADULT: 750 mg PO, Q12H; CHILD: 20 mg/kg PO, Q12H (max. per dose 750 mg). Urinary-tract infections ADULT: 25-750 mg PO, Q12H; 400 mg IV infusion, Q8-12H, administered over 60 minutes; CHILD: 10 mg/kg PO, Q12H, dose to be doubled in severe infection (max. 750 mg, Q12H); 6 mg/kg IV infusion, Q8H; increased to 10 mg/kg, Q8H (max. per dose 400 mg), in severe infection. Acute uncomplicated cystitis in women ADULT: 250 mg PO, Q12H x 3 days. Acute or chronic prostatitis ADULT: 500 mg PO, Q12H x 28 days; 400 mg IV infusion, Q8-12H administered over 60 minutes. Anthrax (treatment and post-exposure prophylaxis) ADULT: 500 mg PO, Q12H; 400 mg IV infusion, Q12H administered over 60 minutes; CHILD: 15 mg/kg PO, Q12H (max. per dose 500 mg); 10 mg/kg IV infusion, Q12H (max. per dose 400 mg). Prevention of secondary case of meningococcal meningitis CHILD (1 month-4 years): 30 mg/kg PO, STAT (max. per dose 125 mg); CHILD (5-11 years): 250 mg PO, STAT; CHILD (12-17 years): 500 mg PO, STAT. Other infections ADULT: Initially 500 mg PO, Q12H; increased to 750 mg, Q12H, in severe or deep-seated infection; 400 mg IV infusion, Q8-12H administered over 60 minutes."],["Contraindications","Tendinitis and tendon ruptures, peripheral neuropathy, history of myasthenia gravis."],["Cautions","Acute myocardial infarction, avoid excessive alkalinity of urine, bradycardia, congenital long QT syndrome, electrolyte disturbances, heart failure with reduced left ventricular ejection fraction, history of symptomatic arrhythmias."],["Side effects","Nausea, abdominal pain, diarrhoea, vomiting, headache, rashes; with IV use: flatulence, pain at injection site, phlebitis at injection site."],["Renal impairment","CrCl 30-50 mL/min: 250-500mg PO, Q12H; CrCl 5-29 mL/min: 250-500 mg PO, Q18H or 200-400 mg IV, Q18-24H; Haemodialysis: 0.25-0.5 g PO, Q12H or 0.2-0.4 g IV, Q24H."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, compound solution of calcium lactate, sodium chloride 0.9%."],["Counselling","Advise patients to take medicine 2 hours before or after administration of antacids or products containing iron, calcium and zinc."]],"f25":[{"i":"Ciprofloxacin 0.3% eye drop (5mL)","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Ciprofloxacin 2mg/mL infusion solution (100mL) plastic bottle","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Ciprofloxacin 500mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CLARITHROMYCIN","n":"CLARITHROMYCIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Macrolide; binds 50S subunit (23S rRNA), blocking translocation. Also inhibits CYP3A4.","f":[["Indications & dose","Helicobacter pylori eradication in combination with a proton pump inhibitor and amoxicillin ADULT: 500 mg PO, Q12H x 14 days; CHILD (1-5 years): 7.5 mg/kg PO, Q12H (max. per dose 500 mg); CHILD (6-11 years): 7.5 mg/kg PO, Q12H (max. per dose 500 mg)."],["Contraindications","Hypersensitivity to macrolides, history of QT prolongation and cholestatic jaundice, co-administration with medicines which cause QT prolongation and statins."],["Cautions","Renal impairment, hepatic dysfunction, pregnancy, myasthenia gravis."],["Side effects","General GI effects, Abnormal taste, diarrhoea, nausea and vomiting, abdominal pain, dyspepsia, headache, elevated liver enzymes, jaundice, leukopenia, neutropenia, pancreatitis, QT prolongation, seizures, rashes, Stevens-Johnson syndrome. Renal Impairment CrCl <30 mL/minute, half the normal dose."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."]],"f25":[{"i":"Clarithromycin 500mg tablet","v":"E","l":"NRH/RRH/DH","r":"For eradication of H.pylori only"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ERYTHROMYCIN STEARATE","n":"ERYTHROMYCIN STEARATE","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Macrolide; binds 50S ribosomal subunit, inhibiting translocation. Also a motilin agonist (prokinetic).","f":[["Indications & dose","Susceptible infections in patients with penicillin hypersensitivity (e.g., respiratory-tract infections (including Legionella infection), skin and oral infections, and campylobacter enteritis) ADULT: 250-500 mg PO, Q6H; increased to 500-1000 mg, Q6H in severe infections; CHILD (1 month-1 year): 125 mg PO, Q6H; increased to 250 mg, Q6H in severe infections; CHILD (2-7 years): 250 mg PO, Q6H; increased to 500 mg, Q6H in severe infections."],["Contraindications","Hypersensitivity to macrolides, co-administration with ergotamine and statins, severe hepatic impairment."],["Cautions","Hepatic and renal impairment, ventricular arrhythmias, pregnancy, breastfeeding."],["Side effects","Nausea, vomiting, abdominal discomfort, diarrhoea, urticaria, rashes, reversible hearing loss reported after large doses, cholestatic jaundice."],["Renal impairment","Max. 1.5 g/day (ADULT) in severe renal impairment (ototoxicity)."],["Hepatic impairment","Use with caution."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with cautions."]],"f25":[{"i":"Erythromycin stearate 250mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"NORFLOXACIN","n":"NORFLOXACIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Fluoroquinolone; inhibits DNA gyrase and topoisomerase IV. Mainly for urinary infections.","f":[["Indications & dose","Lower urinary tract infections 400 mg PO, Q12H x 7-10 days (3 days in uncomplicated lower urinary tract infections). Chronic relapsing lower urinary tract infections 400 mg PO, Q12H x 12 weeks; may be reduced to 400 mg, Q24H, if adequate suppression within the first 4 weeks. Chronic prostatitis 400 mg PO, Q12H x 30 days."],["Contraindications","Hypersensitivity to quinolones, all medicines or conditions that prolong QT interval, history of tendon disorders related to quinolone use, children."],["Cautions","Peripheral neuropathy, lactation, moderate renal impairment, history of convulsions, do not exceed the recommended dose, ensure adequate hydration, urinary output."],["Side effects","Nausea, vomiting, dizziness, headache, stomachache, weakness, heartburn, insomnia and seizures, rashes, fever, arthralgia. Renal Impairment CrCl ≤ 30 mL/min: 400 mg, Q24H."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."]],"f25":[{"i":"Norfloxacin 400mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"VANCOMYCIN","n":"VANCOMYCIN","g":"Antibacterial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Glycopeptide; binds D-Ala-D-Ala termini, blocking cell wall polymerisation. Gram-positive only (incl. MRSA).","f":[["Indications & dose","Infections due to Gram-positive bacteria including endocarditis, osteomyelitis, septicaemia and soft-tissue infections ADULT: 1-1.5 g IV infusion, Q12H; ELDERLY: 500 mg IV infusion, Q12H, alternatively 1 g, Q24H; NEONATE (up to 29 weeks corrected gestational age): 15 mg/kg IV infusion, Q24H; NEONATE (29 weeks-35 weeks corrected gestational age): 15 mg/kg IV infusion, Q12H; NEONATE (35 weeks corrected gestational age and above): 15 mg/kg IV infusion, Q8H; CHILD: 15 mg/kg IV infusion, Q8H; max. 2 g/day. Surgical prophylaxis (when high risk of MRSA) ADULT: 1 g IV infusion, STAT."],["Contraindications","History of severe hearing loss."],["Cautions","Rapid IV administration, avoid extravasation, renal impairment, occlusive retinal vasculitis."],["Side effects","Erythematous rash on face and upper body (red man syndrome), chills, peripheral oedema, neutropenia, phlebitis, nephrotoxicity, ototoxicity, Stevens-Johnson syndrome, thrombocytopenia, vasculitis."],["Renal impairment","CrCl>50 mL/min: start with 15-20 mg/kg, Q12H; CrCl=20-49 mL/min: start with 15-20 mg/kg, Q24H; CrCl <20 mL/min: longer intervals."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, dextrose 5% sodium chloride 0.9%, compound solution of sodium lactate, sodium chloride 0.9%."],["Note","Administer vancomycin with final concentration not to exceed 5 mg/mL by IV intermittent infusion over at least 60 minutes. Monitor IV site closely, extravasation will cause serious injury with possible necrosis and tissue sloughing. Rotate infusion sites frequently."]],"f25":[{"i":"Vancomycin 500mg powder for injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CLOFAZIMINE","n":"CLOFAZIMINE","g":"Anti-leprosy.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.3 Anti-leprosy Medicines","moa":"Binds mycobacterial DNA and generates reactive oxygen species; also anti-inflammatory (useful in lepra reactions).","f":[["Indications & dose","Multibacillary leprosy in combination with rifampicin and dapsone ADULT: 300 mg PO, every month and 50 mg, Q24H, alternatively 100 mg, Q48H. Lepromatous lepra reactions ADULT: Increased to 300 mg PO, Q24H x max. 3 months. Severe type II (erythema nodosum leprosum) reactions ADULT: Increased to 100mg PO, Q8H x first month (with subsequent reductions), may take 4-6 weeks to attain full effect; CHILD (under 6 years): 1/4 ADULT dose; CHILD (6-12 years): ½ ADULT dose."],["Cautions","Avoid if persistent abdominal pain and diarrhoea; may discolour soft contact lenses."],["Side effects","Skin discoloration, ichthyosis, rash, pruritus, nausea, vomiting, abdominal pain, headache, tiredness."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Counselling","Urine and saliva become red coloured. Take with or after food."]],"f25":[{"i":"Clofazimine 100mg capsule","v":"V","l":"NRH/RRH/DH","r":"For MDR-TB cases only"},{"i":"Clofazimine 50mg capsule","v":"V","l":"NRH/RRH/DH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"DAPSONE","n":"DAPSONE","g":"Anti-leprosy.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.3 Anti-leprosy Medicines","moa":"Sulfone; inhibits dihydropteroate synthase (folate synthesis) in M. leprae.","f":[["Indications & dose","Multibacillary leprosy in combination with rifampicin and clofazimine; Paucibacillary leprosy in combination with rifampicin ADULT (body weight up to 35 kg): 50 mg PO, Q24H; alternatively, 1-2 mg/kg Q24H; ADULT (body weight 35 kg and above): 100 mg PO, Q24H."],["Contraindications","Acute porphyrias."],["Cautions","Anaemia (treat severe anaemia before starting), cardiac disease, G6PD deficiency, pulmonary disease, susceptibility to haemolysis, hypersensitivity to sulfonamides."],["Side effects","haemolysis, methemoglobinemia, reactional states, insomnia, headache, exfoliative dermatitis, photosensitivity, nausea and vomiting, aplastic and haemolytic anaemia, agranulocytosis, cholestatic jaundice."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."]],"f25":[{"i":"Dapsone 50mg tablet","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"RIFAMPICIN","n":"RIFAMPICIN","g":"Anti-leprosy.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.3 Anti-leprosy Medicines","moa":"Inhibits bacterial DNA-dependent RNA polymerase. Bactericidal; potent CYP450 inducer.","f":[["Indications & dose","Multibacillary leprosy in combination with dapsone and clofazimine); Paucibacillary leprosy in combination with dapsone ADULT: (body weight up to 35 kg): 450 mg PO, every month; ADULT (body weight 35 kg and above): 600 mg PO, every month; CHILD: 10-20 mg/kg PO, Q24H. For details, refer to page no. 50"]],"f25":[{"i":"Rifampicin 150mg tablet","v":"V","l":"NRH/RRH","r":""},{"i":"Rifampicin 300mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ETHAMBUTOL (E)","n":"ETHAMBUTOL (E)","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Inhibits arabinosyl transferase, blocking mycobacterial arabinogalactan cell wall synthesis. Bacteriostatic.","f":[["Indications & dose","Tuberculosis, in combination with other antituberculosis medicines ADULT: 15-25 mg/kg PO every day; CHILD: 15-25 mg/kg PO every day, max. 1200 mg per day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Optic neuritis, use in children, unconscious patients, or any other patient who may be unable to discern and report visual changes."],["Cautions","Elderly and pregnancy."],["Side effects","Pruritus, rash, thrombocytopenia, urticaria, colour blindness, loss of visual acuity, optic neuritis, peripheral neuritis, red/green colour-blindness, restriction of visual fields, visual disturbances."],["Renal impairment","ADULT: CrCl >30 mL/min: 15-25 mg/kg (max. 2.5 g), 3 times a week; CHILD: CrCl >30 mL/minute: 15-25 mg/kg (max. 2.5 g), 3 times a week; Avoid, if possible, renal impairment."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Note","Patients should be advised to discontinue therapy immediately if they develop deterioration in vision and promptly seek further advice."]],"f25":[{"i":"Ethambutol 100mg tablet","v":"V","l":"NRH/RRH","r":""},{"i":"Ethambutol 400mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ETHAMBUTOL(E) + ISONIAZID(H) + PYRAZINAMIDE(Z) + RIFAMPICIN(R) [4 FDC]","n":"ETHAMBUTOL(E) + ISONIAZID(H) + PYRAZINAMIDE(Z) + RIFAMPICIN(R) [4 FDC]","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Fixed-dose combination for TB intensive phase: H blocks mycolic acid synthesis, R blocks RNA polymerase, Z disrupts membrane function in acid pH, E blocks arabinogalactan synthesis.","f":[["Indications & dose","Initial treatment of tuberculosis (intensive phase) ADULT: E 15-25 mg/kg + H 4-6 mg/kg + Z 20-30 mg/kg + R 8-12 mg/kg per day; CHILD: E 15-25 mg/kg (max. 1200 mg) + H 7-15 mg/kg (max. 300 mg) + Z 30-40 mg/kg (max. 2000 mg) + R 10-20 mg/kg (max. 600 mg) per day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Hypersensitivity to any medicines in the combination; medicine induced liver diseases."],["Side effects","Nausea, vomiting, loss of appetite; refer to individual medicine components."],["Hepatic impairment","Use with caution in patients with hepatic impairment; dosage reduction may be necessary."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Counselling","Take the medicine 30 minutes to one hour before food and preferably at the same time of the day consistently."]],"f25":[{"i":"Ethambutol 275mg + Isoniazid 75mg + Pyrazinamide 400mg + Rifampicin 150mg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ETHAMBUTOL(E) + ISONIAZID(H) + RIFAMPICIN(R) [3 FDC]","n":"ETHAMBUTOL(E) + ISONIAZID(H) + RIFAMPICIN(R) [3 FDC]","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Fixed-dose TB combination: isoniazid (mycolic acid synthesis), rifampicin (RNA polymerase) and ethambutol (arabinogalactan synthesis).","f":[["Indications & dose","Treatment of tuberculosis with liver disorder (intensive phase) ADULT: E 15-25 mg/kg + H 4-6 mg/kg + R 8-12 mg/kg per day in combination streptomycin; CHILD: E 15-25 mg/kg (max. 1200 mg) + H 7-15 mg/kg (max. 300 mg) + R 10-20 mg/kg (max. 600 mg) per day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Hepatic impairment, concurrent use with saquinavir/ritonavir and other protease inhibitors."],["Side effects","Nausea, vomiting, loss of appetite; refer to individual medicine components."],["Hepatic impairment","Dose reduction may be necessary to reduce hepatotoxicity."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Counselling","Take the medicine half an hour to one hour before food and preferably at the same time of the day consistently."]],"f25":[{"i":"Ethambutol 275mg tab + Isoniazid 75mg + Rifampicin 150mg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ISONIAZID(H)","n":"ISONIAZID(H)","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Prodrug activated by mycobacterial KatG; inhibits InhA, blocking mycolic acid synthesis. Bactericidal for dividing bacilli.","f":[["Indications & dose","Tuberculosis, in combination with other medicines ADULT: 4-6 mg/kg per day; CHILD: H 7-15 mg/kg (max. 300 mg) per day. Treatment for latent tuberculosis infection ADULTS: 5 mg/kg/day, for 6 months; CHILD: 10 mg/kg/day (range, 7–15 mg/kg/day) max. 300 mg for 6 months. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Cautions","Acute porphyrias, alcohol dependence, diabetes mellitus, epilepsy, history of psychosis, HIV infection, malnutrition, alcohol use."],["Side effects","Peripheral neuropathy, loss of appetite, nausea, vomiting, stomach-ache, weakness, dizziness, slurred speech, lethargy, agranulocytosis, anaemia, megaloblastic anaemia, thrombocytopenia, systemic lupus erythematosus, convulsions."],["Renal impairment","Risk of ototoxicity and peripheral neuropathy; prophylactic pyridoxine hydrochloride recommended."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, compatible."],["Counselling","Take the medicine half an hour to one hour before food and preferably at the same time of the day consistently."]],"f25":[{"i":"Isoniazid 100mg tablet","v":"V","l":"NRH/RRH","r":""},{"i":"Isoniazid 300mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ISONIAZID(H) + PYRAZINAMIDE(Z) + RIFAMPICIN(R) (3 FDC)","n":"ISONIAZID(H) + PYRAZINAMIDE(Z) + RIFAMPICIN(R) (3 FDC)","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Fixed-dose combination: isoniazid (mycolic acid), pyrazinamide (membrane energetics in acidic environment), rifampicin (RNA polymerase).","f":[["Indications & dose","Treatment of tuberculosis (intensive phase) in paediatric patients CHILD: H 7-15 mg/kg (max. 300 mg) + Z 30-40 mg/kg (max. 2000 mg) + R 10-20 mg/kg (max. 600 mg) in combination with ethambutol E 15-25 mg/kg (max. 1200 mg) per day. For details, refer to National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Hepatic impairment, concurrent use with saquinavir/ritonavir and other protease inhibitors."],["Side effects","Nausea, vomiting, loss of appetite; refer to individual medicine components."],["Hepatic impairment","Dose reduction may be necessary to reduce hepatotoxicity."],["Counselling","Take the medicine half an hour to one hour before food and preferably at the same time of the day. Consistently."]],"f25":[{"i":"Isoniazid 50mg + Pyrazinamide 150mg + Rifampicin 75mg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ISONIAZID + RIFAMPICIN (2 FDC)","n":"ISONIAZID + RIFAMPICIN (2 FDC)","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Fixed-dose TB continuation-phase combination: isoniazid blocks mycolic acid synthesis; rifampicin blocks RNA polymerase.","f":[["Indications & dose","Treatment of tuberculosis (continuation phase) ADULT: H 4-6 mg/kg + R 8-12 mg/kg; CHILD: H 7-15 mg/kg (max. 300 mg) + R 10-20 mg/kg (max. 600 mg) per day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Hypersensitivity to the medicines in the combination; hepatic and renal impairment, epilepsy, history of psychosis, alcohol dependence, malnutrition, diabetes."],["Side effects","Nausea and vomiting, skin rash, psychotic problems, depression, seizures, peripheral neuropathy may develop by isoniazid, red or orange urine by rifampicin."],["Hepatic impairment","Use with caution in patients with hepatic impairment; dosage reduction may be necessary."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."]],"f25":[{"i":"Isoniazid 50mg + Rifampicin 75mg tablet","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Isoniazid 60mg + Rifampicin 60mg tablet","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Isoniazid 75mg + Rifampicin 150mg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PYRAZINAMIDE","n":"PYRAZINAMIDE","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Prodrug converted to pyrazinoic acid; disrupts membrane energetics of semi-dormant bacilli in acidic environments.","f":[["Indications & dose","Tuberculosis in combination with other medicines ADULT: 20-30 mg/kg per day; CHILD: 30-40 mg/kg (max. 2000 mg) per day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Cautions","History of alcoholism, renal failure, diabetes, chronic gout."],["Side effects","Anorexia, arthralgia, dysuria, fever, flushing, hepatomegaly, hepatotoxicity, jaundice, liver failure, nausea, photosensitivity, rash, splenomegaly, thrombocytopenia, vomiting."],["Renal impairment","CrCl < 30 mL/min: 25-35 mg/kg/dose."],["Hepatic impairment","Reduce dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Seek medical attention if there are signs of liver disorder: persistent nausea, vomiting, malaise, jaundice."]],"f25":[{"i":"Pyrazinamide 500mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"RIFAPENTINE","n":"RIFAPENTINE","g":"Antituberculosis.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Long-acting rifamycin; inhibits DNA-dependent RNA polymerase. Used weekly with isoniazid (3HP) for TB preventive therapy.","f":[["Indications & dose","Tuberculosis, Active (medicine-susceptible) ADULT Initial phase: 600 mg twice weekly (with an interval ≥72 hours between doses) for 2 months in combination with isoniazid or other anti-tuberculosis agent; Continuation phase: 600 mg once weekly for 4 months in combination with isoniazid or other anti-tuberculosis agent. Tuberculosis, latent ADULT Administer for 3 months in combination with isoniazid, body weight: • 25.1 to 32 kg - 600 mg once weekly • 32.1 to 49.9 kg - 750 mg once weekly • ≥50 kg - 900 mg once weekly Tuberculosis, active pulmonary infection CHILD: Initial phase: 600 mg twice weekly (with an interval ≥72 hours between doses) for 2 months in combination with isoniazid or other anti-tuberculosis agent. Continuation phase: 600 mg once weekly for 4 months in combination with isoniazid or other anti-tuberculosis agent. Tuberculosis, latent infection CHILD (≥2 years and Adolescents): In combination with isoniazid, body weight: • 10 to 14 kg - 300 mg once weekly • 14.1 to 25 kg - 450 mg once weekly • 25.1 to 32 kg - 600 mg once weekly • 32.1 to 49.9 kg - 750 mg once weekly • ≥50 kg - 900 mg once weekly"],["Contraindications","Preexisting porphyria, hypersensitivity to rifamycin’s analog."],["Cautions","If clostridium difficile-associated diarrhoea (superinfection), hypersensitivity or anaphylaxis, and Steven-Johnson syndrome occur, discontinue the therapy. Monitor liver function test prior to therapy and every 2-4 weeks during therapy."],["Side effects","Anaemia, neutropenia, lymphopenia, leukopenia, thrombocytosis, diarrhoea, nausea, vomiting, anorexia, skin rash, increase ALT/AST, headache, arthralgia, proteinuria, pyuria, hematuria, gout, hyperglycemia, relapse of pulmonary tuberculosis, cough, conjunctivitis."],["Hepatic impairment","Pre-existing hepatic problems should have liver function tests; Monitor every 2-4 weeks during therapy. Renal Impairment No dose adjustment necessary."],["Pregnancy category","C"],["Breast-feeding","Outweigh the potential benefits against potential risk of breast-feeding mother before prescribing. Monitor infants exposed to rifapentine for hepatotoxicity such as yellowing eyes, loss of appetite, vomiting and colour change in urine and stool."],["Counselling","Take with/without food. Advise patients for liver function (ALT/AST) test every 2-4 weeks. Remove contact lenses during therapy since permanent staining may occur. Advise breast-feeding mothers of potential risk of rifapentine for their infants. It should be taken under Directly Observed Therapy (DOT) or Self Administration Therapy (SAT). Inform patients about red-orange discoloration skin, teeth, and body fluids. 6.2.4.2 Second line medicines (MDR-TB)"]],"f25":[{"i":"Rifapentine 150mg tablet","v":"V","l":"NRH/RRH/DH","r":"For treatment of latent TB infection (LTBI) only"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"AMIKACIN","n":"AMIKACIN","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Aminoglycoside; binds 30S subunit causing misreading. Resists many aminoglycoside-modifying enzymes.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: 15-20 mg/kg once daily; CHILD: 15-20 mg/kg once daily. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."]],"f25":[{"i":"Amikacin 250mg/mL injection (2mL) vial","v":"V","l":"NRH/RRH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"BEDAQUILINE","n":"BEDAQUILINE","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Diarylquinoline; inhibits mycobacterial ATP synthase. Used in drug-resistant TB.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: (100 mg tablet) 4 tabs of for first 2 weeks, then 2 tabs once day on Monday, Wednesday and Friday for 22 weeks; CHILD: first 14 days, 6 mg/kg/day then 3-4 mg/kg thrice weekly. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."]],"f25":[{"i":"Bedaquiline 100mg tablet","v":"V","l":"NRH/RRH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CYCLOSERINE","n":"CYCLOSERINE","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"D-alanine analogue; inhibits alanine racemase and D-Ala-D-Ala ligase, blocking cell wall synthesis.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: 10-15 mg/kg/day, max. 1 g per day; CHILD: 15-20 mg/kg/day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."]],"f25":[{"i":"Cycloserine 250mg tablet","v":"V","l":"NRH","r":"For MDR-TB cases only"}],"lv":["NRH"],"ch":[],"al":""},{"k":"ETHIONAMIDE","n":"ETHIONAMIDE","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Prodrug activated by EthA; inhibits InhA (mycolic acid synthesis), like isoniazid.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: 15-20 mg/kg, max. 1 g per day; CHILD: 15-20mg/kg/day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Pediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Severe hepatic dysfunction."],["Cautions","Diabetes mellitus, thyroid disease, psychiatric symptoms, alcoholic."],["Side effects","GI disorders, postural hypotension, depression, dizziness, drowsiness, headache, nausea, vomiting, diarrhoea, hepatitis."],["Renal impairment","CrCl <30 mL/min: 250-500 mg/day."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Ethionamide 250mg tablet","v":"V","l":"NRH","r":"For MDR-TB cases only"}],"lv":["NRH"],"ch":[],"al":""},{"k":"LEVOFLOXACIN","n":"LEVOFLOXACIN","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Fluoroquinolone; inhibits DNA gyrase and topoisomerase IV. Better gram-positive and TB activity than ciprofloxacin.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years (30-45 kg body weight): (250 mg) 3 tablets per day; 46-to >70 kg body: 4 tablets, max. 1.5 g per day; CHILD: 15-20mg/kg/day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Hypersensitivity to quinolones."],["Cautions","G-6-PD deficiency, moderate to severe hepatic and renal failure, seizures, pregnancy and breast-feeding exposure to strong sunlight and UV light."],["Side effects","Constipation, flatulence, hyperhidrosis, dyspnoea."],["Renal impairment","For normal renal function dosing of 750 mg/day CrCl 20-49 mL/min: 750 mg, Q48H; CrCl 10-19 mL/min: 750 mg initial dose, then 500 mg, Q48H; Normal renal function dosing of 500 mg/day CrCl 20-49 mL/min: 500 mg initial dose, then 250 mg, Q24H; CrCl 10-19 mL/min: 500 mg initial dose, then 250 mg, Q48H; Normal renal function dosing of 250 mg/day CrCl 20-49 mL/min: No dose adjustment required; CrCl 10-19 mL/min: 250 mg, Q48H (except in uncomplicated UTI, where no dosage adjustment is required)."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."]],"f25":[{"i":"Levofloxacin 250mg tablet","v":"V","l":"NRH/RRH/DH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"LINEZOLID","n":"LINEZOLID","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Oxazolidinone; binds 23S rRNA of the 50S subunit, preventing initiation complex formation.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years (30-45 kg body weight): dose ???; 46-to >70 kg body: (600 mg tablet) 1 tablet, max. 1.2 g per day; CHILD: < 16 kg body weight: 15 mg/kg once daily; >16 kg body weight: 10-12mg/kg/day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."]],"f25":[{"i":"Linezolid 600mg tablet","v":"V","l":"NRH/RRH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"MOXIFLOXACIN","n":"MOXIFLOXACIN","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Fluoroquinolone; inhibits DNA gyrase and topoisomerase IV. Respiratory and TB activity.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: (400 mg tablet) 1 tablet per day, max. 400 mg per day; CHILD: 10-15mg/kg/day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Paediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Contraindications","Hypersensitivity to quinolone group of antibiotics, acute myocardial infarction, bradycardia, congenital long QT syndrome, electrolyte disturbances, heart failure with reduced left ventricular ejection fraction, history of symptomatic arrhythmias."],["Cautions","Risk of tendon inflammation or rupture with concurrent corticosteroid, organ transplant recipients and in patients more than 60 years old."],["Side effects","Nausea, diarrhoea, dizziness, immune hypersensitivity reaction, prolonged QT interval."],["Hepatic impairment","No dosage adjustment required, use with caution in severe hepatic impairment."],["Pregnancy category","C"],["Counselling","Use sunscreen and protective clothing and avoid excessive exposure to sunlight. Take the medicine at least 4 hours before or 8 hours after products containing iron, zinc, magnesium, or aluminium."]],"f25":[{"i":"Moxifloxacin 0.5% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"},{"i":"Moxifloxacin 400mg tablet","v":"V","l":"NRH/RRH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Moxifloxacin 0.5% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"PARA-AMINOSALICYLATE SODIUM","n":"PARA-AMINOSALICYLATE SODIUM","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Folate antagonist in mycobacteria (competes with para-aminobenzoic acid). Bacteriostatic.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: 8-12 g/day in 2-3 divided doses, max. 12 g; CHILD: 200 mg/kg/day. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update and National Guidelines for Management of Pediatric Tuberculosis in Bhutan 2nd Edition December 2020."],["Cautions","Gastric ulcer, hepatic and renal impairment, sensitivity to tartrazine dyes, nasal polyps, and asthma."],["Side effects","Pericarditis, vasculitis, encephalopathy, fever, skin eruptions, goitre, hypoglycaemia, abdominal pain, diarrhoea, nausea, vomiting, agranulocytosis, anaemia (haemolytic), leukopenia, thrombocytopenia, hepatitis, jaundice, optic neuritis, eosinophilic pneumonia. Renal Impairment CrCl 10-50 mL/min: 50 - 75% of dose; CrCl <10 mL/min: 50% of dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Counselling","GI disturbances may be minimised by taking the medicine with or after meals or with an antacid."]],"f25":[{"i":"Para-aminosalicylate sodium 60% w/w delayed release granules (4g) sachet","v":"V","l":"NRH/RRH/DH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"STREPTOMYCIN","n":"STREPTOMYCIN","g":"Anti-tuberculosis in MDR-TB.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.4 Antituberculosis Medicines","moa":"Aminoglycoside; binds 30S subunit causing misreading of mRNA.","f":[["Indications & dose","Medicine-resistant tuberculosis in combination with other medicines ADULT and > 14 years: 12-18 mg/kg, max. 1 g. For details, refer to Integrated National Guidelines for Management of Tuberculosis in Bhutan 7th Edition December 2020 Update."],["Contraindications","Pregnancy, myasthenia gravis."],["Cautions","Use with caution to patients with pre-existing renal, vestibular or auditory problems, infants and the elderly."],["Side effects","Pain at the injection site, ototoxicity (vestibular and auditory damage), nephrotoxicity, electrolyte, vertigo, tinnitus, imbalance, rarely, allergic reactions."],["Renal impairment","Should preferably be avoided; If essential, CrCl 10-50 mL/min: Q24-72H; CrCl <10 mL/min: Q72-96H."],["Hepatic impairment","Use with caution."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, avoid."],["Note","IV administration is not recommended."]],"f25":[{"i":"Streptomycin 1g powder for injection vial","v":"V","l":"NRH/RRH","r":"For MDR-TB cases only"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"AMPHOTERICIN B","n":"AMPHOTERICIN B","g":"Antifungal.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.3 Antifungals medicines","moa":"Polyene; binds ergosterol in fungal membranes, forming pores that leak ions. Fungicidal.","f":[["Indications & dose","Systemic fungal infection LIPOSOMAL ADULT: 3 mg/kg IV infusion, Q24H, max. 5 mg/kg/day; CHILD: 3mg/kg IV infusion, Q24H, max. 5mg/kg/day. Cryptococcal meningitis LIPOSOMAL ADULT: 6 mg/kg/day IV infusion; CHILD: same as adult dose. Visceral leishmaniasis LIPOSOMAL: Immunocompetent patients ADULT: 3 mg/kg IV infusion, Q24H on days 1-5, 14 and 21; CHILD: same as adult; Immunocompromised patients ADULT: 4 mg/kg IV infusion, Q24H on days 1-5, 10, 17, 24, 31 and 38; CHILD: same as adult."],["Cautions","Avoid rapid infusion, co-administration with other medicines that cause hypokalemia and other nephrotoxic medicines."],["Side effects","Abdominal pain, abnormal liver function (discontinue treatment), anaemia, arrhythmias, blood disorders, blood pressure changes, cardiovascular effects, chest pain, diarrhoea, disturbances in renal function, dyspnoea, electrolyte disturbances, febrile reactions, headache, hypokalaemia, hypomagnesaemia, nausea, rash, renal tubular acidosis, thrombocytopenia, vomiting."],["Renal impairment","Use only if no alternative, nephrotoxicity may be reduced with use of liposomal formulation."],["Pregnancy category","B"],["Breast-feeding","Excretion in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5%."],["Note","Liposomal formulation to be used in severe systemic or deep mycoses where toxicity precludes the use of conventional formulation. Liposomal formulation is contraindicated in children under 1 month of age. Test dose of 1 mg should be given over 15 minutes."]],"f25":[{"i":"Amphotericin B 50mg liposomal powder for injection (with microfilter) vial","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CLOTRIMAZOLE","n":"CLOTRIMAZOLE","g":"Antifungal (vaginal insert).","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.3 Antifungals medicines","moa":"Imidazole; inhibits fungal lanosterol 14-alpha-demethylase, blocking ergosterol synthesis.","f":[["Indications & dose","Vaginal Candidiasis Pessary by vagina, 100 mg, Q12H x 3 days or 100 mg, before bedtime x 6 nights."],["Side effects","Occasionally, local irritation or mild inflammation."],["Pregnancy category","B"],["Counselling","Place the pessary high up the vagina just before you go to sleep."]],"f25":[{"i":"Clotrimazole 100mg viginal tablet with applicator","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Clotrimazole 100mg vaginal tablet with applicator → now Clotrimazole 100mg pessary, Pack of 6 with applicator"]],"al":""},{"k":"FLUCONAZOLE","n":"FLUCONAZOLE","g":"Antifungal (triazole).","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.3 Antifungals medicines","moa":"Triazole; inhibits fungal CYP51 (14-alpha-demethylase), blocking ergosterol synthesis. Good CSF penetration.","f":[["Indications & dose","Systemic mycoses ADULT: 200 mg daily up to 6 months; CHILD over 2 years: 3-6 mg/kg daily up to 6 months. Cryptococcal meningitis ADULT: 400 mg on Day 1, then 200 mg daily for up to 8 weeks; CHILD: 6 -12 mg/kg daily for up to 8 weeks (every 72 hours in neonate up to 2 weeks old). Prophylaxis of cryptococcal meningitis in immunocompromised patients: 200 mg daily. Systemic candidiasis: 200 mg daily for up to 4 weeks; CHILD: 6-12 mg/kg daily (every 72 hours in NEONATE up to 2 weeks old). Oesophageal and oropharyngeal candidiasis ADULT: 200 mg on Day 1, then 100 mg daily for until symptoms resolve; CHILD: 6 mg/kg on day 1, followed by 3 mg/kg daily (every 72 hours in NEONATE up to 2 weeks old). Vaginal candidiasis ADULT: 150 mg as a single dose."],["Contraindications","concurrent use of medicines that cause QT prolongation."],["Cautions","hypersensitivity to other azoles, proarrhythmic conditions, hepatic, renal impairment."],["Side effects","nausea, vomiting, flatulence and diarrhoea, headache, taste disturbances, dizziness, seizure, alopecia pruritus, rash, toxic epidermal necrolysis and Stevens-Johnson syndrome, hyperlipidaemia, leukopenia, thrombocytopenia, hypokalaemia."],["Renal impairment","For multiple dosing, administer usual load then adjust daily doses as follows. CrCl ≤50 mL/minute: administer 50% of recommended dose or administer every 48 hours."],["Pregnancy category","C"],["Breast-feeding","Excrete in breast milk, not recommended."],["Counselling","Take with or after food. take at regular intervals and complete the full course."]],"f25":[{"i":"Fluconazole 0.3% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"},{"i":"Fluconazole 100mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Fluconazole 0.3% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"],["Extended in 2025","Fluconazole 100mg tablet: now supplied down to DH"]],"al":""},{"k":"GRISEOFULVIN","n":"GRISEOFULVIN","g":"Antifungal.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.3 Antifungals medicines","moa":"Binds fungal tubulin, disrupting mitotic spindle; deposits in keratin precursor cells.","f":[["Indications & dose","Dermatophyte infections of the skin, scalp, hair and nails where topical therapy has failed or is inappropriate ADULT: 500 mg PO, Q24H, alternatively 1 g PO, Q24H; higher dose for severe infections, reduce dose when response occurs; CHILD (1 month-11 years): 10 mg/kg/day (max. 500 mg/dose), increased if necessary to 20 mg/kg/day (max. 1 g/dose) for severe infections. Tinea capitis caused by Trichophyton tonsurans ADULT: 1 g PO, Q24H; alternatively, 1 g/day in divided doses; CHILD (1 month-11 years): 15-20 mg/kg PO, Q24H (max. 1 g/dose)."],["Contraindications","Severe liver disease, lupus erythematosus and related conditions, porphyria and pregnancy."],["Cautions","Pregnancy, intense exposure to sunlight."],["Side effects","Headache, nausea, vomiting, rashes, photosensitivity, dizziness, fatigue, leukopenia, systemic lupus erythematosus, erythema multiforme, toxic epidermal necrolysis, peripheral neuropathy, and confusion."],["Hepatic impairment","Avoid in severe liver disease."],["Pregnancy category","C"],["Breast-feeding","Avoid."],["Note","Long courses of treatment are needed (6 weeks for skin; 3 months for nails infections). Effective contraception required during and for at least 1 month after administration to women (important: effectiveness of oral contraceptives may be reduced, additional contraceptive precautions e.g. barrier method, required); Men should avoid fathering a child during and for at least 6 months after administration."],["Counselling","Take with or after food. Take at regular intervals and complete the full course."]],"f25":[{"i":"Griseofulvin 250mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"MICONAZOLE","n":"MICONAZOLE","g":"Antifungal (topical).","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.3 Antifungals medicines","moa":"Imidazole; inhibits ergosterol synthesis (14-alpha-demethylase).","f":[["Indications & dose","Susceptible fungal infection of skin and mucous membrane by topical application, apply thin layer over infected area twice daily for two to four weeks depending on severity."],["Cautions","For topical use only, avoid contact with eyes."],["Side effects","Occasional irritation, burning, allergic dermatitis, maceration."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","Treatment should be prolonged for 10 days after all lesions have disappeared to prevent relapse."]],"f25":[{"i":"Miconazole 2% cream (15g) tube","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"NYSTATIN","n":"NYSTATIN","g":"Antifungal.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.3 Antifungals medicines","moa":"Polyene; binds ergosterol and forms membrane pores. Not absorbed orally, so used topically/in the gut.","f":[["Indications & dose","Intestinal candidiasis ADULT: 500,000 -1,000,000 units PO, Q6H, double in severe infections; Oral candidiasis NEONATE and INFANT: 1 mL topically in mouth, Q6H after meals; CHILD and ADULT: 1 mL swish in the mouth and retain for as long as possible before swallowing, Q6H."],["Side effects","Nausea, vomiting, stomach pain, diarrhoea."],["Pregnancy category","C (Oral paint)."],["Breast-feeding","Excretion in milk unknown, use with caution."]],"f25":[{"i":"Nystatin 500,000IU Immediate-release tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Nystatin 500,000IU Immediate-release tablet: now supplied down to PHC"],["Specification changed in 2025","Nystatin 500,000IU tablet → now Nystatin 500,000IU Immediate-release tablet"]],"al":""},{"k":"ACYCLOVIR","n":"ACYCLOVIR","g":"Anti-herpes.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.1 Anti-herpes medicines","moa":"Guanosine analogue phosphorylated by viral thymidine kinase; inhibits viral DNA polymerase and terminates the DNA chain.","f":[["Indications & dose","Herpes simplex, suppression ADULT and CHILD (12-17 years): 400 mg PO, Q12H; increased to 400 mg, Q8H; dose may be increased if recurrences occur on standard suppressive therapy or for suppression of genital herpes during late pregnancy (from 36 weeks’ gestation), therapy interrupted every 6-12 months to reassess recurrence frequency, consider restarting after two or more recurrences. Herpes simplex, prophylaxis in the immunocompromised ADULT: 200-400 mg PO, Q6H; CHILD (1 month-1 year): 100-200 mg PO, Q6H; CHILD (2-17 years): 200-400 mg PO, Q6H; ADULT: 5 mg/kg IV every 8 hours for 5 to 7 days. Herpes simplex (non-genital); Herpes simplex, (non-genital) in immunocompromised or if absorption impaired ADULT: 200 mg PO, Q4H x 5 days (longer if new lesions appear during treatment or if healing incomplete). Herpes simplex, treatment; Herpes Simplex, treatment in immunocompromised or if absorption impaired CHILD (1 month-23 months): 100 mg PO, Q4H x 5 days; CHILD (2-17 years): 200 mg PO, Q4H x 5 days; Longer duration if new lesions appear during treatment or if healing incomplete. Genital herpes simplex, treatment of first episode ADULT: 400 mg PO, Q8H x 5 days (400 mg, 5 times a day for 7-10 days for immunocompromised). Genital herpes simplex, treatment of recurrent infection ADULT: 800 mg PO, Q8H x 2 days (for 5-10 days in immunocompromised patients). Severe genital herpes simplex, initial infection treatment of herpes simplex in the immunocompromised ADULT: Initially 5 mg/kg IV every 8 hours for 5 days, alternatively 10 mg/kg every 8 hours for at least 14 days in encephalitis (at least 21 days if also immunocompromised). Herpes simplex encephalitis CHILD: 3 months-12 years 20 mg/kg IV every 8 hours for 10 days; ≥ 12 years and ADULT: 10 mg/kg IV every 8 hours for 10 days. Herpes simplex mucocutaneous CHILD: 3 months-12 years 10 mg/kg IV every 8 hours for 7 days; ≥ 12 years and ADULT (immunocompromised): 5 mg/kg IV every 8 hours for 7 days. Varicella zoster (chickenpox), treatment; Herpes zoster (shingles), treatment ADULT: 800 mg PO, Q4H (5 times daily) x 7 days; CHILD (1 month-1 year): 200 mg PO, Q6H x 5 days; CHILD (2-5 years): 400 mg PO, Q6H x 5 days; CHILD (6-11 years): 800 mg PO, Q6H x 5 days; ADULT: 5 mg/kg IV every 8 hours for 5 days. Varicella zoster (chickenpox), treatment; Herpes zoster (shingles), treatment in immunocompromised ADULT: 10 mg/kg IV every 8 hours for 5 days. Herpes zoster (shingles), treatment in immunocompromised ADULT: 800 mg PO, Q4H (5 times daily) continued for 2 days after crusting of lesions; CHILD (1 month-1 year): 200 mg PO, Q6H continued for 2 days after crusting of lesions; CHILD (2-5 years): 400 mg PO, Q6H continued for 2 days after crusting of lesions; CHILD (6-11 years): 800 mg, PO, Q6H continued for 2 days after crusting of lesions. Herpes zoster, treatment in encephalitis; Varicella zoster, treatment in encephalitis ADULT and CHILD: 10 mg/kg PO, Q6H x 7 days, to be started 1 week after exposure; ADULT: 10 mg/kg IV every 8 hours for 10–14 days, possibly longer in immunocompromised or if severe infection."],["Cautions","Renal failure, elderly, maintain adequate hydration, immunocompromised patient, patient on nephrotoxic medicines."],["Side effects","Malaise, nausea, vomiting, diarrhoea, headache, abdominal pain, fatigue, pruritus, rashes, urticaria."],["Renal impairment","ORAL CrCl 10-25 mL/minute/1.73 m²: if normal dosing regimen 800 mg every 4 hours: administer 800 mg every 8 hours; CrCl <10 mL/minute/1.73 m²: if normal dosing regimen 200 mg every 4 hours, 200 mg every 8 hours, or 400 mg every 12 hours: administer 200 mg every 12 hours; if normal dosing regimen 800 mg every 4 hours: administer 800 mg every 12 hours. INTRAVENOUS CrCl 25-50 mL/minute/1.73 m²: administer recommended dose every 12 hours; CrCl 10-25 mL/minute/1.73 m²: administer recommended dose every 12 hours; CrCl <10 mL/minute/1.73 m²: administer 50% recommended dose every 24 hours."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Note","Avoid rapid infusion, infuse over 1 hour to prevent renal damage. Maintain adequate hydration of patients. Check for phlebitis and rotate infusion sites. Avoid I.M. or Subcutaneous administration."]],"f25":[{"i":"Acyclovir 3% eye ointment (5g) tube","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Acyclovir 400mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Acyclovir 500mg lyophilised powder for injection vial","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Acyclovir 3% eye ointment (5 g) tube: now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"ABACAVIR","n":"ABACAVIR","g":"Antiretroviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"NRTI (guanosine analogue); terminates viral DNA chain by inhibiting reverse transcriptase. HLA-B*5701 linked hypersensitivity.","f":[["Indications & dose","Treatment of HIV infections in combination with other antiretroviral agents ADULT: 300 mg twice daily or 600 mg once daily; CHILD (3 months to 16 years): 8 mg/kg body weight twice daily (max: 300 mg twice daily) in combination with other antiretroviral agents. For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Contraindications","Patients who are HLA-B*5701-positive, moderate or severe hepatic impairment."],["Cautions","Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, reported with nucleoside analogs, including abacavir, most of these cases have been in women, female gender and obesity may be risk factors, suspend dosing in those who develop clinical or laboratory findings suggestive of lactic acidosis or pronounced hepatotoxicity."],["Side effects","Nausea, headache, malaise/fatigue, Hypersensitivity reaction, diarrhoea, musculoskeletal pain, hypertriglyceridemia, hepatic: AST increased, depression, fever/chills, viral respiratory and ear/nose/throat infections rash, anxiety."],["Renal impairment","No dose adjustment required."],["Hepatic impairment","Mild dysfunction (Child-Pugh score 5-6): 200 mg twice daily (oral solution is recommended). Moderate-to-severe dysfunction: use is contraindicated."],["Counselling","May be taken with or without food. If you miss a dose, take it as soon as you remember. If it is near the time of the next dose, skip the missed dose. Take your next dose at the regular time. Do not double the dose to catch up."]],"f25":[{"i":"Abacavir 20mg/mL syrup (240mL) bottle","v":"V","l":"NRH/RRH","r":""},{"i":"Abacavir 300mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Abacavir/Lamivudine/Dolutegravir 60mg/30mg/5mg table added (Till DH). Reason: A pediatric-specific ABC/DTG/3TC FDC regimen, aligned with WHO 2021 recommendations, improves dosing accuracy, palatability, and adherence while reducing pill burden and the risks associated with compounded alternative second-line regimens."]],"al":""},{"k":"LAMIVUDINE (3TC)","n":"LAMIVUDINE (3TC)","g":"Antiretroviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"NRTI (cytidine analogue); inhibits HIV and hepatitis B reverse transcriptase, terminating DNA chains.","f":[["Indications & dose","HIV infection in combination with other antiretroviral medicines ADULT: 150 mg PO twice daily or 300 mg PO once daily; CHILD (Neonates): 2 mg/kg PO Q12hr; ≥ 1 month: 4 mg/kg PO Q12hr; ≥ 3 months: 5 mg/kg PO Q12. For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Cautions","Renal impairment, obesity, history of pancreatitis in children, hepatic decompensation, anaemia, neutropenia."],["Side effects","Cough, fatigue and malaise, fever, musculoskeletal pain, headache, nausea, diarrhoea, abdominal pain and insomnia, peripheral neuropathy."],["Renal impairment","CrCl 30-49 mL/min: 50 mg, Q24H; CrCl 15-29 mL/min: 150 mg first dose, then 100 mg, Q24H; CrCl 5-14 mL/min: 150 mg first dose, then 50 mg, Q24H; CrCl <5 mL/min: 50 mg first dose, then 25 mg, Q24H."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."]],"f25":[{"i":"Lamivudine 10mg/mL syrup (240mL) bottle","v":"V","l":"NRH/RRH","r":""},{"i":"Lamivudine 150mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Abacavir/Lamivudine/Dolutegravir 60mg/30mg/5mg table added (Till DH). Reason: A pediatric-specific ABC/DTG/3TC FDC regimen, aligned with WHO 2021 recommendations, improves dosing accuracy, palatability, and adherence while reducing pill burden and the risks associated with compounded alternative second-line regimens."]],"al":""},{"k":"ZIDOVUDINE (AZT)","n":"ZIDOVUDINE (AZT)","g":"Antiretroviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"NRTI (thymidine analogue); inhibits HIV reverse transcriptase and terminates DNA chains.","f":[["Indications & dose","HIV infection in combination with other antiretroviral medicines ADULT: 300 mg PO twice daily; CHILD (Birth to 4 weeks): 4mg/kg PO Q12hr; >4 weeks: 12 mg/kg PO Q12hr. For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Contraindications","Acute porphyria, abnormally low haemoglobin concentration, abnormally low neutrophil counts."],["Side effects","Anaemia, anorexia, diarrhoea, fever, granulocytopenia, severe headache, leukopenia, nausea, pain, rash, vomiting, weakness, hyperpigmentation of nails (bluish brown)."],["Renal impairment","Reduce oral dose to 300-400 mg/day in divided doses."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid. 6.4.2.2 Non-Nucleoside Reverse Transcriptase Inhibitors (NNRTIs)"]],"f25":[{"i":"Zidovudine 10mg/mL syrup (240mL) bottle","v":"V","l":"NRH/RRH","r":""},{"i":"Zidovudine 300mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"EFAVIRENZ (EFV)","n":"EFAVIRENZ (EFV)","g":"Antiretroviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"NNRTI; binds an allosteric pocket of HIV-1 reverse transcriptase, non-competitively inhibiting it.","f":[["Indications & dose","HIV infection in combination with other antiretroviral medicines ADULT: 400 mg PO hs once daily; CHILD (body weight base): • 3.5 - < 5 kg: 100 mg Q24hr • 5 - < 7.5 kg: 150 mg Q24hr • 7.5 - < 15 kg: 200 mg Q24hr • 15 - < 20 kg: 250 mg Q24hr • 20 - < 25 kg: 300 mg Q24hr • 25 - < 32.5 kg: 350 mg Q24hr • 32.5 - < 40 kg: 400 mg Q24hr • ≥ 40 kg: 600 mg Q24hr For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Cautions","Acute porphyrias, elderly, history of psychiatric disorders, history of seizures."],["Side effects","Total cholesterol increased; diarrhoea, HDL increased, dizziness, rash, fever, depression, insomnia, cough, vomiting, anxiety, nausea."],["Hepatic impairment","Not recommended in moderate to severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excretion in milk unknown, avoid."],["Counselling","Take on an empty stomach preferably at bedtime. Tablets should not be broken. 6.4.2.3 Protease Inhibitors"]],"f25":[],"lv":["NRH","RRH"],"ch":[["Deleted in 2025","Efavirenz 200mg tablet removed (was available RRH). Reason: Efavirenz-based regimens are no longer recommended due to treatment failures and there are no patients on an efavirenz-containing regimen"]],"al":""},{"k":"LOPINAVIR/RITONAVIR (LPV/r)","n":"LOPINAVIR/RITONAVIR (LPV/r)","g":"Antiretroviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"Lopinavir inhibits HIV protease (prevents polyprotein cleavage); low-dose ritonavir boosts it by inhibiting CYP3A4.","f":[["Indications & dose","Treatment of HIV infection in combination with other antiretroviral agents ADULT: 400 mg/100 mg (LPV/r) PO twice daily; CHILD 7 - <15 kg: 12 mg/kg/dose Q12hr based on lopinavir component; 15 – 40 kg: 10 mg/kg/dose Q12hr based on lopinavir component; > 40 kg: same as adults. For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Contraindications","Co-administration with medications highly dependent upon CYP3A4 for clearance, co-administration with strong CYP3A4 inducers."],["Cautions","Cardiac conduction disorders, pancreatitis, patients at high risk of cardiovascular disease (especially if 10-year cardiovascular risk greater than 20%), structural heart disease."],["Side effects","Diarrhoea, nausea, rash, headache, weakness, abdominal pain, insulin resistance, fat accumulation and hyperlipidaemia, elevated transaminase (SGOT and SGTP)."],["Renal impairment","Use with caution."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, avoid. 6.4.2.4 Integrase inhibitors"]],"f25":[{"i":"Lopinavir 200mg + ritonavir 50mg tablet","v":"V","l":"NRH/RRH","r":""},{"i":"Lopinavir/ritonavir (80mg+20mg)/mL syrup (160mL) bottle","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"DOLUTEGRAVIR (DTG)","n":"DOLUTEGRAVIR (DTG)","g":"Antiretroviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"Integrase strand-transfer inhibitor; blocks integration of HIV DNA into host DNA.","f":[["Indications & dose","HIV infection without resistance to other integrase inhibitors, in combination with other antiretrovirals ADULT 50 mg PO once daily; CHILD (12-17 years, body weight > 40 kg) 50 mg PO once daily. HIV infection in patient resistance to other integrase inhibitors is suspected, in combination with other antiretrovirals ADULT 50 mg PO twice daily. HIV non-occupational exposure; prophylaxis (initiate therapy within 72 hours of exposure) ADULT: 50 mg PO once daily, in combination with emtricitabine 200 mg or tenofovir disoproxil fumarate 300 mg PO once daily, treatment duration is 28 days. HIV infection in combination with other antiretrovirals in patients with concomitant enzyme inducers CHILD (12-17 years, body weight > 40 kg): 50 mg PO twice daily. HIV infection in 4 weeks and older, body weight (Tablet for oral suspension): • 3 kg to < 6 kg: 5 mg PO once daily • 6 kg to <10 kg: 15 mg PO once daily • 10 kg to <14 kg: 20 mg PO once daily • 14 kg to < 20 kg: 25 mg PO once daily or 40 mg PO once daily (film coated tablet) • >20 kg: 30 mg PO once daily or 50 mg PO once daily (film coated tablet)."],["Contraindications","Concomitant use with dofetilide, hypersensitivity to dolutegravir, woman planning to become pregnant and first trimester."],["Cautions","Hepatitis B and C, severe hepatic impairment-not recommended, severe renal impairment."],["Side effects","Anxiety, depression, diarrhea, dizziness, fatigue, flatulence, gastrointestinal discomfort, headache, nausea, skin reactions, osteonecrosis, sleep disorders, arthralgia, hepatic disorders, hypersensitivity, immune reconstitution inflammatory syndrome, myalgia, suicidal tendencies."],["Pregnancy category","X"],["Breast-feeding","Excreted in milk in animal studies. Infant risk cannot be ruled out, instruct mothers not to breastfeed if they are receiving this therapy."],["Note","Do not interchange tablets and tablets for oral suspension on a mg-per-mg basis. Dose must be adjusted for the new dosage formulation if switching from one formulation to the other."],["Counselling","Administer at least 2 hours before or 6 hours after taking cation-containing antacids or laxatives. Advised woman of childbearing potential to use effective contraception. Perform pregnancy test before initiation of Dolutegravir. Missed dose: If a dose is more than 20 hours late on the once daily regimen (or more than 8 hours late on the twice daily regimen), the missed dose should not be taken and the next dose should be taken at the normal time. 6.4.2.5 Fixed-dose combinations"]],"f25":[{"i":"Dolutegravir 50mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Abacavir/Lamivudine/Dolutegravir 60mg/30mg/5mg table added (Till DH). Reason: A pediatric-specific ABC/DTG/3TC FDC regimen, aligned with WHO 2021 recommendations, improves dosing accuracy, palatability, and adherence while reducing pill burden and the risks associated with compounded alternative second-line regimens."]],"al":""},{"k":"DOLUTEGRAVIR (DTG) + LAMIVUDINE (3TC) + TENOFOVIR (TDF)","n":"DOLUTEGRAVIR (DTG) + LAMIVUDINE (3TC) + TENOFOVIR (TDF)","g":"Antiretroviral (3-FDC).","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"TLD: integrase inhibitor (dolutegravir) plus two NRTIs (lamivudine, tenofovir) that terminate viral DNA chains.","f":[["Indications & dose","Treatment of HIV infection in combination with other antiretroviral agents ADULT: DTG 50 mg PO once daily; 3TC 150 mg PO twice daily or 300 mg PO once daily; TDF 300 mg once daily; CHILD: DTG (12-17 years, body weight > 40 kg): 50 mg PO once daily; 3TC (Neonates): 2 mg/kg PO Q12hr; ≥ 1 month: 4 mg/kg PO Q12hr; ≥ 3 months: 5 mg/kg PO Q12; TDF not recommended in child age < 10 years. For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Contraindications","as under individual medicines."],["Cautions","as under individual medicines."],["Side effects","as under individual medicines. Renal/ hepatic impairment as under individual medicines."],["Pregnancy category","as under individual medicines."],["Breast-feeding","as under individual medicines."],["Counselling","Take after meals at regular intervals."]],"f25":[{"i":"Dolutegravir 50mg + Lamivudine 300mg + Tenofovir 300mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"LAMIVUDINE (3TC) + TENOFOVIR (TDF)","n":"LAMIVUDINE (3TC) + TENOFOVIR (TDF)","g":"Antiretroviral (2-FDC).","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"Two NRTIs: cytidine analogue (lamivudine) and nucleotide adenosine analogue (tenofovir) inhibiting reverse transcriptase.","f":[["Indications & dose","Treatment of HIV infection in combination with other antiretroviral agents; Pre exposure prophylaxis (PrEP) ADULT: 3TC 150 mg PO twice daily or 300 mg PO once daily; TDF 300 mg once daily; CHILD: 3TC (Neonates): 2 mg/kg PO Q12hr; ≥ 1 month: 4 mg/kg PO Q12hr; ≥ 3 months: 5 mg/kg PO Q12; TDF not recommended in child age < 10 years. For details, refer to National Guidelines on Treatment & Management of HIV & AIDS 3rd edition 2020."],["Contraindications","as under individual medicines."],["Cautions","as under individual medicines."],["Side effects","as under individual medicines."],["Renal impairment","as under individual medicines."],["Pregnancy category","as under individual medicines."],["Breast-feeding","as under individual medicines."]],"f25":[{"i":"Lamivudine 300mg + Tenofovir 300mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"TENOFOVIR","n":"TENOFOVIR","g":"Antiviral.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.3 Anti-hepatitis medicines","moa":"Nucleotide reverse transcriptase inhibitor (adenosine analogue); inhibits HIV and HBV polymerase.","f":[["Indications & dose","Chronic hepatitis B infection ADULT 300 mg PO, Q24H."],["Cautions","Hepatic impairment, lactic acidosis, renal impairment, elderly patient."],["Side effects","Pruritus, rash, nausea, abdominal pain, vomiting, dizziness, insomnia, fever, lactic acidosis, hepatomegaly, angioedema."],["Renal impairment","CrCl 30-49 mL/min: 300 mg, Q48H; CrCl 10-29 mL/min: 300 mg, Q72-96H; CrCl <10 mL/min: no recommendation available; avoid."],["Pregnancy category","B"],["Breast-feeding","Excretion in milk unknown, avoid."]],"f25":[{"i":"Tenofovir 300mg tablet","v":"V","l":"NRH/RRH","r":"For Hepatitis B infections only"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ARTHEMETHER + LUMEFANTRINE","n":"ARTEMETHER + LUMEFANTRINE","g":"Antimalarial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.5.3 Antimalarials medicines","moa":"Artemether's endoperoxide bridge, activated by haem iron, generates free radicals that kill parasites rapidly. Lumefantrine blocks haem detoxification and clears remaining parasites.","f":[["Indications & dose","Treatment of acute uncomplicated falciparum malaria (except pregnant women in their first trimester) chloroquine-resistant non-falciparum malaria ADULT and CHILD: a total dose of 5–24 mg/kg body weight of artemether and 29–144 mg/ kg body weight of lumefantrine. Recommended dosage regimen: Artemether + lumefantrine is given twice a day for 3 days (total, six doses). The first two doses should, ideally, be given 8 h apart. Body weight Dose (mg) of artemether + lumefantrine (kg) given twice daily for 3 days 5 to < 15 20 + 120 15 to < 25 40 + 240 25 to < 35 60 + 360 ≥ 35 80 + 480"],["Contraindications","History of arrhythmias, clinically relevant bradycardia, and of congestive heart failure accompanied by reduced left ventricular ejection fraction, family history of sudden death or of congenital QT interval prolongation, breastfeeding."],["Cautions","Electrolyte disturbances, concomitant use with other medicines known to cause QT-interval prolongation, hepatic impairment, renal impairment, pregnancy, monitor patients unable to take food (greater risk of recrudescence)."],["Side effects","Abdominal pain, anorexia, diarrhoea, vomiting, nausea, palpitations, cough, headache, dizziness, sleep disturbances, asthenia, arthralgia, myalgia, pruritus, rashes."],["Renal impairment","Use with caution."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Artemether 20mg + Lumefanthrine 120mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"artemether coartem ACT"},{"k":"ARTESUNATE","n":"ARTESUNATE","g":"Antimalarial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.5.3 Antimalarials medicines","moa":"Artemisinin derivative; iron-activated endoperoxide generates free radicals that damage plasmodial proteins. Rapid schizonticide.","f":[["Indications & dose","Treatment of P. vivax and P. falciparum malaria ADULT and CHILD (20 kg and greater): 2.4 mg/kg IV (slow bolus over 1 to 2 minutes) at 0 hours, at 12 hours, at 24 hours, and then once daily until parasite density is 1% or less; MAX. 7 days. Follow with a full course of oral antimalarial therapy when patient can tolerate oral medications; administer with an antimalarial agent that is active against the hypnozoite liver stage forms of Plasmodium, such as primaquine, to patients with severe malaria due to P. vivax or P. ovale. CHILD (Less than 20 kg): 3 mg/kg IV at 0 hours, at 12 hours, at 24 hours, and then once daily, if necessary, until parasite density is 1% or less; MAX duration, 7 days. Follow with a full course of oral antimalarial therapy when patients can tolerate oral medications."],["Contraindications","Known serious hypersensitivity artesunate."],["Cautions","Consider discontinuing if hypotension, dyspnoea, urticaria, or generalised rash occurs. Post-treatment haemolytic anaemia, sometimes requiring transfusion."],["Side effects","Anaemia, increased transaminase, thrombocytopenia, hyperbilirubinemia, leukocytosis,"],["Renal impairment","No specific dosage adjustments are needed."],["Hepatic impairment","No specific dosage adjustments are needed."],["Pregnancy category","No data available."]],"f25":[{"i":"Artesunate 30mg powder for injection vial","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CHLOROQUINE","n":"CHLOROQUINE","g":"Antimalarial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.5.3 Antimalarials medicines","moa":"Accumulates in the parasite food vacuole and inhibits haem polymerase, so toxic free haem builds up.","f":[["Indications & dose","Acute attacks of malaria due to P. vivax, P. malariae, P. ovale, and susceptible strains of P. falciparum ADULT: 1 g PO, then 500 mg PO after 6-8 hrs, then 500 mg PO at 24 hr and 48 hr after initial dose; total dose of 2500 mg in 3 days; CHILD: first dose, 10 mg base/kg (not to exceed 600-mg base/dose); second dose (6 hr after first dose) 5 mg base/kg (not to exceed 300 mg base/dose); third dose (24 hr after first dose) 5 mg base/kg (not to exceed 300 mg base/dose); fourth dose (36 hr after first dose) 5 mg base/kg (not to exceed 300 mg base/dose), total dose of 25 mg base/kg. Prophylaxis of malaria in geographic areas where resistance to chloroquine is not present ADULT: 500 mg PO weekly on the same day each week; begin 1-2 weeks before travel, during travel, and for 4 weeks after leaving endemic area; CHILD: 5 mg/kg PO weekly, not to exceed 500 mg, on the same day each week; begin 1-2 weeks before travel, during travel, and for 4 weeks after leaving endemic area."],["Contraindications","Psoriasis; porphyria, retinal or visual field changes."],["Cautions","Diabetes, history of auditory damage, alcoholism, epilepsy, heart failure, hepatic impairment, acute porphyrias."],["Side effects","GI disturbances, headache, pruritus, rashes, skin reactions, visual disturbances, keratopathy and non-reversible retinopathy can occur, skin reactions, hair loss, and discoloration of skin, nails, and mucous membranes."],["Renal impairment","CrCl <10 mL/min: 50% of dose."],["Hepatic impairment","Use with caution in patients with hepatic impairment, alcoholism, or concurrent therapy with hepatotoxic agents."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Note","Dosing is based on chloroquine base; chloroquine phosphate 16.6 mg is equivalent to 10 mg chloroquine base."],["Counselling","Take after food."]],"f25":[{"i":"Chloroquine 150mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"PRIMAQUINE","n":"PRIMAQUINE","g":"Antimalarial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.5.3 Antimalarials medicines","moa":"8-aminoquinoline; oxidative damage to parasite mitochondria. Kills liver hypnozoites (radical cure of P. vivax) and gametocytes. Check G6PD.","f":[["Indications & dose","Prevention of relapse of P. vivax and P. ovale malaria ADULT: 30 mg PO daily for 14 days; CHILD: 0.8 mg/kg PO once daily (0.5 mg base/kg/dose) for 14 days, max. 52.6 mg/day (equivalent to 30 mg of primaquine base) in combination with appropriate blood-stage antimalarial agents. Chemoprophylaxis in P. vivax and P. ovale malaria ADULT: 30 mg PO daily for 14 days after departure from malaria-endemic area; CHILD: 0.5 mg/kg (max. 30 mg/day), start 1-2 days prior to travel and continue for 7 days after departure from malaria endemic area. Treatment of uncomplicated P. vivax and P. ovale malaria ADULT: 30 mg PO daily for 14 days with chloroquine or hydroxychloroquine. Alternatively, for mild G6PD deficiency or as an alternative to daily regimen: 45 mg PO weekly for 8 weeks; CHILD: 0.5 mg/kg (max. 30 mg/day) daily for 14 days with chloroquine or hydroxychloroquine."],["Contraindications","Acutely ill patients who tend to develop granulocytopenia (e.g., rheumatoid arthritis, SLE), concurrent use with other medications causing haemolytic anaemia or myeloid bone marrow suppression, concurrent use with or recent use of quinacrine."],["Cautions","G-6-PD deficiency, systemic disease associated with granulocytopenia (e.g., rheumatoid arthritis), pregnancy and breastfeeding."],["Side effects","Nausea, vomiting, anorexia, abdominal pain."],["Renal impairment","CrCl <10 mL/min: 50% of dose."],["Hepatic impairment","Use with caution."],["Pregnancy category","D"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","Take this medicine on an empty stomach."]],"f25":[{"i":"Primaquine 7.5mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"QUININE","n":"QUININE","g":"Antimalarial.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.5.3 Antimalarials medicines","moa":"Blood schizonticide; inhibits haem detoxification in the parasite food vacuole.","f":[["Indications & dose","Non-complicated P. falciparum malaria ADULT: 648 mg PO Q8hr for 7 days; CHILD: 30 mg/kg/day PO divided three times per day for 3–7 days; should not exceed the usual adult PO dosage. Chloroquine-resistant P falciparum malaria ADULT: 648 mg PO Q8hr x 3-7 days with concomitant tetracycline, doxycycline, or clindamycin; CHILD: 30 mg/kg/day PO divided three times per day for 3-7 days, with concomitant doxycycline, tetracycline or clindamycin; should not exceed the usual adult PO dosage. Chloroquine-resistant P vivax malaria ADULT: 648 mg PO Q8hr for 3-7 days with concomitant doxycycline (or tetracycline) and PO primaquine; CHILD: 30 mg/kg/day PO three times per day x 3–7 days, with concomitant doxycycline & PO primaquine; should not exceed the usual adult PO dosage."],["Contraindications","Myasthenia gravis, optic neuritis, G6PD deficiency, thrombotic thrombocytopenic purpura, haemolytic uremic syndrome, thrombocytopenia, pregnancy."],["Cautions","Atrial fibrillation, heart block, hepatic impairment, elderly."],["Side effects","Agitation, tinnitus, abdominal pain, acute renal failure, angioedema, blood disorders, cardiovascular effects, cinchonism, confusion, diarrhoea, dyspnoea, flushed skin, headache, hearing impairment, hot skin, hypersensitivity reactions, hypoglycaemia (especially after parenteral administration), intravascular coagulation, muscle weakness, nausea, photosensitivity, rashes, temporary blindness, thrombocytopenia, vertigo, visual disturbances, vomiting."],["Renal impairment","CrCl 10-50 mL/min: Q8-12H; CrCl <10 mL/min: Q24H."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution. 6.5.3.2 For chemoprevention"]],"f25":[{"i":"Quinine 300mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Quinine 300mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SULFAMETHOXAZOLE (SMZ) + TRIMETHOPRIM (TMP) (Co-trimoxazole)","n":"SULFAMETHOXAZOLE (SMZ) + TRIMETHOPRIM (TMP) (Co-trimoxazole)","g":"Pneumocystis and toxoplasmosis medicine.","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.5.4 Antipneumocystis and antitoxoplasmosis medicines","moa":"Sequential folate blockade (dihydropteroate synthase and dihydrofolate reductase). Active against Pneumocystis and Toxoplasma.","f":[["Indications & dose","Prophylaxis of Pneumocystis (Carinii) Jiroveci pneumonia in HIV patients ADULT: 80 -160 mg TMP PO every day or 160 mg TMP 3 times/week on consecutive or alternate days; CHILD > 2 months: 150 mg TMP/m²/day PO divided Q12 hr for 3 days/week on consecutive or alternate days. Treatment ADULT: 5-20 mg TMP/kg/day PO/IV divided Q6-8 hr; CHILD>2 months: 15-20 mg TMP/kg/day PO/IV divided Q6-8 hr for 21 days. HIV-infection-Toxoplasma encephalitis ADULT: Initial therapy, SMZ/TMP 25/5 mg/kg PO or IV twice daily for 6 weeks; CHILD >2 months 10-15 mg TMP PO/IV in divided Q 8-12 hours for ≥6 week; Chronic maintenance ADULT: SMZ/TMP 800/160 mg PO once or twice daily; CHILD >2 months: 150 mg TMP/m²/day in 2 divided doses. HIV-infection Toxoplasma encephalitis primary prophylaxis ADULT: SMZ/TMP 800/160 mg PO daily or SMZ/TMP 800/160 mg PO 3 times weekly; CHILD >2 months: 150 mg TMP/m²/day in 2 divided doses. Children <2 months, not recommended. For details, refer to page no. 40"]],"f25":[{"i":"Cotrimoxazole (Sulphamethoxazole 200mg + Trimethoprim 40mg) /5mL syrup (60mL) bottle","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Cotrimoxazole (Sulphamethoxazole 400mg+Trimethoprim 80mg) tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"cotrimoxazole septran bactrim"},{"k":"ERGOTAMINE + CAFFEINE","n":"ERGOTAMINE + CAFFEINE","g":"Antimigraine.","sec":"7. ANTIMIGRAINE MEDICINES","sub":"7.1 For treatment of acute attack","moa":"Ergotamine is a 5-HT1B/1D and alpha-adrenergic agonist causing cranial vasoconstriction; caffeine enhances its absorption.","f":[["Indications & dose","Acute migraine ADULT: 1 tablet, to be taken at onset, then 1 tablet every 30 minutes if required; max. 3 tablets in 24 hours; max. 4 tablets per attack; max. 6 tablets in one week; max. 2 courses of treatment in one month; CHILD: not recommended."],["Contraindications","Pregnancy and breastfeeding, sepsis, acute porphyria, peripheral or coronary vascular disease, severe hypertension, severe hepatic and renal impairment."],["Cautions","Anaemia, cardiac disease, dependence, elderly, risk of peripheral vasospasm."],["Side effects","Abdominal pain, dizziness, malaise, nausea and vomiting, cyanosis, peripheral vasoconstriction, weakness in extremities. Over dosage Chronic self-poisoning can lead to sustained vasoconstriction and eventual gangrene. Acute overdose may occur with only 2-3 times the normal dose; symptoms include vomiting, diarrhoea, thirst, paraesthesia, cold extremities, rapid and weak pulse, confusion, convulsion and coma."],["Renal impairment","Avoid."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","X"],["Breast-feeding","Excreted in milk, avoid."],["Note","Only use ergotamine if the headache is unresponsive to simple analgesics."]],"f25":[{"i":"Ergotamine tartrate 1mg + Caffeine 100mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PROPRANOLOL","n":"PROPRANOLOL","g":"Antimigraine.","sec":"7. ANTIMIGRAINE MEDICINES","sub":"7.2 For prophylaxis","moa":"Non-selective beta-blocker (beta-1 and beta-2); reduces heart rate, contractility and renin release. Membrane-stabilising.","f":[["Indications & dose","Prophylaxis of migraine ADULT: 80 mg/day PO divided Q6-8H; increased by 20-40 mg/day every 3-4 weeks; not to exceed 160-240 mg/day divided Q6-8H."],["Note","Withdraw therapy if satisfactory response is not seen after 6 weeks. For details, refer to page no. 84."]],"f25":[{"i":"Propranolol 40mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CYCLOSPORINE (Neoral®)","n":"CYCLOSPORINE (Neoral®)","g":"Immunosuppressant.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.1 Immunomodulators for non-malignant disease","moa":"Calcineurin inhibitor; binds cyclophilin, blocking NFAT activation and IL-2 transcription in T cells.","f":[["Indications & dose","and dosage Organ transplants (used alone) ADULTs and CHILD (> 3 months): 10-15 mg/kg PO, administered 4-12 hours prior to transplantation; followed by 10-15 mg/kg/day for 1-2 weeks postoperatively; maintenance dose 2-6 mg/kg/day. Nephrotic syndrome ADULT: 5 mg/kg/day PO, Q12H; CHILD: 5-6 mg/kg/day PO, Q12H."],["Contraindications","Abnormal renal function, malignancy, uncontrolled hypertension and infections, use with tacrolimus, breastfeeding."],["Cautions","Monitor kidney function, liver function, and blood pressure, measure serum potassium especially in marked renal dysfunction, measure blood lipids before treatment and thereafter as appropriate, pregnancy and breastfeeding."],["Side effects","Abdominal pain, anorexia, diarrhoea, fatigue, gingival hyperplasia, headache, hypercholesterolemia, hepatic dysfunction, hyperkalemia, hyperlipidemia, hypertension, hyperuricemia, hypomagnesaemia, muscle cramps, myalgia, nausea, paraesthesia, renal dysfunction, tremor, vomiting."],["Renal impairment","Reduce dose by 25–50% if serum creatinine increases more than 30% above baseline."],["Hepatic impairment","Adjust dose based on bilirubin and liver enzymes."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Note","Due to differences in bioavailability, care should be taken when switching between different brands of cyclosporine, lower doses are required when used with other immunosuppressants."],["Counselling","Avoid excessive exposure to UV light (sunlight)."]],"f25":[{"i":"Cyclosporine 100mg capsule (Neoral®)","v":"V","l":"NRH","r":""},{"i":"Cyclosporine 25mg capsule (Neoral®)","v":"V","l":"NRH","r":""},{"i":"Cyclosporine 50mg capsule (Neoral®)","v":"V","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":"ciclosporin"},{"k":"MYCOPHENOLATE MOFETIL (Cellcept®)","n":"MYCOPHENOLATE MOFETIL (Cellcept®)","g":"Immunosuppressant.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.1 Immunomodulators for non-malignant disease","moa":"Inhibits inosine monophosphate dehydrogenase, blocking de novo guanine synthesis in lymphocytes.","f":[["Indications & dose","Prophylaxis of acute renal transplant rejection (in combination with a corticosteroid and cyclosporine) ADULT: 1 g PO, Q12H, starting within 72 hours of transplantation; CHILD: 600 mg/m² PO, Q12H; max. 2g/day. Prophylaxis of acute rejection in renal transplantation (in combination with a corticosteroid and tacrolimus) CHILD: 300 mg/m² PO, Q12H; max. 2g/day. Prophylaxis of acute cardiac transplant rejection ADULT: 1.5 g PO, Q12H, starting within 5 days of transplantation."],["Cautions","Elderly, children, active serious GI disease, delayed graft function, increased susceptibility to skin cancer (avoid exposure to strong sunlight)."],["Side effects","Diarrhoea, vomiting, and abdominal pain, GI ulceration and bleeding, abnormal liver function tests, hepatitis, jaundice, pancreatitis, oedema, tachycardia, hypertension, hypotension, vasodilatation, cough, dyspnea, insomnia, agitation, tremor, dizziness, headache, influenza-like syndrome infections, hyperglycemia, renal impairment, increased risk of malignancies, particularly of the skin, blood disorders (including leukopenia, anaemia, thrombocytopenia, pancytopenia), disturbances of electrolytes and blood lipids, arthralgia, alopecia, acne, rash."],["Renal impairment","GFR <25 mL/min/1.73 m²: not to exceed 1 g, Q12H."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, avoid."],["Note","Monitor complete blood counts every week for 4 weeks, then twice a month for 2 months then every month in the first year (neutropenia warrants interruption of treatment)."],["Counselling","Patients should be warned to report immediately any signs or symptoms of bone marrow suppression e.g. infection or inexplicable bruising or bleeding."]],"f25":[{"i":"Mycophenolate mofetil 250mg capsule","v":"V","l":"NRH","r":""},{"i":"Mycophenolate mofetil 250mg capsule (CellCept®)","v":"V","l":"NRH","r":""},{"i":"Mycophenolate mofetil 500mg capsule","v":"V","l":"NRH/RRH","r":""},{"i":"Mycophenolate mofetil 500mg capsule (CellCept®)","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Mycophenolate mofetil 250mg capsule added (Till NRH). Reason: For non-transplant patients"],["Added in 2025","Mycophenolate mofetil 500mg capsule added (Till RRH). Reason: For non-transplant patients"]],"al":""},{"k":"TACROLIMUS (Pangraf®)","n":"TACROLIMUS (Pangraf®)","g":"Immunosuppressant.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.1 Immunomodulators for non-malignant disease","moa":"Calcineurin inhibitor; binds FKBP-12, blocking IL-2 transcription and T-cell activation.","f":[["Indications & dose","Prophylaxis of graft rejection following liver transplantation, starting 12 hours after transplantation ADULT: 100-200 mcg/kg/day PO, Q12H; CHILD: 150 mcg/kg PO, Q12H. Prophylaxis of graft rejection following kidney transplantation, starting within 24 hours of transplantation ADULT: 200-300 mcg/kg/day PO, Q12H; CHILD: 150 mcg/kg PO, Q12H."],["Contraindications","Hypersensitivity to castor oil and macrolides."],["Cautions","UV light (avoid excessive exposure to sunlight and sunlamps), increased risk of infections, lymphoproliferative disorders, malignancies, neurotoxicity, QT-interval prolongation."],["Side effects","Acne, alopecia, anaemia, anorexia, arthralgia, ascites, bloating, blood disorders, cholestasis, confusion, constipation, depression, diarrhoea, dizziness, dyspepsia, dyspnea, electrolyte disturbances, ﬂatulence, gastro-intestinal inﬂammation, haemorrhage, headache, hepatic dysfunction, hyperglycemia, hyperkalemia, hypertension, hyperuricemia, hypokalemia, impaired hearing, ischemic events, photosensitivity."],["Renal impairment","Use lower end of dosing range, monitor renal function and adjust dose accordingly."],["Hepatic impairment","Dose reduction necessary in moderate and severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Note","To ensure maintenance of therapeutic response, when a patient is stabilised on a particular brand, oral tacrolimus products should be prescribed and dispensed by brand name only."],["Counselling","Avoid excessive exposure to UV light (sunlight)."]],"f25":[{"i":"Tacrolimus 1mg tablet (Pangraf®)","v":"V","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"CYCLOPHOSPHAMIDE","n":"CYCLOPHOSPHAMIDE","g":"Cytotoxic.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.1 Cytotoxic medicines","moa":"Alkylating agent (prodrug activated in liver); cross-links DNA. Metabolite acrolein causes haemorrhagic cystitis.","f":[["Indications & dose","Acute myeloid leukaemia; Breast cancer; Burkitt's lymphoma; Chronic lymphoid leukaemia; Chronic myeloid leukaemia; Hodgkin's disease, Stages III and IV; Malignant histiocytosis; Malignant lymphoma - mixed small and large cell; Mantle cell lymphoma, Stages III and IV; Multiple myeloma; Mycosis fungoides, Advanced; Neuroblastoma, Disseminated disease; non-Hodgkin’s lymphoma; Ovarian cancer, Adenocarcinoma; Retinoblastoma; Small lymphocytic lymphoma, Nodular or diffuse; (Single agent) ADULT and CHILD: 40 to 50 mg/kg IV in divided doses over 2 to 5 days OR 10 to 15 mg/kg IV every 7 to 10 days OR 3 to 5 mg/kg IV twice weekly; ORALLY (single agent) 1 to 5 mg/kg/day PO for both initial and maintenance dosing. Lupus nephritis ADULT and CHILD (Induction, low-dose regimen): 500 mg IV every 2 weeks for a total of 6 doses; ADULT (Induction, high-dose regimen): 500-1000 mg/m² BSA IV once monthly for 6 months; CHILD (Induction, high-dose regimen): 500 to 750 mg/m² IV pulse dose; if tolerated, increase to 750 mg/m²/pulse (MAX 1000 to 1200 mg/pulse) and administer 6 monthly pulses. Systemic lupus erythematosus Organ- or life-threatening disease ADULT: 0.75 to 1 g/m² BSA IV once monthly for 6 months."],["Contraindications","Severe bone marrow depression, and pre-existing hemorrhagic cystitis."],["Cautions","Hepatic and renal impairment, leukopenia, thrombocytopenia, recent radiation therapy or chemotherapy, diabetes melitus."],["Side effects","Leukopenia, alopecia, hemorrhagic cystitis occurs in 5-10% of patients, anorexia, cardiotoxicity, disturbances of carbohydrate metabolism, interstitial pulmonary fibrosis, pancreatitis, pigmentation of nails, palms and soles, urothelial toxicity."],["Renal impairment","Reduce dose if serum creatinine concentration greater than 120 micromol/litre."],["Hepatic impairment","Dose reduction may be required."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."],["Note","Manufacturer’s literature should be consulted for specific dosage information."],["Counselling","Take the tablets on an empty stomach. Drink plenty of water with this medicine. Use effective contraception during and for at least 3 months after treatment in men or women to prevent conception."]],"f25":[{"i":"Cyclophosphamide 200mg powder for injection vial","v":"E","l":"NRH","r":""},{"i":"Cyclophosphamide 50mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"DOXORUBICIN","n":"DOXORUBICIN","g":"Cytotoxic.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.1 Cytotoxic medicines","moa":"Anthracycline; intercalates DNA, inhibits topoisomerase II and generates free radicals (cardiotoxic).","f":[["Indications & dose","Chemotherapy of neoplastic disease (alone or in combination with other cytotoxic medicines) ADULT: 60-75 mg/m² Iv infusion, Q21 days, or 25-30 mg/m²/day on 2 or 3 successive days, repeated every 3 to 4 weeks, or 20 mg/m² once a week; CHILD: 30 mg/m²/day on three successive days every 4 weeks. 2 2"],["Contraindications","Hepatic impairment, myelosuppression, myocardial infarction, myocardial insufficiency."],["Cautions","Cardiac diseases, hypertension and previous myocardial irradiation."],["Side effects","Dehydration, diarrhoea, red coloration of the urine."],["Hepatic impairment","Reduce dose according to bilirubin or avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excretion in milk unknown, avoid."],["IV fluid compatibility","Dextrose 5%."],["Note","Great care should be taken to prevent exposure of skin to doxorubicin, any doxorubicin solution that comes in contact with the skin or mucosa should be washed off thoroughly with soap and water."]],"f25":[{"i":"Doxorubicin powder for injection (10mg) vial","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"FLUOROURACIL (5-FU)","n":"FLUOROURACIL (5-FU)","g":"Cytotoxic.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.1 Cytotoxic medicines","moa":"Pyrimidine analogue; its metabolite inhibits thymidylate synthase and is incorporated into RNA and DNA.","f":[["Indications & dose","Treatment of some solid tumours including GI tract cancers and breast cancer; In combination with folinic acid in advanced colorectal cancer ADULT: 500 mg/m² IV injection, days 1-5 OR 450-600 mg/m² IV injection weekly OR 200-400 mg/m² IV infusion, Q24H; Max. 800 mg/day. 2 2"],["Contraindications","Poor nutritional status, bone marrow suppression, serious infection, recent surgery, dihydropyrimidine dehydrogenase deficiency."],["Cautions","Discontinue in case of stomatitis, oesophagopharyngitis, leukopenia, thrombocytopenia, GI bleeding, haemorrhage and diarrhoea, pregnancy."],["Side effects","Loss of appetite, headache, nausea and vomiting, diarrhoea, mucositis, myelosuppression, alopecia, photosensitivity, hand-foot syndrome."],["Hepatic impairment","Use with caution."],["Pregnancy category","D"],["Breast-feeding","Excretion in milk unknown, avoid."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Fluorouracil 50mg/mL injection (10mL) ampoule","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"FOLINIC ACID","n":"FOLINIC ACID","g":"Chemotherapy rescue agent.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.1 Cytotoxic medicines","moa":"Reduced folate bypassing dihydrofolate reductase; rescues normal cells from methotrexate and potentiates 5-FU.","f":[["Indications & dose","Prevention of methotrexate-induced adverse effects ADULT: 15 mg IM or IV injection or IV infusion, Q6H x 24 hours, started 12-24 hours after start of methotrexate infusion. Suspected methotrexate over dosage ADULT: Initial dose equal to or exceeding dose of methotrexate, to be given at a maximum rate of 160mg/minute. Metabolic disorders leading to folate deficiency CHILD: 15 mg IV infusion, Q24H, larger doses may be required in older children."],["Contraindications","Vitamin B12 deficiency anaemia, pernicious anaemia, intrathecal injection."],["Cautions","Pernicious anaemia or other megaloblastic anemias caused by vitamin B12 deficiency; avoid simultaneous administration of methotrexate."],["Side effects","Diarrhoea, nausea, vomiting, stomatitis, thrombocytosis."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5%, compound solution of sodium lactate, sodium chloride 0.9%, water for injection."]],"f25":[{"i":"Folinic acid 10mg/mL injection (5mL) vial","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"METHOTREXATE","n":"METHOTREXATE","g":"Antineoplastic medicine.","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.1 Cytotoxic medicines","moa":"Inhibits dihydrofolate reductase, blocking purine and thymidine synthesis. Anti-inflammatory at low dose via adenosine release.","f":[["Indications & dose","Active rheumatoid arthritis (RA) by oral administration, 7.5 mg once weekly (as a single dose or divided into 3 doses of 2.5 mg given at intervals of 8 hour) adjusted according to response; max total weekly dose: 20 mg. Psoriasis 10 to 25 mg once weekly, adjusted according to response. Not recommended for the children; Reduce dose in elderly."],["Contraindications","Significant renal impairment and haematological failure, significant pleural effusion or ascites is present, liver impairment, pregnancy and lactation."],["Cautions","Blood counts should be monitored."],["Side effects","Ulcerative stomatitis, leukopenia, hepatotoxicity, nausea, abdominal distress, malaise, fatigue, chills, fever, dizziness, decreased resistance to infection, rash, bone marrow depression, gingivitis, renal failure, headache, blurred vision; uncommon with low dose maintenance therapy."],["Note","Pulmonary toxicity may be a special problem in RA. Patient to seek advice if dyspnea, cough or fever develops."]],"f25":[{"i":"Methotrexate 2.5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"METHYLPREDNISOLONE SUCCINATE","n":"METHYLPREDNISOLONE SUCCINATE","g":"Adrenal hormones and synthetic substitutes (corticosteroid).","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.2 Hormones and antihormones","moa":"IV glucocorticoid; receptor-mediated suppression of inflammatory genes. Used for pulse therapy.","f":[["Indications & dose","Suppression of inflammatory and allergic disorders; Cerebral oedema associated with malignancy ADULT: Initially 10-500 mg IM or slow IV injection or IV infusion; CHILD: 0.5-1.7 mg/kg/day IM or slow Iv injection or IV infusion, Q6H-Q12H, divide doses depending on condition and response. Treatment of graft rejection reactions ADULT: Up to 1 g/day Iv infusion, up to 3 days; CHILD: 10-20 mg/kg IV injection, Q24H x 3 days. Severe erythema multiforme; Lupus nephritis; Systemic onset juvenile idiopathic arthritis CHILD: 10-30 mg/kg IV injection Q24H."],["Contraindications","Hypersensitivity to corticosteroids, systemic fungal infections, concurrent administration of live vaccines; intrathecal administration, serious infections, use in premature infants."],["Cautions","Cirrhosis, hypertension, ocular herpes simplex, diverticulitis, myasthenia gravis, peptic ulcer disease, ulcerative colitis, psychotic tendencies, pregnancy, diabetes, cardiovascular disorder, renal insufficiency, ocular disease; head injury. Side Effects Acne, adrenal suppression, arthralgia, bladder dysfunction, cardiomegaly, Cushing syndrome, delayed wound healing, diabetes, fat embolism, hyperglycemia, indigestion, insomnia, osteoporosis, syncope, tachycardia, vertigo."],["Renal impairment","Use with caution, fluid retention may occur."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, use with caution."],["IV fluid compatibility","Dextrose 5%, dextrose 5% sodium chloride 0.9%, sodium chloride 0.9%."]],"f25":[{"i":"Methylprednisolone succinate 500mg powder for injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ALLOPURINOL","n":"ALLOPURINOL","g":"Medicine used to treat gout (xanthine oxidase inhibitor).","sec":"8. IMMUNOMODULATORS AND ANTINEOPLASTICS","sub":"8.2.3 Supportive medicines","moa":"Xanthine oxidase inhibitor (via its metabolite oxypurinol); reduces uric acid production.","f":[["Indications & dose","Prophylaxis of gout ADULT: Initially 100 mg PO daily, preferably after food, then adjusted according to plasma uric acid concentration; Usual maintenance dose in mild conditions: 100-200 mg PO daily; Usual maintenance dose in moderately severe conditions: 300-600 mg PO in divided doses daily (Max. per dose 300 mg); Usual maintenance dose in severe conditions: 700-900 mg PO daily in divided doses (Max. per dose 300 mg). Prophylaxis of hyperuricemia associated with cancer chemotherapy and hyperuricemia nephropathy, enzyme disorders causing increased serum urate e.g. Lesch-Nyhan syndrome (children) ADULT: 600-800 mg in divided doses, starting before 1-2 days before chemotherapy; CHILD (1 month-14 years): 10-20 mg/kg PO daily; Max. 400 mg per day; CHILD (15-17 years): Initially 100 mg PO daily; dose to be increased according to response, up to 900 mg daily in divided doses (max. per dose 300 mg)."],["Contraindications","Not a treatment for acute gout but continue if attack develops when already receiving allopurinol and treat attack separately."],["Cautions","Prophylactic administration of NSAIMs (not aspirin) is recommended until a month after the uric acid level becomes normal, adequate fluid intake must be ensured (2-3 litres/day)."],["Side effects","GI disorders, rashes, sometimes with fever may be seen (If mild, withdraw therapy and then re-introduce cautiously at a very low dose and increase gradually, discontinue immediately if recurrence occurs)."],["Renal impairment","Max. 100 mg daily, increased only if response is inadequate. In severe impairment, reduce daily dose below 100 mg, or increase dose interval."],["Hepatic impairment","Reduce dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, not known to be harmful."],["Counselling","Take after food with plenty of fluids."]],"f25":[{"i":"Allopurinol 100mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CARBIDOPA + LEVODOPA","n":"CARBIDOPA + LEVODOPA","g":"Antiparkinsonian medicine.","sec":"9. ANTIPARKINSONISM MEDICINES","sub":"","moa":"Levodopa is converted to dopamine in the brain. Carbidopa blocks peripheral dopa decarboxylase, raising CNS delivery and reducing nausea.","f":[["Indications & dose","Parkinson disease ADULT: Initially half to one tablet PO, Q6-8H, adjust according to response; maintenance dose 200-2000 mg/day (8 tablets), Q6-8H; CHILD: safety and efficacy not established."],["Contraindications","Narrow-angle glaucoma, concurrent administration of MAOIs or use within the last 4 days."],["Cautions","History of MI with residual atrial, nodal or ventricular arrhythmias, peptic ulcer, seizure, severe cardiovascular, respiratory, renal, hepatic or endocrine disease, bronchial asthma patients, major psychotic disorder, glaucoma."],["Side effects","Abnormal dreams, anorexia, anxiety, arrhythmias, chorea, confusion, dementia, depression, dizziness, drowsiness, dry mouth, dyskinesia, dystonia, euphoria, fatigue, insomnia, nausea, palpitations, postural hypotension, psychosis, syncope, taste disturbances, vomiting."],["Renal impairment","Use with caution. Pregnancy Category C"],["Hepatic impairment","Use with caution."],["Breast-feeding","Excreted in milk, avoid."],["Counselling","Advise patients to avoid activities requiring mental alertness or coordination until medicine effects are realised, as medicine may cause somnolence or sudden sleep onset. Inform patient to report symptoms of depression, suicidal behavior, or psychotic behavior, including hallucinations. Advise patients that medicine may discolour saliva, sweat, or urine to a dark red, brown, or black colour; garments may be discoloured. Instruct patients to avoid change in diet to high-protein foods as this may delay absorption."]],"f25":[{"i":"Levodopa 250mg + Carbidopa 25mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"TRIHEXYPHENIDYL","n":"TRIHEXYPHENIDYL","g":"Antiparkinsonian medicine.","sec":"9. ANTIPARKINSONISM MEDICINES","sub":"","moa":"Central muscarinic (M1) antagonist; restores dopamine-acetylcholine balance in the striatum.","f":[["Indications & dose","Parkinsonism; Medicine-induced extrapyramidal symptoms (but not tardive dyskinesia) ADULT: 1 mg PO, Q24H, then increased in steps of 2 mg every 3-5 days; adjusted according to response; maintenance 5-15 mg/day, Q6-8H (max. 20 mg/day). Parkinson’s disease (in combination with levodopa/carbidopa ADULT: 2-6mg/day PO, in divided doses. Dystonia CHILD (3 months-17 years): Initially 1-2 mg/day PO, Q12-24H, then increased in steps of 1 mg every 3-7 days, dose to be adjusted according to response and side-effects (max. 2 mg/kg/day)."],["Contraindications","Angle-closure glaucoma, cardiovascular disease, GI obstruction, myasthenia gravis."],["Cautions","GI obstruction, urinary retention, elderly, prostatic hypertrophy, hypertension."],["Side effects","Dry mouth, GI disturbances, dizziness, blurred vision, less commonly urinary retention, tachycardia, hypersensitivity, nervousness, mental confusion, excitement and psychiatric disturbances in some susceptible patients (at high doses)."],["Renal impairment","Use with caution. Pregnancy Category C"],["Hepatic impairment","Use with caution."],["Breast-feeding","Excreted in milk, avoid."],["Note","Avoid abrupt withdrawal in patients taking long-term treatment."],["Counselling","Tablets should be taken with or after food. Do not drive or operate machineries."]],"f25":[{"i":"Trihexyphenidyl 2mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FERROUS SULPHATE + FOLIC ACID","n":"FERROUS SULPHATE + FOLIC ACID","g":"Antianemic medicine.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.1 Anti-anemia medicines","moa":"Supplies elemental iron for haemoglobin synthesis and folate for DNA synthesis in erythropoiesis.","f":[["Indications & dose","Severe anaemia ADULT: One tablet PO, Q12H x 3 months; CHILD: 1-2 mg/kg/day up to a maximum of 15 mg/day. Prevention of iron and folate deficiencies in pregnancy ADULT: One tablet PO, Q12H throughout pregnancy."],["Contraindications","Hemochromatosis, hemolytic anaemia, anemias due to causes other than iron deficiency."],["Cautions","Avoid use in peptic ulcer diseases, ulcerative colitis, enteritis, patient receiving frequent blood transfusion. Avoid use in premature infants until the vitamin E stores, deficient at birth, are replenished. Administration of iron for >6 months should be avoided except in patients with continuous bleeding or menorrhagia."],["Side effects","GI irritation, vomiting, constipation (dose related), diarrhoea, faecal impaction."],["Pregnancy category","A"],["Breast-feeding","Excreted in breast milk, safe."],["Counselling","Take this medicine after food and take an iron rich diet like green vegetables, liver, beef, beans and peaches; May discolour stools, do not worry."]],"f25":[{"i":"Ferrous sulphate 200mg + Folic acid 0.40mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Ferrous sulphate 60mg + Folic acid 0.40mg tablet → now Ferrous sulphate 200mg + Folic acid 0.40mg tablet"]],"al":""},{"k":"FOLIC ACID","n":"FOLIC ACID","g":"Antianemic medicine.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.1 Anti-anemia medicines","moa":"Converted to tetrahydrofolate, a cofactor for purine and thymidylate synthesis; prevents megaloblastic anaemia and neural tube defects.","f":[["Indications & dose","Folate-deficiency megaloblastic anaemia ADULT: 5 mg PO, Q24H x 4 months (until term in pregnant women), in malabsorption states, doses up to 15 mg/day may be required; CHILD (1-11 months): Initially 500 mcg/kg PO, Q24H (max. 5 mg/dose) x up to 4 months, in malabsorption states, doses up to 10 mg/day may be required. Prevention of neural tube defects (women at a low risk of conceiving a child with a neural tube defect) ADULT: 400 mcg, PO Q24H, to be taken before conception and until week 12 of pregnancy. Prevention of neural tube defects (women in the high-risk group) ADULT: 5 mg PO, daily until week 12 of pregnancy. Prevention of methotrexate-induced side effects in rheumatic disease, Crohn’s disease and severe psoriasis ADULT and CHILD: 5 mg PO once weekly, dose to be taken on a different day to methotrexate dose. Prophylaxis in chronic hemolytic states ADULT: 5 mg PO, every 1-7 days, frequency dependent on underlying disease. Prophylaxis of folate deficiency in dialysis ADULT: 5 mg PO, every 1-7 days; CHILD (1 month-11 years): 250 mcg/kg PO, Q24H (max. 10 mg/dose). Hemolytic anaemia; Metabolic disorders ADULT: 5-10 mg PO, Q24H; CHILD (1 month-11 years): 2.5-5 mg PO, Q24H."],["Cautions","Should never be given alone for pernicious anaemia (may precipitate subacute combined degeneration of spinal cord)."],["Side effects","Gastro-intestinal disturbances (rare)."],["Pregnancy category","A"],["Breast-feeding","Excreted in breast milk, safe."]],"f25":[{"i":"Folic acid 5mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"IRON SUCROSE","n":"IRON SUCROSE","g":"Anti-anemia.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.1 Anti-anemia medicines","moa":"IV iron complex taken up by macrophages; iron is released to transferrin for haemoglobin synthesis.","f":[["Indications & dose","Iron deficiency anaemia associated with chronic kidney disease; Haemodialysis-dependent CKD: 100 mg elemental iron IV (injection or infusion over 2-5 min) per dialysis session not to exceed total cumulative dose of 1000 mg divided in 3 doses/week. Non-dialysis-dependent CKD: 200 mg IV injection for 5 doses in over 14 days (cumulative 1000 mg in 14-day period). Peritoneal dialysis-dependent CKD: 300 mg IV infusion (1.5 hour) for 2 doses 14 days apart, THEN 400 mg IV infusion (2.5 hour) 14 days later (cumulative 1000 mg divided in 3 doses/week). CHILD≥2 years: Haemodialysis-dependent: 0.5 mg/kg IV Q2 weeks for 12 weeks; not to exceed 100 mg/dose. Non-dialysis dependent or peritoneal-dependent (on erythropoietin): 0.5 mg/kg IV Q4 weeks for 12 weeks; not to exceed 100 mg/dose."],["Contraindications","below 2 years of age, hypersensitivity to iron sucrose and any content of it."],["Cautions","a test dose of 1 mL should be given by IM route and patient kept under observation for 30 minutes; adrenaline injection should be available in case of anaphylaxis."],["Side effects","Hypotension, muscle cramps, headache, nausea."]],"f25":[{"i":"Iron sucrose 20mg/mL injection (5mL) ampoule","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ERYTHROPOIETIN","n":"ERYTHROPOIETIN","g":"Hematopoietic.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.1 Anti-anemia medicines","moa":"Recombinant EPO; stimulates erythroid progenitor proliferation via the EPO receptor (JAK2/STAT5).","f":[["Indications & dose","CKD on dialysis, By IV injection, initiate treatment when haemoglobin (Hgb) level < 10 g/dL, ADULT: initially 50-100 units/kg 3 times weekly. CKD not on dialysis, by IV/SC injection, ADULT: 50-100 units /kg 3 times weekly initially. Reduce dose by 25% if Hgb approaches 12 g/dL or increases >1 g/dL in any 2-week period. Increase by 25% If haemoglobin <10 g/dL and does not increase by 1 g/dL after 4 weeks of therapy. Note: Haemoglobin levels should not exceed 12 g/dL and should not rise >1 g/dL per 2-week time period during therapy in any patient. Chemotherapy related anaemia, by SC injection, ADULT: 150 units/kg 3 times weekly initially; alternatively, 40,000 units SC once weekly until completion of chemotherapy course."],["Contraindications","hypersensitivity to human albumin, patients unable to receive thromboprophylaxis, pure red cell aplasia following erythropoietin therapy, uncontrolled hypertension."],["Cautions","Concurrent infection, epilepsy, malignant disease, cardiovascular disease, sickle-cell disease, thrombocytosis."],["Side effects","Fever, headache, cardiovascular events, diarrhoea, hypertensive crisis, inﬂuenza-like symptoms, nausea, vomiting, shunt thrombosis."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use caution."]],"f25":[{"i":"Erythropoietin 2,000IU injection (0.5mL) pre-filled syringe","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"VITAMIN B (Mecobalamin)","n":"VITAMIN B (Mecobalamin)","g":"Antianemic medicine.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.1 Anti-anemia medicines","moa":"Active form of vitamin B12; cofactor for methionine synthase (DNA synthesis, myelin maintenance).","f":[["Indications & dose","and dosage Pernicious anaemia ADULT: 1 mg IM or SC injection, Q24H x 7 days, then weekly for 1 month, then monthly; CHILD: 0.03-0.05 mg/day x 2 or more weeks (to a total dose of 1-5 mg), then with 0.1 mcg/month as maintenance dosage. B Deficiency ADULT: Initial, 0.30 mcg IM injection, Q24H x 5-10 days; Maintenance 0.1-0.2 mg monthly; CHILD: 0.2 mcg/kg/day IM injection x 2 days, followed by 1 mg/day x 2-7 days; then 0.1 mcg/week for 1 month; Maintenance 100 mcg."],["Cautions","Leber optic nerve atrophy, nasal disease."],["Side effects","Arthralgia, dizziness, headache, nasopharyngitis, hypokalemia."],["Pregnancy category","A"],["Breast-feeding","Excreted in milk, safe."],["Counselling","Avoid IV route; Anaphylactic shock has occurred."]],"f25":[],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"DABIGATRAN","n":"DABIGATRAN","g":"Anticoagulant.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Direct, reversible thrombin (factor IIa) inhibitor.","f":[["Indications & dose","Deep-vein thrombosis (DVT)and pulmonary embolism (PE). Prophylaxis of recurrent DVT and recurrent PE: ADULT (18–74 years) 150 mg PO twice daily, (75–79 years) 110–150 mg PO twice daily, and (≥80 years) 110 mg PO twice daily. Oral therapy should be initiated following at least 5 days treatment with a parenteral anticoagulant. DVT and PE in patients with moderate renal impairment and at increased risk of bleeding (both treatment and prophylaxis): ADULT 110–150 mg PO twice daily, following at least 5 days treatment with a parenteral anticoagulant. DVT and PE in patients receiving concomitant verapamil (both treatment and prophylaxis): ADULT 110 mg PO twice daily, following at least 5 days treatment with a parenteral anticoagulant. Prophylaxis of stroke and systemic embolism in nonvalvular atrial fibrillation and with one or more risk factors*: ADULT (18– 74 years) 150 mg PO twice daily, (75–79 years) 110–150 mg PO twice daily and (≥80 years) 110 mg PO twice daily. Prophylaxis of stroke and systemic embolism in nonvalvular atrial fibrillation and with one or more risk factors in patients receiving concomitant verapamil: ADULT 110 mg PO twice daily. Prophylaxis of stroke and systemic embolism in nonvalvular atrial fibrillation and with one or more risk factors in patients at increased risk of bleeding and with moderate renal impairment: ADULT 110–150 mg PO twice daily. Prophylaxis of venous thromboembolism (VTE) following total hip replacement surgery: ADULT (18–74 years) 110 mg PO to be taken 1–4 hours after surgery, followed by 220 mg PO once daily for 28–35 days initiated on the first day after surgery, (75 years and above) 75 mg PO, to be taken 1–4 hours after surgery, followed by 150 mg PO once daily for 28–35 days initiated on the first day after surgery. Prophylaxis of VTE following total hip replacement surgery in patients on concomitant amiodarone or verapamil: ADULT (18 years and above) 75 mg, PO to be taken 1–4 hours after surgery, followed by 150 mg PO once daily for 28–35 days, initiated on the first day after surgery. Prophylaxis of VTE following total knee replacement surgery: ADULT (18–74 years) 110 mg PO to be taken 1–4 hours after surgery, followed by 220 mg once daily for 10 days, initiated on the first day after surgery, (≥75 years) 75 mg, to be taken 1–4 hours after surgery, followed by 150 mg once daily for 10 days, initiated on the first day after surgery. Prophylaxis of VTE following total knee replacement surgery in patients receiving concomitant amiodarone or verapamil: ADULT (18–74 years) 75 mg PO to be taken 1–4 hours after surgery, followed by 150 mg once daily for 28–35 days, initiated on the first day after surgery, (≥75 years) 75 mg PO to be taken 1–4 hours after surgery, followed by 150 mg once daily for 28–35 days initiated on the first day after surgery. Heparin-induced thrombocytopenia (HIT) with thrombosis ADULT: 150 mg PO twice daily after 5 or more days of treatment with a parenteral non-heparin anticoagulant; Without thrombosis:150 mg PO twice daily until platelet count recovery. Treatment and prophylaxis of venous thromboembolism (VTE) following treatment with parenteral anticoagulant for at least 5 days CHILD 8 to 18 years (11 to <16 kg): 75 mg PO twice daily; (16 to <26kg): 110 mg PO twice daily; (26 to <41kg): 150 mg PO twice daily; (41 to <61kg): 185 mg PO twice daily; (61 to <81kg): 220 mg PO twice daily; and (>81 kg): 260 mg PO twice daily. Surgery: Discontinue dabigatran 1 to 2 days (CrCl ≥50 mL/min) or 3 to 5 days (CrCl <50 mL/min) before invasive or surgical procedures because of the increased risk of bleeding. Risk factors* for stroke and systemic embolism includes previous stroke or transient ischemic attack, symptomatic heart failure, age 75 years and above, diabetes mellitus, hypertension, etc."],["Contraindications","Active pathological bleeding, mechanical prosthetic heart valve, serious hypersensitivity reaction (e.g.: anaphylaxis to Dabigatran, or any excipients of the product). Concomitant use with other anticoagulants."],["Cautions","Anesthesia with postoperative indwelling epidural catheter (risk of paralysis -give initial dose at least 2 hours after catheter removal and monitor neurological signs); bacterial endocarditis; bleeding disorders; body weight less than 50 kg; elderly >75 years; gastritis; gastro-esophageal, reflux; esophagitis; recent biopsy; recent major trauma; thrombocytopenia."],["Side effects","Impaired hepatic functions, anaemia, diarrhoea, haemorrhage, nausea, vomiting, wound complications, angioedema, and skin reactions, GI discomfort, thrombocytopenia."],["Renal impairment","Avoid use if creatinine clearance less than 30 mL/minute."],["Hepatic impairment","Avoid use in severe impairment; consider avoiding those with liver enzymes greater than 2 times the upper limit of normal."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk in less amounts, Infant risk cannot be ruled out."],["Note","Dabigatran oral capsule or tablet is indicated only in adults and children 8 to 18 years of age. Do not substitute different dosage forms (e.g. capsules) for oral pellets on a milligram-to-milligram basis and do not combine more than 1 dosage form to achieve the total dose."],["Counselling","When given concomitantly with amiodarone or verapamil, doses should be taken at the same time."]],"f25":[],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"DESMOPRESSIN","n":"DESMOPRESSIN","g":"Haemostatic.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Synthetic vasopressin analogue; V2 receptor agonist (renal water reabsorption) and releases factor VIII and von Willebrand factor.","f":[["Indications & dose","and dosage Management of diabetes insipidus by SC, IM or IV injection, ADULT and CHILD > 12 years, 2 to 4 mcg in 2 divided doses; CHILD (3 months above to 12 years) IV/SC injection, 0.4 mcg once daily. By oral administration, Adults, 100 mcg three times a day, adjusting within the range 200 mcg to 1200 mcg daily according to response; Child 2 -11 years, 50 mcg twice daily. Treatment haemophilia A and Willebrand disease (type1) By intravenous injection; INFANTS > 3 MONTHS, CHILDREN AND ADULT, 0.3 mcg/kg over 15 - 30 minutes."],["Contraindications","Cardiac insufficiency, condition treated with diuretics, hyponatremia, moderate to severe renal impairment."],["Cautions","Pregnancy, psychogenic polydipsia, congestive heart failure, children, elderly, asthma."],["Side effects","Facial flushing, headache and dizziness, hyponatremia, water intoxication, palpitation, edema, tachycardia, weight gain, dry mouth. Renal dose adjustment Avoid in patients with moderate to severe renal impairment (creatinine clearance <50mL/min)."],["Pregnancy category","B"],["Breast-feeding","Amount too small to be harmful."]],"f25":[{"i":"Desmopressin 100μg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ENOXAPARIN","n":"ENOXAPARIN","g":"Anticoagulant.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Low-molecular-weight heparin; potentiates antithrombin, mainly inhibiting factor Xa.","f":[["Indications & dose","Prophylaxis of deep-vein thrombosis in surgical patients ADULT: 20-40 mg SC injection, 2 hours before surgery and then 20-40 mg, Q24H x 7 to 10 days. Prophylaxis for deep vein thrombosis in medical patients: 40 mg SC injection, Q24H for at least 6 days; CHILD (< 2 months): 0.75 mg/kg SC injection, Q12H; CHILD (≥2 months): 0.5 mg/kg SC injection, Q12H. Treatment of deep vein thrombosis and pulmonary embolism: 1.5 mg/kg SC injection, Q24H for at least 5 days (and until oral anticoagulation established); CHILD (< 2 months): 1.5 mg/kg SC injection, Q12H; CHILD (≥ 2 months): 1 mg/kg SC injection, Q12H. Treatment of unstable angina and non ST-segment- elevation myocardial infarction ADULT: 1 mg/kg SC injection, Q12H x 2 to 8 days."],["Contraindications","Acute bacterial endocarditis, major bleeding disorder, hemorrhagic stroke, medicine induced thrombocytopenia."],["Cautions","Renal or hepatic impairment; history of GI ulceration, uncontrolled hypertension, spinal or epidural anaesthesia; lactation and pregnancy; elderly, hyperkalemia."],["Side effects","Thrombocytopenia, injection site irritation, pain and ecchymosis, skin necrosis; hypersensitivity, erythema, anaemia, hemorrhagic complications, atrial fibrillation, pulmonary oedema, pneumonia and osteoporosis on prolonged use."],["Renal impairment","Dosage adjustment needed if CrCl <30 mL/minute."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Enoxaparin 10mg/0.1mL injection (0.6mL) pre-filled syringe","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is Medical Specialist, Gynecologist and General Surgeon"}],"lv":["NRH","RRH"],"ch":[],"al":"lmwh clexane"},{"k":"HEPARIN (Unfractionated)","n":"HEPARIN (Unfractionated)","g":"Anticoagulant.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Binds antithrombin, accelerating inactivation of thrombin (IIa) and factor Xa.","f":[["Indications & dose","Hemodialysis ADULT: 1000-5000 units initially by IV injection, followed by (by continuous IV infusion) 250-1000 units/hour. Maintenance of line patency (line flushing) ADULT and CHILD: 100 units/mL to be flushed through Q4-8H; INFANTS (<10 kg): 10 units/mL. DVT Prophylaxis ADULT: 5000 units SC injection, Q8-12H. ST Elevation Myocardial Infarction ADULT: Concurrent bolus of 60 units/kg (max. 4000 units), then 12 units/kg/hour (max. 1000 units/hour) as continuous IV infusion; Check aPTT Q4-6H; adjust to target of 1.5-2 times the upper limit of control (50-70 seconds); usual range 10-30 units/kg/hour. Unstable angina; non-ST-elevation myocardial infarction ADULT: Initial bolus of 60 units/kg (max. 4000 units), followed by an initial infusion of 12 units/kg/hour (max. 1000 units/hour); Treatment of venous thromboembolism ADULT: 80 units/kg (or 5000 units) IV injection followed by continuous IV infusion of 18 units/kg/hour (or 1300 units/hour)."],["Contraindications","Severe thrombocytopenia, uncontrolled active bleeding, suspected intracranial haemorrhage, intramuscular use, hypersensitivity to pork products."],["Cautions","Elderly, bacterial endocarditis, haemophilia, severe hypertension, gastrointestinal ulceration, hepatic disease."],["Side effects","Thrombocytopenia, local irritation, erythema, injection site ulcer, increased liver aminotransferase, haemorrhage, hematoma, osteoporosis, hyperkalemia. Renal Impairment Risk of bleeding increased in severe impairment; dose may need to be reduced."],["Hepatic impairment","Risk of bleeding increased; Reduce dose or avoid in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Compatible"],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Heparin 5000 IU/mL injection (5mL) vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":"ufh"},{"k":"TRANEXAMIC ACID","n":"TRANEXAMIC ACID","g":"Antifibrinolytic agent.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Antifibrinolytic; blocks lysine-binding sites on plasminogen, preventing fibrin breakdown.","f":[["Indications & dose","Treatment and prophylaxis of haemorrhage associated with excessive fibrinolysis; To control bleeding during neurosurgical operations ADULT: 1-1.5 g PO, Q8-12H, alternatively 15-25 mg/kg PO, Q8-12H; 0.5-1g Slow IV injection, Q8-12H administered at a rate not exceeding 100 mg/minute; dose followed by 25-50 mg/kg continuous IV infusion, dose given over 24 hours."],["Contraindications","Active intravascular clotting, history of convulsion, thromboembolic disease."],["Cautions","Irregular menstrual bleeding, massive hematuria, patients receiving OCP."],["Side effects","Nausea, vomiting, diarrhoea, infrequently hypotension, thrombosis."],["Renal impairment","Dose reduction required in impairment."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Tranexamic acid 250mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Tranexamic acid 100mg/mL injection (5mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Tranexamic acid 250mg tablet: now supplied down to DH"]],"al":""},{"k":"WARFARIN","n":"WARFARIN","g":"Anticoagulant.","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Vitamin K epoxide reductase (VKORC1) inhibitor; reduces synthesis of factors II, VII, IX, X and proteins C and S.","f":[["Indications & dose","Prophylaxis of venous thrombosis, stroke and thromboembolism; Cardiac valve replacement; Post myocardial infarction ADULT: Induction dose, 10 mg PO, daily for 2 days; subsequent daily maintenance dose (3-9 mg/day) to be determined depending upon the prothrombin time."],["Contraindications","Avoid use within 48 hours of postpartum, haemorrhage stroke, significant bleeding, cerebrovascular haemorrhage."],["Cautions","Peptic ulcer, severe hypertension, bacterial endocarditis."],["Side effects","Haemorrhage, rash, alopecia, diarrhoea."],["Renal impairment","Use with caution in mild to moderate impairment; In severe renal impairment, monitor INR more frequently."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","X"],["Breast-feeding","Excreted traces amount in milk, use with caution."],["Note","Warfarin usually takes 3-5 days to reach steady state, use heparin during this period. Dose adjusted according to the International Normalised Ratio (INR)."],["Counselling","Do not start or stop any other medicines without checking with the doctor; do regular blood tests, take medication at the same time each day with food or without food."]],"f25":[{"i":"Warfarin 1mg tablet","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is an INR facility. The three formulation should"},{"i":"Warfarin 3mg tablet","v":"V","l":"NRH/RRH","r":"have different colours as per FDA recommendation"},{"i":"Warfarin 5mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"FRESH FROZEN PLASMA (FFP)","n":"FRESH FROZEN PLASMA (FFP)","g":"Blood and blood components.","sec":"11. BLOOD PRODUCTS OF HUMAN ORIGIN AND PLASMA SUBSTITUTES","sub":"11.1 Blood and blood components","moa":"Replaces all soluble coagulation factors and plasma proteins.","f":[["Indications & dose","Multiple factor deficiencies, severe liver disease, DIC, warfarin reversal. Fresh frozen plasma prepared from whole blood within 6 hours of collection and frozen immediately in a plasma freezer. It contains both stable and unstable coagulation factors like fibrinogen, factor V and VIII. Precautions It should not be used simply for volume correction in the absence of coagulation deficit nor as a source of albumin or immunoglobulin. FFP should not be used where a suitable alternative product is available. Once thawed the plasma should be used immediately especially for correction of unstable clotting factors. It cannot be refrozen after thawing. Integrity of the bag should be checked before use."],["Side effects","Acute allergic reactions are common, febrile (non hemolytic reaction), viral transmission, bacterial contamination - sepsis."],["Note","Transfusion of FFP or liquid plasma does not require crossmatching."]],"f25":[{"i":"Fresh - frozen plasma","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"PLATELETS","n":"PLATELETS","g":"Blood and blood components.","sec":"11. BLOOD PRODUCTS OF HUMAN ORIGIN AND PLASMA SUBSTITUTES","sub":"11.1 Blood and blood components","moa":"Replaces platelets to support primary haemostasis.","f":[["Indications & dose","Bleeding due to low platelet count or impaired function. Platelet is a component obtained by centrifugation of fresh blood within 6 to 8 hours. One unit of platelet concentrate increases the platelet count by 10,000 to 20,000/ul of blood."],["Contraindications","Not generally indicated for prophylaxis of bleeding in surgical patients, unless known to have significant preoperative platelet deficiency. Precautions Repeated transfusions can lead to production of antibodies against platelets causing destruction of platelets. The clinician advising platelet transfusions should keep this in mind Presence of hypersplenism, DIC or septicemia can affect the increase in platelet count. Not indicated Immune/Idiopathic thrombocytopenia (ITP), thrombotic thrombocytopenia (TTP)."],["Side effects","Febrile, non-haemolytic and allergic reactions are common in patients receiving multiple transfusions."],["Note","Cross-matching is not required unless gross red cell contamination is seen in the unit chosen for transfusion."]],"f25":[{"i":"Platelets","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"RED BLOOD CELLS","n":"RED BLOOD CELLS","g":"Blood and blood components.","sec":"11. BLOOD PRODUCTS OF HUMAN ORIGIN AND PLASMA SUBSTITUTES","sub":"11.1 Blood and blood components","moa":"Restores oxygen-carrying capacity (haemoglobin).","f":[["Indications & dose","Chronic symptomatic anaemia, acute blood loss. Red blood cells a component obtained by removal of part of the plasma either by sedimentation method or centrifugation of whole blood. Precautions: -Same as for whole blood."],["Side effects","Same as whole blood."]],"f25":[{"i":"Red blood cells","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"WHOLE BLOOD","n":"WHOLE BLOOD","g":"Blood and blood components.","sec":"11. BLOOD PRODUCTS OF HUMAN ORIGIN AND PLASMA SUBSTITUTES","sub":"11.1 Blood and blood components","moa":"Restores red cell mass, volume and (if fresh) plasma factors.","f":[["Indications & dose","Acute blood loss, exchange transfusion and massive transfusion. Whole blood freshly drawn blood maintains all the properties for a limited period usually 24 hours. Changes in the whole blood after 24 hours: 1. Decreased unstable coagulation blood factors like V and VIII. 2. Decreased platelet viability. Whole blood after 48 hours of storage contains no viable platelets. 3. Decreased 2, 3 DPG levels – (However it regenerates after transfusion in the circulation of the recipient) Increased potassium level in plasma due to release of the intracellular potassium. 4. Increased acidity of the plasma. Precautions Identical ABO group or ABO compatible blood should be used. Rh negative patients should get Rh negative blood especially women in childbearing age groups."],["Contraindications","Patients with chronic, decompensated anaemia."],["Side effects","Circulatory overload in cases of decompensated anaemia, heart and renal failure. Formation of antibodies in the patient against donor red cell antigens and human leukocyte antigens (HLA) leading to transfusion reactions. Transfusion transmitted infections (TTIs). Citrate intoxication in neonates and in patients with impaired liver function getting massive transfusion. Hyperkalemia in massive transfusion."]],"f25":[{"i":"Whole blood","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ANTI-TETANUS IMMUNOGLOBULIN (HUMAN)","n":"ANTI-TETANUS IMMUNOGLOBULIN (HUMAN)","g":"Sera and immunoglobulin.","sec":"11. BLOOD PRODUCTS OF HUMAN ORIGIN AND PLASMA SUBSTITUTES","sub":"11.2.1 Human immunoglobulins","moa":"Passive immunity; antibodies neutralise unbound tetanospasmin toxin.","f":[["Indications & dose","Post exposure prophylaxis By IM injection, ADULT: initially 250 units, then increased to 500 units, dose is only increased if more than 24 hours have elapsed or there is risk of heavy contamination or following burns; CHILD: initially 250 units, then increased to 500 units, dose is only increased if more than 24 hours have elapsed or there is risk of heavy contamination or following burns. Treatment of tetanus infection, By IM injection, ADULT: 150 units/kg, dose may be given over multiple sites."],["Contraindications","hypersensitivity to gamma globulins, IgA, thimerosal."],["Cautions","thrombocytopenia or coagulation disorder, IgA deficiency, interference with live virus vaccines."],["Side effects","injection site pain, lethargy, chest tightness, anaphylaxis (rare), serum sickness, with fever, vomiting, diarrhoea, bronchospasm and urticaria may often occur 7-10 days after the injection. Pregnancy Category C"],["Breast-feeding","excretion unknown, no adverse effects reported."],["Note","Immunoglobulins should be protected from light. Opened multi-dose vials must be used within the period recommended in the product literature."]],"f25":[{"i":"Anti-tetanus immunoglobulin (Human) 500 IU injection vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"HUMAN ALBUMIN","n":"HUMAN ALBUMIN","g":"Plasma volume expander.","sec":"11. BLOOD PRODUCTS OF HUMAN ORIGIN AND PLASMA SUBSTITUTES","sub":"11.2.2 Plasma substitutes","moa":"Raises plasma oncotic pressure, drawing fluid into the intravascular space; binds and transports drugs and bilirubin.","f":[["Indications & dose","Ascites and large volume paracentesis (refractory to sodium restriction (90 mmol/day) Normal premorbid renal function: 1 unit (100 mL) IV infusion, STAT following every 3 litres of ascites drained; Renal function is impaired: 100 mL, IV infusion, per 2 litres of ascites. Spontaneous bacterial peritonitis (SBP) and cirrhosis 1.5 g/kg IV infusion within 6-hours of detection (day 1) and 1 g/kg on day 3. Hepatorenal Syndrome (HRS) confirmed 25-50 g /day IV infusion, for a total of 72 hours. Hypoproteinemia in the acutely ill patient 50-75 g IV infusion, administered not exceeding 2 mL/minute. Shock Initial dose of 20 g IV infusion, administered at a rate of 2-4 mL/minute; with rate of infusion increased in emergencies and repeated in 15-30 minutes if necessary; Max. 2 g/kg in absence of active bleeding. Burns 20-80 g/day IV infusion administered at the rate of about 1 mL per minute; Beyond 24 hours, the goal is the maintenance of a plasma albumin concentration of 25 g/L or a colloid osmotic pressure of 20 mmHg. Adult respiratory distress syndrome 50 g IV infusion over the first 24 hours together with diuretic therapy; then dose adjusted according to requirement."],["Contraindications","Severe anaemia, cardiac failure."],["Cautions","Rapid infusion may cause vascular overload, chronic renal insufficiency, patients on sodium restriction, preterm infants."],["Side effects","Hypersensitivity reaction, oedema, fever, chill, headache, flushing, nausea."],["Renal impairment","Use with caution in patients with renal impairment."],["Hepatic impairment","Use with caution in patients with hepatic impairment."],["Pregnancy category","C"],["Breast-feeding","Compatible."],["IV fluid compatibility","Dextrose 5%, dextrose 10%, compound solution of sodium lactate, dextrose 5% in sodium chloride 0.45%."],["Note","Albumin 25% can be diluted with sodium chloride 0.9% or dextrose 5%. When dosing albumin, the 5% solution should be used in hypovolemic patients and the 25% solution should be used in patients in whom fluid and sodium intake is restricted. Albumin should not be diluted with sterile water because this can cause hemolysis."]],"f25":[{"i":"Human albumin 20% injection (100mL) bottle","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"AMLODIPINE","n":"AMLODIPINE","g":"Medicine use for heart failure, antianginal, antiarrhythmic and antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Dihydropyridine calcium channel blocker; blocks L-type channels in vascular smooth muscle, causing arterial vasodilation.","f":[["Indications & dose","Hypertension and Prophylaxis of angina ADULT: Initially 5 mg PO, Q24H, max. 10 mg/day. Hypertension Child (1 month-11 years): Initially 100-200 mcg/kg PO, Q24H; increased if necessary up to 400 mcg/kg Q24H, adjusted at intervals of 1-2 weeks; max. 10 mg/day."],["Contraindications","Cardiogenic shock, unstable angina, significant aortic stenosis."],["Cautions","Hepatic impairment."],["Side effects","Abdominal pain, dizziness, fatigue, flushing, headache, nausea, oedema, palpitation, sleep disturbances."],["Hepatic impairment","Dose reduction."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, avoid."]],"f25":[{"i":"Amlodipine 5mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Amlodipine 5mg tablet: now supplied down to PHC"]],"al":""},{"k":"BISOPROLOL","n":"BISOPROLOL","g":"Medicine use for heart failure, antianginal, antiarrhythmic and antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Cardioselective beta-1 blocker; lowers heart rate, contractility and renin. Mortality benefit in heart failure.","f":[["Indications & dose","Congestive heart failure ADULT: Initially 1.25 mg once daily for 1 week, then increased if tolerated to 2.5 mg once daily for 1 week. Can be increased in the order of 3.75 mg once daily for 1 week, 5 mg once daily for 4 weeks, 7.5 mg once daily for 4 weeks, and 10 mg once daily if tolerated according to patient conditions, maximum 10 mg per day. Hypertension and Angina ADULT: Initially 5 mg once daily, titrate up to 10 mg or 20 mg once daily if necessary to achieve adequate response. Arrhythmias 2.5 mg once daily, titrate the dose as needed MAX: 10 mg per day."],["Contraindications","Acute or decompensated heart failure requiring intravenous inotropes and sino-atrial block, severe bradycardia."],["Cautions","Gradually increase the dose in stable heart failure."],["Side effects","Constipation, muscle cramps, muscle weakness, postural hypotension."],["Renal impairment","CrCl less than 40 mL/min: Initial, 2.5 mg orally once daily, titrate cautiously."],["Hepatic impairment","Hepatitis or cirrhosis: Initial, 2.5 mg orally once daily, titrate cautiously."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use caution."]],"f25":[{"i":"Bisoprolol 5mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CARVEDILOL","n":"CARVEDILOL","g":"Medicine use for heart failure, antianginal, antiarrhythmic and antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Non-selective beta-blocker with alpha-1 blockade (vasodilation); antioxidant. Mortality benefit in heart failure.","f":[["Indications & dose","Angina ADULT: Initially 12.5 mg PO, Q12H x 2 days, then increased to 25 mg, Q12H. Hypertension ADULT: Initially 12.5 mg PO, Q24H x 2 days, then increased to 25 mg, Q24H; increased if necessary up to 50 mg/day, dose to be increased at intervals of at least 2 weeks as a single dose or in divided doses; ELDERLY: Initially 12.5 mg PO, Q24H. Adjunct to diuretics, digoxin, or ACE inhibitors in symptomatic chronic heart failure ADULT: Initially 3.125 mg PO, Q12H, then increased to 6.25 mg, Q12H, then increased to 12.5 mg, Q12H, then increased to 25 mg, Q12H, dose should be increased at intervals of at least 2 weeks up to the highest tolerated dose; Max. 25 mg, Q12H in patients with severe heart failure or body-weight less than 85 kg; max. 50 mg, Q12H in patients over 85 kg."],["Contraindications","Bronchial asthma, bronchospasm, COPD, 20/30 AV block, cardiogenic shock, severe bradycardia, decompensated heart failure requiring intravenous inotropes, severe hepatic impairment."],["Cautions","Anesthesia or surgery, cerebrovascular insufficiency, diabetes mellitus, hyperthyroidism or thyrotoxicosis, liver disease, peripheral vascular disease, compromised left ventricular function, heart failure, pheochromocytoma, and myasthenia gravis, avoid beta-blocker use in non-allergic bronchospasm. Sudden discontinuance can exacerbate angina and lead to myocardial infarction, mild to moderate hepatic impairment, elderly."],["Side effects","Dizziness, fatigue, hypotension, weight gain, hyperglycemia, diarrhoea, bradycardia, nausea, cough, headache, atrioventricular block, oedema, angina, hypercholesterolemia, hypertriglyceridemia, vomiting, dyspnea, syncope."],["Hepatic impairment","Avoid in hepatic impairment."],["Pregnancy category","C; D in second and third trimester."],["Breast-feeding","Excretion in milk unknown, avoid."],["Note","Beta-blocker therapy in patients with heart failure can be extremely difficult to manage, the initiation and up-titration should be undertaken in consultation with a specialist."],["Counselling","Take medication with food and don’t stop the medication suddenly."]],"f25":[{"i":"Carvedilol 12.5mg tablet","v":"E","l":"NRH/RRH","r":""},{"i":"Carvedilol 3.125mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ISOSORBIDE DINITRATE","n":"ISOSORBIDE DINITRATE","g":"Antianginal (nitrates).","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Organic nitrate; releases nitric oxide, raising cGMP and relaxing venous (and coronary) smooth muscle, reducing preload.","f":[["Indications & dose","Prophylaxis of angina ADULT: 2.5-5 mg sublingually, 15 minutes before performing activities likely to cause angina; 20-240 mg/day PO, in divided doses. Treatment of angina ADULT: 2.5-5 mg sublingually; repeated Q5-10 minutes; not to exceed 3 doses in 15-30 minute. Resistant congestive heart failure; left ventricular failure 30-120mg/day in divided doses, up to 240 mg/day in heart failure."],["Contraindications","Severe anaemia, shock, markedly low blood pressure, closed angle glaucoma, head trauma, cerebral haemorrhage."],["Cautions","Allergies to nitrates, head trauma/cerebral haemorrhage, hypertrophic cardiomyopathy, increased intraocular pressure, postural hypotension, acute myocardial infarction (MI), congestive heart failure, hyperthyroidism."],["Side effects","Throbbing headache, flushing, postural hypotension, tachycardia; paradoxical bradycardia."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["Note","Regular prophylaxis with oral medication is effective if given regularly at adequate dosage and is considerably cheaper; for mild or occasional chest pain, immediate sublingual treatment is preferred."],["Counselling","Sublingual tablet to place under your tongue and let it dissolve slowly."]],"f25":[{"i":"Isosorbide dinitrate 5mg sublingual tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Deleted in 2025","Isosorbide dinitrate 10mg tablet removed (was available DH). Reason: Substituted by Ranolazine and availability of ISDN 5mg sublingual"]],"al":""},{"k":"METOPROLOL SUCCINATE","n":"METOPROLOL SUCCINATE","g":"Antianginal, antihypertensive (beta-blockers).","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Cardioselective beta-1 blocker (extended release); reduces heart rate and myocardial oxygen demand.","f":[["Indications & dose","Hypertension, Treatment 25-100 mg/day PO, STAT or Q12H; dose increased every week as needed up to 400 mg Q24H; CHILD (≥ 6 Years): 1 mg/kg PO, Q24H (max. 50 mg/dose/day; 2 mg/kg; 200 mg/day). Angina, Treatment 100 mg PO, STAT; dose increased at weekly intervals as needed up to 400 mg/day. Heart failure 25 mg PO, Q24H x 2 weeks in patients with NYHA Class II heart failure and 12.5 mg PO, Q24H in patients with more severe heart failure; Double the dose every two weeks to up to 200 mg."],["Contraindications","Child <6 years, Severe bradycardia, second- or third-degree heart block, cardiogenic shock, decompensated cardiac failure, sick sinus syndrome."],["Cautions","Bronchospastic disease, major surgery, diabetes and hypoglycemia, thyrotoxicosis, hepatic impairment, peripheral vascular disease, pheochromocytoma."],["Side effects","Tiredness, dizziness, depression, shortness of breath, bradycardia, hypotension, diarrhoea, pruritus, rash."],["Hepatic impairment","Reduce dose in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Note","For treatment of angina, if treatment is to be discontinued, reduce the dosage gradually over a period of 1 to 2 weeks."]],"f25":[{"i":"Metoprolol succinate 25mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"NIFEDIPINE","n":"NIFEDIPINE","g":"Antianginal (calcium channel blockers).","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Dihydropyridine calcium channel blocker; arterial vasodilation. Also a tocolytic.","f":[["Indications & dose","and dosage Angina prophylaxis; Hypertension 20 mg PO, Q12H, increased up to max. of 40 mg, Q12H."],["Contraindications","Cardiogenic shock, acute attacks of angina, unstable angina and within 1 month of myocardial infarction."],["Cautions","Diabetes mellitus, elderly, heart failure, poor cardiac reserve, severe hypotension."],["Side effects","Asthenia, dizziness, GI disturbance, headache, hypotension, lethargy, oedema, palpitation, vasodilatation."],["Hepatic impairment","reduces the dose in severe liver disease."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","SR tablets should not be broken and swallowed whole."]],"f25":[{"i":"Nifedipine 20mg sustained release tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Nifedipine 20mg sustained release tablet: now supplied down to PHC"]],"al":""},{"k":"NITROGLYCERIN","n":"NITROGLYCERIN","g":"Antianginal.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Nitrate; releases nitric oxide, raising cGMP and causing venodilation (reduces preload) and coronary dilation.","f":[["Indications & dose","Induction of controlled hypotension during surgery; Congestive heart failure; Unstable angina 5 mcg/minute IV infusion, increase by 5 mcg/minute, every 3-5 minutes to 20 mcg/minute; If no response at 20 mcg/minute increase by 10mcg/minute, every 3-5 minutes, up to 200 mcg/minute."],["Contraindications","Hypersensitivity to nitrates, hypotensive conditions and hypovolemia, hypertrophic obstructive cardiomyopathy, aortic stenosis, cardiac tamponade, constrictive pericarditis, mitral stenosis, marked anaemia, head trauma, cerebral haemorrhage, closed angle glaucoma."],["Cautions","Heart failure due to obstruction, hypothermia, hypothyroidism, hypoxemia, malnutrition, recent history of myocardial infarction, susceptibility to angle-closure glaucoma, tolerance, ventilation and perfusion abnormalities."],["Side effects","Dizziness, postural hypotension, tachycardia, throbbing headache, flushing, heartburn, nausea, rash, syncope, temporary hypoxemia, vomiting; With transdermal use Application site reactions; With IV use abdominal pain, apprehension, diaphoresis, muscle twitching, palpitation, restlessness, retrosternal discomfort, severe hypotension."],["Renal impairment","Use with caution in severe impairment."],["Hepatic impairment","Caution in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5% sodium chloride 0.9%, compound solution of sodium lactate."],["Note","injection is to be used only after suitable dilution, final concentration should not exceed 400 mcg/mL."]],"f25":[{"i":"Nitroglycerin 5mg/mL injection (5mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":"gtn glyceryl trinitrate"},{"k":"VERAPAMIL","n":"VERAPAMIL","g":"Antianginal, antiarrhythmic.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Non-dihydropyridine calcium channel blocker; slows SA/AV nodal conduction and reduces contractility.","f":[["Indications & dose","Supraventricular arrhythmias 40-120 mg PO, Q8H; CHILD (2-17 years): 40-120 mg PO, Q8-12H. Angina 80-120 mg PO, Q8H, not to exceed 480 mg/day. Hypertension ADULT: 240-480 mg/day PO, Q8-12H; CHILD (2-17 years): 40-120mg PO, Q8-12H. Prophylaxis of cluster headache ADULT: 240-960 mg/day PO, Q6-8H."],["Contraindications","Acute porphyrias, atrial flutter or fibrillation associated with accessory conducting pathways, bradycardia, cardiogenic shock, history of heart failure and significantly impaired left ventricular function (even if controlled by therapy), hypotension, second- and third-degree AV block, sick sinus syndrome, sino-atrial block."],["Cautions","Acute phase of myocardial infarction (avoid, if bradycardia, hypotension and left ventricular failure), first degree AV block."],["Side effects","Constipation, ankle oedema, dizziness, fatigue, flushing, headache, nausea, vomiting, angioedema, arthralgia, asystole."],["Renal impairment","Use with caution."],["Hepatic impairment","Dose may need to be reduced; in cirrhosis, reduce dose by 20-50% of normal dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Verapamil 40mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ADENOSINE","n":"ADENOSINE","g":"","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.2 Antiarrhythmic agents","moa":"Activates A1 receptors in the AV node, opening K+ channels and transiently blocking AV conduction (terminates re-entrant SVT).","f":[["Indications & dose","Rapid reversion to sinus rhythm of paroxysmal supraventricular tachycardias, including those associated with accessory conducting pathways ADULT: Initially 6 mg rapid IV injection, administered into central or large peripheral vein and given over 2 seconds, followed by 12 mg after 1-2 minutes if required, then 12 mg after 1-2 minutes if required, increments should not be given if high level AV block develops at any particular dose; CHILD (1-11 months): Initially 150 mcg/kg rapid IV injection, then increased in steps of 50-100 mcg/kg, Q1-2 minutes (max. 500 mcg/kg/dose) if required, dose to be repeated until tachycardia terminated or maximum single dose given; CHILD (1-11 years): Initially 100 mcg/kg rapid IV injection, then increased in steps of 50-100 mcg/kg, Q1-2 minutes (max. 12 mg/dose) if required, dose to be repeated until tachycardia terminated or maximum single dose given; CHILD (12-17 years): Initially 3 mg rapid IV injection, followed by 6 mg after 1-2 minutes if required, followed by 12 mg after 1-2 minutes if required."],["Contraindications","Asthma, chronic obstructive lung disease, decompensated heart failure, long QT syndrome, second-or third-degree AV block and sick sinus syndrome (unless pacemaker fitted), severe hypotension."],["Cautions","Atrial fibrillation or flutter with accessory pathways, autonomic dysfunction, bundle branch block, first-degree AV block, heart transplant, left main coronary artery stenosis, left to right shunt, pericardial effusion, pericarditis, QT-interval prolongation, recent myocardial infarction, severe heart failure, stenotic carotid artery disease with cerebrovascular insufficiency, stenotic valvular heart disease, uncorrected hypovolemia."],["Side effects","Angina (discontinue), apprehension, arrhythmia (discontinue if asystole or severe bradycardia occur), AV block, dizziness, dyspnea, flushing, headache, nausea, sinus pause, blurred vision, hyperventilation, metallic taste, palpitation, sweating, weakness."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, avoid."],["IV fluid compatibility","Sodium chloride 0.9%."],["Note","3 mg dose ineffective in a number of patients, therefore higher initial dose may be necessary but for patients with heart transplant who are very sensitive to effects of adenosine should not receive higher initial dose."]],"f25":[{"i":"Adenosine 3mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"AMIODARONE","n":"AMIODARONE","g":"Antiarrhythmic. For details, refer to page no.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.2 Antiarrhythmic agents","moa":"Class III antiarrhythmic (K+ channel block prolongs repolarisation) with class I, II and IV actions.","f":[["Indications & dose","Treatment of arrhythmias, particularly when other medicines are ineffective or contraindicated (including paroxysmal supraventricular, nodal and ventricular tachycardias, atrial fibrillation and flutter, ventricular fibrillation, and tachyarrhythmias associated with Wolff Parkinson-White syndrome), by Orally, ADULT: 200 mg PO, Q8H x 1 week, then reduce to 200 mg, Q12H x 1 week, followed by maintenance dose, usually 200 mg/day or the minimum dose required to control arrhythmia; CHILD (1 month-11 years): Initially 5-10 mg/kg (max. 200 mg/dose) PO, Q12H x 7-10 days, then reduced to 5-10 mg/kg Q24H; max. 200 mg/day; by Injection, ADULT: Initially 5 mg/kg IV infusion, to be given over 20-120 minutes with ECG monitoring, subsequent infusions given if necessary according to response; max. 1.2 g/day; CHILD: Initially 5-10 mg/kg IV infusion, dose given over 20 minutes to 2 hours, then 300 mcg/kg/hour, adjusted according to response; increased if necessary up to 1.5 mg/kg/hour; max. 1.2 g/day. Ventricular fibrillation or pulseless ventricular tachycardia refractory to defibrillation (for cardiopulmonary resuscitation) ADULT: Initially 300 mg IV injection, dose to be considered after administration of adrenaline, dose should be given diluted in 20mL Dextrose 5%, then 150mg if required, followed by (900 mg/24H); CHILD: 5 mg/kg (max. 300 mg/dose) IV injection, dose to be given over at least 3 minutes."],["Contraindications","Severe conduction disturbances and sinus node disease (unless pacemaker fitted), iodine sensitivity, sino-atrial heart block and sinus bradycardia (except in cardiac arrest), thyroid dysfunction; With IV use Bolus injection in cardiomyopathy and congestive heart failure, circulatory collapse, severe arterial hypotension, severe respiratory failure."],["Cautions","Acute porphyrias, conduction disturbances, elderly, heart failure, hypokalemia, severe bradycardia; With IV use Moderate and transient fall in blood pressure; severe hepatocellular toxicity."],["Side effects","Bradycardia, hyperthyroidism, hypothyroidism, jaundice, nausea, persistent slate grey skin discoloration, phototoxicity, pulmonary toxicity, raised serum transaminases, reversible corneal microdeposits, sleep disorders, taste disturbances, tremor, vomiting."],["Hepatic impairment","Avoid in severe impairment. Liver function tests required before treatment and then every 6 months."],["Pregnancy category","D"],["Breast-feeding","Excreted in milk, use with caution."],["IV fluid compatibility","Dextrose 5%."],["Counselling","Patients should be advised to shield the skin from light during treatment and for several months after discontinuing amiodarone; a wide-spectrum sunscreen to protect against both long-wave ultraviolet and visible light should be used."]],"f25":[{"i":"Amiodarone 200mg tablet","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Medical Specialist"},{"i":"Amiodarone 50mg/mL injection (3mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"DIGOXIN","n":"DIGOXIN","g":"Antiarrhythmic and medicine used in heart failure.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.2 Antiarrhythmic agents","moa":"Inhibits Na+/K+-ATPase, raising intracellular Ca2+ (positive inotropy); increases vagal tone, slowing AV conduction.","f":[["Indications & dose","Rapid digitalization, for atrial fibrillation or flutter ADULT: 0.75-1.5 mg PO, in divided doses; reduce dose in the elderly. Maintenance, for atrial fibrillation or flutter ADULT: Maintenance 125-250 mcg/day, dose according to renal function and initial loading dose, reduce dose in the elderly. Heart failure (for patients in sinus rhythm) ADULT: 62.5-125 mcg PO, Q4H; reduce dose in the elderly. Emergency loading dose, for atrial fibrillation or flutter ADULT: Loading dose 0.75-1 mg IV infusion, given over at least 2 hours, then PO; maintenance, start on the following day, reduce dose in the elderly."],["Contraindications","Constrictive pericarditis, hypertrophic cardiomyopathy, intermittent complete heart block, myocarditis; second degree AV block, Supraventricular arrhythmias associated with accessory conducting pathways e.g. Wolff-Parkinson-White syndrome (although can be used in infancy), ventricular tachycardia or fibrillation."],["Cautions","Hypercalcemia, hypokalemia, hypomagnesaemia, hypoxia, recent myocardial infarction, severe respiratory disease, sick sinus syndrome, thyroid disease."],["Side effects","Arrhythmias, blurred vision, conduction disturbances, diarrhoea, dizziness, eosinophilia, nausea, rash, vomiting, yellow vision."],["Renal impairment","Reduce dose, monitor plasma-digoxin concentration in renal impairment"],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution. Iv fluid compatibility Dextrose 5%, dextrose 10%, compound solution of sodium lactate, sodium chloride 0.9%."],["Note","Adjust maintenance dose by estimating CrCl and measuring serum levels; Use lower end of dosing (0.125 mg/day) in patients with impaired renal function or low lean body mass. When switching from IV to oral route may need to increase dose by 20-33% to maintain the same plasma-digoxin concentration."]],"f25":[{"i":"Digoxin 250µg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Digoxin 250µg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"DILTIAZEM","n":"DILTIAZEM","g":"Antiarrhythmic.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.2 Antiarrhythmic agents","moa":"Non-dihydropyridine calcium channel blocker; slows AV conduction and dilates coronary arteries.","f":[["Indications & dose","Paroxysmal supraventricular tachycardia and Atrial fibrillation 0.25 mg/kg (average adult dose, 20 mg) IV bolus over 2 minutes; after 15 minutes, 0.35 mg/kg of actual body weight over 2 min (average adult dose, 25 mg) direct IV if first dose tolerated but response inadequate; Continuous infusion 10 mg/hr, IV initially; increased to no more than 15 mg/hr x 24 hours."],["Contraindications","Use in new-born, concomitant beta-blocker therapy. cardiogenic shock, ventricular tachycardia."],["Cautions","Hepatic and renal failure, heart failure or significantly impaired left ventricular function, bradycardia (avoid if severe), first degree AV block or prolong PR interval."],["Side effects","Oedema, headache, dizziness, AV block, peripheral oedema, bradyarrhythmia, headache, hypotension, nausea, vomiting, vasodilation, extrasystoles, flushing, medicine-induced gingival hyperplasia, myalgia, diarrhea, constipation, bronchitis, sinus congestion, dyspnea."],["Renal impairment","Start with a smaller dose."],["Hepatic impairment","Reduce dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Dextrose 5%, sodium chloride 0.9%."],["Note","Use weight-based dosing for lower body weight patients."]],"f25":[{"i":"Diltiazem 5mg/mL injection (10mL) ampoule","v":"V","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"ESMOLOL","n":"ESMOLOL","g":"Antiarrhythmic agent.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.2 Antiarrhythmic agents","moa":"Ultra-short-acting cardioselective beta-1 blocker (metabolised by red cell esterases).","f":[["Indications & dose","Intraoperative tachycardia and/or hypertension I.V.: Initial bolus: 80 mg (1 mg/kg) over 30 seconds, followed by a 150 mcg/kg/minute infusion. Adjust infusion rate as needed to maintain desired heart rate and/or blood pressure, up to 300 mcg/kg/minute. Supraventricular tachycardia or gradual control of postoperative tachycardia/hypertension: I.V.: Loading dose: 500 mcg/kg over 1 minute; follow with a 50 mcg/kg/minute infusion for 4 minutes. Supraventricular tachycardias (SVT): Usual dosage range: 50-200 mcg/kg/minute with average dose of 100 mcg/kg/minute."],["Contraindications","sinus bradycardia, heart block greater than first degree, cardiogenic shock, uncompensated heart failure."],["Cautions","Bronchospastic disease, cerebrovascular insufficiency, CHF, DM, hyperthyroidism, liver disease, renal impairment, peripheral vascular disease. Avoid sudden discontinuation, can exacerbate angina and lead to myocardial infarction."],["Side effects","Asymptomatic and symptomatic hypotension, diaphoresis, peripheral ischemia."],["Pregnancy category","C"],["IV fluid compatibility","Stable in dextrose 5% in .0.45% normal saline, dextrose 5% in 0.9% normal saline, dextrose 5%, compound sodium lactate solution."],["Note","Concentrations >10 mg/mL or infusion into small veins or through a butterfly catheter should be avoided (can cause thrombophlebitis). Infusions must be administered with an infusion pump."]],"f25":[],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ENALAPRIL","n":"ENALAPRIL","g":"Antihypertensive and medicine used in heart failure.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"ACE inhibitor (prodrug); reduces angiotensin II and aldosterone and increases bradykinin.","f":[["Indications & dose","Hypertension ADULT: Initially 5 mg PO, Q4H; lower initial doses may be required when used in addition to diuretic or in renal impairment; maintenance 20 mg, Q24H; max. 40 mg/day; CHILD (1 month-11 years): Initially 100 mcg/kg PO, Q24H, then increased if necessary up to 1 mg/kg/day in 1-2 divided doses; CHILD (12-17 years) (body weight up to 50 kg): Initially 2.5 mg PO, Q24H, maintenance 10-20 mg/day in 1-2 divided doses; CHILD (12-17 years)(body-weight 50 kg and above): Initially 2.5 mg PO, Q24H, maintenance 10-20 mg/day in 1-2 divided doses; max. 40 mg/day. Heart failure ADULT: Initially 2.5mg PO, Q24H, increased if tolerated to 10-20 mg, Q12H, dose increased gradually over 2-4 weeks; CHILD (1 month-11 years): Initially 100 mcg/kg PO, Q24H, then increased if necessary up to 1 mg/kg/day, Q24H in 1-2 divided doses; CHILD (12-17 years) (body-weight up to 50 kg): Initially 2.5mg PO, Q24H, maintenance 10-20mg/day in 1–2 divided doses; CHILD (12-17 years) (body-weight 50 kg and above): Initially 2.5mg PO, Q24H, maintenance 10-20 mg/kg in 1-2 divided doses; max. 40 mg/day. Prevention of symptomatic heart failure in patients with asymptomatic left ventricular dysfunction ADULT: Initially 2.5 mg PO, Q24H, increased if tolerated to 10-20 mg, Q12H, dose increased gradually over 2-4 weeks."],["Contraindications","Hypersensitivity to ACE inhibitors (including angioedema) and in known or suspected renal artery stenosis, pregnancy."],["Cautions","Patients receiving diuretics, renal impairment, peripheral vascular disease, discontinue STAT if the patient becomes pregnant."],["Side effects","Dizziness, hypotension, headache, chest pain, cough, rash."],["Renal impairment","CrCl <30 mL/min: Initiate 2.5 mg, titrate to response, not to exceed 40 mg; CrCl ≥30 mL/min: Initiate 5 mg/day, titrate to maximum of 40 mg; Dialysis: 2.5 mg PO on day of dialysis, adjust dose on no non-dialysis days according to BP."],["Hepatic impairment","Close monitoring of patients required."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Note","Profound first dose hypotension may occur when ACE inhibitors are introduced in patients with severe heart failure or those receiving high doses of diuretics, high dose vasodilator therapy, hypovolemic, impaired renal, aged 70 years or more."]],"f25":[{"i":"Enalapril 5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FUROSEMIDE","n":"FUROSEMIDE","g":"Antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Loop diuretic; inhibits the Na+/K+/2Cl- cotransporter in the thick ascending limb of the loop of Henle.","f":[["Indications & dose","Resistant hypertension by ORALLY, ADULT: 40-80 mg/day; by INJECTION, ADULT: Initially 20–50 mg, IV injection or IV infusion, then increased in steps of 20 mg every 2 hours if required, doses greater than 50 mg given by IV infusion only; max. 1.5 g per day. For details, refer to page no. 110."]],"f25":[{"i":"Furosemide 10mg/mL injection (2mL) ampoule","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Furosemide 40mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"HYDRALAZINE","n":"HYDRALAZINE","g":"Antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Direct arteriolar vasodilator (interferes with smooth muscle Ca2+ release); reflex tachycardia.","f":[["Indications & dose","Moderate to severe hypertension (adjunct) ADULT: Initially 25 mg PO, Q12H, increased if necessary up to 50, Q12H. Hypertensive emergencies (including during pregnancy); Hypertension with renal complications ADULT: Initially 200-300 mcg/minute IV infusion; maintenance 50-150 mcg/minute; OR ADULT: 5-10 mg diluted with 10 mL sodium chloride 0.9%, slow IV injection, Q20-30 minutes. Heart failure (with long acting nitrate) ADULT: Initially 25 mg PO, Q8-12H; maintenance 50-75 mg, Q6H. Resistant hypertension (adjunct): CHILD (1 month-11 years): 250-500 mcg/kg PO, Q8-12H, increased if necessary to 7.5 mg/kg/day; max. 200 mg/day; CHILD (12-17 years): 25 mg PO, Q12H, increased to 50-100 mg, Q12H; *Slow IV injection: CHILD (1 month-11 years): 100-500 micrograms/kg, dose repeated if necessary q4-6H; max. 3mg/kg/ day; max 60mg/day; CHILD (12-17 years): 5-10mg, dose repeated if necessary q4-6 hours; Continuous IV infusion CHILD (1 month-11 years): 12.5-50 micrograms/kg/hour; max. 3mg/kg/day; CHILD (12-17 years): 3-9mg/hour; max. 3mg/kg/day; *Continuous IV infusion is the preferred route in cardiac patients."],["Contraindications","Severe tachycardia, high-output heart failure, myocardial Insufficiency due to mechanical obstruction, cor pulmonale, dissecting aortic aneurysm."],["Cautions","Cerebrovascular disease, coronary artery disease, occasionally blood pressure reduction too rapid even with low parenteral doses, pulmonary hypertension, discontinue slowly to avoid rapid rise in blood pressure."],["Side effects","Tachycardia, palpitations, flushing, hypotension, fluid retention, GI disturbances, headache, dizziness, systemic lupus erythematosus-like syndrome after long-term therapy with over 100mg daily."],["Renal impairment","Reduce dose if eGFR > 30 mL/min/1.72m . 2"],["Hepatic impairment","Reduce dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Hydralazine 20mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""},{"i":"Hydralazine 25mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"HYDROCHLOROTHIAZIDE","n":"HYDROCHLOROTHIAZIDE","g":"Antihypertensive (Diuretics).","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Thiazide diuretic; inhibits the Na+/Cl- cotransporter in the distal convoluted tubule.","f":[["Indications & dose","Hypertension ADULTS: 12.5-50 mg PO, Q24hr initially and increase to 50 mg daily if required; CHILD (<6 months): 1-3 mg/kg/day PO, Q12hr; not to exceed 37.5 mg/day; CHILD (6 months – years): 1-2 mg/kg/day PO, Q24hr or Q12hr; CHILD (2-12 years): 1-3 mg/kg/day. Oedema ADULT: 25-100mg PO, Q12-24hr; not to exceed 200 mg/day; CHILD (<6 months): 1-3 mg/kg/day PO, Q12hr; CHILD (6 months – years): 1-3 mg/kg/day PO, Q24hr or Q12hr; CHILD (2-12 years): 1-3 mg/kg/day. Hypertension and Mild fluid retention in heart failure 25 mg PO, Q12-24hr; Max. ADULT: 200 mg/day; CHILD (<6 months-2 years): 37.5 mg/day; CHILD (2-12 years): 3 mg/kg/day (100 mg/day)."],["Contraindications","Severe renal or severe hepatic impairment, hyponatremia, hypercalcemia, refractory hypokalemia, symptomatic hyperuricemia, Addison’s disease."],["Cautions","Gout, diabetes, fluid and electrolyte imbalance, hypercholesterolemia, systemic lupus erythematosus, hypercalcemia, hypotension, liver or renal disease, hypokalemia, parathyroid disease."],["Side effects","GI disturbances, water and electrolyte disturbances, hyperglycemia, hyperuricemia, dizziness, epigastric distress, fatigue, headache, hypotension, muscle weakness, rash, vertigo."],["Renal impairment","CrCl <10 mL/min: Avoid use; CrCl ≥10 mL/min: dose adjustment not necessary."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Take this medicine in the morning regularly as instructed."]],"f25":[{"i":"Hydrochlorothiazide 25mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"LOSARTAN","n":"LOSARTAN","g":"Antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Angiotensin II type 1 receptor blocker; vasodilation and reduced aldosterone without bradykinin build-up (less cough).","f":[["Indications & dose","Hypertension (including reduction of stroke risk in hypertension with left ventricular hypertrophy) ADULT: 18-75 years: Initially 50 mg PO, Q24H for several weeks, then increased if necessary to 100 mg, Q24H; ADULT (76 years and over): Initially 25 mg PO, Q24H for several weeks, then increased if necessary to 100 mg, Q24H; CHILD (6-17 years) (body-weight 20-49 kg): Initially 700 mcg/kg PO, Q24H (max. 25 mg/dose), adjusted according to response to 50 mg/day; max. 50 mg/day; CHILD (6-17 years) (body-weight 50 kg and above): Initially 50 mg PO, Q, adjusted according to response to 1.4 mg/kg, Q24H; max. 100 mg/day. Hypertension with intravascular volume depletion ADULT: (18-75 years): Initially 25 mg PO, Q24H for several weeks, then increased if necessary up to 100 mg, Q24H; CHILD 6-17 years (body-weight 50 kg and above): Initially 25 mg PO, Q24H; adjusted according to response to 1.4 mg/kg, Q24H. Chronic heart failure when ACE inhibitors are unsuitable or contra-indicated ADULT: Initially 12.5 mg PO, Q24H, increased if tolerated to up to 150 mg, Q24H, doses to be increased at weekly intervals; max. 100 mg/day. Diabetic nephropathy in type 2 diabetes mellitus ADULT (18-75 years): Initially 50 mg PO, Q24H for several weeks, then increased if necessary to 100 mg, Q24H; ADULT (76 years and over): Initially 25mg PO, Q24H for several weeks, then increased if necessary to 100 mg, Q24H."],["Cautions","Angioedema, volume-depletion, severe congestive heart failure (CHF), hepatic or renal impairment."],["Side effects","Fatigue, hypoglycemia, anaemia, urinary tract infection, chest pain, weakness, diarrhoea, upper respiratory tract infection, hypotension, dizziness, cellulitis, gastritis, nausea."],["Hepatic impairment","Dose reduction in mild to moderate impairment. Avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excretion in milk unknown, avoid."],["Counselling","Dizziness or light-headedness may occur after the first dose of this medicine; do not drive or operate machinery."]],"f25":[{"i":"Losartan 25mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Losartan 50mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Added in 2025","Losartan 50mg tablet added (Till PHC). Reason: Cost-effective and improves patient compliance by reducing pill burden, while also optimizing inventory space, aligning with AHA-recommended dosing (50–100 mg/day), and serving the large national patient population."]],"al":""},{"k":"METHYLDOPA","n":"METHYLDOPA","g":"Antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Converted to alpha-methylnoradrenaline, a central alpha-2 agonist that reduces sympathetic outflow. Safe in pregnancy.","f":[["Indications & dose","Hypertension ADULT: Initially 250 mg PO, Q8-12H, dose should be increased gradually at intervals of at least 2 days; max. 3 g/day; ELDERLY: Initially 125 mg PO, Q12H, dose should be increased gradually; max. 2 g/day."],["Contraindications","Acute porphyria, depression, pheochromocytoma, active liver disease."],["Cautions","CHF, dialysis patients, oedema, hemolytic anaemia, hypotension, severe bilateral CVD, history of liver disease, avoid abrupt withdrawal, risk of decreased libido and impotence in men."],["Side effects","Angina, bradycardia, orthostatic hypotension, depression, dizziness, lethargy, sedation, rash, gynecomastia, impotence, dry mouth, nausea, vomiting, hemolytic anaemia, thrombocytopenia, liver toxicity, arthralgia, autoimmune disease."],["Renal impairment","CrCl >50 mL/min: Q8hr; CrCl 10-50 mL/min: q8-12H; CrCl <10 mL/min: q12-24hr."],["Hepatic impairment","Avoid in acute liver disease."],["Pregnancy category","B"],["Note","Methyldopa is used in hypertension in pregnancy, where other medicines are contraindicated."],["Counselling","May cause drowsiness, do not drive or operate machinery."]],"f25":[{"i":"Methyldopa 250mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"NIMODIPINE","n":"NIMODIPINE","g":"Antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Lipophilic dihydropyridine calcium channel blocker selective for cerebral vessels; prevents vasospasm after subarachnoid haemorrhage.","f":[["Indications & dose","Subarachnoid haemorrhage 60 mg PO, Q4 hours for 21 days, start therapy within 96 hours after subarachnoid haemorrhage."],["Contraindications","Acute porphyria, unstable angina, within 1 month of myocardial infarction."],["Cautions","Cerebral oedema, hypotension, severely raised intracranial pressure, congestive heart failure, Reflex tachycardia, hepatic impairment, cirrhosis."],["Side effects","Flushing, gastro-intestinal disorders, headache, nausea, sweating and thrombocytopenia, variation in heart rate. Renal Impairment Monitor renal function closely. Hepatic Impairment Reduce dosage to 30 mg every 4 hours in patients with liver failure."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."]],"f25":[{"i":"Nimodipine 30mg tablet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"SODIUM NITROPRUSSIDE","n":"SODIUM NITROPRUSSIDE","g":"Antihypertensive.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.3 Antihypertensive agents","moa":"Releases nitric oxide (and cyanide), causing potent arterial and venous dilation.","f":[["Indications & dose","Management of hypertensive crisis; congestive heart failure; controlled hypotension to reduce bleeding during surgery by IV infusion, ADULT: Initial: 0.3-0.5 mcg/kg/minute; increase in increments of 0.5 mcg/kg/minute, titrating to the desired hemodynamic effect or the appearance of headache or nausea; max dose: 10 mcg/kg/minute; CHILD: 0.3 mcg/kg/minute; increase in increments of 0.5 mcg/kg/minute, titrating to the desired hemodynamic effect or the appearance of headache or nausea; max dose: 8 mcg/kg/minute."],["Contraindications","Compensatory hypertension (aortic coarctation, arteriovenous shunting), high output failure, congenital optic atrophy."],["Cautions","Head trauma, hyponatremia, hypothyroidism, severe renal and hepatic impairment, elderly."],["Side effects","Excessive hypotensive response, palpitation, substernal distress, disorientation, psychosis, headache, restlessness, thyroid suppression, nausea, vomiting, weakness, muscle spasm, tinnitus, hypoxia, diaphoresis, thiocyanate toxicity."],["Renal impairment","GFR < 30 mL/min: limit infusion rate to less than 3 mcg/kg/min."],["Hepatic impairment","Use with caution, avoid prolonged use."],["Pregnancy category","C"],["Note","Not suitable for direct injection. Requires dilution prior to infusion. Administration requires the use of an infusion pump."],["Counselling","Solutions are highly sensitive to light. Solutions should be wrapped with aluminium foil or other opaque material to protect from light. Compatibility Stable in compound sodium lactate, dextrose 5% and sodium chloride 0.9%."]],"f25":[{"i":"Sodium nitroprusside 50mg powder for injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Sodium nitroprusside 500mg powder for injection vial → now Sodium nitroprusside 50mg powder for injection vial"]],"al":""},{"k":"DOPAMINE","n":"DOPAMINE","g":"Medicine used in heart failure.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.4 Medicines used in heart failure","moa":"Dose-dependent: D1 (renal/mesenteric dilation) at low dose, beta-1 (inotropy) at moderate, alpha-1 (vasoconstriction) at high dose.","f":[["Indications & dose","Cardiogenic shock in infarction or cardiac surgery, congestive heart failure, septic shock, ADULT: Initial 2-5 mcg/kg/min IV infusion, increase in 5-10 mcg/kg/min (max. 50 mcg/kg/min); CHILD: Initially 5 mcg/kg/min (max. 20 mcg/kg/min)."],["Contraindications","Pheochromocytoma, tachyarrhythmia."],["Cautions","Hypovolemia, hyperthyroidism, ventricular arrhythmias."],["Side effects","Chest pain, dyspnea, headache, hypotension, nausea, palpitation, tachycardia, vasoconstriction, vomiting."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["IV fluid compatibility","Dextrose 5%, dextrose 5% in sodium chloride 0.9%, compound sodium lactate solution."]],"f25":[{"i":"Dopamine 40mg/mL injection (5mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SPIRONOLACTONE","n":"SPIRONOLACTONE","g":"Medicine used in heart failure.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.4 Medicines used in heart failure","moa":"Aldosterone antagonist at the mineralocorticoid receptor in the collecting duct; potassium-sparing diuretic.","f":[["Indications & dose","Oedema; Ascites in cirrhosis of the liver ADULT: 100-400 mg PO, Q24hr, adjusted according to response. Malignant ascites ADULT: Initially 100-200 mg PO, Q24hr, then increased if necessary to 400 mg Q24hr, maintenance dose adjusted according to response. Nephrotic syndrome ADULT: 100-200 mg PO, Q24hr. Oedema in congestive heart failure ADULT: Initially 100 mg PO, Q24hr, alternatively initially 25-200 mg/kg PO, dose may be taken as a single dose or divided doses, maintenance dose adjusted according to response. Moderate to severe heart failure (adjunct) ADULT: Initially 25 mg PO, Q24hr, then adjusted according to response to 50 mg, Q24hr. Resistant hypertension (adjunct) ADULT: 25 mg PO, Q24hr. Primary hyperaldosteronism in patients awaiting surgery ADULT: 100-400 mg PO, Q24hr, may be used for long-term maintenance if surgery inappropriate, use lowest effective dose; CHILD (1 month-11 years): Initially 1-3 mg/kg PO, Q12-24hr; increased if necessary up to 9 mg/kg/day, in resistant ascites; CHILD (12-17 years): Initially 50-100 mg/day, Q12-24hr; increased if necessary up to 9 mg/kg/day, in resistant ascites; max. 400 mg/day."],["Contraindications","Hyperkalemia, anuria, Addison’s disease."],["Cautions","Elderly patients, acute porphyria."],["Side effects","Acute renal failure, agranulocytosis, alopecia, breast pain, changes in libido, dizziness, drowsiness, electrolyte disturbances, GI disturbances, gynaecomastia, hepatotoxicity, hyperkalaemia (discontinue), hypertrichosis, hyperuricemia, hyponatraemia, leg cramps, leukopenia, malaise, menstrual disturbances, rash, Stevens-Johnson syndrome, thrombocytopenia."],["Renal impairment","CrCl >50 mL/min: 25 mg/Q24hr; CrCl 30-50 mL/min: 25 mg/Q 48 Hr"],["Pregnancy category","C"],["Breast-feeding","Metabolite excreted in milk, use with caution."],["Note","For hypertension, doses >75 mg/day may not provide additional reductions in blood pressure."]],"f25":[{"i":"Spironolactone 25mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CLOPIDOGREL","n":"CLOPIDOGREL","g":"Antiplatelet.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.5.1 Antiplatelet medicines","moa":"Prodrug (CYP2C19-activated); irreversibly blocks platelet P2Y12 ADP receptors.","f":[["Indications & dose","Prevention of atherothrombotic events in percutaneous coronary intervention (adjunct with aspirin) in patients not already on clopidogrel ADULT: Loading dose 300 mg PO, prior to the procedure; OR loading dose 600 mg PO, higher dose may produce a greater and more rapid inhibition of platelet aggregation. Transient ischemic attack for patients with aspirin hypersensitivity, or those intolerant of aspirin; Acute ischemic stroke for patients with aspirin hypersensitivity, or those intolerant of aspirin ADULT: 75 mg PO, Q24hr. Prevention of atherothrombotic events in peripheral arterial disease or within 35 days of myocardial infarction, or within 6 months of ischemic stroke ADULT: 75 mg PO, Q24hr Prevention of atherothrombotic events in acute coronary syndrome without ST-segment elevation (given with aspirin) ADULT: Initially 300 mg PO, then 75 mg Q24hr for up to 12 months. Prevention of atherothrombotic events in acute myocardial infarction with ST-segment elevation (given with aspirin) ADULT (18-75 years): Initially 300 mg PO, then 75 mg for at least 4 weeks; ADULT (76 years and over): 75 mg PO, Q24hr for at least 4 weeks. Prevention of atherothrombotic and thromboembolic events in patients with atrial fibrillation and at least one risk factor for a vascular event (with aspirin) and for whom warfarin is unsuitable ADULT: 75 mg PO, Q24hr."],["Contraindications","Active bleeding."],["Cautions","Discontinue 7 days before elective surgery if antiplatelet effect is not desirable, patients at risk of increased bleeding from trauma, surgery, or other pathological conditions, atrial fibrillation, allergic to aspirin."],["Side effects","Abdominal pain, bleeding disorders (including GI and intracranial), diarrhoea, dyspepsia, constipation, decreased platelets, dizziness, duodenal ulcers, eosinophilia, flatulence, gastric ulcer, gastritis, headache, leukopenia, nausea, paraesthesia, pruritus, rash, vomiting."],["Renal impairment","Use with caution."],["Hepatic impairment","Use with caution (risk of bleeding). Avoid in severe impairment."],["Pregnancy category","D"],["Breast-feeding","Excretion in milk unknown, avoid."]],"f25":[{"i":"Clopidogrel 75mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ALTEPLASE","n":"ALTEPLASE","g":"Thrombolytic agent.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.5.2 Thrombolytic medicines","moa":"Recombinant tissue plasminogen activator; converts fibrin-bound plasminogen to plasmin, lysing clots.","f":[["Indications & dose","ST Elevation Myocardial Infarction (STEMI), If patients report to health facility within 6 hours of symptom onset, by IV injection, ADULT, body weight up to 65 kg: 15 mg IV bolus over 1-2 mins followed by 0.75 mg/kg after 30 mins, then 0.5 mg/kg infused over 60 mins, max total dose of 100 mg over 90 mins. Body weight > 65 kg: 15 mg IV bolus over 1-2 mins, followed IV 50 mg, over 30 minutes then 35 mg over 60 minutes, max. dose of 100 mg administered over 90 minutes. If patients report to a health facility after 6-12 hours of symptom onset, IV injection, ADULT, 10 mg followed by 50 mg over 60 minutes then 10 mg for 4 infusions, each 10 mg infusion given over 30 minutes, max. total 100 mg over 3 hours, 1.5 mg/kg in patients less than 65 kg. Acute ischemic stroke ADULT, 18-79 years, initially IV 90 mg within 4.5 hours of symptom onset, followed by 10% of initial dose administered within 60minutes. Pulmonary embolism ADULT: 10 mg over 1-2 minutes, followed by 90 mg, over 2 hours, max. 1.5 mg/kg in patients less than 65 kg."],["Contraindications","History of stroke in patients with diabetes, hyperglycemia, hypoglycemia, severe stroke, stroke in the last 3 months, convulsion accompanying stroke, recent head trauma."],["Cautions","recent major surgery, cerebrovascular disease, hypertension, acute pericarditis, hemostatic defects, severe hepatic and renal dysfunction, avoid IM injection, elderly, pregnancy."],["Side effects","Stroke, intracranial bleeding, gastrointestinal haemorrhage."],["Pregnancy category","C"],["IV fluid compatibility","Stable in sodium chloride, water for injection."]],"f25":[{"i":"Alteplase 50mg powder for injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"STREPTOKINASE","n":"STREPTOKINASE","g":"Thrombolytic.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.5.2 Thrombolytic medicines","moa":"Bacterial protein that complexes with plasminogen to activate plasminogen to plasmin (non-fibrin-specific).","f":[["Indications & dose","Acute myocardial infarction ADULT: 1,500,000 units IV infusion, to be initiated within 12 hours of symptom onset, dose to be given over 60 minutes. Deep-vein thrombosis; Pulmonary embolism; Acute arterial thromboembolism; Central retinal venous or arterial thrombosis ADULT: 250,000 units IV infusion given over 30 minutes, then 100,000 units, Q1hr for up to 12-72 hours, duration is adjusted according to condition with monitoring of clotting parameters. Intravascular thrombosis CHILD (1 month-11 years): Initially 2500-4000 units/kg IV infusion given over 30 minutes, followed by 500-1000 units/kg/hr continuous IV infusion for up to 3 days until reperfusion occurs; CHILD (12-17 years): Initially 250,000 units IV infusion, given over 30 minutes, followed by 100,000 units/hour continuous IV infusion for up to 3 days until reperfusion occurs."],["Contraindications","Severe uncontrolled hypertension, active internal bleeding, recent intracranial or intra-spinal surgery or trauma, intracranial neoplasm, aneurysm, known bleeding diathesis, recent history of cerebrovascular accident, acute pancreatitis."],["Cautions","History of streptococcal infection (within 12 months), previous streptokinase administration (within 12 months), recent major surgery, cerebrovascular disease, recent GI or genitourinary bleeding, pregnancy, diabetic hemorrhagic retinopathy, atrial fibrillation, mitral valve defect."],["Side effects","Fever, hypotension, haemorrhage at injection site, ecchymosis, gastrointestinal bleeding, epistaxis, cardiac dysrhythmia, intracranial haemorrhage, visual acuity, acute respiratory distress syndrome. Pregnancy Category C"],["Breast-feeding","Excretion in milk unknown. Milk should be discarded during the first 24 hours following thrombolytic therapy."],["Note","Streptokinase should not be used again beyond 4 days of first administration."]],"f25":[],"lv":["NRH","RRH","DH"],"ch":[["Deleted in 2025","Streptokinase 1.5 million IU powder for injection vial removed (was available DH). Reason: Substituted by tenecteplase"]],"al":""},{"k":"SODIUM TETRADECYL SULPHATE","n":"SODIUM TETRADECYL SULPHATE","g":"","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.5.2 Thrombolytic medicines","moa":"Detergent sclerosant; damages vein endothelium, causing thrombosis and fibrosis of the vessel.","f":[["Indications & dose","Sclerotherapy of reticular veins and spider veins in legs and varicose veins, by intravenous injection, ADULT: Test dose: 0.5 mL given several hours prior to administration of larger dose; 0.5-2 mL (preferred maximum: 1 mL) in each vein, maximum 10 mL per treatment session."],["Contraindications","incompetency of collateral deep veins in the legs, incompetency of the valves of the greater and lesser saphenous veins before ligation, thrombophlebitis, tuberculosis, hyperthyroidism, acute infections, prolonged recumbency, cardiac insufficiency, diabetes, arterial disease, varicosities caused by pelvic neoplasia."],["Cautions","Extravasation may cause necrosis of tissues, history of migraine (use smaller volumes), venous insufficiency with lymphoedema (pain and inflammation may worsen)."],["Side effects","Pain, ulcer and urticaria at injection site, nausea, vomiting, headache, skin necrosis, deep vein thrombosis. Pregnancy C"],["Breast-feeding","Excretion in breast milk unknown, use caution."]],"f25":[],"lv":["NRH"],"ch":[],"al":""},{"k":"ATORVASTATIN","n":"ATORVASTATIN","g":"Lipid lowering agent.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.7 Lipid lowering agents","moa":"HMG-CoA reductase inhibitor; reduces hepatic cholesterol synthesis and upregulates LDL receptors.","f":[["Indications & dose","Primary hypercholesterolemia in patients who have not responded adequately to diet and other appropriate measures; Combined hyperlipidemia in patients who have not responded adequately to diet and other appropriate measures ADULT: Usual dose 10 mg PO, Q24hr; increased if necessary up to 80 mg, Q24hr, dose to be increased at intervals of at least 4 weeks. Heterozygous familial hypercholesterolemia in patients who have not responded adequately to diet and other appropriate measures; Homozygous familial hypercholesterolemia in patients who have not responded adequately to diet and other appropriate measures ADULT: Initially 10 mg PO, Q24hr, then increased to 40 mg, Q24hr, dose to be increased at intervals of at least 4 weeks; max. 80 mg, Q24hr. Primary prevention of cardiovascular events in patients at high risk of a first cardiovascular event ADULT: 20 mg PO, Q24hr, dose can be increased if necessary. Secondary prevention of cardiovascular events ADULT: 80 mg PO, Q24hr."],["Contraindications","Active liver disease."],["Cautions","Hemorrhagic stroke."],["Side effects","Back pain, epistaxis, hyperglycemia, nasopharyngitis, pharyngolaryngeal pain, anorexia, blurred vision, chest pain, hypoglycemia, malaise, neck pain, peripheral oedema, pyrexia, tinnitus, weight gain."],["Pregnancy category","X"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Advice patient to report promptly unexplained muscle pain, tenderness, and weakness."]],"f25":[{"i":"Atorvastatin 10mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FENOFIBRATE","n":"FENOFIBRATE","g":"Lipid-lowering agent.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.7 Lipid lowering agents","moa":"PPAR-alpha agonist; increases lipoprotein lipase activity, lowering triglycerides and raising HDL.","f":[["Indications & dose","Hypercholesterolemia, Primary hypercholesterolemia or mixed dyslipidemia; adjunct to diet ADULT: initial, 160 mg PO once daily with a meal; MAX 160 mg/day; Hypertriglyceridemia (Severe), Adjunct to diet ADULT: 160 mg orally once daily with a meal, adjust if necessary following repeat lipid determinations at 4- to 8-week intervals; MAX 160 mg/day."],["Contraindications","Gallbladder disease, pancreatitis."],["Cautions","Correct hypothyroidism before initiating treatment."],["Side effects","Abdominal distension; anorexia, diarrhoea, nausea, alopecia, cholestasis, dizziness, erectile dysfunction, headache, myotoxicity (with myasthenia, myalgia, or very rarely rhabdomyolysis) - special risk in renal impairment; pancreatitis; photosensitivity reactions; pruritus; pulmonary embolism; rash, renal failure, urticaria."],["Renal impairment","Reduce dose in moderate to severe impairment."],["Hepatic impairment","Avoid."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, avoid."]],"f25":[{"i":"Fenofibrate 160mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PENTOXIFYLLINE","n":"PENTOXIFYLLINE","g":"Peripheral vasodilator.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.8 Peripheral vasodilator","moa":"Phosphodiesterase inhibitor; improves red cell deformability and reduces blood viscosity.","f":[["Indications & dose","Peripheral vascular disease; Venous leg ulcers ADULT: 400mg PO, Q8-12hr with meals; minimum 8 weeks for optimum effects."],["Contraindications","Cerebral haemorrhage, extensive retinal haemorrhage, acute myocardial infarction, lactation, porphyria."],["Side effects","GI disturbances, dizziness, headache, rarely flushing, tachycardia, hypersensitivity including rash, pruritus, bronchospasm, angina, hypotension."],["Renal impairment","CrCl <30 mL/min: decrease dose to 400 mg/day."],["Hepatic impairment","Reduce dose in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Counselling","Take this medicine with meals so that it will not upset your stomach."]],"f25":[{"i":"Pentoxifyllin 400mg tablet","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"DOBUTAMINE","n":"DOBUTAMINE","g":"Vasopressor (sympathomimetic).","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.9 Vasopressor agents","moa":"Mainly beta-1 agonist; increases contractility with mild vasodilation.","f":[["Indications & dose","Decreased cardiac output, ADULT: initial dose 0.5 – 1 mcg/kg/min IV infusion, then 2 – 20 mcg/kg/min: not to exceed 40 mcg/kg/min. Heart failure, ADULT: initial dose 0.5 to 1 mcg/kg/min IV; Maintenance dose 2 to 40 mcg/kg/min IV; CHILD, 2 to 20 mcg/kg/min."],["Contraindications","Pheochromocytoma, patients with stable heart failure."],["Cautions","Acute Heart Failure (AHF), myocardial infarction, arrhythmias, atrial fibrillation, hyperthyroidism, severe hypotension bronchial asthma who are hypersensitive to sulphites."],["Side effects","Psychosis, fever, headache, chest pain, tachycardia, arrhythmias, dyspnea, AV block, hypokalemia."],["Pregnancy category","B"],["Breast-feeding","excretion in breast milk unknown."],["IV fluid compatibility","Incompatible with bicarbonates and other strong alkaline solutions"],["Note","Dilute with dextrose 5% or 0.9% normal saline solutions to a concentration of 0.5-1 mg/mL and give by an infusion pump; give higher concentration (max. 5 mg/mL) through central venous catheter."]],"f25":[{"i":"Dobutamine 50mg/mL injection (5mL) ampoule","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Dobutamine 50mg/mL injection (20mL) ampoule → now Dobutamine 50mg/mL injection (5mL) ampoule"]],"al":""},{"k":"LABETALOL","n":"LABETALOL","g":"Vasopressor.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.9 Vasopressor agents","moa":"Combined alpha-1 and non-selective beta blocker; lowers BP without reflex tachycardia. Used in pregnancy.","f":[["Indications & dose","Acute severe hypertension in pregnancy ADULT,10 to 20 mg IV, then 20 to 80 mg every 10 to 30 minutes to a MAX cumulative dosage of 300 mg; OR 1 to 2 mg/min IV infusion; initiate within 30 to 60 minutes. Severe intrapartum or postpartum hypertension ADULT, Initial, 20 mg slow IV injection (over more than 2 minutes). Target lowering to range of 140 to 150/90 to 100 mmHg. If SBP or DBP threshold is still exceeded after 10 minutes, give 40 mg slow IV injection, then if a threshold is still exceeded after a further 10 minutes, give 80 mg slow IV injection. If threshold remains exceeded after a further 10 minutes, switch to hydralazine 10 mg IV over more than 2 minutes. Acute ischemic stroke: Pretreatment ADULT, 10 to 20 mg IV over 1 to 2 minutes, may repeat x 1 dose to achieve blood pressure (BP) less than 185/110 mm Hg prior to alteplase; if BP exceeds 180/105 mm Hg in first 24 hrs after alteplase treatment, administer 10 mg IV followed by a continuous infusion of 2 to 8 mg/min. Hypertensive Emergency ADULT Initial, 20 mg (0.25 mg/kg for an 80 kg patient) by slow IV injection over 2 minutes; additional doses of 40 or 80 mg may be given at 10-minute intervals until desired blood pressure (BP) is achieved or up to a total of 300 mg. Individualise dosage to severity of disease and degree of response OR initial, 2 mg/minute as an IV infusion; adjust infusion rate to BP response and individualise dosage to severity of disease and degree of response. Usual total dosage, 50 to 200 mg; a total dosage of up to 300 mg may be required. CHILD, (1 year and above) Bolus: 0.2 to 1 mg/kg/dose IV bolus up to 40 mg/dose OR 0.25 to 3 mg/kg/hour IV infusion."],["Contraindications","Severe bradycardia, heart block greater than first degree, cardiogenic shock, bronchial asthma, decompensated cardiac failure, conditions associated with severe and prolonged hypotension."],["Cautions","Liver damage."],["Side effects","Lichenoid rash, difficulty in micturition, epigastric pain, liver damage, nausea, postural hypotension, vomiting, weakness."],["Hepatic impairment","Avoid; severe hepatocellular injury reported. Renal Impairment Dose reduction may be required."],["Pregnancy category","C"],["Breast-feeding","Small amount excreted in milk, use with caution."],["IV fluid compatibility","Dextrose 5%, Dextrose 5% sodium chloride 0.9%, compound solution of sodium lactate, sodium chloride 0.9%."]],"f25":[{"i":"Labetalol 5mg/mL injection (20mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"NORADRENALINE","n":"NORADRENALINE","g":"Vasopressor.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.9 Vasopressor agents","moa":"Potent alpha-1 agonist (vasoconstriction) with beta-1 effect; first-line vasopressor in septic shock.","f":[["Indications & dose","Acute hypotension, ADULT: 8-12 mcg/min by IV infusion, titrate to effect. Maintenance dose 2-4 mcg/min; CHILD: 0.05 – 0.1 mcg/kg, titrate to effect, MAX. 1 – 2 mcg/kg/min. Cardiac arrest ADULT, initial 8-12mcg/min by IV infusion, titrate to effect, Maintenance dose 2-4 mcg /min; CHILD; initial 0.05 – 0.1 mcg/kg, titrate to effect, max. 1 - 2 mcg/kg/min. Sepsis and septic shock, ADULT: 0.01-3 mcg/kg/min by IV infusion; CHILD: 0.05 – 0.1 mcg/kg by IV, titrate to effect, MAX. 1-2 mcg/kg/min."],["Contraindications","Hypertension, severe hyperthyroidism, Hypotension due to low volume deficit, Peripheral vascular thrombosis."],["Cautions","Coronary disease, coronary vascular thrombosis, diabetes, elderly, extravasation at injection site may cause necrosis, hypercapnia, hyperthyroidism, hypoxia, mesenteric vascular thrombosis, peripheral vascular thrombosis, Prinzmetal’s variant angina, glaucoma, uncorrected hypovolaemia."],["Side effects","Angle-closure glaucoma, anorexia, anxiety, arrhythmias, bradycardia, confusion, dyspnoea. Headache, hypertension, hypoxia, insomnia, nausea, palpitation, peripheral ischaemia, psychosis, tachycardia, tremor, urinary retention, vomiting, weakness."],["Pregnancy category","C"],["Breast-feeding","Not known if excreted in breast milk, avoid use."],["IV fluid compatibility","Compatible with dextrose 5% in 0.9% normal saline, dextrose 5%, compound sodium lactate solution, normal saline."],["Note","To be administered by using an infusion pump."]],"f25":[{"i":"Noradrenaline 2mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Noradrenaline 1mg/mL injection (1mL) ampoule → now Noradrenaline 2mg/mL injection (2mL) ampoule"]],"al":"norepinephrine"},{"k":"PHENYLEPHRINE","n":"PHENYLEPHRINE","g":"Vasopressor.","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.9 Vasopressor agents","moa":"Selective alpha-1 agonist; vasoconstriction (reflex bradycardia); topical decongestant and mydriatic.","f":[["Indications & dose","and dosage Mild to moderate hypotension ADULT, IV injection 0.1- 0.5 mg in every 15 minutes, not to exceed 0.5 mg/dose. SC/IM 2-5 mg every 1-2 hour if necessary, maintenance 1-10 mg. CHILD ≥ 2years, SC/IM injection 0.1 mg/kg in every 1-2 hour if necessary, maximum 5 mg/dose. Severe hypotension or shock ADULT, 0.1-0.5 mg/dose by IV bolus every 5-10minutes if necessary, not to exceed 0.5 mg. IV infusion , 0.1 to 0.18 mg/ minute, titrate to desired response, alternatively, 0.0005 mg/kg/min, titrate to desired response. CHILD ≥ 2years,IV injection, 0.005 - 0.02 mg/kg once, then 0.0001 – 0.0005 mg/kg/min, not to exceed 0.003-0.005 mg/kg/min."],["Contraindications","Severe hypertension, closed angle glaucoma, severe hyperthyroidism, ventricular tachycardia."],["Cautions","Cerebrovascular insufficiency, hypertension, cardiovascular disorder; prostatic hypertrophy."],["Side effects","Hypertension, anxiety, headache, rebound congestion, bradycardia, palpitation, metabolic acidosis, decreased urine output."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, however safe."]],"f25":[{"i":"Phenylephrine 10mg/mL injection (1mL) ampoule","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"VASOPRESSIN","n":"VASOPRESSIN","g":"Vasopressor (Antidiuretic hormone).","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.9 Vasopressor agents","moa":"V1 receptor agonist (vasoconstriction) and V2 agonist (renal water reabsorption).","f":[["Indications & dose","Pituitary diabetes insipidus ADULT, 5–10 units every 8-12 hourly by IM/SC injection. CHILD, 2.5 -10 units every 8-12 hourly. Esophageal variceal bleeding: ADULT, 20 units IV injection to be administered over 15 minutes. CHILD, 0.3 units/kg (not to exceed 20 units). Septic shock ADULT, 0.01-0.04 unit/min IV infusion."],["Contraindications","Chronic nephritis, cardiac insufficiency."],["Cautions","Asthma, epilepsy, heart failure, hypertension and migraine."],["Side effects","Abdominal cramps, belching, desire to defecate, anginal attacks, peripheral ischemia, myocardial ischemia, constriction of coronary arteries, ﬂuid retention, headache, nausea, pallor, sweating, tremor, vertigo, vomiting, Gangrene(rare)."],["Pregnancy category","C"],["Breast-feeding","unknown whether the medicine is distributed in breast milk, use with caution."]],"f25":[{"i":"Vasopressin 20IU/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"NITROFURAZONE","n":"NITROFURAZONE","g":"Antibacterial (topical).","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.2 Anti-infective medicines","moa":"Topical nitrofuran; reduced to reactive intermediates that damage bacterial DNA and enzymes.","f":[["Indications & dose","Superficial skin infections; Superficial burns Topical application, Q6-8hr after cleaning the affected area."],["Cautions","Sensitization may occur if treatment exceeds 5 days."],["Note","Regular soap and water washing, followed by exposure or dry dressing, will usually be adequate treatment for superficial infections."]],"f25":[{"i":"Nitrofurazone 0.2% cream (500g) container","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SILVER SULFADIAZINE","n":"SILVER SULFADIAZINE","g":"Antibacterial (topical).","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.2 Anti-infective medicines","moa":"Silver ions bind bacterial DNA and cell membranes; sulfadiazine inhibits folate synthesis. Used for burns.","f":[["Indications & dose","Skin infections, particularly gram-negative infection such as pseudomonas infection; Second- and third-degree burns; Infected leg ulcers; Pressure sores Topical application, apply thin layer of ointment over infected or burn areas q12hr."],["Contraindications","Sulfa allergy, G6PD deficiency, premature infants or neonates <2 months of age."],["Cautions","If applied at large areas for long duration, risk of blood disorders and skin discoloration,hepatic and renal impairment, pregnancy and breastfeeding."],["Side effects","prolonged use leads to Itching, rash, erythema multiforme, discoloration of skin and photosensitivity."],["Pregnancy category","C; X (near term)."],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","In burns, apply with sterile applicator, in leg ulcers apply at least 3 times a week."]],"f25":[{"i":"Silver sulphadiazine 1% cream (200g) jar","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Silver sulphadiazine 1% cream (25g) tube → now Silver sulphadiazine 1% cream (200g) jar"]],"al":""},{"k":"BETAMETHASONE VALERATE","n":"BETAMETHASONE VALERATE","g":"Anti-inflammatory and antipruritic medicines (potent corticosteroid).","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Potent topical corticosteroid; glucocorticoid receptor-mediated anti-inflammatory and vasoconstrictive effects.","f":[["Indications & dose","Severe inflammatory skin disorders such as eczema unresponsive to less potent steroids; Psoriasis ADULT and CHILD: topical application, apply thinly over affected areas 1-2 times daily for 1-2 weeks only"],["Contraindications","Underlying infections present, ophthalmic use."],["Cautions","Avoid prolonged use in infants and children and on the face; Do not use this medication near the eyes if you have glaucoma; Use of more than 100 g per week of 0.1% preparation is likely to cause adrenal suppression."],["Side effects","Skin atrophy, dry skin, erythema folliculitis, acneiform lesion, burning, irritation, pigmentation changes, allergic dermatitis."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","Advise patient not to use bandages, wraps, or other occlusive dressing over the treatment area; Discontinue use once psoriasis is controlled; Use beyond 2 weeks is not recommended."]],"f25":[],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CLOBETASOL PROPIONATE","n":"CLOBETASOL PROPIONATE","g":"Anti-inflammatory and antipruritic medicines (very potent corticosteroid).","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Very potent topical corticosteroid; suppresses inflammatory gene expression.","f":[["Indications & dose","Short-term treatment only of severe resistant inflammatory skin disorders such as recalcitrant eczemas unresponsive to less potent corticosteroids; Psoriasis ADULT, apply thinly to the skin, Q12-24hr x 4 weeks; MAX. 50g/week; CHILD, apply thinly to the skin, Q12-24hr x 4 weeks; Moderate scalp psoriasis ADULT: Apply thinly then rinsed off after 15 minutes; Q24hr x 4 weeks, frequency of application should be reduced after clinical improvement."],["Contraindications","Viral, fungal, tubercular skin lesions, ophthalmic use."],["Cautions","not more than 50g of preparation should be applied per week; discontinue use if irritation occurs; pregnancy and lactation; avoid contact with eyes."],["Side effects","skin atrophy, telangiectasia, burning, irritation, hypopigmentation, dry skin."],["Pregnancy category","C (use on smallest area of the skin and for shortest duration possible)."],["Breast-feeding","Excretion in milk unknown; Use with caution (use on smallest area of the skin and for shortest duration possible)."],["Counselling","Advise patients not to use bandages, wraps, or other occlusive dressing over the treatment area, discontinue use once psoriasis is controlled. Use beyond 2 weeks is not recommended. Wash hands after each application."]],"f25":[{"i":"Clobetasol propionate 0.05% cream (15g) tube","v":"N","l":"NRH","r":"Supplied to RRH where there is Dermatologist"}],"lv":["NRH"],"ch":[],"al":""},{"k":"FLUTICASONE PROPIONATE","n":"FLUTICASONE PROPIONATE","g":"Anti-inflammatory and antipruritic.","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Potent corticosteroid (topical/inhaled/nasal); local anti-inflammatory action with low systemic bioavailability.","f":[["Indications & dose","Inflammatory skin disorder like allergic reactions, eczema, psoriasis and severe atopic dermatitis in children not responding to 1% hydrocortisone and other topical corticosteroids cannot be used ADULT and CHILD, Topical application, apply thinly over the affected area, Q12-24hr; reducing the frequency as the condition improves."],["Contraindications","Rosacea, acne vulgaris, perioral dermatitis; primary cutaneous viral infections (e.g.: herpes simplex, chickenpox); perianal and genital pruritus; ulceration of the skin; atrophy of the skin; juvenile dermatosis; dermatoses in infants under 1 year of age, including dermatitis and napkin eruptions."],["Side effects","Pruritus, dryness, skin irritation, eczema, telangiectasia, numbness of fingers, burning, folliculitis, acneiform lesions, urticaria."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."]],"f25":[{"i":"Fluticasone propionate 0.05% cream (15g) tube","v":"N","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"HYDROCORTISONE","n":"HYDROCORTISONE","g":"Anti-inflammatory and antipruritic.","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Mild topical corticosteroid; anti-inflammatory via glucocorticoid receptors.","f":[["Indications & dose","Mild inflammatory skin disorders ADULT and CHILD Topical application, apply thinly for 2-3 times daily, reducing the frequency as the condition improves; Nappy rash CHILD, apply as required for no more than 1 week, discontinued as soon as the inflammation subsides."],["Contraindications","Underlying infections, ophthalmic use, treatment of diaper dermatitis."],["Cautions","Chronic topical therapy, diabetes, cardiovascular disease, hepatic impairment, myocardial infarction, myasthenia gravis, osteoporosis, ocular disease, renal impairment or thyroid disease."],["Side effects","Skin atrophy, striae, acneiform lesion, perioral dermatitis, folliculitis, itching, pigmentation changes, HAP suppression."],["Pregnancy category","C (should not be used extensively, in large amounts, or for prolonged periods of time)."],["Breast-feeding","Excretion in milk unknown, use with caution."],["Note","Hydrocortisone has the few side effects of all topical steroid preparations, only if the lesion is unresponsive patients should be advised to use a stronger preparation."]],"f25":[{"i":"Hydrocortisone 1% cream (15g) tube","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"TRIAMCINOLONE ACETONIDE","n":"TRIAMCINOLONE ACETONIDE","g":"Anti-inflammatory and antipruritic (potent corticosteroid).","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Intermediate-potency corticosteroid; used topically, intra-lesionally or intra-articularly.","f":[["Indications & dose","Inflammatory dermatoses responsive to steroids ADULT and CHILD Topical application, apply thinly over the affected area, Q8-12hr, reducing the frequency as the condition improves."],["Contraindications","Underlying fungal, bacterial, or viral infection, ophthalmic use."],["Cautions","Avoid large amounts or prolonged usage, occlusive dressings increase the risk of systemic absorption, do not use in patients with decreased skin circulation."],["Side effects","Skin atrophy, striae, acneiform lesion, pigmentation changes, HPA suppression."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","Advise patients not to use bandages, wraps, or other occlusive dressing over the treatment area."]],"f25":[{"i":"Triamcinolone acetonide 0.1% ointment (15g) tube","v":"N","l":"NRH/RRH/DH","r":""},{"i":"Triamcinolone acetonide 0.1% oral paste (5g) tube","v":"N","l":"NRH/RRH/DH","r":""},{"i":"Triamcinolone acetonide 40mg/mL preservative free injection (1mL) vial","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Orthopaedic Surgeon"}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Triamcinolone acetonide 0.1% paste (5g) tube → now Triamcinolone acetonide 0.1% oral paste (5g) tube"]],"al":""},{"k":"TACROLIMUS","n":"TACROLIMUS","g":"Anti-inflammatory and antipruritic.","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Topical calcineurin inhibitor; blocks T-cell activation and cytokine release in skin.","f":[["Indications & dose","Moderate to severe atopic dermatitis/eczema (flares) second Line therapy ADULT and CHILD > 15 years: 0.1% ointment, apply thinly twice daily until lesion clears, reduce frequency to once daily, if condition improves. Vitiligo (off-label use) ADULT and CHILD > 15 years: 0.1% ointment apply thinly twice daily for 2-6 months."],["Contraindications","Children below 2 years of age, hypersensitivity, immunodeficiency, generalised erythroderma, congenital epidermal barrier defects, infection at the treatment site."],["Cautions","UV light, avoid excessive exposure to sunlight. Do not use with occlusive dressings."],["Side effects","Burning sensations, pruritus, skin erythema, flu-like symptoms, and headache."],["Pregnancy category","C"],["Breast-feeding","Use with caution."],["Counselling","Apply a thin layer to affected skin, rub in gently and completely."]],"f25":[{"i":"Tacrolimus 0.1% ointment (15g) tube","v":"N","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"PERMETHRIN","n":"PERMETHRIN","g":"Scabicides and pediculicide.","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.5 Scabicides and pediculicides","moa":"Pyrethroid; prolongs Na+ channel opening in arthropod nerve membranes, causing paralysis of mites and lice.","f":[["Indications & dose","Scabies ADULT and CHILD >2 months, apply 5% cream to the entire body including face, neck, scalp, and ears; leave on for 8-14 hours then wash off. Repeat in 7 days if live mites reappear. Crusted scabies ADULT, Apply 5% cream to entire body from the neck down, then wash off after 8 to 14 hours; repeat daily for 7 days then twice weekly until cure; give in combination with ivermectin 200 mcg/kg orally on days 1, 2, 8, 9, and 15; consider additional ivermectin on days 22 and 29 for severe cases. CHILD <2 months, Safety and efficacy not established, Not recommended."],["Contraindications","Hypersensitivity to permethrin, children < 2 months."],["Cautions","Children aged 2 months -2 years; medical supervision required."],["Side effects","Erythema, pruritus, rash, stinging of skin and scalp irritation."],["Pregnancy category","B"],["Breast-feeding","Use with caution."],["Counselling","Advise patients to avoid contact with body orifices and open wounds during application. Instruct patients to report if pruritus persists beyond 4 weeks."]],"f25":[{"i":"Permethrin 5% cream (60g) tube","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"FLUORESCEIN","n":"FLUORESCEIN","g":"Diagnostic agent (ophthalmic).","sec":"14. DIAGNOSTIC AGENTS","sub":"14.1 Ophthalmic agents","moa":"Fluorescent dye that stains epithelial defects and outlines blood flow under blue light.","f":[["Indications & dose","Eye examination (staining of anterior segment of the eye during eye examinations) ADULT and CHILD, Moisten by applying 1-2 drops sterile water or other ophthalmic solution; Application While patient looks down, stroke applicator tip across bulbar conjunctiva for fornix; then have patient blink several time."],["Contraindications","Hypersensitivity to mercury-containing compounds."],["Cautions","History of allergies or asthma."],["Side effects","Skin discoloration."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, compatible."],["Note","Remove contact lens before use to avoid staining, after exam, flush eye with saline eye drops and wait at least 1 hr before reinserting contact lenses."]],"f25":[],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"TROPICAMIDE","n":"TROPICAMIDE","g":"Diagnostic agent (ophthalmic).","sec":"14. DIAGNOSTIC AGENTS","sub":"14.1 Ophthalmic agents","moa":"Short-acting antimuscarinic; blocks iris sphincter (mydriasis) and ciliary muscle (cycloplegia).","f":[["Indications & dose","Refractive procedure ADULT and CHILD, instil 1-2 drops 1% soln. in eyes(s); repeat in 5 min, perform exam within 30 minutes of second instillation; Fundus examination ADULT and CHILD, Instil 1-2 drops 0.5% in the eye(s), 15-20 min prior to exam."],["Contraindications","Angle-closure glaucoma."],["Cautions","Hypertension, hyperthyroidism, diabetes."],["Side effects","Increased intraocular pressure, transient stinging, dry mouth, blurred vision, photophobia, headache, allergic reactions."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Counselling","Do not drive or operate machinery for 1-2 hrs after mydriasis."]],"f25":[{"i":"Tropicamide 1% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"},{"i":"Tropicamide 0.8% + phenylephrine 5% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Tropicamide 0.8% + phenylephrine 5% eye drop (5mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"],["Extended in 2025","Tropicamide 1% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"BARIUM SULPHATE","n":"BARIUM SULPHATE","g":"Radio-contrast media.","sec":"14. DIAGNOSTIC AGENTS","sub":"14.2 Radiocontrast media","moa":"Insoluble, radio-opaque salt that outlines the gastrointestinal tract on X-ray.","f":[["Indications & dose","Radiography of GI tract as a suspension or paste by mouth or by enema."],["Contraindications","intestinal obstruction, intestinal perforation, or conditions with risk of perforation, high risk of aspiration."],["Cautions","Patient with bronchial asthma, cardiac disease, colostomy, constipation, cystic fibrosis, hypertension."],["Side effects","Cardiorespiratory arrest, edema, impaction of intestine, small bowel obstruction."]],"f25":[{"i":"Barium sulphate 95% w/v oral suspension (150mL) bottle","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"GADODIAMIDE","n":"GADODIAMIDE","g":"Radiocontrast media.","sec":"14. DIAGNOSTIC AGENTS","sub":"14.2 Radiocontrast media","moa":"Gadolinium-based contrast; paramagnetic, shortens T1 relaxation to enhance MRI signal.","f":[["Indications & dose","CNS Imaging (MRI) ADULT, 0.2 mL/kg (0.1 mmol/kg) as a bolus IV injection; CHILD (2-16 years), 0.2 mL/kg (0.1 mmol/kg) as a bolus IV injection; Vascular Imaging (MRI): Imaging of kidney ADULT, 0.1 mL/kg (0.05 mmol/kg) as an IV bolus injection; CHILD (2-16 years), 0.1 mL/kg (0.05 mmol/kg) administered as an IV bolus injection; Imaging of intrathoracic (noncardiac), intra-abdominal, an pelvic cavities ADULT, 0.2 mL/kg (0.1 mmol/kg) administered as a bolus IV injection; CHILD (2-16 years), 0.2 mL/kg (0.1 mmol/kg) administered as a bolus IV injection."],["Contraindications","Acute kidney disease or chronic and severe renal impairment (GFR <30 mL/min); CHILD >2 years"],["Cautions","Anaemia, hepatic and renal impairment; Not for intrathecal use."],["Side effects","Injection site reaction, vasodilation, dizziness, headache, nausea, anaphylactic reactions, nephrogenic systemic fibrosis."],["Renal impairment","Dose adjustment required."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["Note","Flush IV line with 5mL of sodium chloride 0.9% to ensure dose is completely administered; Complete the imaging procedure within 1 hour of administration."]],"f25":[],"lv":["NRH"],"ch":[["Deleted in 2025","Gadodiamide 0.5mmol/mL injection (10mL) vial removed (was available RRH). Reason: Substituted by Gadobenate Dimeglumine injection 10ml vial"]],"al":""},{"k":"IODIXANOL","n":"IODIXANOL","g":"Radiocontrast media.","sec":"14. DIAGNOSTIC AGENTS","sub":"14.2 Radiocontrast media","moa":"Iso-osmolar non-ionic iodinated contrast; iodine attenuates X-rays.","f":[["Indications & dose","Intra-arterial (arteriography): Carotid arteries ADULT and CHILD (>12 years), 10-14 mL (not to exceed 175 mL; 80 g); Vertebral arteries ADULT and CHILD (>12 years), 10-12 mL(not to exceed 175 mL; 80 g); Right coronary artery ADULT and CHILD (>12 years), 3-8 mL(not to exceed 200 mL; 80 g); Left coronary artery ADULT and CHILD (>12 years), 3-10 mL (not to exceed 200 mL; 80 g); Left ventricle ADULT and CHILD (>12 years), 20-45 mL(not to exceed 200 mL; 80 g); Aortography ADULT and CHILD (>12 years), 30-70 mL(not to exceed 250 mL; 80 g); Major aorta branch ADULT and CHILD (>12 years), 10-70 mL(not to exceed 250 mL; 80 g); Peripheral arteries ADULT and CHILD (>12 years), 15-30mL(not to exceed 250 mL; 80 g); Aortofermoral runoffs ADULT and CHILD (>12 years), 20-90 mL (not to exceed 250 mL; 80 g); Renal arteries ADULT and CHILD (>12 years), 8-18 mL (not to exceed 250 mL; max. 80 g); Intra-arterial digital subtraction angiography (IA-DSA) Carotid or vertebral arteries ADULT and CHILD (>12 years), 5-8 mL (not to exceed 175 mL; 80 g); Aortography ADULT and CHILD (>12 years), 10-50 mL (not to exceed 250 mL; 80 g); Major aorta branch ADULT and CHILD (>12 years), 2-10 mL (not to exceed 250 mL; 80 g), Aortofemoral runoffs ADULT and CHILD (>12 years), 6-15 mL (not to exceed 250 mL; 80 g); Peripheral arteries ADULT and CHILD (>12 years), 3-15 mL (not to exceed 250 mL; 80 g); IV Administration CECT of head or body ADULT and CHILD (>12 years), 75-150 mL bolus IV, then 100-150 mL infusion not to exceed 150 mL; Excretory urography ADULT and CHILD (>12 years), 1 mL/kg, not to exceed 100 mL; Venography ADULT and CHILD (>12 years), 50-150 mL per lower extremity (not to exceed 250 mL; 80 g); CHILD (1-12 years) for all studies, 1-2 mL/kg; not to exceed 4 mL/kg."],["Contraindications","Intrathecal use; In children with prolonged fasting and use of laxative before administration."],["Cautions","Maintain adequate hydration, renal/hepatic impairment, cardiovascular disease, multiple myeloma, pheochromocytoma, sickle cell disease, elderly patients, thyroid dysfunction."],["Side effects","Discomfort at injection site, angina pectoris, chest pain, headache, migraine, vertigo, paraesthesia, pruritus, skin rash, erythema, dysgeusia."],["Pregnancy category","B"],["Breast-feeding","Poorly excreted in milk, interrupt Breast-feeding and milk for 10 hr after administration."]],"f25":[{"i":"Iodixanol 320mg injection (100mL) vial","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"IOHEXOL","n":"IOHEXOL","g":"Radiocontrast media.","sec":"14. DIAGNOSTIC AGENTS","sub":"14.2 Radiocontrast media","moa":"Low-osmolar non-ionic iodinated contrast; iodine attenuates X-rays.","f":[["Indications & dose","Myelography, urography, arthrography and for visualisation of GI tract and body cavities Route and dose depends on the procedure; administered only by radiologist."],["Contraindications","Significant bacterial infection; Do not immediately repeat myelography."],["Cautions","Severe renal impairment, combined renal/hepatic disease, severe thyrotoxicosis, multiple myeloma, anuria, pheochromocytoma, congestive heart failure, severe arterial/venous disease; dehydration (correct fluid and electrolyte balance before administration), allergies."],["Side effects","Nausea, vomiting, metallic taste, flushing, sensation of heat, weakness, headache, coughing, rhinitis, angina pectoris, cardiac arrest, thromboembolic disorder, nephrotoxicity."],["Renal impairment","Use with caution/dose need to be adjusted."],["Pregnancy category","B"],["Breast-feeding","Excreted in small amounts in milk, use with caution."],["Counselling","Advice patient to maintain adequate hydration after injection is administered."]],"f25":[{"i":"Iohexol 300mg injection (50mL) vial","v":"E","l":"NRH/RRH","r":""},{"i":"Iohexol 350mg injection (100mL) vial","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"SODIUM AMIDOTRIAZOATE + MEGLUMIN AMIDOTRIAZOATE","n":"SODIUM AMIDOTRIAZOATE + MEGLUMIN AMIDOTRIAZOATE","g":"Radiocontrast media.","sec":"14. DIAGNOSTIC AGENTS","sub":"14.2 Radiocontrast media","moa":"Ionic, high-osmolar iodinated contrast (gastrografin); iodine attenuates X-rays.","f":[["Indications & dose","Urography, venography, operative cholangiography, splenoportography, arthrography, discography; computer assisted axial tomography ADULT and CHILD, route and dosage depend on procedure and preparation used (consult manufacturer’s literature); Radiographic exam of GI tract segments ADULT, 30-90 mL PO, CHILD ( <5 years), 30 mL PO (dilute 1:1, if <10 kg OR if debilitated, dilute 1:3), CHILD (5-10 years) 60 mL PO (dilute 1:1, if <10 kg OR if debilitated, dilute 1:3) Tomography ADULT 25-77 mL in 1000 mL tap water PO, 15-30 minutes prior to imaging."],["Contraindications","Hypersensitivity to iodine-containing compounds."],["Cautions","Electrolyte imbalance, history of iodine hypersensitivity, esophagotracheal fistula."],["Side effects","Nausea, vomiting, diarrhoea, metallic taste, flushing, sensations of heat, weakness, dizziness, headache, coughing, rhinitis, sweating, sneezing, lacrimation, visual disturbances, pruritus, salivary gland enlargement, pallor, cardiac disorders, hemodynamic disturbances and hypotension, disseminated intravascular coagulation, fibrinolysis and depression of blood coagulation factors."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Note","Administration, only by radiologists, according to manufacturer’s literature."]],"f25":[],"lv":["NRH"],"ch":[],"al":""},{"k":"MANNITOL","n":"MANNITOL","g":"Diuretic (Osmotic).","sec":"15. DIURETICS","sub":"","moa":"Osmotic diuretic; filtered but not reabsorbed, holds water in the tubule and draws water from brain and eye.","f":[["Indications & dose","Forced diuresis in impending renal failure ADULT, 1 mL/kg IV infusion over 5 minutes and repeated after 2-3 hours; if no response, reassess the patient; if urine flow does increase, 250-500 mL over 5 minutes. Emergency reduction of intracranial pressure, cerebral oedema, and intraocular pressure ADULT and CHILD (12 years and above), 0.25-2 g/kg IV infusion administered over 30-60 minutes, if necessary, dose may be repeated 1-2 times after 4-8 hours; CHILD (1 month-11 years), 0.25-1.5 g/kg IV infusion administered over 30–60 minutes, if necessary, may be repeated 1-2 times after 4-8 hours."],["Contraindications","Established anuria from severe renal disease; congestive cardiac failure; severe dehydration; active intracranial bleeding; pulmonary oedema."],["Cautions","Do not give simultaneously with blood."],["Side effects","Fluid and electrolyte imbalance associated with fluid retention or fluid depletion; occasional idiosyncratic reactions, hypotension, thrombophlebitis; arrhythmia, blurred vision, chest pain, chills, convulsions, cramp, dehydration, dizziness, dry mouth, fever, focal osmotic nephrosis, headache."],["Renal impairment","Use with caution in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Note","If crystals are found in the bottle, warm gently to dissolve before use."]],"f25":[{"i":"Mannitol 20% solution (350mL) bottle","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ALUMINIUM HYDROXIDE + MAGNESIUM HYDROXIDE","n":"ALUMINIUM HYDROXIDE + MAGNESIUM HYDROXIDE","g":"Antacid.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.1 Antacids","moa":"Antacids that neutralise gastric acid; aluminium constipates and magnesium loosens, balancing bowel effects.","f":[["Indications & dose","Dyspepsia and gastro-oesophageal reflux disease ADULT, 1-2 tablets chewed, Q6-8 hr; CHILD (6-12 years), 10mL PO, Q6-8hr."],["Contraindications","Hypophosphatemia, undiagnosed GI or rectal bleeding, appendicitis, porphyria."],["Cautions","Impaired renal function and renal dialysis, hepatic impairment, constipation, dehydration, fluid restriction, GI disorders associated with decreased bowel motility or obstruction."],["Side effects","Constipation, intestinal obstruction (with large doses), hypophosphatemia with increased bone resorption, hypercalciuria, and increased risk of osteomalacia (more common in patients on a low phosphate diet or on prolonged therapy), hyperalbuminemia resulting in osteomalacia, encephalopathy, dementia, and microcytic anaemia (in chronic renal failure treated with aluminium hydroxide as phosphate binding agent)."],["Renal impairment","Avoid in severe impairment."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Do not take other medicines within 2-4 hours of aluminium hydroxide preparations. May be taken with water to reduce constipating effects."]],"f25":[{"i":"Aluminium hydroxide 250mg + Magnesium hydroxide 400mg tablet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"METOCLOPRAMIDE","n":"METOCLOPRAMIDE","g":"Antiemetic.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.2 Antiemetic medicines","moa":"D2 antagonist (chemoreceptor trigger zone) and 5-HT4 agonist; antiemetic and prokinetic.","f":[["Indications & dose","Symptomatic treatment of nausea and vomiting including that associated with acute migraine; Delayed (but not acute) chemotherapy-induced nausea and vomiting; Radiotherapy-induced nausea and vomiting; Prevention of postoperative nausea and vomiting ADULT (body-weight up to 60 kg), Up to 500 mcg/kg slow IV injection, Q8hr, administered over at least 3 minutes; ADULT (body-weight 60 kg and above), 10mg slow IV injection, Q8hr administered over at least 3 minutes; Second-line option for treatment of established postoperative nausea and vomiting; Prevention of delayed chemotherapy-induced nausea and vomiting CHILD, 100-150 mcg/kg slow IV injection, Q8hr (MAX.10 mg/dose), administered over at least 3 minutes; Hiccup in palliative care ADULT, 10 mg PO, Q6-8hr; Nausea and vomiting in palliative care ADULT, 10 mg PO, Q8hr; SC infusion ADULT, 30-100 mg SC infusion, Q24hr; MAX. 500 mcg/kg/day; Metoclopramide should only be prescribed for short term use (up to 5 days)."],["Contraindications","3-4 days after GI surgery, GI haemorrhage, obstruction and perforation, pheochromocytoma."],["Cautions","Asthma, atopic allergy, bradycardia, cardiac conduction disturbances, children, elderly, epilepsy, may mask underlying disorders such as cerebral irritation, Parkinson’s disease, uncorrected electrolyte imbalance, young adults (15-19 years old), hypertension."],["Side effects","Extrapyramidal effects (especially in children and young adults (15-19 years old)), galactorrhea, gynecomastia, hyperprolactinemia, menstrual changes; depression, methemoglobinemia (more severe in G6PD deficiency), neuroleptic malignant syndrome."],["Renal impairment","Avoid or use small doses in severe impairment, increased risk of extrapyramidal reactions."],["Hepatic impairment","Reduce dose."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, avoid."],["IV fluid compatibility","Sodium chloride 0.9%."]],"f25":[{"i":"Metoclopramide 10mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Metoclopramide 5mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ONDANSETRON","n":"ONDANSETRON","g":"Antiemetic.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.2 Antiemetic medicines","moa":"Selective 5-HT3 antagonist in the chemoreceptor trigger zone and vagal afferents.","f":[["Indications & dose","Moderately emetogenic chemotherapy or radiotherapy ADULT, Initially 8 mg PO, 1-2 hours before treatment, then 8 mg, Q12hr x 5 days; Initially by IM injection, or slow IV injection ADULT, Initially 8 mg IM or IV injection, immediately before treatment, then 8 mg PO, Q12hr x 5 days; ELDERLY, 8 mg IM or IV injection administered immediately before treatment, IV infusion to be given over at least 15 minutes, then 8 mg PO, Q12hr x 5 days; Severely emetogenic chemotherapy ADULT, 24 mg PO, 1-2 hours before treatment, then 8 mg, Q12hr x 5 days; Initially by IM injection, or slow IV injection ADULT, Initially 8 mg IM or IV injection, immediately before treatment, followed by 1 mg/hour continuous IV infusion for up to 24 hours, then 8 mg PO, Q12hr x 5 days; Prevention and treatment of chemotherapy and radiotherapy-induced nausea and vomiting: Initial dose CHILD (6 months - 17 years), 150 mcg/kg IV infusion (MAX. 8 mg/dose), immediately before chemotherapy, then 150 mcg/kg, Q4hr for 2 further doses then orally; MAX. 32 mg/day; Prevention and treatment of chemotherapy and radiotherapy induced nausea and vomiting (follow on dose based on body weight) (dose started 12 hours after IV administration) CHILD (6 months - 17 years), Body weight up to 10.1kg: 2 mg PO, Q12hr x 5 days; MAX. 32 mg/day; Body weight 10.1-40 kg: 4 mg PO, Q12hr x 5 days; MAX. 32 mg/day; Body weight 41 kg and above: 8 mg PO, Q12hr x 5 days; MAX. 32 mg/day; Prevention of postoperative nausea and vomiting ADULT, 16 mg PO, 1 hour before anesthesia; CHILD, 100 mcg/kg slow IV injection (MAX. 4 mg/dose) STAT given over at least 30 seconds before, during, or after induction of anesthesia; Treatment of postoperative nausea and vomiting ADULT, 4 mg IM injection, or slow IV injection, STAT; CHILD, 100 mcg/kg slow IV Injection (MAX. 4 mg/dose) STAT given over at least 30 seconds."],["Contraindications","Congenital long QT syndrome."],["Cautions","Severe hepatic impairment, adenotonsillar surgery, subacute intestinal obstruction, susceptibility to QT-interval prolongation (including electrolyte disturbances)."],["Side effects","Constipation, flushing, headache, injection site-reactions; arrhythmias, bradycardia, chest pain, hiccups, hypotension, movement disorders, seizures."],["Hepatic impairment","MAX 8 mg/day in moderate or severe impairment."],["Pregnancy category","B"],["Breast-feeding","Excretion in milk unknown, use with caution."]],"f25":[{"i":"Ondansetron 2mg/mL injection (4mL) ampoule","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is OT"},{"i":"Ondansetron 2mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Ondansetron 4mg tablet → now Ondansetron 2mg tablet"]],"al":""},{"k":"SIMETHICONE","n":"SIMETHICONE","g":"Anti-flatulence.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.3 Antifoaming agent","moa":"Antifoaming agent; lowers surface tension so gas bubbles coalesce and pass.","f":[["Indications & dose","Postoperative gas pain or for use in endoscopic examination ADULT and CHILD more > 12 years, PO 40-360 mg after meals and at bedtime, as needed. Infants and Children <2 years or <11 kg, 20 mg 4 times/day, as needed. Children >2 years or >11 kg, 40 mg 4 times/day, as needed."],["Contraindications","Hypersensitivity to simethicone or any component of the formulation."],["Cautions","Can cause false negative guaiac tests. Side Effects Diarrhoea, nausea, regurgitation, vomiting. Pregnancy Category C."],["Breast-feeding","Not absorbed systemically, not expected to be excreted in breast milk."],["Counselling","Advise patients that medicine will work best when used after meals and at bedtime."]],"f25":[{"i":"Simethicone 100mg/mL (30mL) bottle with dropper","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Endoscopy"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ANTI-HAEMORRHOIDAL","n":"ANTI-HAEMORRHOIDAL","g":"Anti-hemorrhoid.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.4 Anti-hemorrhoidal","moa":"Combination topical: local anaesthetic, corticosteroid and astringents reduce pain, itch and swelling.","f":[["Indications & dose","Symptomatic relief of first-degree haemorrhoids and pruritus ani Apply to rectum, Q12hr and apply after a bowel movement; not more than 7 days."],["Contraindications","Systemic fungal infections."],["Cautions","Local anaesthetic components can be absorbed through the rectal mucosa; local anaesthetic components may cause hypersensitivity."],["Counselling","Apply the ointment as instructed, externally to the anus or rectum using the nozzle."]],"f25":[{"i":"Anti-haemorrhoidal ointment with applicator (15g) tube (beclomethasone 0.025% W/W, Phenylephrine 0.1% w/w & Lidocaine 2.5% W/W)","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Anti-haemorrhoidal ointment with applicator (with steroid) (15g) tube → now Anti-haemorrhoidal ointment with applicator (15g) tube ( beclomethasone 0.025% W/W, Phenylephrine 0.1% w/w & Lidocaine 2.5% W/W"]],"al":""},{"k":"DICYCLOMINE","n":"DICYCLOMINE","g":"Antispasmodic.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.5 Antispasmodic","moa":"Antimuscarinic with direct smooth muscle relaxant effect; relieves intestinal spasm.","f":[["Indications & dose","Symptomatic relief of GI disorders characterised by smooth muscle spasm ADULT, 10-20 mg PO, Q8hr; MAX. 80 mg/day, CHILD (6-23 months), 5-10 mg PO, Q6-8hr, dose to be taken 15 minutes before feeds; CHILD (2-11 years): 10 mg PO, Q8hr; CHILD (12-17 years): 10-20mg PO, Q8hr; MAX. 60 mg/day; IM injection ADULT: 20 mg IM, Q4-6hr as required; CHILD (over 2 years): 10 mg, Q6hr."],["Contraindications","Closed-angle glaucoma, GI obstruction, children below 6 months of age, urinary retention, intestinal atony, myasthenia gravis, unstable CVS, reflux esophagitis, IV use."],["Cautions","Hepatic or renal impairment, benign prostatic hyperplasia, autonomic neuropathy, infants, elderly, pregnancy, congestive heart failure."],["Side effects","Dizziness, xerostomia, blurred vision, somnolence, nervousness, and weakness. Pregnancy-category B"],["Breast-feeding","Excreted in milk, avoid."],["Note","IM should not be used more than 1-2 days, replace IM with PO as soon as possible."],["Counselling","Take 30 minutes before a meal."]],"f25":[{"i":"Dicyclomine 10mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Dicyclomine 10mg/mL injection (2mL) ampoule","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"OMEPRAZOLE","n":"OMEPRAZOLE","g":"Antiulcer.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.6 Antiulcer medicines and medicines used in variceal bleeding","moa":"Proton pump inhibitor; irreversibly blocks parietal cell H+/K+-ATPase.","f":[["Indications & dose","Helicobacter pylori eradication in combination with clarithromycin and metronidazole ADULT: 20 mg PO, Q12hr; CHILD (12-17 years): 40 mg PO, Q24hr; Gastric ulcer ADULT: 20 mg PO, Q24hr x 8 weeks; Duodenal ulcer ADULT: 20 mg PO, Q24hr x 4 weeks; Prophylaxis in patients with a history of NSAIM-associated duodenal, gastric, gastroduodenal lesions and dyspeptic symptoms who require continued NSAIM treatment ADULT: 20 mg PO, Q24hr; Zollinger-Ellison syndrome ADULT: Initially 60 mg PO or IV injection or IV infusion, Q24hr; up to 120 mg/day (if dose>80 mg (PO) and >60 mg (IV), divide it); CHILD (2-17 years): 10-20 mg PO, Q24hr; Gastro-esophageal reflux disease ADULT: 20 mg PO, Q24hr x 4 weeks, continued for a further 4-8 weeks if not fully healed; CHILD (2-17 years): 10-20 mg PO, Q24hr; Acid-related dyspepsia ADULT: 20 mg PO, Q24hr x 2-4 weeks according to response; CHILD (2-17 years): 10-20 mg PO, Q24hr ; IV injection or IV infusion (for all conditions) ADULT: 40 mg, Q24hr; CHILD (1 month-11 years): Initially 0.5 mg/kg, Q24hr (MAX. 20 mg/dose), increased if necessary to 2 mg/kg, Q24hr (MAX. 40 mg/dose); CHILD (12-17 years): 40 mg, Q24hr."],["Cautions","Liver disease."],["Side effects","Headache, abdominal pain, GI disturbance (diarrhoea, nausea, vomiting, constipation), dizziness, rash, cough."],["Renal impairment","Dose adjustment not necessary."],["Hepatic impairment","Dose reduction in severe impairment."],["Pregnancy category","C"],["Breast-feeding","May be excreted in milk, avoid."],["Note","IV injections to be given over 5 minutes and infusion over 20-30 minutes."],["Counselling","The medicine should be taken before food."]],"f25":[{"i":"Omeprazole 20mg capsule","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Omeprazole 40mg powder for injection vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"RANITIDINE","n":"RANITIDINE","g":"Antiulcer.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.6 Antiulcer medicines and medicines used in variceal bleeding","moa":"H2-receptor antagonist on parietal cells; reduces acid secretion.","f":[["Indications & dose","Benign gastric ulcer; Duodenal ulcer ADULT and CHILD (over 12 years): 150 mg PO, Q12hr x 4-8 weeks; CHILD (3-11 years): 2-4 mg/kg PO, Q12hr (MAX. 150 mg/dose); Chronic episodic dyspepsia ADULT: 150 mg PO, Q12hr x 6 weeks; Prophylaxis of NSAIM-associated gastric and duodenal ulcer ADULT: 300 mg PO, Q24hr; Gastro-esophageal reflux disease ADULT: 150 mg PO, Q12hr x 8 weeks or if necessary 12 weeks; 50mg IM or IV injection, Q6-8hr; Prophylaxis of acid aspiration in obstetrics ADULT: 150 mg PO given at onset of labour, then 150 mg, Q6hr; Prophylaxis of acid aspiration in surgical procedures ADULT: 50 mg IM or IV injection given 45-60 minutes before induction of anaesthesia; OR 150mg PO given 2 hours before induction of anaesthesia and also when possible on the preceding evening; Stress ulceration ADULT: 50 mg slow IV injection, Q8hr, then 150mg PO, Q12hr; CHILD (12-17 years): 50 mg IV injection, Q8hr, then 150mg PO, Q12hr; Reflux esophagitis and other conditions where gastric acid reduction is beneficial ADULT and CHILD (12-17 years): 150mg PO, Q12hr, then increased if necessary to 300 mg, Q12hr x 12 weeks in moderate to severe gastro-esophageal reflux disease; , CHILD (6 months-11 years): 2-4 mg/kg PO, Q12hr; Conditions where reduction of gastric acidity is beneficial and oral route not available ADULT: 50mg IM or slow IV injection, Q6-8hr."],["Cautions","Signs and symptoms of gastric cancer (in adults), renal and hepatic impairment, acute porphyria."],["Side effects","Headache, abdominal pain, agitation, reversible confusion states, nausea and vomiting, diarrhoea."],["Renal impairment","CrCl < 50 mL/min: 50mg IV or IM, Q18-24 hr or 150mg PO, Q24hr."],["Hepatic impairment","Dose adjustment not necessary."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Note","For IV injection, dose to be diluted to 20mL and given over at least 2 minutes."]],"f25":[{"i":"Ranitidine 150mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Ranitidine 25mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"OCTREOTIDE","n":"OCTREOTIDE","g":"Somatostatin analogue.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.6 Antiulcer medicines and medicines used in variceal bleeding","moa":"Somatostatin analogue; reduces splanchnic blood flow and portal pressure and inhibits GI hormone secretion.","f":[["Indications & dose","Oesophageal varices bleeding, By IV injection, ADULT: IV bolus 25-50 mcg followed by continuous IV infusion of 25-50 mcg/hour. Acromegaly, By SC/IV injection, ADULT: initially 50 mcg 3 times a day. Titrate to achieve growth hormone levels <5 ng/mL, usual effective dose 100-200 mcg 3 times/day. Complications following pancreatic surgery, By SC inj. ADULT: 100 mcg 3 times daily for 7 consecutive days, starting on the day of surgery at least 1 hour before laparotomy."],["Cautions","Cholelithiasis, pancreatitis, hypothyroidism, cardiovascular diseases, diabetes and excessive fluid loss. Side Effects Colitis, pancreatitis, alopecia, arrhythmia, bradycardia, dehydration, dizziness, dyspnoea, headache, hepatitis, rash."],["Hepatic impairment","Adjustment of maintenance dose may be necessary in patients with liver cirrhosis. Pregnancy Category B"],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["IV fluid compatibility","Stable in dextrose 5%, sodium chloride 0.9%."]],"f25":[{"i":"Octreotide 50μg/mL injection (1mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"GLYCERINE","n":"GLYCERINE","g":"Laxative.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.7 Laxatives","moa":"Osmotic and lubricant (suppository) laxative; draws water and irritates rectal mucosa.","f":[["Indications & dose","Constipation ADULT: 4 g as required; CHILD (1-11 months): 1 g as required; CHILD (1-11 years): 2 g as required; CHILD (12-17 years): 4 g as required."],["Contraindications","Intestinal obstruction."],["Cautions","Moisten suppositories with water before insertion."]],"f25":[{"i":"Glycerin suppository 4g","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Glycerin suppository 4g: now supplied down to PHC"]],"al":""},{"k":"LACTULOSE","n":"LACTULOSE","g":"Laxative.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.7 Laxatives","moa":"Osmotic laxative; colonic bacteria convert it to acids, which trap ammonia as ammonium (hepatic encephalopathy).","f":[["Indications & dose","Constipation ADULT: Initially 15-20 mL PO, Q12hr, adjusted according to response; CHILD (1-11 months): 2.5 mL PO, Q12hr, adjusted according to response; CHILD (1-4 years): 2.5-10mL PO, Q12hr, adjusted according to response; CHILD (5-17 years): 5-20 mL PO, Q12hr, adjusted according to response; Hepatic encephalopathy (portal systemic encephalopathy) ADULT: Adjusted according to response to 30-50 mL PO, Q8hr, subsequently adjusted to produce 2-3 soft stools per day; CHILD (12-17 years): Adjusted according to response to 30-50mL PO, Q8hr, subsequently adjusted to produce 2–3 soft stools per day."],["Contraindications","Galactosaemia, intestinal obstruction."],["Cautions","Lactose intolerance, diabetes, electrolytes abnormalities."],["Side effects","Dehydration, diarrhoea, excessive bowel activity, nausea and vomiting, abdominal cramps and distension."],["Pregnancy category","B"],["Breast-feeding","Excretion in milk unknown, use with caution."],["Note","Lactulose may take up to 48 hours to act."]],"f25":[{"i":"Lactulose 10g/15mL solution (100mL) bottle","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SENNA","n":"SENNA","g":"Laxative.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.7 Laxatives","moa":"Stimulant laxative; colonic bacteria release sennosides that stimulate the myenteric plexus.","f":[["Indications & dose","Constipation ADULT and CHILD (6-17 years): 15-30 mg PO, Q24hr usually taken at night; initial dose should be low then gradually increased; Bowel preparation ADULT: 130 mg PO between 2;00 and 4:00 PM in afternoon of day before procedure."],["Contraindications","GI obstruction; appendicitis, faecal impaction, GI or rectal bleeding, children under 6 years of age."],["Cautions","Should not be used more than 7 days, undiagnosed abdominal pains, nausea, vomiting."],["Side effects","Abdominal spasm, diarrhoea, electrolyte imbalance, excessive bowel activity, nausea, discoloration of urine."],["Pregnancy category","C"],["Breast-feeding","Not excreted in milk, compatible."],["Note","Senna tablet is not recommended for children under 6 years of age."]],"f25":[{"i":"Senna 15mg tablet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ORAL REHYDRATION SALT (ORS)","n":"ORAL REHYDRATION SALT (ORS)","g":"Medicine used in diarrhoea.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.8.1 Oral Rehydration","moa":"Glucose-linked sodium co-transport (SGLT1) in the gut drives water absorption, intact even in secretory diarrhoea.","f":[["Indications & dose","Prevention and treatment of dehydration, according to fluid loss, usually 200-400 mL solution after every loose motion; Moderate dehydration: by oral administration, INFANT (up to 4 months): 200-400 mL; INFANT (4 months -12 months): 400-700 mL; CHILD (12 months up to 2 years): 700-900 mL; CHILD (2 years-5 years): 900-1400 mL; Severe dehydration, By IV injection, 100mL/kg compound solution of sodium lactate (or, sodium chloride 0.9%), divided as follows: INFANT (<12 months): 30mL/kg in the 1st hour and 70mL/kg from the 5th hour; CHILD (12 months-5 years): 30mL/kg in the first ½ hour and 70mL/kg from 2 ½ hours; repeat once if radial pulse is still very weak or not detectable; reassess the child every 1-2 hours; if hydration status is not improving, give the IV drip more rapidly; also administer ORS (about 5mL/kg/hour) as soon as the child can drink; usually after 3-4 hours (infants) and 1-2 hours (children); reassess an infant after 6 hours and a child after 3 hours."],["Cautions","Renal impairment; always assess dehydration; ask about blood in the stool; check for pyrexia and severe malnutrition."],["Counselling","Advice patient or caregiver to dissolve 1 packet in a litre of boiled and cooled water and take small sips throughout the day; if you cannot consume the solution in 24 hour discard it and prepare a fresh one."]],"f25":[{"i":"Oral rehydration salts powder for dilution in 1L: containing (Glucose: 75 mEq; Sodium: 75 mEq or mmol/L; Chloride: 65 mEq or mmol/L; Potassium: 20 mEq or mmol/L; Citrate: 10 mmol/; osmolarity: 245 mOsm/L; Glucose: 13.5 g/L; Sodium chloride: 2.6 g/L; Potassium chloride: 1.5 g/L; Trisodium citrate dihydrate: 2.9 g/L) sachet","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"ors"},{"k":"ZINC SULPHATE","n":"ZINC SULPHATE","g":"Antidiarrhoeal.","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.8.2 Medicines for diarrhoea","moa":"Restores mucosal integrity and immune function; reduces duration and severity of diarrhoea in children.","f":[["Indications & dose","Adjunct to oral rehydration therapy in acute diarrhoea, By oral administration, INFANT (under 6 months): 10 mg daily for 10-14 days; CHILD (6 months-5 years): 20 mg daily for 10-14 days."],["Cautions","Acute renal failure (may accumulate)."],["Side effects","Abdominal pain, dyspepsia, nausea, vomiting, diarrhoea, gastric irritation, gastritis, irritability, headache, lethargy."],["Note","Zinc sulphate tablets may be dispersed in breast milk, in ORS, or in water on a small spoon. Older children may chew the tablets or swallow them with water."]],"f25":[{"i":"Zinc sulphate 20mg tablet SUMMARY Vital Essential Necessary","v":"E","l":"NRH/RRH/DH/PHC","r":"178 229 31"}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"DEFLAZACORT","n":"DEFLAZACORT","g":"Adrenal hormones and synthetic substitutes. corticosteroid. For details, refer to page no. 24","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.1 Adrenal hormones & synthetic substitutes","moa":"Glucocorticoid prodrug; receptor-mediated anti-inflammatory and immunosuppressive effects.","f":[["Indications & dose","Duchenne muscular dystrophy and inflammatory conditions, ADULT and CHILD (≥2 years): 0.9 mg/kg PO once daily with or without food, round up to nearest possible tablet strength. May decrease dose by 25% to 33% in patients who experience intolerable adverse effects."],["Contraindications","Hypersensitivity to deflazacort or any component of its products, live or live attenuated vaccines is not recommended concurrently."],["Cautions","Heart failure, hypertension and renal insufficiency patients, gastrointestinal disorders, Cushing syndrome, risk of thromboembolism, risk of infection, hyperglycemia (monitor recommended)."],["Side effects","Rash, Cushingoid appearance, abdominal pain, respiratory infection, hirsutism, weight gain, rhinitis, arrhythmia, hot flush."],["Renal impairment","No dose adjustment."],["Hepatic impairment","No dose adjustment."],["Pregnancy category","X"],["Breast-feeding","Weigh potential benefit vs risk."]],"f25":[{"i":"Deflazacort 6mg tablet","v":"E","l":"NRH/RRH","r":""},{"i":"Deflazacort 30mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"METHYLPREDNISOLONE","n":"METHYLPREDNISOLONE","g":"Adrenal hormones and synthetic substitutes (corticosteroid).","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.1 Adrenal hormones & synthetic substitutes","moa":"Intermediate-acting glucocorticoid; receptor-mediated anti-inflammatory effect.","f":[["Indications & dose","Suppression of inflammatory and allergic disorders; Cerebral oedema associated with malignancy ADULT: Initially 10-500 mg IM or slow IV injection or IV infusion; CHILD: 0.5-1.7 mg/kg/day IM or slow Iv injection or IV infusion, Q6H-Q12H, divide doses depending on condition and response; Treatment of graft rejection reactions ADULT: Up to 1 g/day IV infusion, up to 3 days; CHILD: 10-20 mg/kg IV injection, Q24H x 3 days; Severe erythema multiforme; Lupus nephritis; Systemic onset juvenile idiopathic arthritis CHILD: 10-30 mg/kg IV injection Q24H."],["Contraindications","Hypersensitivity to corticosteroids, systemic fungal infections, concurrent administration of live vaccines, intrathecal administration, serious infections, use in premature infants."],["Cautions","Cirrhosis, hypertension, ocular herpes simplex, diverticulum, myasthenia gravis, peptic ulcer disease, ulcerative colitis, psychotic tendencies, pregnancy, diabetes, cardiovascular disorder, renal insufficiency, ocular disease, head injury. Side Effects Acne, adrenal suppression, arthralgia, bladder dysfunction, cardiomegaly, Cushing syndrome, delayed wound healing, diabetes, fat embolism, hyperglycemia, indigestion, insomnia, osteoporosis, syncope, tachycardia, vertigo."],["Renal impairment","Use with caution, fluid retention may occur."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk; Use with caution."],["IV fluid compatibility","Compatible with dextrose 5%, dextrose 5% sodium chloride 0.9%, sodium chloride 0.9%."]],"f25":[],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"METHYLERGOMETRINE","n":"METHYLERGOMETRINE","g":"Oxytocic.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.2 Estrogens","moa":"Ergot alkaloid; partial alpha-adrenergic and 5-HT agonist causing sustained uterine contraction.","f":[["Indications & dose","Third stage of labor; post-partum hemorrhage; sub-involution of the uterus; incomplete abortion ADULT, PO 1-2 tablets 3 times daily, MAX 3 days; by IM injection, labor: 0.2 mg when anterior shoulder is delivered or immediately after birth; PPH: by IV injection, 0.25-0.5 mg when anterior shoulder is delivered or immediately after birth."],["Contraindications","Antepartum haemorrhage, first and second stage of labour, impaired pulmonary, hepatic or renal function, severe hypertension, sepsis."],["Cautions","Pre-eclampsia and eclampsia, cardiac disease, sepsis, also exclude multiple pregnancy."],["Side effects","Nausea, vomiting, transient hypertension, vasoconstriction."],["Note","To control bleeding in incomplete abortion, oxytocin should be used as well; the uterus in early pregnancy responds better to the combination than to either medicine alone. Administer IV only in emergency because of potential for hypertension and cerebrovascular accidents. Administer over >1 minute and monitor BP."]],"f25":[{"i":"Methylergometrine 125µg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Methylergometrine 200µg/mL injection (1mL) ampoule, can be stored at room temperature","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Methylergometrine 200µg/mL injection (1mL) ampoule → now Methylergometrine 200µg/mL injection (1mL) ampoule, Can be stored at room temperature"]],"al":"methergine"},{"k":"CONJUGATED OESTROGEN","n":"CONJUGATED OESTROGEN","g":"Conjugated estrogen.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.2 Estrogens","moa":"Oestrogen receptor agonist; replaces oestrogen, and at high dose stabilises endometrium to stop bleeding.","f":[["Indications & dose","Treatment of postmenopausal symptoms, by oral administration, 0.3–1.25 mg daily continuously; with cyclical progestogen for 12–14 days of each cycle. Osteoporosis prophylaxis, by oral administration, Adult, 0.625–1.25 mg daily continuously; with cyclical progestogen for 12–14 days of each cycle."],["Contraindications","Breast carcinoma, liver disease, thromboembolic disorders, vaginal bleeding of unknown cause, suspected oestrogen dependent neoplasia, active thrombophlebitis."],["Cautions","Migraine, epilepsy, asthma, renal and cardiac disease, recurrent and chronic mastitis, may cause retention of salt and water, abnormal mammograms; to discontinue if cancer progression or hypercalcemia occurs, uterine fibromyomata."],["Side effects","Nausea, vomiting, breakthrough bleeding, breast tenderness, breast enlargement."],["Hepatic impairment","Avoid in active liver disease."],["Pregnancy category","X"],["Breast-feeding","Avoid until weaning or for 6 months after birth."]],"f25":[{"i":"Conjugated oestrogen 0.625mg tablet","v":"N","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ETHINYLOESTRADIOL","n":"ETHINYLOESTRADIOL","g":"Estrogen.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.2 Estrogens","moa":"Synthetic oestrogen receptor agonist; suppresses FSH (contraception) and replaces oestrogen.","f":[["Indications & dose","Menstrual disorders, ADULT: 20–50 mcg PO daily from day 5 to 25 of each cycle, to be given with progestogen, added either throughout the cycle or from day 15 to 25. Female hypogonadism, 10–50 mcg daily usually on a cyclical basis, initial oestrogen therapy should be followed by combined oestrogen and progestogen therapy."],["Contraindications","Oestrogen-dependent cancer, history of thromboembolism, hepatic impairment, endometriosis and undiagnosed vaginal bleeding."],["Cautions","Oestrogen predisposes to thromboembolism and, in prolonged courses, to endometrial cancer; care is needed in diabetes, epilepsy, migraine, cardiac or renal disease."],["Side effects","Nausea, vomiting, headache, breast tenderness and weight gain may occur; changes in libido, depression, and amenorrhea occur occasionally; thromboembolism is more common than in the normal population."],["Hepatic impairment","Avoid."],["Pregnancy category","X"],["Breast-feeding","Avoid until weaning or for 6 months after birth."],["Note","For primary amenorrhea, the combined oral contraceptive may be more convenient in establishing cyclical bleeding."]],"f25":[{"i":"Ethinyloestradiol 50µg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ETHINYLOESTRADIOL + LEVONORGESTREL","n":"ETHINYLOESTRADIOL + LEVONORGESTREL","g":"Hormonal contraceptive.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.2 Estrogens","moa":"","f":[["Indications & dose","Contraceptive, Females; (with 28-day combined preparations), PO, 1 active tablet once daily for 21 days, followed by 1 inactive tablet daily for 7 days; subsequent courses repeated without interval, withdrawal bleeding occurs during the interval of inactive tablets being taken, if reasonably certain woman is not pregnant, first course can be started on any day of cycle — if starting on day 6 of cycle or later, additional precautions (barrier methods) necessary during first 7 days, tablets should be taken at approximately the same time each day. Primary amenorrhea, dysfunctional uterine bleeding, endometriosis, menorrhagia and chronic pelvic pain. ADULT, PO, 1 pill once daily."],["Contraindications","History of thromboembolism, active liver disease, undiagnosed vaginal bleeding, breast, and uterine or other hormone-dependent cancers."],["Cautions","Diabetes, hypertension, cardiac or renal disease, migraine, epilepsy may all be made worse; varicose veins, inflammatory bowel disease including Crohn's disease, cigarette smoking, obesity, and age over 35 years may all predispose to thromboembolic disease."],["Side effects","Nausea and vomiting are common in the first few weeks; thromboembolism is more common than in the normal population in patients over 35 years old and smokers."],["Renal impairment","Women with renal disease should be encouraged to use non hormonal forms of contraception."],["Pregnancy category","X"],["Breast-feeding","Avoid."],["Note","Except after delivery, contraceptive pills should be started within 5 days of the start of menstruation; they should not be started less than 4 weeks after delivery; oral contraceptives should be discontinued one month before elective surgery."],["Counselling","Tablets should be taken daily, at the same time of each day. Missed doses: if one dose missed, take as soon as remembered or take 2 tablets next day; if two consecutive doses missed in the first 2 weeks, take 2 tablets as soon as remembered or 2 tablets next day with additional method of contraception for 7 days after missed dose. If two consecutive doses missed in week 3 or 3 consecutive doses missed at any time, an additional method of contraception must be used for 7 days after a missed dose."]],"f25":[{"i":"Ethinyloestradiol 0.03mg + Levonorgestrel 0.15mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":"NRH/RRH/DH/PHC","ch":[],"al":"combined oral contraceptive pill, COC, OCP, birth control pill"},{"k":"MEDROXYPROGESTERONE ACETATE","n":"MEDROXYPROGESTERONE ACETATE","g":"Progestogen.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.3 Progestogens","moa":"Progestogen; suppresses LH surge (ovulation), thickens cervical mucus and makes endometrium atrophic.","f":[["Indications & dose","Dysfunctional uterine bleeding, Secondary amenorrhea, ADULTS, 2.5-10 mg PO daily for 5-10 days beginning 16th-21st day of cycle, repeated for 2 cycles in dysfunctional uterine bleeding (3 cycles in secondary amenorrhea); Mild to moderate endometriosis, 10 mg 3 times daily for 90 consecutive days, beginning on the 1st day of cycle."],["Contraindications","Undiagnosed vaginal bleeding, active liver disease, breast or genital tract carcinoma, porphyria, severe arterial disease."],["Cautions","Diabetes, hypertension, cardiac and renal failure."],["Side effects","Acne, urticaria, fluid retention, weight changes, GI disturbances, changes in libido, breast discomfort, premenstrual symptoms, irregular menstrual cycles; also, depression, insomnia, somnolence, alopecia, hirsutism, anaphylactoid-like reaction and rarely jaundice."],["Renal impairment","Use with caution."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","X"],["Breast-feeding","Excreted in breast milk, safe."]],"f25":[{"i":"Medroxyprogesterone acetate 10mg tablet","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Gynaecologist"}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"MEDROXYPROGESTERONE ACETATE DEPOT (DMPA)","n":"MEDROXYPROGESTERONE ACETATE DEPOT (DMPA)","g":"Hormonal contraceptive.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.3 Progestogens","moa":"","f":[["Indications & dose","Contraception By deep IM injection, (gluteal muscle in average and thin patients and deltoid muscle in obese patients) 150 mg within first 5 days of cycle or within first 5 days after delivery (delay until 6 weeks after delivery if breastfeeding); For long-term contraception, repeat every 12 weeks (if interval greater than 12 weeks and 5 days, exclude pregnancy before next injection and advise patient to use additional contraceptive measures e.g. barrier methods for 14 days after the injection)."],["Contraindications","Undiagnosed vaginal bleeding, history or family history of arterial disease; breast and other hormone-dependent cancers, acute porphyria."],["Cautions","Diabetes, hypertension, heart disease, ovarian cysts, malabsorption syndromes, migraine, active liver disease, recent cholestatic jaundice or history of jaundice in pregnancy."],["Side effects","Irregular menstruation or amenorrhea (50%); nausea and vomiting, headache, breast tenderness, depression, skin disorders and weight changes may sometimes occur, delayed return of fertility (max 24 months)."],["Renal impairment","Use with caution."],["Hepatic impairment","Caution in severe liver disease and recurrent cholestatic jaundice."],["Pregnancy category","X"],["Breast-feeding","Excreted in breast milk, however compatible."],["Counselling","It is recommended that before treatment, full counselling should be provided about the likelihood of menstrual irregularities and the potential of delay in the return to full fertility."]],"f25":[{"i":"Medroxyprogesterone acetate suspension 150mg/mL injection (1mL) vial","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":"NRH/RRH/DH/PHC","ch":[],"al":"DMPA, Depo-Provera, injectable contraceptive, depot injection"},{"k":"HUMAN INSULIN","n":"HUMAN INSULIN","g":"Antidiabetic agent.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.4.1 Insulins","moa":"Activates insulin receptor tyrosine kinase, increasing glucose uptake (GLUT4) and glycogen synthesis and suppressing gluconeogenesis.","f":[["Indications & dose","Diabetes mellitus type 1, SOLUBLE INSULIN, by SC injections, initially 0.2 – 0.4 units/kg/day every 8 hourly, maintenance dose 0.5-1 unit/kg/day adjusted according to patient’s requirements; ISOPHANE INSULIN, by SC injection, 0.5 - 1 unit/kg/day in divided doses (two thirds of dose to be administered in the morning and one third in the evening); MIXTARD INSULIN, by SC injection, 0.5-0.7 units/kg/day. Diabetes mellitus type 2: SOLUBLE INSULIN, by SC injection, 10 units/day initially once or twice daily adjusted according to patients requirements; ISOPHANE INSULIN, by SC injection, 0.2 units/kg/day in divided doses (two thirds of dose to be administered in the morning and one third in the evening); MIXTARD INSULIN, by SC injection, 0.5-1 units/kg/day in divided doses(two thirds of dose to be administered in the morning and one third in the evening); Diabetes ketoacidosis, SOLUBLE INSULIN, By IV injection, 0.1 units/kg/hr. IV bolus, then 0.1 mg/kg/hr continuous IV infusion."],["Contraindications","Hypoglycaemia."],["Cautions","Diarrhoea, nausea/vomiting, malabsorption, hypo- or hyperthyroidism, fever, trauma, infection, surgery, concomitant use of beta blockers."],["Side effects","Fat hypertrophy at injection site, local reactions at injection site, transient oedema, hypoglycemia, weight gain."],["Renal impairment","Insulin requirements may decrease in patients with renal impairment and therefore dose reduction may be necessary."],["Hepatic impairment","Insulin requirements may be decreased in patients with hepatic impairment."],["Pregnancy category","B"],["Breast-feeding","Compatible."],["Counselling","The injection site should be rotated to prevent lipodystrophy. Patients should be educated on symptoms of hypoglycaemia and its management."]],"f25":[{"i":"Insulin isophane 40 IU/mL injection (10mL) vial","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Insulin mixtard (neutral + isophane 30:70) injection (10mL) vial","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Insulin soluble 40 IU/mL injection (10mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"GLIPIZIDE","n":"GLIPIZIDE","g":"Oral antidiabetic agent (sulfonylureas).","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.4.2 Oral hypoglycemic agents","moa":"Sulfonylurea; closes beta-cell K-ATP channels, causing depolarisation and insulin release.","f":[["Indications & dose","Diabetes mellitus type 2, ADULT: initially 2.5-5 mg PO daily, adjusted in increments of 2.5 - 5 mg according to response; allow several days between titration MAX.40 mg/day (doses >15mg should be divided)."],["Contraindications","Hypersensitivity to sulfonamides, type 1 diabetes, diabetic ketoacidosis."],["Cautions","Elderly, debilitated patients, adrenal insufficiency, stress due to infection, fever, trauma or surgery, concomitant use of beta blockers."],["Side effects","Dizziness, drowsiness, headache, tremor, hypoglycemia, photosensitivity."],["Renal impairment","Avoid."],["Hepatic impairment","Avoid."],["Pregnancy category","C"],["Breast-feeding","Avoid."],["Counselling","Preferably take shortly before breakfast or lunch; Patients should be educated on symptoms of hypoglycemia and its management."]],"f25":[{"i":"Glipizide 5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"METFORMIN","n":"METFORMIN","g":"Oral antidiabetic agents (biguanides).","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.4.2 Oral hypoglycemic agents","moa":"Biguanide; activates AMPK, reduces hepatic gluconeogenesis and improves insulin sensitivity. No hypoglycaemia alone.","f":[["Indications & dose","Diabetes mellitus type 2, ADULT, initially 500 mg PO once daily for at least 1 week, then 500 mg twice daily for at least 1 week, and then 500 mg thrice daily titrated up to maximum of 2550 mg per day; doses to be preferably taken with or after meals; polycystic ovary syndrome, ADULT, Initially 500 mg once daily for 1 week, , then 500 mg twice daily for 1 week, then 1.5–1.7 g daily in 2–3 divided doses; doses to be preferably taken with or after meals."],["Contraindications","Ketoacidosis, use of general anaesthesia, chronic heart failure, severe renal impairment (GFR<30mL/min)."],["Cautions","Serious infections, trauma, surgery, heavy alcohol use, elderly."],["Side effects","Anorexia, nausea, vomiting, diarrhoea, occasionally metallic taste, urticaria, malabsorption of vitamin B ."],["Renal impairment","Avoid in severe impairment."],["Hepatic impairment","Risk of lactic acidosis, avoid."],["Pregnancy category","D"],["Breast-feeding","Avoid."]],"f25":[{"i":"Metformin 500mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""},{"i":"Metformin HCL 1g sustained-release tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Added in 2025","Metformin HCL 1g sustained-release tablet added (Till RRH). Reason: First line oral hypoglycemic agent, established safety and efficacy profile, cost effective and will reduce pill burden and enhance patient compliance."]],"al":""},{"k":"PIOGLITAZONE","n":"PIOGLITAZONE","g":"Oral antidiabetic agent.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.4.2 Oral hypoglycemic agents","moa":"PPAR-gamma agonist; increases insulin sensitivity in fat, muscle and liver.","f":[["Indications & dose","Diabetes mellitus type 2 (alone or combined with metformin or a sulphonylurea): ADULTS, initially 15-30 mg once daily, increased to 45 mg once daily according to response; In elderly patients, initiate with lowest possible dose and increase gradually."],["Contraindications","Hepatic impairment, history of heart failure, history of bladder cancer, hematuria."],["Cautions","Cardiovascular disease, in combination with insulin, elderly, women, risk factors for bladder cancer, acute porphyria."],["Side effects","GI disturbances, weight gain, oedema, anaemia, headache, visual disturbances, dizziness, arthralgia, hypoesthesia, hematuria, impotence, less commonly hypoglycemia, fatigue, insomnia, vertigo, sweating, altered blood lipids, proteinuria, liver dysfunction."],["Hepatic impairment","Avoid. Pregnancy Category C"],["Breast-feeding","Excreted in breast milk, avoid."],["Note","Monitor liver function before treatment, then every 2 months for 12 months and periodically thereafter."]],"f25":[{"i":"Pioglitazone 15mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"VILDAGLIPTIN","n":"VILDAGLIPTIN","g":"Oral antidiabetic agents (DPP IV inhibitors).","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.4.2 Oral hypoglycemic agents","moa":"DPP-4 inhibitor; raises incretins (GLP-1, GIP), increasing glucose-dependent insulin and reducing glucagon.","f":[["Indications & dose","Uncontrolled Type 2 diabetes mellitus as dual or triple therapy in combination with other oral antidiabetics, or insulin. ADULT, 50 mg twice daily. Type 2 diabetes mellitus in combination with sulfonylurea (if metformin inappropriate): ADULT: 50 mg daily, to be taken in the morning."],["Contraindications","Ketoacidosis."],["Cautions","Angioedema, severe heart failure."],["Side effects","Asthenia, dizziness, headache, nausea, peripheral oedema, tremor, arthralgia, constipation, hypoglycemia, hepatic dysfunction."],["Renal impairment","Reduce dose to 50 mg once daily if eGFR less than 50 mL/minute/1.73 m²."],["Hepatic impairment","Avoid."],["Breast-feeding","Avoid - present in milk in animal studies."],["Counselling","Patients should be advised to seek prompt medical attention if symptoms of liver toxicity such as nausea, vomiting, abdominal pain, fatigue, and dark urine develop."],["Pregnancy","Avoid - toxicity in animal studies."]],"f25":[{"i":"Vildagliptin 50mg tablet","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Medical Specialist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Vildagliptin 50mg tablet: now supplied down to DH (Supplied to DH where there is Medical Specialist)"]],"al":""},{"k":"ALENDRONATE","n":"ALENDRONATE","g":"Medicine affecting bone metabolism.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.5 Medicines affecting bone metabolism","moa":"Bisphosphonate; binds bone hydroxyapatite and inhibits osteoclast farnesyl pyrophosphate synthase, reducing resorption.","f":[["Indications & dose","Postmenopausal osteoporosis ADULT (female): 10 mg daily or 70 mg once weekly. Prophylaxis 35 mg orally once weekly or 5 mg orally once daily. Osteoporosis in men: 10 mg daily or 70 mg once weekly. Osteoporosis due to corticosteroid: 5 mg orally once daily or 70 mg weekly; Postmenopausal women not receiving estrogen replacement therapy: 10 mg orally once daily or 70 mg weekly. Osteoporosis due to corticosteroid (Prophylaxis): 5 mg or 10 mg orally once daily or 35 mg orally once weekly (off-label dosage). Cystic fibrosis of the lung (Osteopenia): 70 mg orally once weekly (off-label dosage). Paget's disease: 40 mg orally once daily for 6 months; may consider retreatment after a 6-month post-treatment evaluation if relapse is evident based on increase in serum alkaline phosphatase or if serum alkaline phosphatase failed to normalise. Juvenile idiopathic generalised osteoporosis (5 years or older, 20 kg or less) 5 mg orally once daily (off-label dosage). (5 years or older, greater than 20 kg) 10 mg orally once daily (off-label dosage)."],["Contraindications","Abnormalities of oesophagus, hypocalcemia. Patients who are unable to sit or stand upright for at least 30 minutes."],["Cautions","Active gastro-intestinal bleeding. Atypical femoral fractures, duodenitis, dysphagia. Gastritis history (within 1 year) of ulcers. surgery of the upper gastro-intestinal tract. symptomatic esophageal diseases, ulcers. upper gastrointestinal disorders and breastfeeding. Esophageal irritation such as dysphagia, new or worsening heartburn, pain on swallowing or retrosternal pain."],["Side effects","Transient hypocalcemia and hypophosphatemia, abdominal pain, heartburn, nausea, constipation, diarrhoea, flatulence, and esophagitis. Esophagitis, esophageal ulcers, esophageal stricture and esophageal erosions. Myalgia, joint pain, headache, dizziness, peripheral edema, back pain, and weakness."],["Renal impairment","No dosage adjustment necessary if CrCl 35 to 60 mL/min. Avoid if CrCl is less than 35 mL/min."],["Hepatic impairment","No dosage adjustments necessary."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk is unknown, use with caution."],["Note","Patient should receive supplemental calcium and vitamin D if dietary intake is adequate."],["Counselling","Tablets should be swallowed whole and should be taken with plenty of water upright on an empty stomach at least 30 minutes before breakfast (or another oral medicine); Patients should stand or sit upright for at least 30 minutes after administration."]],"f25":[{"i":"Alendronate 70mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"CARBIMAZOLE","n":"CARBIMAZOLE","g":"Antithyroid medicine.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.6 Thyroid hormones and antithyroid medicines","moa":"Prodrug of methimazole; inhibits thyroid peroxidase, blocking iodination and coupling.","f":[["Indications & dose","Hyperthyroidism, ADULT and CHILD 12 years and above, 15-40 mg PO daily in divided doses until the patient is euthyroid, usually 4-8 weeks; then gradually reduce to a maintenance dose of 5-15 mg daily; CHILD 1 month-11 years, 0.75 mg/kg daily until patient is euthyroid, usually after 4–8 weeks, then gradually reduce to a maintenance dose of 30-60% of the initial dose."],["Contraindications","Severe blood disorders."],["Cautions","Liver disorders."],["Side effects","Nausea, mild GI disturbances, headache, rashes and pruritus, arthralgia, rarely myopathy, alopecia, bone marrow suppression, jaundice."],["Renal impairment","Use with caution."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Amount in milk may be sufficient to affect neonatal thyroid function therefore the lowest effective dose should be used."],["Counselling","Warn patient to report immediately if sore throat, mouth ulcers, bruising, fever, malaise, or non-specific illness develops; blood test should be advised at regular intervals."]],"f25":[{"i":"Carbimazole 5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"THYROXINE","n":"THYROXINE","g":"Thyroid hormone.","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.6 Thyroid hormones and antithyroid medicines","moa":"Synthetic T4; converted to T3, which acts on nuclear thyroid hormone receptors.","f":[["Indications & dose","Hypothyroidism, ADULT 18 – 49 years, initially 50–100 mcg PO once daily; adjusted in steps of 25–50 mcg every 3 - 4 weeks, according to response; maintenance 100–200 mcg once daily. ADULTS 50 years and older, initially 25 mcg PO once daily; adjusted in steps of 25 mcg every 4 weeks, adjusted according to response; maintenance 50–200 mcg once daily; CHILD, 10 mcg/kg PO up to maximum of 50 mcg guided by clinical response, growth assessment and laboratory response."],["Contraindications","Thyrotoxicosis."],["Cautions","Cardiovascular diseases, diabetes, elderly, hypertension."],["Side effects","Arrhythmia, angina, tachycardia, skeletal muscle cramps, headache, restlessness, excitability, flushing, sweating, diarrhoea and excessive weight loss."],["Pregnancy category","A"],["Breast-feeding","Excreted in breast milk, however safe."],["Counselling","Dose should be taken preferably at least 30 minutes before breakfast, avoid caffeine-containing liquids, or other medication."]],"f25":[{"i":"Thyroxine 50μg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Thyroxine 25μg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Thyroxine 100mcg tablet → now Thyroxine 50mcg tablet"]],"al":"levothyroxine eltroxin"},{"k":"EQUINE RABIES IMMUNOGLOBULIN (ERIG)","n":"EQUINE RABIES IMMUNOGLOBULIN (ERIG)","g":"Immunoglobulin.","sec":"18. IMMUNOLOGICALS","sub":"18.1 Sera and immunoglobulins","moa":"Passive immunity; equine antibodies neutralise rabies virus at the wound until vaccine response develops.","f":[["Indications & dose","Post-exposure treatment against rabies infection, By local infiltration, or by infiltration or by I.M. injection, 40 IU/kg body weight (MAX: 3000 IU) in and around all cleansed wounds and if there is any remaining, it should be given intramuscularly (IM) on the antero-lateral region or deltoid region (away from the site of vaccine administration). It is not required if more than 7 days have elapsed after the first dose of anti-rabies vaccine, or more than 1 day after the second dose of vaccine. For details and in immunocompromised patients refer to National Guideline for Management of Rabies 2nd Edition, 2014."],["Cautions","No live vaccine (OPV, MR, BCG) should be administered for the next three months after the administration of the ERIG."],["Side effects","Arthralgia, chills, fatigue, fever, headache, hypersensitivity, hypotension, influenza like illness, malaise, nausea, skin reactions, tachycardia."],["Pregnancy category","Pregnancy is not a contraindication for RIG and anti-rabies vaccination when indicated."],["Counselling","Advised to keep patient under observation for 10-15 minutes after administration of ERIG for AEFI. ERIG should not be given intravenously."]],"f25":[{"i":"Anti-rabies immunoglobulin, Equine (eRIG) 300 IU/mL injection (5mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"TETANUS IMMUNOGLOBULIN","n":"TETANUS IMMUNOGLOBULIN","g":"Sera and immunoglobulin.","sec":"18. IMMUNOLOGICALS","sub":"18.1 Sera and immunoglobulins","moa":"Passive immunity; neutralises unbound tetanus toxin.","f":[["Indications & dose","Passive immunisation against tetanus in high-risk cases prophylaxis By IM injection, 1500 units; Established tetanus: By IM or IV injection, at least 10,000 units in association with sedative and other medicines."],["Contraindications","known hypersensitivity to horse serum."],["Cautions","Anaphylaxis or lesser evidence of sensitivity may occur; adrenaline should always be available, possibly in association with corticosteroids and antihistamines."],["Side effects","Serum sickness, with fever, vomiting, diarrhoea, bronchospasm and urticaria may often occur 7-10 days after the injection."]],"f25":[{"i":"Anti-tetanus immunoglobulin (Human) 500 IU injection vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"BACILLUS CALMETTE-GUERIN (BCG)","n":"BACILLUS CALMETTE-GUERIN (BCG)","g":"Vaccine. Vaccine. Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Live attenuated M. bovis; induces cell-mediated immunity against TB (protects children from severe forms).","f":[["Indications & dose","Routine prevention of tuberculosis At birth or at first contact 0.05 mL Intradermal, right upper arm. For details refer to EPI Services Manual for health workers 5th Edition 2020."],["Contraindications","Known HIV infection."],["Cautions","Correct intradermal technique is needed to reduce the risk of ulceration or abscess formation; use a fresh needle and syringe for every child and discard the vial at the end of the session."],["Side effects","A papule or small ulcer appears within 6 weeks, and normally heals within 6 weeks. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"BCG vaccine (freeze dried) 1mL powder for injection vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"HEPATITIS B VACCINE","n":"HEPATITIS B VACCINE","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Recombinant HBsAg; induces protective anti-HBs antibodies.","f":[["Indications & dose","Active immunisation against hepatitis B virus infection, By IM injection into deltoid muscle, ADULT, 3 doses of 1mL (20 mcg) at an interval of 0,1,6; CHILD, 3 doses of 0.5 mL (20 mcg) at an interval of 0, 1, 6; Chronic hemodialysis patients: 4 doses of 2 mL (40 mcg), at an interval of 0, 1, 2, 6 Note the vaccine is used in individuals at high risk of contracting hepatitis B."],["Contraindications","Known hypersensitivity to the components of the vaccine, severe febrile infections."],["Cautions","Should not be administered in the gluteal region or intradermally."],["Side effects","Mild local or systemic reactions are common, temporary swelling, tenderness, and redness at the site of injection, fever, vomiting, diarrhoea."]],"f25":[{"i":"Hepatitis B vaccine injection with vaccine vial monitor (10mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"HUMAN PAPILLOMA VACCINE","n":"HUMAN PAPILLOMA VACCINE","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Virus-like particles of HPV L1 protein; induce neutralising antibodies against oncogenic HPV types.","f":[["Indications & dose","Human papillomavirus type 6, 11, & 16 associated cervical cancer prophylaxis GIRLS and BOYS < 15 years old; CLASS SIX GIRLS and BOYS; OUT of SCHOOL GIRLS and BOYS at 12 year old: 0.5 mL Intramuscular (IM) left upper arm, at 0 and 6 months; 15 years and above: 0.5 mL Intramuscular (IM) left upper arm, at 0, 2 and 6 months. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"Human papilloma vaccine injection vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"MUMPS MEASLES RUBELLA VACCINE","n":"MUMPS MEASLES RUBELLA VACCINE","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Live attenuated viruses; induce humoral and cell-mediated immunity.","f":[["Indications & dose","Prevention of measles, mumps, and rubella 0.5 mL Subcutaneous-left upper arm at 9 and 24th months."],["Contraindications","Allergy to eggs, immune deficiency disorders."],["Cautions","Acute febrile illness, mild febrile illness, malnutrition and diarrhoea are no reason for delaying vaccination. Use a fresh needle and syringe for every child, and discard the vial at the end of the session."],["Side effects","A mild measles like rash and fever may occur about 1 week after the injection. Convulsions and encephalitis are rare complications. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"Measles mumps rubella virus vaccine 0.5mL powder for injection vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"PNEUMOCOCCAL CONJUGATE 13 VACCINE","n":"PNEUMOCOCCAL CONJUGATE 13 VACCINE","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Capsular polysaccharides from 13 serotypes conjugated to a carrier protein; T-cell-dependent response, effective in infants.","f":[["Indications & dose","Prevention of pneumococcal diseases: 0.5 mL Antero-lateral aspect of left mid-thigh at 6 and 10th weeks and 9th months. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"Pneumococcal conjugate 13 vaccine injection (0.5mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"INACTIVATED POLIO VACCINE (IPV)","n":"INACTIVATED POLIO VACCINE (IPV)","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Killed poliovirus (types 1-3); induces serum neutralising antibodies.","f":[["Indications & dose","Prevention of poliomyelitis: 0.5 mL Antero-lateral aspect of left mid-thigh at 14th weeks and 8th months. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"Poliomyelitis vaccine, inactivated injection (0.5mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ORAL POLIO VACCINE (BOPV) LIVE ATTENUATED","n":"ORAL POLIO VACCINE (BOPV) LIVE ATTENUATED","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Live attenuated poliovirus types 1 and 3; induces gut mucosal (IgA) and serum immunity.","f":[["Indications & dose","Prevention of poliomyelitis 2 drops PO at 0 at birth (within 0-14 days as “zero dose”), 6, 10 and 14 weeks. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"Poliomyelitis vaccine, live attenuated (bOPV) oral solution vial with dropper cap","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"PURIFIED VERO-CELL RABIES VACCINE (PVRV)","n":"PURIFIED VERO-CELL RABIES VACCINE (PVRV)","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Inactivated rabies virus; induces neutralising antibodies (pre- and post-exposure).","f":[["Indications & dose","Pre-exposure prophylaxis by Intradermal (ID) injection, 0.1 mL, one site on day 0, 7, 21 and 28; by intramuscular (IM) injection, 0.5 mL, one site on day 0, 7, 21 and 28. Pre-exposure prophylaxis (using PVRV): by Intradermal injection, 0.1 mL, one site at deltoid on day 0, 7 and 28; by intramuscular injection, 0.5 mL, one site at deltoid on day 0, 7 and 28. Booster dose: One site 0.1 mL ID or 0.5 mL IM at 1 year and every 3 years for high risk groups. Post-exposure prophylaxis: 0.1 mL ID or 0.5 mL IM at Day 0 and 3 with no RIGS in individuals who have received full pre-exposure regimens and booster doses. Post-exposure vaccination: Thai Red Cross Regimen–2-2-2-0-2, one dose each (0.1 mL)ID is given at 2 sites, on both arms (over deltoids) on day 0, 3, 7 and 28. Essen Protocol IM Regimen, 0.5 mL IM on day 0,3,7,14 and 28; for adults and children aged ≥2 years, the vaccine should always be administered in the deltoid area of the arm; for children aged <2 years, the antero-lateral area of the thigh is recommended."],["Contraindications","Known hypersensitivity to the components of the vaccine."],["Side effects","Injection site pain, soreness, swelling, erythema, itching, burning, nausea, abdominal pain, diarrhoea, headache, fatigue, fever, chills, muscle ache, dizziness, malaise."],["Pregnancy category","C"],["Breast-feeding","Compatible with breastfeeding."],["Note","Rabies vaccine should not be administered in the gluteal area, as the induction of an adequate immune response may be less reliable. For details refer to National Guidelines for management of rabies 2nd edition 2014."],["Counselling","Patients must be advised not to rub the site of injection after administration of vaccine."]],"f25":[{"i":"Purified vero cell rabies vaccine injection (0.5mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":"For intra-dermal (ID) use only"}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"TETANUS DIPHTHERIA (Td)","n":"TETANUS DIPHTHERIA (Td)","g":"Vaccine.","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Toxoids (inactivated toxins); induce antitoxin antibodies.","f":[["Indications & dose","Prevention of tetanus and diphtheria 0.5 mL Intramuscular left upper arm, Td 1 at PP Class student Td 2 at Class seven students; Out of school 0.5 mL at age of 6 years and 13 years old. Booster dose: 0.5 mL IM every 10 years or after 5 years in the case of a severe or dirty wound or burn (patients that have completed primary immunisation)."],["Cautions","Acute febrile illness, but mild illness is not a reason for delaying vaccination."],["Side effects","Redness or swelling where the shot was given, mild fever, headache. For details refer to EPI Services Manual for health workers 5th Edition 2020."],["Note","Td is only for children 7 years and older, adolescents, and adults. DTaP (Diphtheria, Petanus, and acellular Pertussis) vaccine is preferred for primary immunisation in children aged <7 years."]],"f25":[{"i":"Tetanus Diphtheria (Td) vaccine injection (5mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ATRACURIUM BESYLATE","n":"ATRACURIUM BESYLATE","g":"Muscle relaxant (non-depolarizing).","sec":"19. MUSCLE RELAXANTS (PERIPHERALLY-ACTING) AND CHOLINESTERASE INHIBITORS","sub":"","moa":"Non-depolarising neuromuscular blocker; competitive nicotinic antagonist. Hofmann elimination (safe in renal/hepatic failure).","f":[["Indications & dose","Muscle relaxation (short to intermediate duration) for surgery and intubation, initially 300– 600 mcg/kg, then (by IV injection) 100–200 mcg/kg as required; Neuromuscular blockade during intensive care, initially by IV injection. ADULT, initially 300–600 mcg/kg (initial dose is optional) then (by intravenous infusion) 270– 1770 mcg/kg/hour."],["Contraindications","Neuromuscular disease, lack of ventilator support."],["Cautions","Allergic cross-reactivity between neuromuscular blocking agents has been reported; caution is advised in cases of hypersensitivity to these medicines. Their activity is prolonged in patients with myasthenia gravis and in hypothermia, therefore lower doses are required; resistance may develop in patients with burns who may require increased doses."],["Side effects","Skin flushing, hypotension, tachycardia, bronchospasm and rarely, anaphylactic reactions; most aminosteroid muscle relaxants produce minimal histamine release."],["Renal impairment","No dose adjustment necessary. Pregnancy Category C"],["Hepatic impairment","No dose adjustment necessary."],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["Note","To avoid excessive dosage in obese patients, dose should be calculated based on ideal body weight."]],"f25":[{"i":"Atracurium besylate 10mg/mL injection (2.5mL) ampoule","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"BACLOFEN","n":"BACLOFEN","g":"Muscle relaxant (centrally acting).","sec":"19. MUSCLE RELAXANTS (PERIPHERALLY-ACTING) AND CHOLINESTERASE INHIBITORS","sub":"","moa":"GABA-B receptor agonist in the spinal cord; reduces spasticity.","f":[["Indications & dose","Muscle spasticity of cerebral and spinal origin, ADULT 5-10 mg PO TID daily, increase by 5 mg/dose every 3 days as required (MAX. 80 mg/day); CHILD 8–17 years: Initially 0.3 mg/kg/day in 4 divided doses, increased gradually at weekly intervals until satisfactory response (MAX. 60 mg/day), CHILD, 1 month–7 years: Initially 0.3 mg/kg daily in 4 divided doses, increased gradually at weekly intervals until satisfactory response (MAX.40 mg/day). Review treatment if no benefit within 6 weeks of achieving maximum dose."],["Contraindications","Active peptic ulceration."],["Cautions","Reduce dose in impaired renal function, avoid abrupt withdrawal (hallucinations and seizures may occur), pregnancy."],["Side effects","Transient drowsiness, dizziness, weakness, fatigue."],["Renal impairment","Risk of toxicity, use smaller doses (e.g., 5 mg daily by mouth) and if necessary, increase dosage interval."],["Hepatic impairment","Use with caution."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, amount probably too small to be harmful."],["Counselling","Avoid taking with alcohol and other CNS depressants."]],"f25":[{"i":"Baclofen 10mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"NEOSTIGMINE","n":"NEOSTIGMINE","g":"Muscle relaxant.","sec":"19. MUSCLE RELAXANTS (PERIPHERALLY-ACTING) AND CHOLINESTERASE INHIBITORS","sub":"","moa":"Reversible acetylcholinesterase inhibitor; raises ACh at the neuromuscular junction (reverses non-depolarising block, myasthenia).","f":[["Indications & dose","Counteract the effect of non-depolarizing muscle relaxants, ADULTS, IV injection 0.03 -0.07 mg/kg body weight (MAX. 5mg), repeated if necessary, after or with glycopyrronium or atropine, to be given over 1 minute; Treatment of myasthenia gravis, by IV/IM/SC injection, ADULTS, 1-2.5 mg, dose repeated at suitable intervals throughout the day (usual total daily dose 5–20 mg)."],["Contraindications","mechanical obstruction of the intestinal or urinary tract."],["Cautions","Adequate ventilation must be maintained and complete recovery must be ensured before the patient is transferred to the ward."],["Side effects","Nausea and vomiting, increased salivation, diarrhoea, abdominal cramps, cardiac dysrhythmias, syncope and hypotension; progressive paralysis may occur; management is by artificial ventilation and IV atropine."],["Renal impairment","May need dose reduction."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use caution."]],"f25":[{"i":"Neostigmine 0.5mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"SUXAMETHONIUM","n":"SUXAMETHONIUM","g":"Muscle relaxant (Depolarizing).","sec":"19. MUSCLE RELAXANTS (PERIPHERALLY-ACTING) AND CHOLINESTERASE INHIBITORS","sub":"","moa":"Depolarising neuromuscular blocker; persistent nicotinic receptor activation causes fasciculation then paralysis. Broken down by plasma cholinesterase.","f":[["Indications & dose","Neuromuscular blockade during surgery and intubation, ADULT, IV injection 1-1.5 mg/kg body weight."],["Contraindications","Hyperkalemia, patients with burns, neuropathic or bed ridden patients, known malignant hyperpyrexia, known atypical plasma pseudo-cholinesterase enzymes."],["Cautions","Patients with cardiac, respiratory or neuromuscular disease; raised intraocular pressure, severe sepsis."],["Side effects","Repeated dosing may lead to a paradoxical prolonged non-depolarizing effect, partial and temporary reversal with neostigmine may be possible, but ventilation must be controlled and monitored until spontaneous breathing is fully re-established, and patients may experience muscular pain following recovery from anaesthesia."],["Hepatic impairment","Prolonged apnea may occur in severe liver disease because of reduced hepatic synthesis."],["Pregnancy category","C"],["Breast-feeding","May be resumed once the mother recovers from a neuromuscular block."]],"f25":[{"i":"Suxamethonium 50mg/mL injection (2mL) ampoule","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is OT"}],"lv":["NRH","RRH"],"ch":[],"al":"succinylcholine scoline"},{"k":"VECURONIUM","n":"VECURONIUM","g":"Non-depolarizing muscle relaxant (amino steroid).","sec":"19. MUSCLE RELAXANTS (PERIPHERALLY-ACTING) AND CHOLINESTERASE INHIBITORS","sub":"","moa":"Non-depolarising aminosteroid neuromuscular blocker; competitive nicotinic antagonist.","f":[["Indications & dose","Neuromuscular blockade (intermediate duration) during surgery and intubation: ADULTS, IV injection 0.08 - 0.1 mg/kg initially; maintenance 0.02 – 0.03 mg/kg, adjusted according to response (MAX. 0.1 mg/kg)."],["Contraindications","Neuromuscular disease, lack of ventilator support."],["Cautions","Allergic cross-reactivity between neuromuscular blocking agents has been reported; caution is advised in cases of hypersensitivity to these medicines. Their activity is prolonged in patients with myasthenia gravis and in hypothermia, therefore lower doses are required. Resistance may develop in patients with burns who may require increased doses; low plasma cholinesterase activity in these patients requires dose titration for mivacurium."],["Side effects","Duration is prolonged in hypothermia, hypothyroidism, and myasthenia gravis and in conjunction with aminoglycosides. The effect is slightly prolonged in renal and liver diseases."],["Renal impairment","Use with caution."],["Hepatic impairment","Use with caution in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["Note","To avoid excessive dosage in obese patients, dose should be calculated on the basis of ideal body weight."]],"f25":[{"i":"Vecuronium bromide 2mg/mL injection (2mL) vial","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Vecuronium bromide 4mg/mL injection (2mL) ampoule → now Vecuronium bromide 2mg/mL injection (2mL) vial"]],"al":""},{"k":"NATAMYCIN","n":"NATAMYCIN","g":"Ophthalmic anti-infective agents (anti-fungal).","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.1 Anti-infective agents","moa":"Polyene antifungal; binds ergosterol and blocks fungal membrane function (fungal keratitis).","f":[["Indications & dose","Fungal Blepharitis and conjunctivitis ADULT: Instil 1 drop in affected eye(s) 4-6 times per day. Fungal keratitis ADULT: Instil 1 drop in affected eye(s) every 1-2 hours for 3-4 days, then 1 drop 6-8 times daily; continue for 14-21 days until infection eradicated. CHILD: safety and efficacy not established."],["Contraindications","Hypersensitivity to natamycin or any component of the product."],["Cautions","In keratitis, consider alternative treatment if no improvement in 7-10 days of therapy, corneal abrasion."],["Side effects","Eye irritation and blurred vision."],["Pregnancy category","C"],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Natamycin 5% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Natamycin 5% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"NEOSPORIN (Neomycin + polymyxin + bacitracin)","n":"NEOSPORIN (Neomycin + polymyxin + bacitracin)","g":"Antibacterial.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.1 Anti-infective agents","moa":"Neomycin (30S protein synthesis), polymyxin B (gram-negative membrane disruption) and bacitracin (cell wall synthesis).","f":[["Indications & dose","Bacterial infection, apply 3-4 times daily."],["Contraindications","Known sensitivity to any of the components."],["Counselling","Do not use it after 1 month of opening; do not share the ointment with another patient."]],"f25":[{"i":"Neomycin 3400 IU + Polymyxin 5000 IU + Bacitracin 400 IU eye ointment/g (5g) tube","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Neomycin 3400 IU + Polymyxin 5000 IU+ Bacitracin 400 IU eye ointment/g (5g) tube: now supplied down to DH"],["Specification changed in 2025","Neomycin + Polymixin + Bacitracin eye ointment (5g) tube → now Neomycin 3400 IU + Polymyxin 5000 IU+ Bacitracin 400 IU eye ointment/g (5g) tube"]],"al":""},{"k":"TETRACYCLINE","n":"TETRACYCLINE","g":"Antibacterial.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.1 Anti-infective agents","moa":"Binds 30S ribosomal subunit, blocking aminoacyl-tRNA attachment. Bacteriostatic.","f":[["Indications & dose","Prevention of chlamydial and gonococcal neonatal conjunctivitis, one single application immediately after birth."],["Contraindications","Hypersensitivity to tetracycline group of antibiotics. Side Effects Transient blurring of vision."]],"f25":[{"i":"Tetracycline 1% eye ointment (5g) tube","v":"E","l":"NRH/RRH/DH/PHC","r":"For the prophylaxis of neonatal conjunctivitis"}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"TOBRAMYCIN","n":"TOBRAMYCIN","g":"Antibacterial (aminoglycoside).","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.1 Anti-infective agents","moa":"Aminoglycoside; binds 30S subunit causing mRNA misreading. Good Pseudomonas activity.","f":[["Indications & dose","External infections of the eye and its adnexa caused by susceptible bacteria by ocular instillation, ADULT and CHILD over 1 year, 1 drop twice daily for 1 week; in severe infection, 1 drop four times daily on the first day, then twice daily for 5 to 7 days."],["Contraindications","Hypersensitivity."],["Cautions","Hypersensitivity, pregnancy; breastfeeding, if tobramycin is administered topically in conjunction with systemic aminoglycoside therapy, serum aminoglycoside concentration should be monitored."],["Side effects","Localised ocular toxicity and hypersensitivity including increased lacrimation, itching and oedema of the eyelid and conjunctival erythema."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Tobramycin 0.3% eye drop (5mL)","v":"V","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Tobramycin 0.3% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"KETOROLAC","n":"KETOROLAC","g":"Anti-inflammatory Agent.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.2 Anti-inflammatory agents","moa":"Potent NSAID; non-selective COX inhibitor (ocular or systemic analgesia).","f":[["Indications & dose","Prophylaxis and reduction of inflammation and associated symptoms following ocular surgery and to relieve ocular itching associated with allergic conjunctivitis by ocular instillation, 1 drop to the affected eye three to four times daily."],["Contraindications","Hypersensitivity to Aspirin and NSAIMs."],["Cautions","Post cataract surgery, chronic use of ketorolac eye drop."],["Side effects","Transient ocular burning or stinging, conjunctival hyperaemia, corneal oedema, iritis, ocular inflammation, pain and pressure, superficial keratitis and infection."],["Pregnancy category","C"],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Ketorolac 0.4% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Ketorolac 0.4% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"PREDNISOLONE ACETATE","n":"PREDNISOLONE ACETATE","g":"Anti-inflammatory agents (corticosteroids).","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.2 Anti-inflammatory agents","moa":"Ophthalmic corticosteroid; suppresses ocular inflammation via glucocorticoid receptors.","f":[["Indications & dose","Ophthalmic inflammatory conditions Instil 1-2 drops of 1% solution 2 - 4 times daily, May reduce frequency but do not discontinue prematurely."],["Contraindications","Fungal, mycobacterial, viral infections."],["Cautions","Cataract surgery and glaucoma."],["Side effects","Raised intraocular pressure, optic nerve and pathway injury."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Prednisolone acetate 1% eye drop (5mL)","v":"V","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Prednisolone acetate 1% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"SODIUM CROMOGLYCATE","n":"SODIUM CROMOGLYCATE","g":"Mast cell stabilisers.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.3 Mast cell stabilisers","moa":"Mast cell stabiliser; prevents degranulation and histamine release.","f":[["Indications & dose","Allergic conjunctivitis By ocular instillation, 1 to 2 drops 4-6 times daily."],["Contraindications","Patients with known hypersensitivity to any of the ingredients in the formulation."],["Side effects","Transient burning and stinging."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Sodium cromoglycate 2% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Sodium cromoglycate 2% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"ACETAZOLAMIDE","n":"ACETAZOLAMIDE","g":"Antiglaucoma medicine and diuretic.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.4 Miotics and antiglaucoma medicines","moa":"Carbonic anhydrase inhibitor; reduces aqueous humour production and causes bicarbonate diuresis.","f":[["Indications & dose","Open angle glaucoma, secondary glaucoma, hydrocephalus ADULT, PO 250–750 mg/day in divided doses; CHILD, 8-30 mg/kg daily, MAX. of 750 mg; Mountain sickness: prophylactic: 125 to 250 mg twice daily starting 1 or 2 days before and continuing for 3 days once the highest altitude is reached; treatment: 250 mg twice a day for about 3 days."],["Contraindications","Hypersensitivity to acetazolamide, sulfonamides, hepatic disease, hypokalemia, hyponatremia, cirrhosis, hyperchloremic acidosis, severe renal disease or dysfunction, severe pulmonary obstruction, long-term use in non-congestive angle-closure glaucoma."],["Cautions","Pregnancy; May cause neonatal thrombocytopenia, diabetes, breastfeeding; Not for prolonged use."],["Side effects","Diuresis: paraesthesia, hypokalemia, loss of appetite, drowsiness and depression may occur, especially in the elderly; nausea, vomiting, diarrhoea, taste disturbance."],["Renal impairment","CrCl 10-50 mL/minute: Administer every 12 hours. CrCl <10 mL/minute: Avoid use (ineffective)."],["Hepatic impairment","Use with caution in patients with hepatic dysfunction; in cirrhosis, avoid electrolyte and acid/base imbalances that might lead to hepatic encephalopathy."],["Pregnancy category","C"],["Breast-feeding","Amount too small to be harmful."],["Counselling","May cause drowsiness, do not drive, or operate machinery."]],"f25":[{"i":"Acetazolamide 250mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"BRIMONIDINE","n":"BRIMONIDINE","g":"Antiglaucoma medicine.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.4 Miotics and antiglaucoma medicines","moa":"Alpha-2 agonist; reduces aqueous production and increases uveoscleral outflow.","f":[["Indications & dose","Raised intraocular pressure in open-angle glaucoma or ocular hypertension in patients whom beta-blockers are inappropriate; adjunctive therapy when intraocular pressure is being inadequately controlled by other anti-glaucoma therapy by ocular instillation,1 drop 2 times daily."],["Cautions","Severe cardiovascular disease; cerebral coronary insufficiency, Raynaud’s syndrome, postural hypotension, depression, hepatic or renal impairment; pregnancy, breast feeding."],["Side effects","Ocular reactions include hyperemia, burning, stinging, burning, blurring, pruritus, allergy, and conjunctival follicles; occasionally corneal erosion and staining, photophobia, eyelid inflammation, conjunctivitis; headache, dry mouth, taste alteration, fatigue, dizziness, drowsiness."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Brimonidine 0.2% eye drop (5mL)","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"DORZOLAMIDE","n":"DORZOLAMIDE","g":"Antiglaucoma.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.4 Miotics and antiglaucoma medicines","moa":"Topical carbonic anhydrase inhibitor; reduces aqueous humour production.","f":[["Indications & dose","Glaucoma by ocular instillation, 1 drop to the affected eye 3-4 times a day."],["Contraindications","Hyperchloremic acidosis, severe renal impairment with CrCl <30 mL/min."],["Cautions","Chronic corneal defects, history of intraocular surgery, history of renal calculi, low endothelial cell count, systemic absorption follows topical application."],["Side effects","Asthenia, bitter taste, blurred vision, conjunctivitis, eyelid inflammation, headache, lacrimation, nausea, ocular irritation, superficial punctate keratitis."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Dorzolamide 2% eye drop (10mL)","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Dorzolamide 2% eye drop (5mL) → now Dorzolamide 2% eye drop (10mL)"]],"al":""},{"k":"LATANOPROST","n":"LATANOPROST","g":"Miotic and antiglaucoma medicine.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.4 Miotics and antiglaucoma medicines","moa":"Prostaglandin F2-alpha analogue; increases uveoscleral outflow of aqueous humour.","f":[["Indications & dose","Elevated Intraocular Pressure (Open-angle glaucoma or ocular hypertension) ADULT: Instil 1 drop in affected eye(s) once daily, in the evening MAX. once daily. CHILD: Safety and efficacy not established."],["Contraindications","Hypersensitivity to latanoprost, benzalkonium chloride, or other components of product. Herpetic keratitis with prostaglandin analogs."],["Cautions","Angle closure glaucoma, aphakia and patients with known risk factors for macular edema, macular edema, including cystoid macular edema, active intraocular inflammation (e.g., iritis, uveitis)."],["Side effects","Eye discoloration, eye discomfort, eye inflammation, blurred vision, rash, dry eye, upper respiratory infection."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Advise patients about the possible change in eye colour. Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Latanoprost 0.005% eye drop (2.5mL), which can be stored at room temperature","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Latanoprost 0.005% eye drop (2.5mL) → now Latanoprost 0.005% eye drop (2.5mL), which can be stored at room temperature"]],"al":""},{"k":"TIMOLOL MALEATE","n":"TIMOLOL MALEATE","g":"Anti-glaucoma medicine (miotics).","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.4 Miotics and antiglaucoma medicines","moa":"Non-selective beta-blocker; reduces aqueous humour production by the ciliary body.","f":[["Indications & dose","Intraocular pressure in primary open-angle glaucoma, By ocular instillation,1 drop 2 times daily."],["Contraindications","Systemic absorption may follow topical application therefore eye drops containing a beta-blocker are contra-indicated in patients with bradycardia, heart block, or uncompensated heart failure, asthma."],["Side effects","Ocular stinging, burning, pain, itching, erythema, dry eyes and allergic reactions including anaphylaxis and blepharitis."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Timolol maleate 0.5% eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"ATROPINE","n":"ATROPINE","g":"Mydriatics and cycloplegic.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.5 Mydriatics","moa":"Long-acting antimuscarinic; mydriasis and cycloplegia (uveitis, refraction in children).","f":[["Indications & dose","Refraction procedures in young children; anterior uveitis, Apply a small amount into the conjunctival sac once or twice a day."],["Contraindications","Narrow angle glaucoma."],["Cautions","Infant and elder patients; the action of the medicine may persist for up to 7 days after stopping treatment."],["Side effects","Blurred vision, stinging, eye irritation, photophobia."],["Counselling","May cause drowsiness do not drive or operate machinery."]],"f25":[{"i":"Atropine 1% eye ointment (5g) tube","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CYCLOPENTOLATE","n":"CYCLOPENTOLATE","g":"Mydriatic and cycloplegic (antimuscarinic).","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.5 Mydriatics","moa":"Intermediate-acting antimuscarinic; mydriasis and cycloplegia for refraction.","f":[["Indications & dose","Refraction procedures in young children, Uveitis by ocular instillation, diagnostic procedures: 1-2 drops repeated after every 5 to 15 minutes; Treatment of uveitis; CHILDREN 3 months - 17 years, 1-2 drops up to four times daily."],["Contraindications","Narrow-angle glaucoma or anatomical narrow angles."],["Cautions","Premature and small infants, driving or hazardous activities, children with spastic paralysis or brain damage, Down's syndrome, elderly, may interfere with anti-glaucoma action of carbachol or pilocarpine, predisposition to angle-closure glaucoma, young children."],["Side effects","Blurred vision, burning sensation in the eye, photophobia."],["Counselling","Advice not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Cyclopentolate 1% eye drop(5mL)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Cyclopentolate 0.5% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"],["Specification changed in 2025","Cyclopentolate 0.5% eye drop (5mL) → now Cyclopentolate 1% eye drop (5mL)"]],"al":""},{"k":"HOMATROPINE","n":"HOMATROPINE","g":"Mydriatic.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.5 Mydriatics","moa":"Antimuscarinic; mydriasis and cycloplegia, relieves ciliary spasm in uveitis.","f":[["Indications & dose","Mydriasis induction ADULT, 1-2 drops of 2% solution, repeat in 5 to 10 mins if needed; Uveitis 1-2 drops of 2% solution, every 3 to 4 hours."],["Contraindications","Primary or narrow angle glaucoma."],["Cautions","Infants and young children, Down syndrome patient, keratoconus and elderly patient."],["Side effects","Follicular conjunctivitis, vascular congestion, edema, xerostomia, burning, irritation, stinging, blurred vision, exudate, eczematoid dermatitis."],["Note","Paralysis of accommodation will continue for up to 12 hours."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Homatropine 2% eye drop (5mL)","v":"N","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Homatropine 2% eye drop (5 mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"]],"al":""},{"k":"HYDROXYPROPYL METHYLCELLULOSE","n":"HYDROXYPROPYL METHYLCELLULOSE","g":"Surgical aid (Ophthalmic).","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.6 Miscellaneous","moa":"Viscous lubricant that replaces tear film (and protects endothelium in eye surgery).","f":[["Indications & dose","Ophthalmic surgical aid in anterior segment surgical procedures, including cataract extraction and intraocular lens implantation, by INTRAOCULAR injection, 2% injection to be injected carefully into the anterior chamber by using a 20 gauge or smaller cannula. Additional doses may be injected during surgery to fully maintain the chamber and to replace any fluid lost during the surgical procedure."],["Cautions","Glaucoma."],["Side effects","Transient increase in intraocular pressure, corneal oedema, hypopyon, iritis."]],"f25":[{"i":"Hydroxypropyl methylcellulose 2% Intra-occular injection (3mL) pre-filled syringe","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Hydroxypropyl methylcellulose 2% Intra-occular injection (3mL) pre-filled syringe: now supplied down to DH"]],"al":""},{"k":"CARBOXYMETHYLCELLULOSE","n":"CARBOXYMETHYLCELLULOSE","g":"Ophthalmic preparations/lubricant. Ocular irrigant. Hormonal contraceptive.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.6 Miscellaneous","moa":"Viscous lubricant tear substitute; stabilises tear film in dry eye.","f":[["Indications & dose","Dry eye and tear deficiency ADULT: Instil 1-2 drops 3-4 hourly as required. CHILD: Apply as required."],["Contraindications","Corneal abrasion, ocular infection, ocular trauma, visual disturbance. Contact lenses."],["Cautions","Hypersensitivity to ingredients."],["Side effects","Irritation in eye, continued eye redness, Pain in eye, Blurred vision, Redness of the eye."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Carboxymethyl cellulose 1% eye drop (10mL)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SODIUM CHLORIDE (HYPERTONIC) EYE DROP","n":"SODIUM CHLORIDE (HYPERTONIC) EYE DROP","g":"Ocular irrigant.","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.6 Miscellaneous","moa":"","f":[["Indications & dose","Corneal oedema following post cataract surgery and glaucoma, Instil 1-2 drops every 3 or 4 hours or as directed by the physician."],["Side effects","Temporary burning and irritation."],["Note","NEMF 2022 lists 3%; NEML 2025 changed the specification to 5%."],["Counselling","Advise not to drive or operate heavy machinery after using this medicine as it may cause blurring of vision. Do not touch the tip of the container to any surface. Not to be used longer than one month after the bottle is opened. Remove contact lenses prior to the administration. If more than one topical ophthalmic medicine is used, the medicine should be administered at least 5 minutes apart."]],"f25":[{"i":"Sodium chloride 5% (hypertonic) eye drop (5mL)","v":"E","l":"NRH/RRH/DH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":"NRH/RRH/DH","ch":[],"al":"hypertonic saline eye drop"},{"k":"LEVONORGESTREL","n":"LEVONORGESTREL","g":"Hormonal contraceptive. Hormonal contraceptive.","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.1.1 Oral hormonal contraceptives","moa":"Progestogen; delays or inhibits ovulation (emergency contraception) and thickens cervical mucus.","f":[["Indications & dose","Emergency hormonal contraception, PO 1.5 mg (two tabs) as a single dose as soon as possible after unprotected sex (preferably within 12 hours but no later than after 72 hours) or 1 tablet each 12 hours apart."],["Contraindications","Severe liver disease, porphyria, severe arterial disease, undiagnosed vaginal bleeding."],["Cautions","Past ectopic pregnancy, severe malabsorption syndromes."],["Side effects","Nausea, vomiting, headache, dizziness, breast discomfort, depression, skin disorders, disturbances of appetite, irregular menstrual period."],["Hepatic impairment","Caution in severe liver disease and recurrent cholestatic jaundice."],["Pregnancy category","X"],["Breast-feeding","Avoid."],["Counselling","Avoid repeated use."]],"f25":[{"i":"Levonorgestrel 1.5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CLOMIPHENE","n":"CLOMIPHENE","g":"Ovulation inducer.","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.2 Ovulation inducers","moa":"Selective oestrogen receptor modulator; blocks hypothalamic oestrogen feedback, raising FSH/LH to induce ovulation.","f":[["Indications & dose","Anovulatory infertility, PO 50 mg daily for 5 days, starting within about 5 days of onset of menstruation (preferably on 2nd day) or at any time if cycles have ceased; second course of 100 mg daily for 5 days may be given in absence of ovulation; most patients who are going to respond will do so to first course; 3 courses should constitute adequate therapeutic trial; long term cyclical therapy not recommended; Male infertility, 25 mg/day for 3 months."],["Contraindications","Abnormal uterine bleeding, hormone dependent tumours, ovarian cyst."],["Cautions","Polycystic ovary syndrome, uterine fibroids."],["Side effects","Visual disturbance - withdraw treatment; hot flushes, abdominal discomfort; occasionally nausea, vomiting depression, insomnia, breast tenderness, weight gain, rashes, dizziness and hair loss, headache, intermenstrual spotting, menorrhagia, endometriosis, convulsions."],["Hepatic impairment","Avoid in severe impairment."],["Pregnancy category","X"],["Breast-feeding","May inhibit lactation, avoid."],["Note","Patients planning to conceive should be warned that there is risk of multiple pregnancies."]],"f25":[{"i":"Clomifene 50mg tablet","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Gynaecologist"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"MISOPROSTOL","n":"MISOPROSTOL","g":"Uterotonics (prostaglandin analogues).","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.3 Uterotonics","moa":"Prostaglandin E1 analogue; uterine contraction and cervical ripening, and gastric mucosal protection.","f":[["Indications & dose","Cervical ripening procedure - Induction of labour, (Insert) 200 mcg vaginally; leave in for 24 hours or until active labour onset, (Tablet) 20 mcg to 25 mcg orally every 2 hours. NSAID-induced gastric ulcer; Prophylaxis,200 mcg ORALLY 4 times daily. Postpartum haemorrhage 600 to 1000 mcg orally, sublingually, or rectally one time (guideline dosage). Termination of pregnancy,(Buccal, Sublingual or Vaginal) Monotherapy, up to 70 days' gestation: 800 mcg buccally, SL or vaginally every 3 hours for up to 3 doses (3 doses typically used in studies; however, a number of maximum doses not specified.(Vaginal or Sublingual) Monotherapy, second trimester: 400 mcg vaginally or SL every 3 hours for up to 5 doses. Vaginal administration is preferred over sublingual administration in nulliparous women. If abortion is not complete after 5 doses, the cycle may be started again following a 12-hour rest period (guideline dosage). (Vaginal/sublingual) Alternative monotherapy regimen, second trimester: Loading dose of 600 to 800 mcg vaginally followed by 400 mcg SL (or vaginally) every 3 hours may be more effective (guideline dosage). Incomplete medication abortion, up to 70 days gestation: May use a repeat dose of misoprostol 1 week after treatment depending on clinical circumstances or patient preferences (guideline dosage). Ulcer of duodenum,800 mcg/day in 2 or 4 divided doses for 4 weeks."],["Contraindications","Pregnancy, breastfeeding, allergy to prostaglandins."],["Cautions","Conditions where hypotension might precipitate severe complications (e.g. cerebrovascular disease or cardiovascular disease), inflammatory bowel disease."],["Side effects","Nausea, vomiting, diarrhoea, abdominal cramps, flatulence, dizziness, dyspepsia, menorrhagia."],["Renal impairment","Use with caution. Pregnancy Category X"],["Breast-feeding","Excreted in breast milk, avoid."]],"f25":[{"i":"Misoprostol 25µg oral tablet","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Misoprostol 100µg tablet","v":"V","l":"NRH/RRH","r":"Supplied to DH where there is Gynaecologist"}],"lv":["NRH","RRH","DH"],"ch":[["Added in 2025","Misoprostol 25µg oral tablet added (Till DH). Reason: For labour induction"]],"al":""},{"k":"OXYTOCIN","n":"OXYTOCIN","g":"Uterotonic.","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.3 Uterotonics","moa":"Oxytocin receptor agonist; increases intracellular Ca2+ in myometrium, causing rhythmic uterine contraction.","f":[["Indications & dose","Induction of labour, by IV infusion, 0.001– 0.004 IU/mins initially (not to be started for at least 6 hours after administration of vaginal prostaglandin), dose increased at intervals of at least 30 minutes until a maximum of 3–4 contractions occur every 10 minutes up to max. 0.02 IU/minute; if regular contractions are not established after a total of 5 units, stop induction attempt (may be repeated next day starting again at 0.001–0.004 IU/minute); Treatment of postpartum haemorrhage, by slow IV injection, 5 IU, repeated if necessary."],["Contraindications","Hypertonia of uterus; mechanical obstruction to delivery; failed trial of labour; severe pre-eclampsia; foetal distress; placenta praevia."],["Cautions","Hypertension; high parity, previous caesarean section, multiple pregnancies, women over 35 years."],["Side effects","High doses cause violent uterine contractions leading to uterine rupture and/or foetal asphyxiation; arrhythmias, maternal hypertension and subarachnoid haemorrhage may also occur, headache, nausea, vomiting. Pregnancy Category X"],["Breast-feeding","Excreted in breast milk, commencement of breastfeeding should be delayed for at least 1 day when discontinued, use caution."],["Note","Do not use as IV bolus; to control bleeding in incomplete abortion, methylergometrine should be used; the uterus in early pregnancy responds better to methylergometrine."]],"f25":[{"i":"Oxytocin 5IU/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CAFFEINE CITRATE","n":"CAFFEINE CITRATE","g":"","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.5 Medicines administered to the neonate","moa":"Adenosine receptor antagonist; stimulates the respiratory centre (apnoea of prematurity).","f":[["Indications & dose","Neonatal apnea, By IV infusion, initially 10-20 mg/kg, administered over 30 minutes, then after 24 hours of initial dose administer 5 mg/kg/day over 10 minutes; increased if necessary to 10 mg/kg/day."],["Cautions","Cardiovascular diseases, gastro-esophageal reflux disorder, seizure disorders."],["Side effects","Fluid and electrolyte imbalance, hyperglycemia, hypertension, hypoglycemia, irritability, restlessness, tachycardia."],["Hepatic impairment","Use with caution in patients with hepatic impairment. Renal Impairment Use with caution in patients with renal impairment."]],"f25":[{"i":"Caffeine citrate 20mg/mL injection (1mL) vial","v":"V","l":"NRH/RRH","r":""},{"i":"Caffeine citrate 20mg/mL oral solution (3mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FINASTERIDE","n":"FINASTERIDE","g":"Medicines used in benign prostatic hyperplasia.","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.6.1 Medicines used in benign prostatic hyperplasia","moa":"5-alpha-reductase (type 2) inhibitor; reduces DHT, shrinking the prostate.","f":[["Indications & dose","Benign prostatic hyperplasia, ADULT 5mg daily."],["Cautions","Obstructive uropathy."],["Side effects","Decreased libido, erectile dysfunction, ejaculation disorders, and reduced volume of ejaculate; rarely gynecomastia, pruritus rash."],["Renal impairment","No dose adjustment necessary. Pregnancy Category X"],["Hepatic impairment","Use with caution."],["Note","Review treatment at 3 - 6 months and then every 6 - 12 months. May require several months of treatment before benefit is obtained."],["Counselling","Take in the morning after breakfast. Women of childbearing potential should avoid handling crushed or broken tablets of finasteride."]],"f25":[{"i":"Finasteride 5mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"TAMSULOSIN","n":"TAMSULOSIN","g":"Medicine used in benign prostatic hyperplasia.","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.6.1 Medicines used in benign prostatic hyperplasia","moa":"Selective alpha-1A antagonist; relaxes prostate and bladder neck smooth muscle.","f":[["Indications & dose","Symptomatic relief in benign prostatic hypertrophy, PO ADULT, 0.4 mg once daily."],["Contraindications","History of micturition, syncope, history of postural hypotension."],["Cautions","Cataract surgery, concomitant antihypertensives, elderly."],["Side effects","Postural hypotension, headache, rhinitis, dizziness, back pain, tachycardia, syncope."],["Renal impairment","Use with caution if eGFR less than 10 mL/min. Pregnancy Category B"],["Hepatic impairment","Avoid in severe impairment."],["Counselling","Dizziness on standing may occur especially when starting treatment or dose is increased; stop the treatment if there is no benefit after 4-6 weeks of maximal treatment."]],"f25":[{"i":"Tamsulosin 0.4mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"OXYBUTYNIN","n":"OXYBUTYNIN","g":"Medicine used in urinary frequency enuresis, and incontinence.","sec":"21. MEDICINES FOR REPRODUCTIVE HEALTH, PERINATAL CARE AND URINARY-TRACT DISORDERS","sub":"21.6.2 Medicines used in urinary frequency enuresis and incontinence","moa":"Antimuscarinic (M3) with direct antispasmodic effect on the detrusor.","f":[["Indications & dose","Urinary frequency, urgency and incontinence; neurogenic bladder disorders instability, ADULT AND CHILD 12 years and above, PO 5 mg 2-3 times daily increased to 5 mg 4 times daily if required; CHILD 5 – 11 years, initially 2.5 – 3 mg twice daily increased to 5 mg 2-3 times daily; ELDERLY, initially 2.5-3 mg 2 times daily, increased to 5 mg 2 times daily if tolerated. Nocturnal enuresis associated with overactive bladder, CHILD 5-17 years, 2.5 – 3 mg twice daily increased to 5 mg 2-3 times a day, last dose to be taken before bed."],["Contraindications","Myasthenia gravis, bladder outflow obstruction or urinary retention, severe ulcerative colitis, toxic mega colon, and in gastro-intestinal obstruction or intestinal atony; glaucoma, paralytic ileus."],["Cautions","Acute porphyria."],["Side effects","Dryness of mouth, constipation, flatulence and taste disturbances, dryness of eyes, blurred vision, dizziness, headache, fatigue, palpitation, difficulty in micturition, heat intolerance and dryness of skin."],["Renal impairment","Use with caution."],["Hepatic impairment","Use with caution."],["Pregnancy category","B"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Do not drive or operate machinery."]],"f25":[{"i":"Oxybutynin 2.5mg tablet","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Paediatrician"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"ARIPIPRAZOLE","n":"ARIPIPRAZOLE","g":"Antipsychotic.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"Partial agonist at D2 and 5-HT1A receptors and antagonist at 5-HT2A.","f":[["Indications & dose","Schizophrenia ADULT: Initially 10-15 mg PO once daily. Usual maintenance dose 15 mg PO once daily, MAX. Dose 30 mg once daily. CHILD (15-17 years): Initial 2 mg PO once daily for 2 days, then 5 mg PO once daily for 2 days, and then target dose, 10 mg PO once daily. May increase to MAX. 30 mg daily. Moderate to severe manic episodes in Bipolar I Disorder and recurrence prevention of mania ADULT: Initially 15 mg PO once daily MAX. dose 30 mg once daily. CHILD (10 years or older): Initial 2 mg PO once daily for 2 days, then 5 mg PO once daily for 2 days, and then target dose, 10 mg PO once daily. May increase to MAX. 30 mg daily, titrated in 5 mg daily increments. ELDERLY > 65 years consider lower starting dose (5 mg once daily) when clinical factors warrant."],["Contraindications","CNS depression, comatose state and pheochromocytoma."],["Cautions","Cerebrovascular disease, elderly (reduce initial dose). The dose may need to be reviewed if concomitant use with strong CYP3A4/CYP2D6 inhibitors or inducers. Compulsive behaviour and impaired impulse control has been reported."],["Side effects","Anxiety, abnormal appetites, diabetes mellitus, fatigue, gastrointestinal discomfort, headache, hypersalivation, nausea and vision disorders."],["Renal impairment","No dosage adjustment required in renal impairment."],["Hepatic impairment","No dosage adjustment required in mild-moderate hepatic impairment. Use with caution in severe hepatic impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, use with caution."]],"f25":[{"i":"Aripiprazole 10mg tablet","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"CHLORPROMAZINE","n":"CHLORPROMAZINE","g":"Antipsychotic.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"Typical (low-potency) antipsychotic; D2 antagonist with marked anticholinergic, antihistaminic and alpha-blocking effects.","f":[["Indications & dose","Psychosis, mania, agitation, violent behaviour ADULT: PO 25 mg 3 times daily (or 75 mg at night); normal maintenance dose 75-300 mg daily, maximum (psychosis) 1 g daily; CHILD: 1-5 years, 0.5 mg/kg 6 hourly, MAX. 40 mg daily; CHILD 6-12 years, 1/3 to 1/2 adult dose, MAX. 75 mg daily; ELDERLY: 1/3 to 1/2 adult dose; by deep IM injection, ADULT: 25-50 mg 3-4 times daily; CHILD: dose same as by oral administration; Intractable hiccup ADULT: PO 25-50 mg 3-4 times daily."],["Contraindications","Bone marrow depression, closed-angle glaucoma, and coma due to CNS depressants, hypothyroidism, pheochromocytoma."],["Cautions","Cardiovascular and cerebrovascular disorders, respiratory disease; parkinsonism, epilepsy, acute infections, history of jaundice, leukopenia, hypothyroidism, myasthenia gravis, prostatic hypertrophy, angle-closure glaucoma, the elderly (particularly in very hot or very cold weather; reduce dose), avoid abrupt withdrawal, patients should remain supine and blood pressure monitored for 30 minutes after intramuscular injection (risk of hypotension), diabetes."],["Side effects","Extrapyramidal symptoms and on prolonged administration, occasionally potentially irreversible tardive dyskinesias; hypothermia (occasionally pyrexia), drowsiness, apathy, pallor, nightmares, dizziness, excitement, insomnia, headache, confusion, depression; more rarely, agitation, EEG changes, convulsions, and nasal congestion; anticholinergic symptoms including dry mouth, constipation, blurred vision, and difficulty in micturition; hypotension, tachycardia, and arrhythmias; respiratory depression; menstrual disturbances, galactorrhea, gynecomastia, impotence, weight gain; sensitivity reactions such as agranulocytosis, leukopenia, leukocytosis, hemolytic anaemia, photosensitization, contact sensitization and rash, jaundice, and alterations in liver function; neuroleptic malignant syndrome; lupus erythematosus-like syndrome; corneal and lens opacities, and purplish pigmentation of the skin, cornea, and retina (with prolonged high dosage); intramuscular injection may be painful and cause hypotension and tachycardia (see cautions) and nodule formation."],["Renal impairment","Starts with small doses in severe renal impairment because of increased cerebral sensitivity."],["Hepatic impairment","Can precipitate coma, avoid."],["Pregnancy category","C"],["Breast-feeding","excreted in breast milk, avoid."],["Counselling","Tablets should not be crushed; Do not drive or operate machinery, avoid alcohol."]],"f25":[{"i":"Chlorpromazine 100mg tablet","v":"E","l":"NRH/RRH/DH","r":""},{"i":"Chlorpromazine 25mg/mL injection (2mL) ampoule","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FLUPHENAZINE DECANOATE","n":"FLUPHENAZINE DECANOATE","g":"Antipsychotic.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"High-potency typical antipsychotic (depot); D2 receptor antagonist.","f":[["Indications & dose","Maintenance in schizophrenia and other psychoses: By deep IM injection, ADULT: Test dose 12.5 mg, dose to be administered into the gluteal muscle, then 12.5-100 mg after 4-7 days, then 12.5-100 mg every 14-35 days, adjusted according to response; ELDERLY, Test dose 6.25 mg, dose to be administered into the gluteal muscle, then 12.5-100 mg after 4-7 days, then 12.5-100 mg every 14-35 days, adjusted according to response."],["Contraindications","Comatose states, CNS depression, pheochromocytoma, marked cerebral atherosclerosis."],["Cautions","QT prolongation, cardiovascular disease, Parkinson’s disease, epilepsy (and conditions predisposing to epilepsy), depression, myasthenia gravis, prostatic hypertrophy, or a personal or family history of angle-closure glaucoma, severe respiratory disease, elderly."],["Side effects","Extrapyramidal symptoms and on prolonged administration, occasionally potentially irreversible tardive dyskinesias; hypothermia (occasionally pyrexia), drowsiness, apathy, pallor, nightmares, dizziness, excitement, insomnia, headache, confusion, depression; more rarely, agitation, EEG changes, convulsions, and nasal congestion; anticholinergic symptoms including dry mouth, constipation, blurred vision, and difficulty in micturition; hypotension, tachycardia, and arrhythmias; respiratory depression; menstrual disturbances, galactorrhea, gynecomastia, impotence, weight gain; sensitivity reactions such as agranulocytosis, leukopenia, leukocytosis, hemolytic anaemia, photosensitization, contact sensitization and rash, jaundice, and alterations in liver function; neuroleptic malignant syndrome; lupus erythematosus-like syndrome; corneal and lens opacities, and purplish pigmentation of the skin, cornea, and retina (with prolonged high dosage); intramuscular injection may be painful and cause hypotension and tachycardia (see cautions) and nodule formation."],["Renal impairment","Start with low doses in severe renal impairment because of increased cerebral sensitivity. Pregnancy Category C"],["Hepatic impairment","May precipitate coma. Avoid in hepatic failure."],["Breast-feeding","Enters breast milk, avoid."],["Counselling","Drowsiness may affect performance of skilled tasks (e.g., driving or operating machinery) especially at the start of treatment; Effects of alcohol are enhanced; Patients should avoid excessive exposure to sunlight."]],"f25":[{"i":"Fluphenazine decanoate 25mg/mL injection (1mL) ampoule","v":"E","l":"NRH","r":"Supplied to DH where there is Psychiatrist"}],"lv":["NRH"],"ch":[],"al":""},{"k":"HALOPERIDOL","n":"HALOPERIDOL","g":"Antipsychotic. Antipsychotic.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"High-potency typical antipsychotic; potent D2 antagonist (high extrapyramidal risk).","f":[["Indications & dose","Psychosis, mania, agitation, violent behaviour, By IM injection, Initially 2–5 mg, repeated if necessary, repeated dose given according to response and tolerability, for debilitated patients, use elderly dose (max.12 mg/day); ELDERLY, Initially 1-2.5 mg, repeated if necessary, repeated dose given according to response and tolerability; (max.12 mg/day)."],["Contraindications","Bone marrow depression, closed-angle glaucoma, coma due to CNS depressants, Parkinsonism, pheochromocytoma, bradycardia, QT interval prolongation, lesions of basal ganglia."],["Cautions","Cardiovascular and cerebrovascular disease, respiratory disease, parkinsonism, epilepsy, pregnancy and breast-feeding, history of jaundice; caution in elderly patients who are susceptible to postural hypotension and to hyper-and hypothermia in very hot or very cold weather."],["Side effects","Extrapyramidal effects are common at higher dosage, hypothermia, drowsiness, insomnia, depression, occasional reactions like agranulocytosis, leukopenia and photosensitivity may occur."],["Renal impairment","Start with low doses in severe renal impairment because of increased cerebral sensitivity."],["Hepatic impairment","May precipitate coma. Avoid in severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","May cause drowsiness, if affected do not operate machinery and avoid alcohol."]],"f25":[{"i":"Haloperidol 5mg/mL injection (1mL) vial","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"QUETIAPINE","n":"QUETIAPINE","g":"Antipsychotic.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"Atypical antipsychotic; D2 and 5-HT2A antagonist with strong H1 blockade (sedation).","f":[["Indications & dose","Bipolar ADULT: PO 50 mg twice daily on day 1, 100 mg PO twice daily on day 2, PO 150 mg twice daily on day 3, PO 200 mg twice daily on day 4; usual dose range PO 400 - 800 mg daily in 2 divided doses, MAX. Up to 800 mg per day. ELDERLY: Initially 50 mg PO daily, adjust accordingly to the response in steps of 50 mg daily. CHILD (12 - 17 years): 25 mg twice daily on day 1, increase to 50 mg twice daily on day 2, then 100 mg twice daily on day 3, then 150 mg twice daily on day 4, then continue at the target dose of 200 mg twice daily beginning on day 5. May increase based on clinical response and tolerability at increments ≤100 mg/day up to 300 mg twice daily; Max/dose 600 mg per day. Schizophrenia ADULT: Initially PO 25 mg twice daily on day 1, 50 mg twice daily on day 2, 100 mg twice daily on day 3, 150 mg twice daily on day 4; usual dose range: 300 - 450 mg daily; MAX. dose: 750 mg daily. ELDERLY: initially 25 mg daily, adjust accordingly to the response in steps of 25 mg - 50 mg daily. CHILD (12 - 17 years): 25 mg twice daily, adjusted according to the response in steps of 25 - 50 mg; MAX. 750 mg/day."],["Contraindications","Hypersensitivity to quetiapine or any components of the product."],["Cautions","Cerebrovascular disease. Treatment of depression in patients under 25 years, increase risk of suicidal thoughts. When taken with a strong CYP3A4 inducer (e.g; phenytoin, carbamazepine, rifampin, St John's wort) greater than 7 – 14 days, titrate dose based on clinical response and tolerability as much as 5 folds. When the CYP3A4 inducer is discontinued, reduce quetiapine to the original dose within 7 to 14 days. When used together with a strong CYP3A4 inhibitor (e.g; ketoconazole, itraconazole, ritonavir) reduce quetiapine dose to one-sixth of the original dose. When the CYP3A4 inhibitor is discontinued, increase quetiapine dose by 6-fold."],["Side effects","Increase diastolic and systolic arterial pressure (paediatric), orthostatic hypotension, tachycardia, hyperglycemia, serum cholesterol and triglyceride raise, weight gain, increase appetite, nausea, vomiting, dry mouth, somnolence, agitation, drowsiness, dizziness, rhinitis, constipation, indigestion and fatigue."],["Renal impairment","No dose adjustment necessary"],["Hepatic impairment","25 mg once daily; increase dose based on response and tolerability by 25 to 50 mg/day to effective dose."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, use with caution."],["Counselling","Take with/without food. Advise patients to stand from sitting position slowly, as the medicine may cause orthostatic hypotension and avoid abrupt discontinuation of the medicine. Counsel diabetic patients to monitor signs/symptoms of hyperglycemia. Inform patients of weight gain, dry mouth, nausea and vomiting."]],"f25":[{"i":"Quetiapine 300mg tablet","v":"E","l":"NRH/RRH","r":""},{"i":"Quetiapine 50mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"RISPERIDONE","n":"RISPERIDONE","g":"Antipsychotic.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"Atypical antipsychotic; potent 5-HT2A and D2 antagonist.","f":[["Indications & dose","Acute and chronic psychoses ADULT: PO 2 mg in 1-2 divided doses on day 1 then 4 mg in 1-2 divided doses on day 2; doses above 10 mg daily only if benefit considered to outweigh risk (max. 16 mg daily); ELDERLY, initially 0.5 mg twice daily increased in steps of 0.5 mg twice daily to 1-2 mg twice daily; CHILD under 15 years, not recommended; Mania: ADULT: initially PO 2 mg once daily, increased if necessary in steps of 1 mg daily; usual dose range 1-6 mg daily; ELDERLY, initially 0.5mg twice daily increased in steps of 0.5mg twice daily to 1-2 mg twice daily."],["Cautions","Acute porphyrias, cataract surgery, dehydration, dementia, prolactin-dependent tumours."],["Side effects","Insomnia, agitation, anxiety, headache, drowsiness, impaired concentration, fatigue, blurred vision, constipation, nausea and vomiting, dyspepsia, abdominal pain, hyperprolactinemia (with galactorrhea, menstrual disturbances, amenorrhea, gynecomastia), sexual dysfunction, priapism, urinary incontinence, tachycardia, hypertension, rash, rhinitis; cerebrovascular accidents, neutropenia and thrombocytopenia have been reported, rarely, seizures, hyponatremia, abnormal temperature regulation, oedema."],["Renal impairment","Initial and subsequent oral doses should be halved."],["Hepatic impairment","Initial and subsequent oral doses should be halved."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Orodispersible tablets should be placed on the tongue, allowed to dissolve, and swallowed."]],"f25":[{"i":"Risperidone 2mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"FLUOXETINE","n":"FLUOXETINE","g":"Antidepressant.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.2.1 Medicines used in depressive disorders","moa":"SSRI; blocks the serotonin transporter, raising synaptic serotonin. Long half-life.","f":[["Indications & dose","Depressive illness 20 mg PO once daily increased after 3 weeks if necessary; Usual dose 20-60 mg (ELDERLY 20-40 mg) once daily; MAX. 80 mg (elderly max. 60 mg) once daily; CHILD 8 -18 YEARS, 10-20 mg per day. Obsessive-compulsive disorder Initially PO 20 mg once daily increased after two weeks if necessary, usual dose 20-60 mg (ELDERLY 20-40 mg) once daily; MAX. 80 mg (ELDERLY max. 60 mg) once daily; Discontinue if no improvement within 10 weeks; CHILD 7-18 years, initial 10 mg per day gradually increased after 2 weeks to 20 mg."],["Cautions","Elderly, ventricular arrhythmia, diabetes, seizures."],["Side effects","Possible changes in blood sugar, fever, neuroleptic malignant syndrome-like event, abnormal bleeding, aplastic anaemia, cerebrovascular accident, ecchymosis, eosinophilic pneumonia, GI haemorrhage, hemolytic anaemia, pancreatitis, pancytopenia, thrombocytopenia, thrombocytopenic purpura, alopecia, headache"],["Renal impairment","Use with caution."],["Hepatic impairment","Reduce dose or increase dose interval."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Dose should be taken preferably in the morning. Patients should be counselled about the effects on driving and skilled tasks."]],"f25":[{"i":"Fluoxetine 20mg Capsule","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Fluoxetine 20mg tablet → now Fluoxetine 20mg Capsule"]],"al":""},{"k":"MIRTAZAPINE","n":"MIRTAZAPINE","g":"Antidepressant.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.2.1 Medicines used in depressive disorders","moa":"Alpha-2 antagonist (increases noradrenaline and serotonin release); blocks 5-HT2, 5-HT3 and H1 (sedation, appetite).","f":[["Indications & dose","Major depression ADULT: Initially PO 15–30 mg daily at bedtime for 2-4 weeks. Adjust according to response up to 45 mg once daily or 45 mg daily in 2 divided doses MAX. 45 once daily. Gradually taper the dose over 2-4 weeks."],["Contraindications","Use in combination with monoamine oxidase inhibitors (MAOI therapy) including linezolid and IV methylene blue. MAOIs should not be introduced within 2 weeks of cessation of therapy with mirtazapine. Avoid use with benzodiazepines and alcohol."],["Cautions","Cardiovascular disease or family history of QT-prolongation, concomitant use with other QT prolonging medicines, diabetes mellitus, elderly. History of mania, seizures, and urinary retention. Hypotension, psychoses, susceptibility to angle-closure glaucoma."],["Side effects","Anxiety, somnolence, xerostomia, appetite increased, arthralgia, back pain, confusion, constipation, diarrhoea, dizziness, drowsiness, dry mouth, fatigue. headache (on discontinuation), myalgia, nausea, oedema, postural, hypotension, sleep disorders, tremor, vomiting, increase cholesterol and weight."],["Renal impairment","If CrCl < 30 mL/minute/1.73 m²; adjust initial dose 7.5-15 mg, titrate dose slowly."],["Hepatic impairment","Use caution in patients with hepatic impairment."],["Pregnancy category","C"],["Breast-feeding","Present in milk, use with caution (only if potential benefit outweighs risk)."],["Counselling","Cause drowsiness should be taken at bedtime. Advised care giver as it may increase risk of suicidal thoughts and behavior in young adult patients (aged <24 years)."]],"f25":[{"i":"Mirtazapine 15mg tablet","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"VENLAFAXINE","n":"VENLAFAXINE","g":"Antidepressant.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.2.1 Medicines used in depressive disorders","moa":"SNRI; inhibits serotonin and (at higher doses) noradrenaline reuptake.","f":[["Indications & dose","Major depression PO 75 mg once daily initially, may be increased by 75 mg/day at intervals of at least 2 weeks (MAX. 375 mg/day) Generalised anxiety PO 75 mg once daily, increased if necessary up to 225 mg once daily, dose to be increased at intervals of at least 2 weeks (MAX. 225 mg/day)."],["Contraindications","Uncontrolled hypertension, high risk of serious ventricular arrhythmia, electrolyte disturbance."],["Cautions","History of MI, bleeding disorder; epilepsy, angle closure glaucoma, diabetes."],["Side effects","Constipation, nausea, dizziness, dry mouth, insomnia, suicidal ideation, nervousness, drowsiness; asthenia, headache, sexual dysfunction, sweating, anorexia, weight changes, diarrhea, dyspepsia, vomiting, abdominal pain, hypertension, palpitation, vasodilation, changes in serum cholesterol, chills, pyrexia, dyspnea, abnormal dreams, agitations, confusions, anxiety, hypertonia, paraesthesia, tremor, urinary frequency, menstrual disturbance, mydriasis, tinnitus, hypotension, postural hypotension, alopecia, Steven-Johnson syndrome."],["Renal impairment","Use half normal dose if eGFR less than 30 mL/minute. Use with caution. Pregnancy Category C"],["Hepatic impairment","Consider reducing dose by 50% in mild or moderate impairment; use with caution and reduce dose by at least 50% in severe impairment."],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","To be taken after food. Do not chew or crush the tablet, swallow whole. Do not drive or operate machineries."]],"f25":[{"i":"Venlafaxine 75mg extended release tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"BUPRENORPHINE","n":"BUPRENORPHINE","g":"Medicine for disorders due to psychoactive substances.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.4 Medicines for disorders due to psychoactive substance use","moa":"Partial mu-opioid agonist with high receptor affinity and kappa antagonism; ceiling on respiratory depression.","f":[["Indications & dose","and dosage Little or no opioid withdrawal ADULT: sublingual 0.4 mg to 4 mg or delay the initial dose. Moderate to severe opioid withdrawal 6 to 8 mg in divided dose. The maximum amount of buprenorphine at the end of the first day of induction ranges from 8 to 16 mg. The maintenance dosage should be individualised for each patient. The maintenance dosage will vary between individuals and should be determined by progressively increasing the dose until the minimal effective dose is identified. The mean maintenance daily dose is 8 mg. The majority of patients will not require doses exceeding 16 mg/day; however, the efficacy and safety of buprenorphine tablets was tested in clinical trials in doses up to 24 mg per day. After a satisfactory period of stabilisation has been achieved, the dosage may be reduced gradually to a lower maintenance dose, when appropriate treatment deemed may be discontinued."],["Contraindications","hypersensitivity, significant respiratory depression, acute and severe bronchial asthma, children < 16 years of age."],["Cautions","risk of opioid addiction, abuse and misuse which may lead to overdose."],["Side effects","Sedation, vomiting, nausea, dizziness, constipation, hypoventilation, headache, hypotension, miosis, dry mouth, euphoria, fatigue, respiratory depression, hepatotoxicity, cyanosis, ECG abnormalities"],["Hepatic impairment","Severe impairment: reduce the starting and titration increment dose by half and monitor for signs and symptoms of hepatotoxicity."],["Pregnancy category","C"],["Breast-feeding","Enters breast milk, not recommended."],["Counselling","Do not drink any fluids immediately following administration by sublingual route. May cause dizziness, drowsiness, confusion, or blurred vision (use caution when driving, climbing stairs, rising from sitting or lying position, or engaging in tasks requiring alertness)."]],"f25":[{"i":"Buprenorphine 2mg tablet","v":"E","l":"NRH","r":"Supplied to RRH where there is Psychiatrist"}],"lv":["NRH"],"ch":[],"al":""},{"k":"DISULFIRAM","n":"DISULFIRAM","g":"Medicines for disorders due to psychoactive substances.","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.4 Medicines for disorders due to psychoactive substance use","moa":"Inhibits aldehyde dehydrogenase; acetaldehyde builds up after alcohol, causing an unpleasant reaction.","f":[["Indications & dose","Management of chronic alcoholism ADULT: 500mg PO once daily initially for 1-2 weeks, not to exceed 500mg/day. Only administer after the patient has abstained from ethanol for at least 12 hours. Maintenance: 250mg once in a day, continue therapy until a basis for self-control is established."],["Contraindications","Ethanol and any alcohol containing products (e.g, mouth wash, hand rub solution), metronidazole, severe cardiac disease, coronary occlusion, psychosis."],["Cautions","Never administered to patients in a state of alcohol in-toxification or without patient’s full knowledge, diabetes, hypothyroidism, seizures, nephritis and hepatic impairment."],["Side effects","Fatigue, hepatitis, optic neuritis, psychotic disorder, rash, polyneuritis, acneiform eruption, metallic aftertaste, headache, impotence."],["Pregnancy category","C"],["Breast-feeding","excretion in breast milk unknown, not recommended."],["Counselling","Do not drink any alcohol, including products containing alcohol (such as cough and cold syrups or some mouthwashes), or use alcohol-containing skin products while taking this medication and for at least 3 days (preferably 14 days) after stopping this medication. Drowsiness, tiredness, or visual changes may occur."]],"f25":[{"i":"Disulfiram 250mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"BECLOMETHASONE DIPROPIONATE","n":"BECLOMETHASONE DIPROPIONATE","g":"Anti-asthmatic medicine.","sec":"23. MEDICINES ACTING ON THE RESPIRATORY TRACT","sub":"23.1 Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease","moa":"Inhaled corticosteroid; reduces airway inflammation via glucocorticoid receptors.","f":[["Indications & dose","Chronic asthma not controlled by short acting β-2 agonists ADULT: by inhalation, 2 MDIs 2-3 times daily and in severe cases up to 4 times; CHILD: by inhalation,1 MDI 2-3 times daily."],["Cautions","Systemic therapy may be required during periods of stress or when either airway obstruction or mucus prevents medicine access to smaller airways."],["Side effects","Inhaled corticosteroids have considerably fewer systemic effects than oral corticosteroids; high doses of inhaled corticosteroids used for prolonged periods have been associated with oropharyngeal candidiasis cough and lower respiratory tract infection including pneumonia; adrenal suppression, growth retardation in children and adolescents, impaired bone metabolism, glaucoma and cataract."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, Use with caution."],["Counselling","Advise patient to avoid spraying in or around eyes; advise patient that medicine may cause dizziness and to use caution while driving or performing other tasks requiring mental alertness. Advise patients for MDI inhalation technique (refer to salbutamol MDI). Rinse the mouth with water after inhalation to reduce the risk of oral candidiasis or use a spacer device if available."]],"f25":[{"i":"Beclometasone dipropionate 50µg metered-dose Inhilar with meter reading (200 actuations)","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Extended in 2025","Beclometasone dipropionate 50µg metered-dose inhaler with meter reading (200 actuations): now supplied down to PHC"],["Specification changed in 2025","Beclometasone dipropionate 50µg inhaler (200 actuations) → now Beclometasone dipropionate 50µg metered-dose Inhilar with meter reading (200 actuations)"]],"al":""},{"k":"FLUTICASONE + SALMETEROL","n":"FLUTICASONE + SALMETEROL","g":"Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease.","sec":"23. MEDICINES ACTING ON THE RESPIRATORY TRACT","sub":"23.1 Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease","moa":"Inhaled corticosteroid (anti-inflammatory) plus long-acting beta-2 agonist (sustained bronchodilation).","f":[["Indications & dose","Prophylaxis of asthma and management of chronic obstructive pulmonary disease ADULT and CHILD over 5 years: by inhalation, initially 1 MDI twice daily, increased up to 2 to 3 MDIs twice daily in severe cases."],["Contraindications","Hypersensitivity to fluticasone, salmeterol or any ingredients in the formulation."],["Cautions","Arrhythmia, susceptibility to QT prolongation and diabetes; excessive dose of inhaled corticosteroids should be avoided in children."],["Side effects","Fine tremor, headache, muscle cramp, palpitation, tachycardia, arrhythmia, myocardial ischemia and disturbances of sleep behaviour; inhaled corticosteroids used in high doses and for prolonged period of time can cause adrenal suppression and reduction in bone mineral density; in older patients with COPD, higher doses of inhaled corticosteroid are associated with increased risk of lower respiratory tract infection including pneumonia; oral candidiasis."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["Counselling","Do not use the preparation for the relief of acute attack; Rinse the mouth with water after inhalation to reduce the risk of oral candidiasis or use a spacer device if available. For MDI inhalation technique refer to salbutamol MDI."]],"f25":[{"i":"Fluticasone 125μg + Salmeterol 25μg Metered-dose inhaler (120 doses)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Fluticasone 125μg + Salmeterol 25μg inhaler (120 actuations) → now Fluticasone 125μg + Salmeterol 25μg Metered-dose inhaler (120 doses)"]],"al":""},{"k":"IPRATROPIUM","n":"IPRATROPIUM","g":"Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease.","sec":"23. MEDICINES ACTING ON THE RESPIRATORY TRACT","sub":"23.1 Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease","moa":"Short-acting muscarinic antagonist; blocks bronchial M3 receptors, causing bronchodilation.","f":[["Indications & dose","Chronic obstructive pulmonary disease ADULT by inhalation of nebulized solution, 250-500 mcg 3-4 times daily. Adjunct in acute bronchospasm ADULT 500 mcg repeated as required. CHILD up to 6 years, 125-250 mcg, maximum 1mg daily; CHILD 6-12 years, 250 mcg, MAX. 1mg daily."],["Contraindications","Hypersensitivity to ipratropium or any ingredients in the formulation."],["Cautions","Prostatic hypertrophy; pregnancy; glaucoma (in case of nebulized medicine in association with salbutamol); risk of paradoxical bronchospasm."],["Side effects","Occasionally dry mouth; rarely urinary retention and constipation; tachycardia and atrial fibrillation."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, use with caution."],["Counselling","Advise patient to avoid spraying in or around eyes; advise patient that medicine may cause dizziness and to use caution while driving or performing other tasks requiring mental alertness."]],"f25":[{"i":"Ipratropium respiratory 0.25mg/mL solution (15mL) bottle","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SALBUTAMOL","n":"SALBUTAMOL","g":"Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease.","sec":"23. MEDICINES ACTING ON THE RESPIRATORY TRACT","sub":"23.1 Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease","moa":"Short-acting beta-2 agonist; raises cAMP in airway smooth muscle (bronchodilation) and shifts K+ into cells.","f":[["Indications & dose","Asthma, Bronchospasm in patients with reversible obstructive airway ADULT by nebulization (respiratory solution). For intermittent administration ADULT, 0.5-1 mL of respiratory solution diluted to a final volume of 2-4 mL with 0.9% sodium chloride to be inhaled from a suitably driven nebulizer until aerosol generation ceases; CHILD under 12 years, 0.03 mL/kg of solution diluted to 2-4 mL with 0.9% sodium chloride and inhaled from a nebulizer. For continuous administration 1-2 mL of the respiratory solution diluted to 100 mL with 0.9% sodium chloride to contain 50-100 mcg salbutamol per mL. The diluted solution to be administered as aerosol by a suitably driven nebulizer. The usual rate of administration is 1-2 mg per hour by inhalation. Management of chronic asthma 2 puffs upto 4 times daily; CHILD, 1 puff, increase to 2 puffs, if necessary, up to 4 times daily; Prophylaxis of allergen or exercise induced bronchospasm 2 puffs as and when required."],["Contraindications","Hypersensitivity and thyrotoxicosis."],["Cautions","Hyperthyroidism, myocardial insufficiency, arrhythmias, hypertension, elderly patients, diabetics."],["Side effects","Fine tremor, nervous tension, headache, peripheral vasodilatation, tachycardia, sleep and behavioural disturbance in children."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, Use with caution."],["Counselling","MDI inhalation technique: 1. Without spacer 0. Put the metal canister into the “boot” making certain it is seated correctly 1. Shake the inhaler several times. This mixes the propellant and medicine 2. Remove the cap off from the mouthpiece 3. Breathe out to the end of a normal breath 4. Hold the inhaler in its upright position (with the mouthpiece at the bottom) 5. Put the mouthpiece in your mouth, past your teeth and above your tongue. Close your lips around the mouthpiece so that the medication does not go in your eyes 6. While breathing in slowly and deeply through your mouth, fully press down once on the top of the metal canister of your inhaler 7. Hold your breath for 5 to 10 seconds 8. Breathe out slowly 9. If you take more than one spray, wait 15 to 30 seconds (or as directed in the package insert) before taking the next puff. Then repeat steps 3-9 10. Replace the cap on the mouthpiece after you are finished 11. If you are inhaling a steroid, rinse your mouth out with water, swish, gargle and spit. 2. With spacer 0. Make sure that the metal canister of your MDI is inserted correctly into the plastic “boot” or holder 1. Remove the cap from the mouthpiece of both the MDI and the spacer 2. Insert the MDI mouthpiece in the soft opening of the spacer. The MDI canister needs to be in an upright position 3. Shake the MDI with the attached spacer several times 4. Breathe out, away from the spacer to the end of your normal breath 5. Place the mouthpiece of the spacer into your mouth, past your teeth and above your tongue. Close your lips around the mouthpiece. If you are using a spacer with a mask, place the mask over your nose and mouth. Be sure the mask has a good seal against your cheeks and chin. There should be no space between the mask and your skin 6. Press down on the top of the metal canister once, to release the medicine into the spacer 7. Breathe in deeply and slowly through your mouth. If the spacer makes a “whistling” sound, you are breathing in too fast. You should NOT hear a whistle 8. Hold your breath for 5 to 10 seconds 9. Breathe out slowly 10. If you are instructed to take more than one puff (spray), wait about 15 to 30 seconds (or as directed by the package insert) before taking the next puff. Then repeat steps 4-10 11. Replace the cap on the mouthpiece of the MDI inhaler and spacer after you have finished 12. If you are inhaling a steroid, rinse your mouth out with water, swish, gargle and spit."]],"f25":[{"i":"Salbutamol 100µg inhaler (200 actuations)","v":"V","l":"NRH/RRH/DH/PHC","r":""},{"i":"Salbutamol respiratory 5mg/mL solution (15mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":"albuterol asthalin"},{"k":"THEOPHYLLINE+ETOPHYLLINE","n":"THEOPHYLLINE+ETOPHYLLINE","g":"Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease.","sec":"23. MEDICINES ACTING ON THE RESPIRATORY TRACT","sub":"23.1 Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease","moa":"Methylxanthines; inhibit phosphodiesterase and antagonise adenosine receptors, causing bronchodilation.","f":[["Indications & dose","Prophylaxis and relief of reversible bronchospasm associated with asthma (Acute and Chronic), bronchitis including chronic bronchitis, emphysema, and other obstructive airway diseases where there is a reversible airway narrowing ADULT PO 1 tablet 1 to 2 times daily."],["Contraindications","Hypersensitivity; Neonates and lactation."],["Cautions","Patients with severe cardiac disease, hypertension, hyperthyroidism, acute myocardial injury, CCF, history of peptic ulcer, children, pulmonary oedema, hepatic dysfunction, pregnancy and smokers."],["Side effects","Cardiac arrhythmias in pre-existing cardiac disease, tachycardia anorexia, nausea, tremors, CNS excitation, and hyperglycemia."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, Use with caution."]],"f25":[],"lv":["NRH","RRH","DH"],"ch":[["Deleted in 2025","Theophylline 69mg + Etophylline 231mg retard tablet removed (was available DH). Reason: Since it is not recommended by GINA and GOLD guidelines. Extended beclometasone MDI till PHC"]],"al":""},{"k":"TIOTROPIUM","n":"TIOTROPIUM","g":"Anti-asthmatic and medicines for chronic pulmonary obstructive disease.","sec":"23. MEDICINES ACTING ON THE RESPIRATORY TRACT","sub":"23.1 Anti-asthmatic medicines and medicines for chronic obstructive pulmonary disease","moa":"Long-acting muscarinic (M3) antagonist; sustained bronchodilation in COPD.","f":[["Indications & dose","Chronic obstructive pulmonary disease ADULT by inhalation, 2 puffs once daily."],["Contraindications","Hypersensitivity to tiotropium or any ingredients in the formulation."],["Cautions","Immediate hypersensitivity reactions, acute bronchospasm, closed-angle glaucoma, cardiac arrhythmias, anticholinergic medications, bladder obstruction, prostatic hypertrophy, urinary retention, urinary tract obstruction, arthralgia and lymphadenopathy."],["Side effects","Upper respiratory tract infection, constipation, oral ulcer, dry mouth, sinusitis, atrial fibrillation, urinary retention, angioedema, allergic reaction and abdominal pain."],["Renal impairment","Moderate to severe renal impairment (creatinine clearance of < 60 mL/min) should be monitored closely for anticholinergic side effects."],["Pregnancy category","C"],["Breast-feeding","Excretion in breast milk unknown, Use with caution."],["Counselling","Advise patient to avoid spraying in or around eyes; advise patient that medicine may cause dizziness and to use caution while driving or performing other tasks requiring mental alertness. Advise patients for MDI inhalation technique (refer under salbutamol MDI)."]],"f25":[{"i":"Tiotropium 2.5µg Metered-dose inhaler (120 actuations)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Tiotropium 9µg inhaler (200 actuations) → now Tiotropium 2.5µg Metered-dose inhaler (120 actuations)"]],"al":""},{"k":"CALCIUM POLYSTYRENE SULFONATE","n":"CALCIUM POLYSTYRENE SULFONATE","g":"Medicine for correcting water, electrolyte and acid–base disturbance.","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.1 Oral","moa":"Cation-exchange resin; exchanges calcium for potassium in the colon, removing K+ in faeces.","f":[["Indications & dose","Hyperkalemia ADULT PO 4 times daily in water (not in fruit squash which has high potassium content); CHILD: PO 0.5 g to 1 g/kg daily in 3-4 divided dose."],["Contraindications","Obstructive bowel disease; hypokalemia."],["Cautions","Children (impaction of resin with excessive dosage or inadequate dilution), pregnancy and breastfeeding."],["Side effects","GI disturbance, constipation; hypokalemia, hypocalcemia, hypomagnesaemia; nausea, vomiting; GI tract ulceration or necrosis which could lead to perforation."],["Counselling","Reconstitutes powdered resin as suspension in water or syrup; for each 1g of powdered resin add 3-4 mL of water or syrup; do not refrigerate."]],"f25":[{"i":"Calcium polystyrene sulfonate powder (15g) sachet","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"POTASSIUM CHLORIDE","n":"POTASSIUM CHLORIDE","g":"Medicine for correcting water, electrolyte and acid–base disturbance.","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.1 Oral","moa":"Replaces potassium, restoring membrane potential in nerve and muscle.","f":[["Indications & dose","Hypokalemia induced by diuretics ADULT PO 1 tablet 2 to 3 times daily depending on the serum potassium level."],["Contraindications","Do not combine with spironolactone and angiotensin-converting-enzyme inhibitors (e.g. enalapril)."],["Cautions","Administer with caution and reduce dosage in elderly patients and in patients with renal impairment due to risk of hyperkalemia."],["Side effects","Hyperkalemia, gastro duodenal ulcerations, diarrhoea, nausea and vomiting."],["Pregnancy category","B"],["Counselling","Take after meals to reduce the risk of gastrointestinal ulcerations. Hypokalemia is defined as a serum potassium concentration below 3.5 mmol/litre."],["Note","1 mg KCl is equal to 0.013 mEq KCl."]],"f25":[{"i":"Potassium chloride 15% injection (10mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Potassium chloride 600mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SODIUM BICARBONATE","n":"SODIUM BICARBONATE","g":"Medicine for correcting water, electrolyte and acid–base disturbance. Parenteral","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.1 Oral","moa":"Buffers hydrogen ions, raising blood pH; alkalinises urine.","f":[["Indications & dose","Metabolic acidosis ADULT PO 1 to 2 tablets 2-3 times daily."],["Contraindications","Alkalosis, hypernatremia, severe pulmonary edema, hypocalcemia."],["Cautions","Avoid prolonged use in urinary conditions, cardiac disease, elderly, patients on sodium-restricted diet, respiratory acidosis, monitoring of plasma pH is advised."],["Side effects","Hypokalemia may be exacerbated, increase blood pressure, pulmonary oedema."],["Renal impairment","Avoid."],["Hepatic impairment","In patients with fluid retention, avoid large amounts of sodium."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, however, is safe."],["Note","Metabolic acidosis due to early renal failure or diabetic ketoacidosis is usually accompanied by hypernatremia; it is best to correct this by infusion of sodium chloride 0.9% injection, which may restore the kidney’s own ability to generate bicarbonate."]],"f25":[{"i":"Dry Sodium bicarbonate concentrate 650gm dialysate powder packet","v":"V","l":"NRH","r":""},{"i":"Sodium bicarbonate 500mg tablet","v":"E","l":"NRH/RRH","r":""},{"i":"Sodium bicarbonate 7.5 % injection (25mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Sodium bicarbonate 99.9% w/w powder (450g) packet","v":"N","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Sodium bicarbonate powder (450g) packet → now Sodium bicarbonate 99.9% w/w powder (450g) packet"]],"al":""},{"k":"DEXTROSE + SODIUM CHLORIDE","n":"DEXTROSE + SODIUM CHLORIDE","g":"Parenteral.","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.2 Parenteral","moa":"Provides free water, calories and sodium for maintenance fluid needs.","f":[["Indications & dose","Preoperative and postoperative fluid replacement By IV infusion, typical rate during surgery, 5 mL/kg/hour."],["Cautions","Monitor for signs of vascular overload; unduly rapid replacement may lead to pulmonary oedema; restrict intake in impaired renal function, cardiac failure, hypertension, peripheral and pulmonary oedema."],["Side effects","Administration of large doses may give rise to sodium accumulation and oedema."]],"f25":[{"i":"Dextrose 5% sodium chloride 0.45% solution for injection (500mL) plastic bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Dextrose 5% sodium chloride 0.9% solution for injection (500mL) plastic bottle","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"SODIUM CHLORIDE","n":"SODIUM CHLORIDE","g":"Electrolytes and minerals.","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.2 Parenteral","moa":"Isotonic crystalloid; expands extracellular fluid volume and replaces sodium and chloride.","f":[["Indications & dose","Hyponatremia: 4 to 8 mmol/L/day; max. 10 to 12 mmol/L/day. Intravenous fluid replacement, Additive, Maintenance fluids: 33 to 40 mEq sodium/L based on a patient receiving 2 to 3 L/day. Management of diabetic ketoacidosis by IV infusion ADULT 500 mL Given over 10-15 minutes, repeat if blood pressure remains below 90 mmHg, when blood pressure is over 90 mmHg should be given at a rate that replaces deficit and provides maintenance."],["Cautions","Monitor for signs of vascular overload, unduly rapid replacement may lead to pulmonary oedema, dilutional hyponatremia, hypertension, peripheral oedema."],["Side effects","Excessive infusion may result in sodium retention; symptoms of hypernatremia include restlessness, flushing of the skin, pyrexia and tachycardia, hyperchloremic acidosis, oedema."],["Note","Sodium chloride 0.9% solution contains 154 mEq/L (154 mmol/L) sodium and 154 mEq/L ((154 mmol/L)) chloride. Calculated osmolarity is 308 mOsmol/L. Dose, rate and duration of administration should be guided by laboratory values, clinical condition , age, weight and concomitant therapy. It should be determined by a physician."]],"f25":[{"i":"Sodium Chloride 0.9% (100mL) Ecoflac plus Polyethylene container with special packaging of rubber seal on top of bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Sodium Chloride 0.9% (1L) Ecoflac plus Polythene container with special packaging of rubber seal on top of bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Sodium Chloride 0.9% (500mL) Ecoflac plus Polyethylene container with special packaging of rubber seal on top of bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Sodium chloride 0.9% solution for injection (100mL) plastic bottle","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is OT"},{"i":"Sodium chloride 0.9% solution for injection (1L) plastic bottle","v":"V","l":"NRH/RRH","r":""},{"i":"Sodium chloride 0.9% solution for injection (500mL) plastic bottle","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SODIUM CHLORIDE (HYPERTONIC SOLUTION)","n":"SODIUM CHLORIDE (HYPERTONIC SOLUTION)","g":"Electrolytes and minerals.","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.2 Parenteral","moa":"Raises serum sodium and osmolality, drawing water out of cells (cerebral oedema, symptomatic hyponatraemia).","f":[["Indications & dose","Hyponatremic seizures by IV central venous, ADULT 1 mL/kg to raise the Na to ≥ 125mmol/L; Cerebral oedema and raised intracranial pressure by IV central venous, 3-5mL/kg over 10-20 minutes."],["Note","3 mL/kg of 3% sodium chloride will increase plasma Na by approximately 2-3 mmol/L. The increase may be greater if a large diuresis occurs; Sodium chloride 3% injection solution contains 30 g/L sodium chloride, 513 mEq/L sodium and chloride (each), and an osmolarity of 1027 mOsmol/L."]],"f25":[{"i":"Sodium chloride 3% (hypertonic) solution for injection (100mL) plastic bottle","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Extended in 2025","Sodium chloride 5% (hypertonic) eye drop (5mL): now supplied down to DH (Supplied to DH where there is Ophthalmologist)"],["Specification changed in 2025","Sodium chloride 3% (hypertonic) eye drop (5mL) → now Sodium chloride 5% (hypertonic) eye drop (5mL)"],["Specification changed in 2025","Sodium chloride 3% (hypertonic) solution for injection (500mL) plastic bottle → now Sodium chloride 3% (hypertonic) solution for injection (100mL) plastic bottle"]],"al":""},{"k":"COMPOUND SODIUM LACTATE SOLUTION","n":"COMPOUND SODIUM LACTATE SOLUTION","g":"Electrolytes and minerals.","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.2 Parenteral","moa":"Balanced crystalloid (Ringer's lactate); lactate is metabolised to bicarbonate. Expands extracellular volume.","f":[["Indications & dose","Pre-and post-operative fluid and electrolyte replacement; Hypovolemic shock."],["Contraindications","Metabolic or respiratory alkalosis; hypocalcemia or hypochlorhydria."],["Cautions","Restrict intake in impaired renal function, cardiac failure, hypertension, peripheral and pulmonary oedema, and toxaemia during pregnancy."],["Side effects","Excessive administration may cause metabolic alkalosis; administration of large doses may give rise to oedema."],["Pregnancy category","C"],["Breast-feeding","Excretion unknown, use with caution."],["Note","The dosage, volume, rate and duration of administration depends on the age, weight, clinical conditions of the patients and concomitant therapy. It should be determined by a physician."]],"f25":[{"i":"Compound sodium lactate solution for injection (500mL) plastic bottle","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"WATER FOR INJECTION","n":"WATER FOR INJECTION","g":"Parenteral (diluent).","sec":"24. SOLUTIONS CORRECTING WATER, ELECTROLYTE AND ACID–BASE DISTURBANCE","sub":"24.3 Miscellaneous","moa":"Sterile diluent for reconstituting and diluting parenteral medicines.","f":[["Indications & dose","Vehicle for dilution and reconstitution of suitable medicinal products for parenteral administration."]],"f25":[{"i":"Water for injection (5mL) plastic ampoule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CALCIUM CARBONATE + VITAMIN D3","n":"CALCIUM CARBONATE + VITAMIN D3","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Supplies calcium; vitamin D3 increases intestinal calcium absorption.","f":[["Indications & dose","Management of combined calcium and vitamin D deficiency including chronic kidney disease and hyperparathyroidism PO, ADULT, 1 tablet twice or thrice daily preferably with food."],["Contraindications","Hypercalcemia, hypercalciuria, hypervitaminosis D, hypophosphatemia, renal calculi, suspected digoxin toxicity."],["Cautions","Achlorhydria, hypo parathyroid, history of nephrolithiasis, sarcoidosis."],["Side effects","Constipation, flatulence, nausea, abdominal pain and diarrhoea, hypercalcemia."],["Renal impairment","Use with caution."],["Pregnancy category","Available data suggests safe use during pregnancy."],["Breast-feeding","Available data suggests safe use during lactation."],["Counselling","Take the medicine after meals."]],"f25":[{"i":"Calcium carbonate 1250mg (elemental calcium 500mg) + Vitamin D3 600 IU tablet","v":"N","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Calcium carbonate 1250mg (elemental calcium 500mg) + Vitamin D3 250 IU tablet → now Calcium carbonate 1250mg (elemental calcium 500mg) + Vitamin D3 600 IU tablet"]],"al":""},{"k":"CALCIUM CARBONATE","n":"CALCIUM CARBONATE","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Supplies calcium; also binds dietary phosphate and neutralises acid.","f":[["Indications & dose","Calcium deficiency, Prophylaxis ADULT: (19-70 years): 1000 mg elemental calcium per day in divided doses; Age >70 years and Women (51-70 years): 1200 mg elemental calcium per day in divided doses. CHILD (0-6 months): 200 mg elemental calcium/day; 7-12 months: 260 mg elemental calcium/day; 1-3 years 700 mg elemental calcium/day; 4-8 years: 1000 mg elemental calcium/day; 9-18 years: 1300 mg elemental calcium/day. Postmenopausal osteoporosis and prophylaxis for bone fracture: 1200 mg elemental calcium per day in divided doses. Renal failure-associated hyperphosphatemia Stage 3-5 CKD Not to exceed 2000 mg/day; Stage 5 CKD not to exceed 1500 mg/day. Antenatal care WHO guideline suggests in populations where calcium intake is low, elemental calcium of 1.5-2 g/day is recommended to prevent preeclampsia in pregnant women."],["Contraindications","Hypercalcemia, hypercalciuria, renal calculi, hypophosphatemia, suspected digoxin toxicity."],["Cautions","Achlorhydria, inflammatory bowel disease, mineral stores deficiencies, vitamin D deficiency. Take in doses of less than 500 mg (elemental calcium) at a time for greatest absorption."],["Side effects","Constipation, flatulence, swollen abdomen, myocardial infarction, urolithiasis, prostate cancer, milk alkali syndrome."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk."],["Counselling","Take with meals. Advise patients to limit intake of oxalate-rich foods (soy; green, leafy vegetables; animal protein) to avoid reduced absorption through Ca-oxalate formation."]],"f25":[{"i":"Calcium carbonate 1250mg (elemental calcium 500mg) tablet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"CALCITRIOL (1,25-DIHYDROXYCHOLECALCIFEROL)","n":"CALCITRIOL (1,25-DIHYDROXYCHOLECALCIFEROL)","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Active vitamin D; acts on vitamin D receptors to increase gut calcium absorption and suppress PTH (no renal activation needed).","f":[["Indications & dose","chronic kidney disease on dialysis and osteodystrophy ADULT Initially 0.25 mcg daily, adjusted in steps of 0.25 mcg every 2-4 weeks if required; Usual dose 0.5-1 mcg daily. Renal osteodystrophy (hypocalcaemia) ADULT Initially 0.25 mcg once daily on alternate days, adjusted in steps of 0.25 mcg every 2-4 weeks if required; Usual dose 0.5-1 mcg daily. Established postmenopausal osteoporosis ADULT 0.25 mcg twice daily, plasma-calcium concentration and creatinine to be monitored. Hypocalcemia in hypoparathyroidism, postsurgical or idiopathic CHILD (1 to 5 years) Initial 0.25 mcg/day, dose may be increased at 2 to 4 weeks, Usual dose range 0.25 to 0.75 mcg once daily. CHILD (6 years and older) Initial 0.25 mcg/day; Dose may be increased at 2 - 4-week intervals; Usual dose range, 0.5 to 2 mcg once daily. Secondary hyperparathyroidism CHILD (predialysis, 3 years and older) Initial 0.25 mcg daily, may be increased to 0.5 mcg/day. CHILD (predialysis, < 3 years) 0.01 to 0.015 mcg/kg/day."],["Contraindications","Hypercalcemia, Vitamin D toxicity and Hypersensitivity to calcitriol."],["Cautions","Monitor plasma calcium, phosphate, and creatinine during dosage titration. Monitor plasma-calcium concentration in patients receiving high doses."],["Side effects","Urinary tract infection, abdominal pain, apathy, dehydration, drowsiness. Muscle weakness."],["Renal impairment","No dose adjustment required."],["Pregnancy category","C"],["Breast-feeding","Enters breast milk, not recommended."]],"f25":[{"i":"Calcitriol 0.25µg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"MULTIVITAMIN","n":"MULTIVITAMIN","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Replaces multiple vitamins as cofactors for metabolic enzymes.","f":[["Indications & dose","Treatment of Wernicke’s encephalopathy and Korsakoff psychosis in alcoholic and malnourished patients by slow IV injection or infusion 10mL every 4-8 hours for up to 2 days."],["Contraindications","Known hypersensitivity to parenteral thiamine, vitamin B complex, or multivitamin injection."],["Cautions","Anaphylaxis may occur; facilities for treatment must be available during and shortly after administration."],["Pregnancy category","A"],["Breast-feeding","Safe."]],"f25":[],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"PYRIDOXINE (Vitamin B ) 6","n":"PYRIDOXINE (Vitamin B6)","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Converted to pyridoxal phosphate, a cofactor in amino acid metabolism; prevents isoniazid neuropathy.","f":[["Indications & dose","Deficiency states: By oral administration, 20-50 mg 1-3 times a day; Isoniazid induced neuropathy (prophylaxis): 10-20 mg daily; Isoniazid induced neuropathy (treatment): 50 mg 3 times daily."],["Cautions","Long term large doses may induce neuropathy."],["Side effects","sensory neuropathies, unstable gait, paresthesias, decreased sensation, decreased folic acid. Pregnancy A"],["Breast-feeding","Safe."]],"f25":[{"i":"Pyridoxine (Vitamin B6) 25mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"RETINOL (Vitamin A)","n":"RETINOL (Vitamin A)","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Needed for rhodopsin (vision), epithelial differentiation and immunity.","f":[["Indications & dose","Prophylaxis of Vitamin A deficiency: By oral administration, CHILD over 1 year, 1 capsule every 6 months; CHILD under 1 year, 3 drops every 6 months; night blindness, established vitamin A deficiency: CHILD over 1 year and ADULT, 1 capsule on day 1, 2 and 14; CHILD under 1 year, 3 drops day 1,2 and 14; all ages: repeat only after 6 months."],["Contraindications","Hypervitaminosis A, malabsorption syndrome."],["Cautions","Toxicity with repeated doses."],["Side effects","Rough skin, dry hair, enlarged liver and raised ESR, raised serum calcium and serum alkaline phosphatase concentrations. may occur with over dosage."],["Renal impairment","use with caution."],["Pregnancy category","Excessive doses may be teratogenic. High levels of vitamin A may cause birth defects, women who are (or may become) pregnant are advised not to take vitamin A supplements (including tablets and fish liver oil drops), except on the advice of a doctor or an antenatal clinic."],["Breast-feeding","Excreted in breast milk, safe at RDA levels."]],"f25":[{"i":"Retinol (Vitamin A) 200,000 units capsule","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SEVELAMER","n":"SEVELAMER","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Non-absorbed polymer that binds dietary phosphate in the gut (CKD hyperphosphataemia).","f":[["Indications & dose","Hyperphosphatemia, CKD not on dialysis and on dialysis (based on serum phosphorus level) ADULT, 5.5 mg/dL - < 7.5 mg/dL: 800 mg 3 times daily; 7.5 mg/dL - < 9 mg/dL: 1,200 to 1,600 mg 3 times daily; ≥ 9 mg/dL: 1,600 mg 3 times daily. Maintenance dose is based on serum phosphorus level (3.5 to 5.5 mg/dL): >5.5 mg/dL: Increase by 400 to 800 mg at 2-week intervals; 3.5 to 5.5 mg/dL: Maintain current dose; < 3.5 mg/dL: Decrease by 400 to 800 mg. Hyperphosphatemia, CKD not on dialysis CHILD ≥ 6 year: BSA ≥ 0.75 - < 1.2 m : 800 mg 3 times daily with meals (titrate as needed by 400 mg per dose at 2 weeks intervals); BSA ≥ 1.2 m : 1,600 mg 3 times daily with meals (titrate as needed by 800 mg per dose at 2 weeks intervals). CKD on dialysis CHILD > 6 to 17 years: 800 - 1600 mg 3 times after meals and adjust dose according to serum phosphate level. Conversion dose • Calcium acetate 667 mg: initiate 800 mg. • Calcium acetate 1,334 mg: initiate 1200 mg - 1,600 mg • Calcium acetate 2,001 mg: initiate 2000 mg - 2,400 mg"],["Contraindications","Hypophosphatemia and bowel obstruction."],["Cautions","Gastro-intestinal disease and may occur in reduction in folic acid and vitamins (D, E, K), monitor recommended, GI surgery."],["Side effects","Vomiting, nausea, diarrhoea, constipation, dyspepsia, skin rash, metabolic acidosis, peritonitis."],["Renal impairment","No dose adjustment necessary."],["Hepatic impairment","No dose adjustment, use with caution."],["Pregnancy category","C"],["Breast-feeding","Use only if potential benefits outweigh the potential risk."],["Counselling","Take with food. Advice pregnant women to take folic acid and vitamins (D, E, K), since reduction of this supplement may occur. Tablets should not be crushed, broken or chewed."]],"f25":[{"i":"Sevelamer 800mg tablet","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Medical Specialist"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"THIAMINE (VITAMIN B1)","n":"THIAMINE (VITAMIN B1)","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Converted to thiamine pyrophosphate, a cofactor for pyruvate dehydrogenase and transketolase (prevents Wernicke's).","f":[["Indications & dose","Beriberi by IM injection or slow IV infusion, 10-20 mg 3 times daily for up to 2 weeks, then PO maintenance 10-25 mg 3 times daily for 1 month. Prophylactic in alcoholic patients: by oral administration,10-25 mg daily; Wernicke Encephalopathy: by IV injection, 100 mg IV followed by 50-100 mg IM/IV until consuming a regular balanced diet."],["Cautions","Anaphylactic shock may occur following repeated parenteral doses."],["Side effects","Injection site reaction, hypersensitivity reaction."],["Renal impairment","Use with caution (parenteral formulation)."],["Pregnancy category","A, C (exceeding RDA)."],["Breast-feeding","Safe."]],"f25":[{"i":"Thiamine (Vitamin B1) 100mg/mL injection (1mL) ampoule","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Thiamine (Vitamin B1) 75mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"VITAMIN B COMPLEX","n":"VITAMIN B COMPLEX","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Replaces B vitamins that serve as enzyme cofactors in energy metabolism.","f":[["Indications & dose","Treatment of deficiency PO, ADULT and CHILD (5-14 years) 1 tablet 3 times daily; CHILD (2-4 years) 1 tablet once daily; Prophylaxis of deficiency ADULT 1–2 tablets once daily; By IM injection, ADULT 2 mL daily."],["Contraindications","Known hypersensitivity to parenteral thiamine, vitamin B complex or multivitamin injection."],["Cautions","Injection may occasionally cause anaphylaxis; thiamine deficiency should be treated with thiamine; vitamin B complex does not include pyridoxine, which should be prescribed specifically if indicated."],["Side effects","Occasional rashes and allergic reactions."],["Pregnancy category","A (not exceeding RDA)."],["Breast-feeding","Safe."],["Counselling","Take with or after food."]],"f25":[{"i":"Vitamin B complex tablet: containing Vitamin B1 (Thiamine) 1.2 mg ; Vitamin B2 (Riboflavin) 1.4 mg ; Vitamin B3 (Nicotinamide) 16 mg; Vitamin B5 (Calcium D Pantothenate) 6 mg; Vitamin B6 (Pyridoxine HCL) 1.4 mg; Vitamin B12 (Cyanocobalamin) 2.5 mg; Folic acid 200 mcg; Biotin 50 mcg","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Vitamin B complex tablet: containing Vitamin B1 (Thiamine nitrate); Vitamin B2 (Riboflavin); Vitamin B3 (Nicotinamide); Vitamin B5 (Calcium D Pantothenate); Vitamin B6 (Pyridoxine HCL); Vitamin B12 (Cyanocobalamin) → now Vitamin B complex tablet: containing Vitamin B1 (Thiamine) 1.2 mg ; Vitamin B2 (Riboflavin) 1.4 mg ; Vitamin B3 (Nicotinamide) 16 mg; Vitamin B5 (Calcium D Pantothenate) 6 mg; Vitamin B6 (Pyridoxine HCL) 1.4 mg; Vitamin B12 (Cyanocobalamin) 2.5 mg; Folic acid 200 mcg; Biotin 50 mcg"]],"al":""},{"k":"VITAMIN-C","n":"VITAMIN-C","g":"Vitamins and multivitamins.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Ascorbic acid; antioxidant and cofactor for collagen hydroxylation; enhances iron absorption.","f":[["Indications & dose","Prevention of scurvy PO 25-75mg daily; Treatment of scurvy at least 250mg daily in divided doses."],["Cautions","G6PD deficiency, may cause iron overload."],["Side effects","Flushing, flank pain, faintness, headache, diarrhoea, dyspepsia, nausea, vomiting, hyperoxaluria (large doses)."],["Renal impairment","Patients prone to recurrent calculi should not take excessive doses for extended periods of time. Pregnancy A (not exceeding RDA)."],["Breast-feeding","Safe."],["Counselling","To be taken after the meals and drink plenty of fluids."]],"f25":[{"i":"Vitamin C 250mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"VITAMIN D3 (CHOLECALCIFEROL)","n":"VITAMIN D3 (CHOLECALCIFEROL)","g":"Vitamins and minerals.","sec":"25. VITAMINS & MINERALS","sub":"","moa":"Hydroxylated in liver and kidney to calcitriol, which increases calcium and phosphate absorption.","f":[["Indications & dose","Hypoparathyroidism 50,000-200,000 IU PO once daily with calcium supplements; Prophylaxis and treatment of osteoporosis (>50 years) PO 800-1000 IU once daily with calcium supplements; Vitamin D resistant rickets PO 12,000-500,000 IU once daily; Familial hypophosphatemia PO 10,000-60,000 IU once daily with phosphate supplements."],["Contraindications","Hypercalcemia, Hypervitaminosis D, hypercalciuria, severe renal impairment, nephrolithiasis."],["Cautions","Concurrent use of cardiac glycosides."],["Side effects","Constipation, loss of appetite, nausea."],["Breast-feeding","Distributed into breast milk, Use with caution."],["Note","Obtain serum calcium twice weekly during titration, discontinue if the patient becomes hypercalcemic."],["Counselling","Instruct patients to maintain adequate intake of calcium and avoid additional vitamin D supplements."]],"f25":[],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"AMINO ACID SOLUTION","n":"AMINO ACID SOLUTION","g":"Intravenous nutritional supplement.","sec":"26. PARENTERAL NUTRITION","sub":"","moa":"Supplies essential and non-essential amino acids for protein synthesis in parenteral nutrition.","f":[["Indications & dose","Parenteral nutrition when GI absorption is impaired, Amino acid supplement for hypercatabolic or hypermetabolic states by IV infusion, ADULT 200-800 mL/day at 40-50 drops/minute; CHILD 20-40 mL/Kg/day.Solid organ transplant: Perioperative 1.5-2 g/kg/day; Renal failure Acute (severely malnourished or hypercatabolic) 1.5-1.8 g/kg/day; Chronic on dialysis 1.2-1.3 g/kg/day; Chronic not on dialysis 0.6-0.8 g/kg/day; Hepatic failure With encephalopathy 0.6-1 g/kg/day; Without encephalopathy: 1-1.5 g/kg/day."],["Contraindications","Inborn errors of amino acid metabolism, pulmonary edema or acidosis."],["Cautions","Hyperglycemia, hepatobiliary disorder, renal impairment, fluid overload may occur, as bacterial overgrowth may readily occur in amino acid solutions; adequate simultaneous dextrose infusion must be given to allow maximal utilisation of amino acids by the body."],["Side effects","Electrolyte imbalance, hyperammonemia, refeeding syndrome, thrombosis, infusion reaction, pulmonary embolism."],["Pregnancy category","C"],["Breast-feeding","Excretion in milk unknown, use with caution."]],"f25":[{"i":"Amino acid 10% injection (200mL) bottle","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"BUDESONIDE","n":"BUDESONIDE","g":"Decongestant (corticosteroid).","sec":"27. EAR, NOSE AND THROAT MEDICINES","sub":"27.1 Decongestants","moa":"Corticosteroid with high first-pass metabolism; local anti-inflammatory action (nasal/inhaled).","f":[["Indications & dose","Prophylaxis and treatment of rhinitis and management of nasal polyps by nasal administration, ADULT and CHILD (over 12 years) spray into each nostril one to two times daily; Treatment can be continued for up to 3 months."],["Contraindications","Status asthmaticus, acute bronchospasm, active pulmonary TB and untreated upper respiratory infections."],["Side effects","Systemic absorption following nasal use may lead to adrenal suppression."]],"f25":[],"lv":["NRH","RRH"],"ch":[["Deleted in 2025","Budesonide 50µg nasal spray (200 sprays) removed (was available RRH). Reason: Substituted by Fluticasone furoate nasal spray 27.5 mcg/actuation (120 actuation)"]],"al":""},{"k":"COMPOUND BENZOIN","n":"COMPOUND BENZOIN","g":"Antitussive and decongestant.","sec":"27. EAR, NOSE AND THROAT MEDICINES","sub":"27.1 Decongestants","moa":"Aromatic resin inhalation; vapour soothes airway mucosa and loosens secretions.","f":[["Indications & dose","Nasal obstruction; viral respiratory conditions; adjunct in bacterial respiratory conditions 5 mL in 500 mL hot water for inhalation."],["Cautions","The inhalation should not be made with boiling water, to avoid the risk of scalding; children and elderly should be supervised."],["Counselling","This inhalation will help clear your breathing; in children, care must be taken to prevent burning."]],"f25":[{"i":"Compound benzoin inhalation (450mL) bottle","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"OXYMETAZOLINE","n":"OXYMETAZOLINE","g":"Antitussive and decongestant.","sec":"27. EAR, NOSE AND THROAT MEDICINES","sub":"27.1 Decongestants","moa":"Alpha-adrenergic agonist; constricts nasal mucosal vessels (decongestant). Rebound congestion with prolonged use.","f":[["Indications & dose","Relief of nasal congestion ADULT and CHILD (above 6 years) 1-2 drops in each nostril twice daily for up to 3 days. CHILD (< 6 years) Not recommended."],["Cautions","Hypertension, heart failure, coronary artery disease, diabetes, hyperthyroidism, prostatic hyperplasia, prolonged use may cause rebound congestion, close angle glaucoma."],["Side effects","local irritation, dryness of mouth and throat, rebound congestion, insomnia."],["Pregnancy category","C"]],"f25":[{"i":"Oxymetazoline 0.05% nasal drop (5mL)","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Oxymetazoline 0.05% nasal drop (10mL) → now Oxymetazoline 0.05% nasal drop (5mL)"]],"al":""},{"k":"BETAHISTINE DIHYDROCHLORIDE","n":"BETAHISTINE DIHYDROCHLORIDE","g":"Medicines for Meniere’s disease.","sec":"27. EAR, NOSE AND THROAT MEDICINES","sub":"27.2 Medicines for Meniere’s disease","moa":"Weak H1 agonist and potent H3 antagonist; improves inner ear microcirculation (Meniere's disease).","f":[["Indications & dose","Vertigo, tinnitus and hearing loss associated with Meniere's disease PO, initially 16mg 3 times daily, preferably with food; Maintenance 32-48mg daily. CHILD Not recommended."],["Contraindications","Pheochromocytoma."],["Cautions","Asthma, history of peptic ulcer, pregnancy and breastfeeding."],["Side effects","GI disturbances, headache, rashes, pruritus."],["Counselling","Take with or after food."]],"f25":[{"i":"Betahistine dihydrochloride 16mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"CINNARIZINE","n":"CINNARIZINE","g":"Medicines for Meniere’s disease.","sec":"27. EAR, NOSE AND THROAT MEDICINES","sub":"27.2 Medicines for Meniere’s disease","moa":"H1 antagonist and calcium channel blocker; reduces vestibular stimulation (vertigo, motion sickness).","f":[["Indications & dose","Relief of symptoms of vestibular disorders, such as vertigo, tinnitus, nausea, and vomiting in Ménière’s disease ADULT: 30 mg PO 3 times a day; CHILD 12–17 years: 30 mg PO 3 times a day CHILD: 5–11 years: 15 mg PO 3 times a day. Motion sickness ADULT: Initially 30 mg, dose to be taken 2 hours before travel, then 15 mg every 8 hours if required, dose to be taken during journey; CHILD 12–17 years: Initially 30 mg, dose to be taken 2 hours before travel, then 15 mg every 8 hours if required, dose to be taken during journey; CHILD 5–11 years: Initially 15 mg, dose to be taken 2 hours before travel, then 7.5 mg every 8 hours if required, dose to be taken during journey."],["Contraindications","Acute porphyria."],["Cautions","Epilepsy, glaucoma (in children), Parkinson’s disease (in adults), prostatic hypertrophy (in adults), pyloroduodenal obstruction, susceptibility to angle closure glaucoma (in adults), urinary retention."],["Side effects","Drowsiness, gastrointestinal discomfort, nausea, weight increased, hyperhidrosis, vomiting."],["Pregnancy category","Advise pregnant patients to avoid using cinnarizine."],["Breast-feeding","Avoid."],["Counselling","Advised patients that drowsiness may affect performance of skilled tasks, sedating effects enhanced by alcohol."]],"f25":[{"i":"Cinnarizine 15mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"HYDROXYCHLOROQUINE","n":"HYDROXYCHLOROQUINE","g":"Disease modifying anti-rheumatoid medicines (DMARMs).","sec":"28. MEDICINES FOR DISEASES OF JOINTS","sub":"28.2 Disease Modifying Anti-Rheumatic Medicines (DMARMs)","moa":"Raises lysosomal pH in immune cells and inhibits toll-like receptor signalling, reducing antigen presentation.","f":[["Indications & dose","Active rheumatoid arthritis, systemic and discoid lupus erythematosus and dermatological conditions caused or aggravated by sunlight PO, ADULT 200-400 mg daily, daily maximum dose to be based on ideal body-weight; MAX. 6.5 mg/kg per day; CHILD 5-6.5 mg/kg once daily (MAX. per dose 400 mg), dose given based on ideal body-weight."],["Contraindications","Long-term therapy in children."],["Cautions","Acute porphyrias, elderly, G6PD deficiency, alcoholics, concurrent use of hepatotoxic medicines should be avoided; myasthenia gravis; heart failure, psoriasis, neurological disorders (especially in those with a history of epilepsy), Severe GI disorders."],["Side effects","GI disturbances, headache, pruritus, rashes, skin reactions, corneal changes or deposits, aplastic anaemia, retinal damage with long-term use."],["Renal impairment","Use with caution."],["Hepatic impairment","Caution in moderate to severe impairment."],["Pregnancy category","C"],["Breast-feeding","Excreted in milk, avoid."],["Note","To avoid excessive dosage in obese patients, the dose of hydroxychloroquine should be calculated based on ideal body weight."],["Counselling","Report if there are any visual disturbances and get the vision checked; Take with food or milk; Do not take antacids for at least 4 hours before or after hydroxychloroquine to reduce possible interference with hydroxychloroquine absorption."]],"f25":[{"i":"Hydroxychloroquine 200mg tablet","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Medical Specialist"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"LEFLUNOMIDE","n":"LEFLUNOMIDE","g":"Disease-modifying agents used in rheumatoid disorders (DMARDs).","sec":"28. MEDICINES FOR DISEASES OF JOINTS","sub":"28.2 Disease Modifying Anti-Rheumatic Medicines (DMARMs)","moa":"Inhibits dihydroorotate dehydrogenase, blocking pyrimidine synthesis in activated lymphocytes.","f":[["Indications & dose","Rheumatoid arthritis PO, ADULT 100 mg daily for 3 days, then 10-20 mg daily, or 10-20 mg daily without loading dose (MAX. 20mg per day). Psoriatic arthritis PO, ADULT 100 mg daily for 3 days, then 20 mg daily. Juvenile idiopathic arthritis, body weight (< 20 kg) 10 mg alternative days; (20 - 40 kg) 10 mg once daily; (> 40 kg) 20 mg once daily."],["Contraindications","Hypersensitivity to leflunomide, pregnancy, hepatic impairment."],["Cautions","Pre-existing intestinal lung disease, severe or uncontrolled infections, severe immunodeficiency, bone marrow dysplasia, concomitant use with live vaccines, malignancy, and lymphoproliferative disorders."],["Side effects","Nausea and vomiting, diarrhoea and ulcer of mouth, alopecia, rash, Stevens-Johnson syndrome, jaundice, dizziness, hypertension, headache, joint pain, peripheral neuropathy, myelosuppression, hepatotoxicity, and upper respiratory tract infection."],["Renal impairment","Use with caution."],["Hepatic impairment","Baseline ALT 2-3 times ULN may reduce dose 10 mg once daily, then monitor ALT weekly. If persistent ALT 2-3 times ULN, stop leflunomide and initiate wash out* procedure."],["Pregnancy category","X"],["Breast-feeding","Excretion in breast milk unknown/Not recommended."],["Note","The active metabolite persists for a long period; to aid medicine elimination in case of serious adverse effect, or before starting another disease-modifying antirheumatic, or before conception, stop treatment and give either cholestyramine or charcoal, activated. Procedure may be repeated as necessary."],["Counselling","Advice female patients to avoid pregnancy during therapy and before completion of the medicine elimination process and male patients who wish to father a child should also undergo the drug elimination procedure. Advise patients to avoid live vaccines during therapy. Observe yellow eyes, skin colour changes and tingling sensation. Do not donate blood while on therapy."]],"f25":[{"i":"Leflunomide 10mg tablet","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[],"al":""},{"k":"SULFAZALAZINE","n":"SULFAZALAZINE","g":"Disease-modifying agents used in rheumatoid disorders (DMARDs).","sec":"28. MEDICINES FOR DISEASES OF JOINTS","sub":"28.2 Disease Modifying Anti-Rheumatic Medicines (DMARMs)","moa":"Sulfasalazine; split in the colon into 5-ASA (local anti-inflammatory) and sulfapyridine (systemic immunomodulation).","f":[["Indications & dose","Rheumatoid arthritis PO, ADULT (delayed release tablet) 0.5-1 g/day 2 times per day; Increase weekly to maintenance dose of 2 g/day; if inadequate response, increase to 3 g/day after administering for 12 weeks. Juvenile idiopathic arthritis CHILD (6 years or older) gradually titrates at weekly intervals up to 30-50 mg/kg/day 2 times per day after meals; not to exceed 2 g/day. Ulcerative colitis ADULT 3-4 g/day PO 3 times per day after meals. Maintenance: 0.5 g QID when endoscopic exam confirms improvement. If GI intolerance, reduce dose by 50% and gradually increase to desired dose over several days. If GI intolerance persists, stop therapy for 5-7 days and reintroduce at lower daily dose. CHILD (6 years or older) Initially 40-60 mg/kg/day Q4-8 hour after meals; Maintenance 30 mg/kg/day Q8H after meals. Crohn’s Disease ADULT 3-6 g/day in divided doses for up to 16 weeks."],["Contraindications","Hypersensitivity to sulfonamides, or to salicylates, intestinal or urinary tract obstruction and porphyria."],["Cautions","Administer tablets with caution to patients with severe allergy or bronchial asthma. Patients with glucose-6 phosphate dehydrogenase deficiency should be observed closely for signs of hemolytic anaemia. More than 4 g/day can increase risk of haematological and hepatic toxicity."],["Side effects","Anorexia, alter taste, insomnia, nausea, vomiting, gastric distress, apparently reversible oligospermia."],["Renal impairment","Use not recommended, weigh risk vs benefit."],["Hepatic impairment","Use not recommended, weigh risk vs benefit."],["Pregnancy category","B"],["Breast-feeding","Excreted in milk, use with caution."],["Counselling","Adequate fluid intake must be maintained to prevent crystalluria and stone formation. Take after meals. Do not crush, chew or break the tablet."]],"f25":[{"i":"Sulfasalazine 500mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":"sulfasalazine"},{"k":"HYALURONIDASE","n":"HYALURONIDASE","g":"Dispersion agent.","sec":"30. MEDICINES FOR SOFT TISSUE INFLAMMATION","sub":"","moa":"Enzyme that breaks down hyaluronic acid in connective tissue, increasing tissue permeability for injected fluids.","f":[["Indications & dose","Enhanced permeation of local anaesthetic in surgical aid in cataract extraction, intraocular implantation, corneal transplant, glaucoma filtration, retinal detachment surgery; osteoarthritis by SC or IM injection, 1500 units dissolved in solution to be injected (ensure compatibility); by local anaesthesia 1500 units mixed with local anaesthetic solution (ophthalmology, 15 units/mL); Hypodermoclysis 1500 units dissolved in 1 mL water for injection or 0.9% sodium chloride injection, administer before start of 500-1000 mL infusion fluid; Extravasation or hematoma 1500 units dissolved in 1 mL water for injections or 0.9% sodium chloride injection, infiltrate into affected area (as soon as possible after extravasation)."],["Contraindications","Do not apply directly to cornea; avoid infection or malignancy sites; not for anaesthesia in unexplained premature labour; not to be used to reduce swelling of bites or stings; not for IV administration."],["Cautions","Infants or elderly (control speed and total volume and avoid overhydration especially in renal impairment)."],["Side effects","Angioedema, urticarial, local injection site reactions."],["Pregnancy category","There are no adequate and well-controlled studies in pregnant women."],["Breast-feeding","Excretion in milk unknown, use caution."]],"f25":[{"i":"Hyaluronidase 1500IU/mL injection (1mL) vial","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is Ophthalmologist"}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"DEXTROSE","n":"DEXTROSE","g":"Medicines for use in haemodialysis.","sec":"31. MEDICINES FOR USE IN HAEMODIALYSIS","sub":"","moa":"Provides glucose for energy; corrects hypoglycaemia (concentrated) or supplies free water (5%).","f":[["Indications & dose","5% injection Rehydration in diarrhoea, trauma and post-operatively; 10% injection Postoperative rehydration when additional energy is required; 25% injection Correction of hypoglycemia by IV infusion. 50% injection (haemodialysis): Treatment of haemodialysis-associated hypotension, hypoglycaemia and muscle cramps 1 mL/kg IV infusion."],["Cautions","5% and 10% injection Monitor for signs of vascular overload and blood glucose; unduly rapid replacement may lead to pulmonary oedema; sodium depletion may occur due to dilution; 10% injection Thrombophlebitis may occur at the infusion site, use caution in diabetes."],["Pregnancy category","A"],["Note","The dosage, volume, rate and duration of administration depends on the age, weight, clinical conditions of the patients and concomitant therapy and should be determined by a physician."]],"f25":[{"i":"Dextrose 5% (500mL) Ecoflac plus Polythene container with special packaging of rubber seal on top of bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Dextrose 10% solution for injection (100mL) plastic bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Dextrose 10% solution for injection (500mL) plastic bottle","v":"V","l":"NRH/RRH/DH","r":""},{"i":"Dextrose 25% solution for injection (100mL) plastic bottle","v":"V","l":"NRH/RRH/DH/PHC","r":""},{"i":"Dextrose 5% (250mL) Ecoflac plus Polyethylene container with special packaging of rubber seal on top of bottle","v":"E","l":"NRH/RRH","r":""},{"i":"Dextrose 5% solution for injection (500mL) plastic bottle","v":"V","l":"NRH/RRH/DH/PHC","r":""},{"i":"Dextrose 50% injection (100mL) plastic bottle","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ABACAVIR + LAMIVUDINE + DOLUTEGRAVIR (paediatric)","n":"ABACAVIR + LAMIVUDINE + DOLUTEGRAVIR (paediatric)","g":"Antiretroviral fixed-dose combination (paediatric)","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"Two NRTIs (abacavir, lamivudine) that terminate viral DNA chains plus an integrase strand-transfer inhibitor (dolutegravir).","f":[["Indications & dose","HIV in children (dispersible 60/30/5 mg tablets, once daily by weight): 6-9.9 kg 3 tablets; 10-13.9 kg 4 tablets; 14-19.9 kg 5 tablets; 20-24.9 kg 6 tablets. Disperse in water."],["Contraindications","HLA-B*5701 positive or prior abacavir hypersensitivity; moderate to severe hepatic impairment."],["Side effects","Abacavir hypersensitivity reaction (fever, rash, GI and respiratory symptoms; stop permanently), headache, insomnia, nausea."],["Note","Added to NEML 2025 (till DH). Follow the national paediatric ART guideline for weight bands."]],"f25":[{"i":"Abacavir 60mg + Lamivudine 30mg + Dolutegravir 5mg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"APIXABAN","n":"APIXABAN","g":"Anticoagulant (direct oral factor Xa inhibitor)","sec":"10. MEDICINES AFFECTING THE BLOOD","sub":"10.2 Medicines affecting coagulation","moa":"Direct, reversible inhibitor of free and clot-bound factor Xa; reduces thrombin generation.","f":[["Indications & dose","Stroke prevention in non-valvular AF ADULT: 5 mg PO Q12H; reduce to 2.5 mg Q12H if at least 2 of: age 80 years or more, weight 60 kg or less, serum creatinine 133 micromol/L or more. VTE prophylaxis after hip replacement ADULT: 2.5 mg PO Q12H for 32-38 days; after knee replacement 2.5 mg Q12H for 10-14 days (start 12-24 hours after surgery). DVT/PE treatment ADULT: 10 mg PO Q12H for 7 days, then 5 mg Q12H; to prevent recurrence after 6 months, 2.5 mg Q12H."],["Contraindications","Active clinically significant bleeding; lesions with high bleeding risk; hepatic disease with coagulopathy; prosthetic heart valves; concurrent other anticoagulants (except when switching)."],["Side effects","Bleeding (gum, GI, haematuria, epistaxis), anaemia, bruising, nausea."],["Note","Only the 2.5 mg tablet is on NEML 2025 (changed from 5 mg). Avoid if CrCl <15 mL/min."]],"f25":[{"i":"Apixaban 2.5mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Specification changed in 2025","Apixaban 5 mg → now Apixaban 2.5 mg"]],"al":""},{"k":"AZITHROMYCIN","n":"AZITHROMYCIN","g":"Antibacterial (macrolide)","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.2.2 Watch group antibiotics","moa":"Macrolide; binds the 23S rRNA of the 50S ribosomal subunit, blocking translocation. Long tissue half-life.","f":[["Indications & dose","Severe scrub typhus or leptospirosis in pregnant women and children (NEML 2025 indication) ADULT: 500 mg IV infusion Q24H, switch to oral when able, total 5-7 days; CHILD: 10 mg/kg IV Q24H (max 500 mg). Infuse over at least 60 minutes (1 mg/mL) or 3 hours (2 mg/mL); never as IV bolus."],["Contraindications","Hypersensitivity to macrolides; history of cholestatic jaundice or hepatic dysfunction with prior azithromycin."],["Side effects","Diarrhoea, nausea, abdominal pain, injection-site pain and phlebitis, raised liver enzymes, QT prolongation."],["Note","Caution with QT-prolonging drugs, hypokalaemia or hypomagnesaemia."]],"f25":[{"i":"Azithromycin 500 mg injection IV","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Added in 2025","Azithromycin 500 mg injection IV added (Till DH). Reason: Severe leptospirosis/scrub typhus for a special population (pregnant women and children)."]],"al":""},{"k":"BENZOIC ACID","n":"BENZOIC ACID","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Keratolytic and antifungal (Whitfield's ointment with salicylic acid).","f":[["Indications & dose","Base for compounding Whitfield's ointment for tinea."]],"f25":[{"i":"Benzoic acid powder (450g) packet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"BETAMETHASONE DIPROPIONATE","n":"BETAMETHASONE DIPROPIONATE","g":"Topical corticosteroid (potent)","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.4 Anti-inflammatory and antipruritic medicines","moa":"Potent topical corticosteroid; glucocorticoid receptor-mediated suppression of inflammatory gene expression with local vasoconstriction.","f":[["Indications & dose","Severe inflammatory dermatoses (eczema, psoriasis plaques, lichen planus) ADULT and CHILD over 1 year: apply thinly 1-2 times daily; use for the shortest period, ideally up to 2-4 weeks, avoiding face and flexures."],["Contraindications","Untreated bacterial, fungal or viral skin infection; rosacea; acne; perioral dermatitis; widespread plaque psoriasis."],["Side effects","Skin atrophy, striae, telangiectasia, folliculitis, contact dermatitis; adrenal suppression with large areas or occlusion."],["Note","Replaces betamethasone valerate on the 2025 list."]],"f25":[{"i":"Betamethasone dipropionate 0.05% cream (15g) tube","v":"N","l":"NRH","r":"Supplied to RRH where there is Dermatologist"}],"lv":["NRH"],"ch":[],"al":""},{"k":"HAEMODIALYSIS CONCENTRATES","n":"HAEMODIALYSIS CONCENTRATES","g":"Dialysis solutions","sec":"31. MEDICINES FOR USE IN HAEMODIALYSIS","sub":"","moa":"Acid (Part A) and bicarbonate concentrates are mixed with treated water to make dialysate; diffusion across the membrane corrects electrolytes and acid-base.","f":[["Indications & dose","Haemodialysis / online HDF. Part A with K+ 3 is chosen according to pre-dialysis potassium (NEML 2025 addition)."]],"f25":[{"i":"Bi-carbonate dialysis solution (10L) with powder packet","v":"V","l":"NRH/RRH","r":""},{"i":"Concentrated acidic solution( with glucose) Part A 5 liters solutions for On-line HDF (5008S machine) jerrycan","v":"V","l":"NRH","r":""},{"i":"Part A dialysate concentrate solution 5 L (with K+3)","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Part A dialysate concentrate solution 5 L (with K+3) added (Till DH). Reason: Required based on the patient's pre-dialysis blood potassium levels."],["Specification changed in 2025","Concentrated acidic solution( with glucose) Part A 10 liters solutions for On-line HDF (5008S machine) jerrycan → now Concentrated acidic solution( with glucose) Part A 5 liters solutions for On-line HDF (5008S machine) jerrycan"]],"al":""},{"k":"CALAMINE","n":"CALAMINE","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Zinc carbonate/oxide with iron oxide; mild astringent and antipruritic with cooling effect.","f":[["Indications & dose","Compounding calamine lotion for pruritus."]],"f25":[{"i":"Calamine powder (450g) packet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"COAL TAR","n":"COAL TAR","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Antimitotic, keratoplastic and antipruritic; slows epidermal proliferation.","f":[["Indications & dose","Compounding for psoriasis and chronic eczema."]],"f25":[{"i":"Coal tar solution 20% (400mL) bottle","v":"N","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Coal tar solution (450mL) bottle → now Coal tar solution 20% (400mL) bottle"]],"al":""},{"k":"DAPAGLIFLOZIN","n":"DAPAGLIFLOZIN","g":"Antidiabetic / heart failure and CKD (SGLT2 inhibitor)","sec":"17. MEDICINES FOR ENDOCRINE DISORDERS","sub":"17.4.2 Oral hypoglycemic agents","moa":"Inhibits sodium-glucose co-transporter 2 in the proximal tubule, causing glycosuria and natriuresis; lowers glucose, preload and intraglomerular pressure.","f":[["Indications & dose","Type 2 diabetes ADULT: 10 mg PO once daily (alone or with other agents). Heart failure with reduced ejection fraction ADULT: 10 mg once daily. Chronic kidney disease ADULT: 10 mg once daily."],["Contraindications","Type 1 diabetes; diabetic ketoacidosis; hypersensitivity. Do not start if eGFR <25 mL/min/1.73 m²; less effective for glucose lowering if eGFR <45."],["Side effects","Genital fungal infections, urinary tract infection, polyuria, volume depletion and hypotension, euglycaemic ketoacidosis (rare)."],["Note","Stop 3 days before major surgery and during acute illness (sick-day rule). Extended to RRH in NEML 2025."]],"f25":[{"i":"Dapagliflozin 10 mg tablet","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Extended in 2025","Dapagliflozin 10 mg: now supplied down to RRH"]],"al":""},{"k":"DPT VACCINE","n":"DPT VACCINE","g":"Vaccine","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Diphtheria and tetanus toxoids with pertussis antigens; induce antitoxin and anti-pertussis antibodies.","f":[["Indications & dose","Prevention of diphtheria, tetanus, and pertussis Booster at 24 months 0.5 mL Intramuscular (IM) antero-lateral aspect of left mid-thigh. For details refer to EPI Services Manual for health workers 5th Edition 2020."],["Side effects","Mild local or systemic reactions are common, temporary swelling, tenderness and redness at the site of injection, fever, vomiting, diarrhoea. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"Diphtheria pertussis tetanus (DPT) vaccine suspension for injection (0.5mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"PENTAVALENT VACCINE","n":"PENTAVALENT VACCINE","g":"Vaccine (DPT-HepB-Hib)","sec":"18. IMMUNOLOGICALS","sub":"18.2 Vaccines","moa":"Diphtheria and tetanus toxoids, pertussis, hepatitis B surface antigen and Hib conjugate; induces protective antibodies to all five.","f":[["Indications & dose","Prevention of diphtheria, tetanus, pertussis, hepatitis B and haemophilus influenza B 0.5 mL Intramuscular (IM) antero-lateral aspect of left mid-thigh at 6, 10 and 14th weeks."],["Contraindications","Known hypersensitivity to any component of the vaccine, or a severe reaction to a previous dose of the combination vaccine or any of its constituents is an absolute contraindication to subsequent doses of the combination vaccine or the specific vaccine known to have provoked an adverse reaction."],["Cautions","Careful injection technique will reduce the risk of thigh abscess; use a fresh needle and syringe for every child and discard the vial at the end of the session."],["Side effects","Mild local or systemic reactions are common, temporary swelling, tenderness and redness at the site of injection, fever, vomiting, diarrhoea. For details refer to EPI Services Manual for health workers 5th Edition 2020."]],"f25":[{"i":"DPT - Hep B - Hib vaccine injection (0.5mL) vial","v":"V","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"FLUTICASONE FUROATE (nasal)","n":"FLUTICASONE FUROATE (nasal)","g":"Intranasal corticosteroid","sec":"27. EAR, NOSE AND THROAT MEDICINES","sub":"27.1 Decongestants","moa":"Topical corticosteroid with high glucocorticoid receptor affinity; reduces nasal mucosal inflammation, oedema and mediator release.","f":[["Indications & dose","Allergic and perennial rhinitis ADULT and CHILD 12 years and over: 2 sprays (55 mcg) into each nostril once daily, reduce to 1 spray each nostril once controlled; CHILD 2-11 years: 1 spray into each nostril once daily (increase to 2 if needed, then reduce)."],["Contraindications","Hypersensitivity. Caution after recent nasal surgery or trauma, untreated nasal infection."],["Side effects","Epistaxis, nasal dryness and irritation, headache; rarely nasal septal perforation, raised IOP."],["Note","Replaces budesonide nasal spray (deleted in NEML 2025)."]],"f25":[{"i":"Fluticasone nasal spray 27.5 mcg/actuation (120 actuation)","v":"E","l":"NRH/RRH","r":"Supplied to DH where there is ENT Specialist"}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Fluticasone nasal spray 27.5 mcg/actuation (120 actuation) added (Till DH). Reason: A mainstay treatment for allergic and perennial rhinitis, offers broader age suitability than budesonide and fluticasone propionate due to its U.S. FDA approval for use in children as young as 2 years."]],"al":""},{"k":"GADOBENATE DIMEGLUMINE","n":"GADOBENATE DIMEGLUMINE","g":"MRI contrast (gadolinium-based)","sec":"14. DIAGNOSTIC AGENTS","sub":"14.2 Radiocontrast media","moa":"Paramagnetic gadolinium chelate that shortens T1 relaxation (high relaxivity); partly excreted via bile, aiding liver imaging.","f":[["Indications & dose","MRI of CNS and liver ADULT: 0.1 mmol/kg (0.2 mL/kg of 0.5 M solution) IV bolus; liver 0.05 mmol/kg."],["Contraindications","Hypersensitivity to gadolinium agents. Caution in severe renal impairment (nephrogenic systemic fibrosis risk), though lower than gadodiamide."],["Side effects","Headache, nausea, injection-site reaction, taste disturbance; rarely anaphylactoid reactions."],["Note","Replaces gadodiamide (deleted in NEML 2025)."]],"f25":[{"i":"Gadobenate Dimeglumine injection 10ml vial","v":"E","l":"NRH","r":""}],"lv":["NRH"],"ch":[["Added in 2025","Gadobenate Dimeglumine injection 10ml vial added (Till NRH). Reason: Lower NSF risk when compared to Gadodiamide. It can be used in renal impairment with caution as it has higher relaxivity → stronger T1 enhancement, especially for small lesions; partial hepatobiliary excretion → superior for liver MRI and CNS imaging."]],"al":""},{"k":"HYDROXYZINE","n":"HYDROXYZINE","g":"Sedating antihistamine (anxiolytic)","sec":"3. ANTIALLERGICS AND MEDICINES USED IN ANAPHYLAXIS","sub":"","moa":"First-generation (piperazine) H1-receptor inverse agonist; central H1 blockade gives sedative and anxiolytic effects.","f":[["Indications & dose","Pruritus ADULT: 25 mg PO at night, increased if needed to 25 mg 3-4 times daily (max 100 mg/day; elderly max 50 mg/day). Anxiety ADULT: 50-100 mg daily in divided doses. CHILD 6 months-5 years: 5-15 mg at night, up to 50 mg daily in divided doses; CHILD 6-17 years: 15-25 mg at night, up to 50-100 mg daily in divided doses."],["Contraindications","Prolonged QT interval or risk factors for it; porphyria; early pregnancy; breast-feeding."],["Side effects","Drowsiness, dry mouth, headache, fatigue; QT prolongation (rare)."],["Note","Added to NEML 2025 (till PHC) in place of promethazine for children and the elderly."]],"f25":[{"i":"Hydroxyzine hydrochloride 25mg tablet","v":"E","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Added in 2025","Hydroxyzine hydrochloride 25mg tablet added (Till PHC). Reason: Promethazine is not recommended for children and elderly due to risk of increased sedation, anticholinergic burden, extra pyramidal symptoms and has no dependence."]],"al":""},{"k":"METHYL HYDROXYBENZOATE","n":"METHYL HYDROXYBENZOATE","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Paraben preservative; antimicrobial in compounded preparations.","f":[["Indications & dose","Preservative for compounded liquids and creams."]],"f25":[{"i":"Methyl hydroxybenzoate powder 99% w/w (500g) Jar","v":"N","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Specification changed in 2025","Methyl hydroxybenzoate powder (500g) container → now Methyl hydroxybenzoate powder 99% w/w (500g) Jar"]],"al":""},{"k":"METHYL SALICYLATE","n":"METHYL SALICYLATE","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Counter-irritant (rubefacient) producing local warmth that masks deeper pain.","f":[["Indications & dose","Compounding liniments for musculoskeletal pain."]],"f25":[{"i":"Methyl salicylate solution (450mL) bottle","v":"N","l":"NRH/RRH/DH/PHC","r":"."}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"MUPIROCIN","n":"MUPIROCIN","g":"Topical antibacterial","sec":"13. DERMATOLOGICAL MEDICINES (TOPICAL)","sub":"13.2 Anti-infective medicines","moa":"Binds bacterial isoleucyl-tRNA synthetase, stopping protein synthesis; active against staphylococci (incl. MRSA) and streptococci.","f":[["Indications & dose","Impetigo and infected minor skin lesions ADULT and CHILD: apply up to 3 times daily for up to 10 days."],["Contraindications","Hypersensitivity."],["Side effects","Local burning, itching, rash; resistance with prolonged use."],["Note","On NEML 2025."]],"f25":[{"i":"Mupirocin 2% cream (15g) tube","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"NEVIRAPINE","n":"NEVIRAPINE","g":"Antiretroviral (NNRTI)","sec":"6. ANTI-INFECTIVE MEDICINES","sub":"6.4.2 Antiretrovirals","moa":"Non-nucleoside reverse transcriptase inhibitor; binds an allosteric pocket of HIV-1 reverse transcriptase.","f":[["Indications & dose","Infant prophylaxis (HIV-exposed newborn, WHO dosing) birth to 6 weeks: 2-2.5 kg 10 mg (1 mL) PO once daily; 2.5 kg or more 15 mg (1.5 mL) once daily; continue for 6 weeks (12 weeks if high risk, per national PMTCT guideline). Maternal: single 200 mg dose more than 2 hours before delivery (NEML 2025 remark)."],["Contraindications","Moderate to severe hepatic impairment; previous severe rash or hepatitis with nevirapine."],["Side effects","Rash (including Stevens-Johnson syndrome), hepatotoxicity, nausea, fever."],["Note","Added to NEML 2025 (till RRH)."]],"f25":[{"i":"Nevirapine 50mg/5ml oral suspension","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Nevirapine 50mg/5ml oral suspension added (Till RRH). Reason: Preferred first line ART regimen for pregnant women (stat single dose of NVP 200 mg > 2 hours prior to delivery) and neonate"]],"al":""},{"k":"OLANZAPINE","n":"OLANZAPINE","g":"Atypical antipsychotic","sec":"22. MEDICINES FOR MENTAL AND BEHAVIOURAL DISORDERS","sub":"22.1 Medicines used in psychotic disorders","moa":"Antagonist at 5-HT2A and D2 receptors, with strong H1, M1 and alpha-1 blockade (sedation, weight gain).","f":[["Indications & dose","Schizophrenia, combination therapy for mania, preventing recurrence in bipolar disorder ADULT: PO 10 mg daily adjusted to usual range of 5-20 mg daily; Doses greater than 10 mg daily only after reassessment; MAX 20 mg daily."],["Cautions","Prostatic hypertrophy, paralytic ileus, diabetes mellitus (risk of exacerbation or ketoacidosis), low leucocyte or neutrophil count, bone marrow depression, hypereosinophilic disorders, myeloproliferative disease, Parkinson's disease, increased appetite, raised triglyceride concentration, oedema."],["Side effects","Mild, transient antimuscarinic effects, drowsiness, speech difficulty, exacerbation of Parkinson's disease, akathisia, asthenia, increased appetite, raised triglyceride concentration, oedema, hyperprolactinemia, weight gain, orthostatic hypotension."],["Renal impairment","Consider initial dose of 5 mg daily."],["Hepatic impairment","Consider initial dose of 5 mg daily."],["Pregnancy category","C"],["Breast-feeding","Excreted in breast milk, avoid."],["Counselling","Orodispersible tablets should be placed on the tongue, allowed to dissolve, and swallowed."]],"f25":[{"i":"Olanzapine 10mg tablet","v":"E","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"PILOCARPINE","n":"PILOCARPINE","g":"Miotic (ophthalmic)","sec":"20. OPHTHALMOLOGICAL PREPARATIONS","sub":"20.4 Miotics and antiglaucoma medicines","moa":"Muscarinic agonist; contracts sphincter pupillae (miosis, thins iris) and ciliary muscle, opening the trabecular meshwork to increase aqueous outflow.","f":[["Indications & dose","Before laser iridotomy or surgery to constrict the pupil ADULT: 1 drop of 2% about 15-30 minutes before the procedure. Angle-closure / glaucoma (specialist): 1 drop up to 4 times daily."],["Contraindications","Acute iritis, anterior uveitis and other conditions where miosis is undesirable."],["Side effects","Brow ache, blurred vision, poor night vision, eye irritation; rarely retinal detachment; systemic sweating or salivation."],["Note","Added to NEML 2025 (till RRH)."]],"f25":[{"i":"Pilocarpine 2% eye drops (5ml)","v":"E","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[["Added in 2025","Pilocarpine 2% eye drops added (Till RRH). Reason: It provides essential iris-thinning and angle-widening effects for glaucoma diagnosis and surgery that no other NEML-listed alternatives offer and proven to safely induce miosis and thin the iris, which is critical for successful and safer laser procedures and surgeries."]],"al":""},{"k":"PODOPHYLLUM RESIN","n":"PODOPHYLLUM RESIN","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Antimitotic; binds tubulin and arrests cell division in wart tissue.","f":[["Indications & dose","Compounding for anogenital warts (avoid in pregnancy)."]],"f25":[{"i":"Podophyllum resin (25g) bottle","v":"N","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"POTASSIUM PERMANGANATE","n":"POTASSIUM PERMANGANATE","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Oxidising agent; antiseptic and astringent.","f":[["Indications & dose","Dilute 1 in 10,000 soaks for weeping eczema and infected wounds."]],"f25":[{"i":"Potassium permanganate crystals (450g) packet","v":"N","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[],"al":""},{"k":"RANOLAZINE","n":"RANOLAZINE","g":"Antianginal","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.1 Antianginal medicines","moa":"Inhibits the late inward sodium current in cardiomyocytes, reducing sodium-dependent calcium overload and diastolic wall tension; does not lower heart rate or BP.","f":[["Indications & dose","Chronic stable angina (add-on when symptoms persist on first-line therapy) ADULT: 500 mg PO Q12H, increased after 2-4 weeks to 1 g Q12H if needed (max 1 g Q12H). Swallow whole."],["Contraindications","Severe renal impairment (CrCl <30 mL/min); moderate or severe hepatic impairment; with strong CYP3A4 inhibitors (e.g. clarithromycin) or inducers (e.g. rifampicin, carbamazepine)."],["Side effects","Dizziness, headache, constipation, nausea, asthenia; QT prolongation."],["Note","Replaces isosorbide dinitrate 10 mg tablet on the 2025 list (ISDN 5 mg sublingual remains)."]],"f25":[{"i":"Ranolazine 500mg tablet","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Added in 2025","Ranolazine 500mg tablet added (Till DH). Reason: Proven safety and therapeutic efficacy for chronic stable angina and emerging evidence for Microvascular Angina for patients with persistent symptoms despite first line therapy. Ranolazine as monotherapy or in addition to other anti-anginal agents, provides increased exercise time, increased time to angina, and decreased use of nitroglycerin."]],"al":""},{"k":"SALICYLIC ACID","n":"SALICYLIC ACID","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Keratolytic; softens and loosens keratin.","f":[["Indications & dose","Compounding for hyperkeratosis, warts, psoriasis scale."]],"f25":[{"i":"Salicylic acid powder (450g) packet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"SULPHUR (precipitated/sublime)","n":"SULPHUR (precipitated/sublime)","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Keratolytic and antiparasitic; converted to hydrogen sulphide and pentathionic acid.","f":[["Indications & dose","Compounding sulphur ointment (e.g. scabies in infants and pregnancy)."]],"f25":[{"i":"Sulphur sublime 99.9% w/w powder (450g) packet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Sulphur sublime powder (450g) packet → now Sulphur sublime 99.9% w/w powder (450g) packet"]],"al":""},{"k":"TENECTEPLASE","n":"TENECTEPLASE","g":"Thrombolytic","sec":"12. CARDIOVASCULAR MEDICINES","sub":"12.5.2 Thrombolytic medicines","moa":"Genetically modified tissue plasminogen activator: more fibrin-specific, resistant to PAI-1 and longer half-life than alteplase, so given as a single bolus.","f":[["Indications & dose","STEMI within 6 hours of symptom onset ADULT: single IV bolus over 5-10 seconds by weight: under 60 kg 30 mg; 60-69 kg 35 mg; 70-79 kg 40 mg; 80-89 kg 45 mg; 90 kg or more 50 mg (consider half dose if 75 years or older). Acute ischaemic stroke within 4.5 hours ADULT: 0.25 mg/kg single IV bolus (max 25 mg)."],["Contraindications","Any previous intracranial haemorrhage; ischaemic stroke in the last 3 months (other than the index stroke); intracranial tumour or AVM; active bleeding; suspected aortic dissection; significant head or facial trauma or major surgery in last 3 weeks; uncontrolled hypertension (above 180/110 mmHg)."],["Side effects","Bleeding (intracranial, GI, injection sites), reperfusion arrhythmias, hypotension, allergic reactions."],["Note","Replaces streptokinase (deleted in NEML 2025, available till DH)."]],"f25":[{"i":"Tenecteplase 50mg injection","v":"V","l":"NRH/RRH/DH","r":""}],"lv":["NRH","RRH","DH"],"ch":[["Added in 2025","Tenecteplase 50mg injection added (Till DH). Reason: Indicated for STEMI and AIS and to replace Streptokinase from NEML due to major bleeding and frequent hypersensitivity."]],"al":""},{"k":"TERLIPRESSIN","n":"TERLIPRESSIN","g":"Vasopressin analogue","sec":"16. GASTROINTESTINAL MEDICINES","sub":"16.6 Antiulcer medicines and medicines used in variceal bleeding","moa":"Prodrug of lysine-vasopressin; V1 receptor agonist causing splanchnic vasoconstriction and reduced portal pressure.","f":[["Indications & dose","Acute oesophageal variceal bleeding ADULT: 2 mg IV Q4H until bleeding is controlled (1 mg Q4H if under 50 kg or after control), for up to 72 hours. Hepatorenal syndrome ADULT (specialist): 1 mg IV Q4-6H."],["Contraindications","Pregnancy; septic shock. Caution in ischaemic heart disease, arrhythmias, uncontrolled hypertension, hyponatraemia, hypoxia (SpO2 under 90%)."],["Side effects","Abdominal cramps, diarrhoea, pallor, hypertension, bradycardia, peripheral and myocardial ischaemia, hyponatraemia, respiratory failure."],["Note","On NEML 2025."]],"f25":[{"i":"Terlipressin 1mg/10mL injection vial","v":"V","l":"NRH/RRH","r":""}],"lv":["NRH","RRH"],"ch":[],"al":""},{"k":"WHITE SOFT PARAFFIN","n":"WHITE SOFT PARAFFIN","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Occlusive emollient; reduces transepidermal water loss.","f":[["Indications & dose","Emollient base for dry skin and compounding."]],"f25":[{"i":"White soft paraffin (1kg) jar","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[],"al":""},{"k":"ZINC OXIDE","n":"ZINC OXIDE","g":"Compounding chemical","sec":"33. CHEMICALS FOR EXTEMPORANEOUS COMPOUNDING","sub":"","moa":"Mild astringent, protective and soothing.","f":[["Indications & dose","Compounding zinc oxide pastes and creams."]],"f25":[{"i":"Zinc oxide powder 99.9% w/w (450g) packet","v":"N","l":"NRH/RRH/DH/PHC","r":""}],"lv":["NRH","RRH","DH","PHC"],"ch":[["Specification changed in 2025","Zinc oxide powder (450g) packet → now Zinc oxide powder 99.9% w/w (450g) packet"]],"al":""}];
